/* ---------- Europe hors France et Portugal ---------- */
const D54 = [
{ id:'stargazy-pie', c:'eu', lat:50.083, lon:-5.542, base:6, prep:50, cook:45, diff:3, tags:['sea','bake','festive'],
  art:{v:'plate',bg:'#26384a',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9c0b0','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Stargazy pie',en:'Stargazy pie'},
  p:{fr:'Mousehole, Cornouailles, Angleterre',en:'Mousehole, Cornwall, England'},
  d:{fr:"Une tourte de sardines dont les têtes traversent la croûte et regardent le ciel. Mousehole la prépare le 23 décembre, en mémoire de Tom Bawcock qui brava la tempête et sauva le village de la famine.",
     en:"A pilchard pie with the heads breaking through the crust to face the sky. Mousehole makes it on 23 December, for Tom Bawcock who braved the storm and saved the village from famine."},
  i:[['sardines',8,'pc'],['puff_pastry',500,'g'],['smoked_bacon',150,'g'],['onion',2,'pc'],['egg',5,'pc'],['heavy_cream',250,'ml'],['white_wine',150,'ml'],['parsley',4,'tbsp'],['mustard_powder',1,'tsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Videz et désarêtez les sardines en gardant la tête et la queue attachées : c'est toute la mise en scène du plat.","Faites rissoler le lard et l'oignon, et faites durcir trois œufs.","Chemisez un moule rond de pâte, garnissez de lard, d'oignon et d'œufs en quartiers.","Disposez les sardines en rayons de roue, tête vers l'extérieur, et versez la crème battue aux œufs restants et au vin.","Couvrez de pâte en faisant passer chaque tête au travers, dorez et enfournez 40 minutes à 190 °C."],
     en:["Gut and bone the sardines keeping head and tail attached: the whole staging of the dish depends on it.","Fry the bacon and onion, and hard-boil three eggs.","Line a round dish with pastry and fill with bacon, onion and quartered eggs.","Arrange the sardines like the spokes of a wheel, heads outward, and pour over the cream beaten with the remaining eggs and the wine.","Cover with pastry, pushing each head through it, glaze and bake for 40 minutes at 190°C."]} },

{ id:'laverbread-gallois', c:'eu', lat:51.622, lon:-3.943, base:4, prep:20, cook:20, diff:1, tags:['sea','breakfast','fast'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'flat',food:['#2f4f2a','#8f5a3a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Laverbread',en:'Laverbread'},
  p:{fr:'Swansea, pays de Galles',en:'Swansea, Wales'},
  d:{fr:"De l'algue laver longuement bouillie, roulée dans du gruau d'avoine et poêlée dans la graisse de bacon. Richard Burton l'appelait le caviar gallois ; il faut huit heures de cuisson pour la rendre mangeable.",
     en:"Laver seaweed boiled at length, rolled in oatmeal and fried in bacon fat. Richard Burton called it Welsh caviar; it takes eight hours of boiling to become edible."},
  i:[['laver_seaweed',400,'g'],['oatmeal',150,'g'],['smoked_bacon',200,'g'],['cockles',300,'g'],['butter',40,'g'],['lemon',1,'pc'],['white_bread',4,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Lavez l'algue à plusieurs eaux pour retirer tout le sable : il en reste toujours, et il se sent.","Faites-la bouillir 6 à 8 heures dans une eau non salée, jusqu'à ce qu'elle devienne une purée noire et lisse.","Égouttez-la et pressez-la : elle doit avoir la consistance d'une confiture épaisse.","Faites griller le bacon et gardez la graisse rendue dans la poêle.","Formez des galettes de purée d'algue roulées dans le gruau d'avoine et poêlez-les 3 minutes par face. Servez avec bacon, coques et citron."],
     en:["Wash the seaweed in several changes of water to remove every grain of sand: some always remains, and you taste it.","Boil it for 6 to 8 hours in unsalted water, until it becomes a smooth black purée.","Drain and press it: it should have the consistency of a thick jam.","Grill the bacon and keep the rendered fat in the pan.","Shape patties of the laver rolled in oatmeal and fry them 3 minutes a side. Serve with bacon, cockles and lemon."]} },

{ id:'hachee-amsterdam', c:'eu', lat:52.370, lon:4.895, base:4, prep:30, cook:120, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#c9754a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Hachee',en:'Hachee'},
  p:{fr:'Amsterdam, Pays-Bas',en:'Amsterdam, Netherlands'},
  d:{fr:"Un ragoût de bœuf et d'oignons au vinaigre et au clou de girofle, si long à mijoter qu'il se défait à la cuillère. Il se sert avec du chou rouge aux pommes : les Néerlandais ne conçoivent pas l'un sans l'autre.",
     en:"A beef and onion stew with vinegar and cloves, simmered so long it falls apart at the spoon. Served with red cabbage and apple: the Dutch cannot conceive of one without the other."},
  i:[['beef_chuck',1,'kg'],['onion',1,'kg'],['butter',80,'g'],['red_wine_vinegar',80,'ml'],['beef_stock',600,'ml'],['cloves',6,'pc'],['bay_leaf',3,'pc'],['juniper_berries',6,'pc'],['brown_sugar',1,'tbsp'],['flour',40,'g'],['red_cabbage',600,'g'],['apple',2,'pc'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le bœuf en cubes et faites-le saisir au beurre en plusieurs fois, sans encombrer la cocotte.","Retirez-le et faites fondre les oignons en lamelles 25 minutes : il en faut autant que de viande.","Singez de farine, versez le vinaigre et laissez-le réduire, puis mouillez du fond.","Ajoutez clous, laurier, genièvre et sucre, remettez la viande et laissez mijoter 2 heures à couvert.","Servez avec un chou rouge braisé aux pommes et des pommes de terre à l'eau."],
     en:["Cut the beef into cubes and sear it in butter in batches, without crowding the pot.","Lift it out and melt the sliced onions for 25 minutes: you need as much onion as meat.","Dust with flour, add the vinegar and reduce it, then moisten with the stock.","Add cloves, bay, juniper and sugar, return the meat and simmer covered for 2 hours.","Serve with braised red cabbage and apple, and boiled potatoes."]} },

{ id:'waterzooi-de-poisson', c:'eu', lat:51.054, lon:3.725, base:4, prep:30, cook:35, diff:2, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e8c46a','#7fae5a','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Waterzooi de poisson',en:'Fish waterzooi'},
  p:{fr:'Gand, Flandre-Orientale, Belgique',en:'Ghent, East Flanders, Belgium'},
  d:{fr:"Un pochage de poissons de rivière dans un bouillon de légumes lié aux jaunes d'œufs. Le waterzooi de Gand était au poisson bien avant d'être au poulet : la pollution de l'Escaut a fait basculer la recette au XXe siècle.",
     en:"River fish poached in a vegetable broth thickened with egg yolks. Ghent waterzooi was fish long before it was chicken: pollution in the Scheldt tipped the recipe over in the 20th century."},
  i:[['pike',400,'g'],['eel',400,'g'],['perch',400,'g'],['leek',3,'pc'],['carrot',3,'pc'],['celery',4,'stalk'],['potato',600,'g'],['butter',100,'g'],['egg_yolk',3,'pc'],['heavy_cream',250,'ml'],['fish_broth',800,'ml'],['parsley',4,'tbsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez tous les légumes en julienne de même épaisseur : dans un waterzooi, ils doivent cuire ensemble.","Faites-les suer au beurre sans coloration, puis mouillez du fumet et laissez cuire 15 minutes.","Coupez le feu et glissez les poissons en gros tronçons : ils pocheront dans la chaleur résiduelle, 8 minutes.","Battez les jaunes et la crème, tempérez d'une louche de bouillon, puis versez dans la soupe hors du feu.","Ne laissez plus jamais bouillir : la liaison tournerait. Citron et persil au moment de servir."],
     en:["Cut all the vegetables into julienne of the same thickness: in a waterzooi they must cook together.","Sweat them in butter without colouring, then moisten with the stock and cook for 15 minutes.","Cut the heat and slide in the fish in large lengths: they poach in the residual warmth, 8 minutes.","Beat the yolks and cream, temper with a ladle of broth, then stir into the soup off the heat.","Never let it boil again: the liaison would split. Lemon and parsley as you serve."]} },

{ id:'malakoff-vaudois', c:'eu', lat:46.500, lon:6.383, base:6, prep:30, cook:20, diff:2, tags:['cheese','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Malakoff vaudois',en:'Vaud malakoff'},
  p:{fr:'Vinzel, Vaud, Suisse',en:'Vinzel, Vaud, Switzerland'},
  d:{fr:"Un beignet de gruyère râpé sur une tranche de pain, frit et servi brûlant avec du vin blanc. Les mercenaires vaudois de Crimée l'auraient rapporté du siège de Malakoff en 1855 ; le village de Vinzel en vit encore.",
     en:"A fritter of grated gruyère on a slice of bread, deep-fried and served scalding with white wine. Vaud mercenaries are said to have brought it back from the siege of Malakoff in 1855; the village of Vinzel still lives on it."},
  i:[['gruyere_cheese',600,'g'],['egg',3,'pc'],['flour',60,'g'],['white_wine',80,'ml'],['garlic',2,'clove'],['kirsch',2,'tbsp'],['white_bread',12,'slice'],['frying_oil',1,'l'],['nutmeg',1,'pinch'],['pepper',null,'']],
  s:{fr:["Râpez le gruyère au gros et laissez-le revenir à température ambiante : froid, il ne lie pas.","Mêlez-le aux œufs, à la farine, au vin blanc, au kirsch, à l'ail pilé et à la muscade, en une pâte compacte.","Laissez reposer 2 heures au frais : la pâte doit se tenir en boule sans couler.","Découpez des ronds de pain de 7 cm et dressez sur chacun une boule de pâte aplatie, en débordant à peine.","Plongez-les pain vers le haut dans l'huile à 175 °C, 4 minutes, jusqu'à ce que le fromage gonfle et dore. Servez immédiatement."],
     en:["Coarsely grate the gruyère and let it come to room temperature: cold, it will not bind.","Mix it with the eggs, flour, white wine, kirsch, pounded garlic and nutmeg, into a dense paste.","Rest it for 2 hours in the cold: the paste should hold its shape without slumping.","Cut 7 cm rounds of bread and set a flattened ball of paste on each, barely overhanging.","Lower them bread side up into oil at 175°C for 4 minutes, until the cheese puffs and colours. Serve immediately."]} },

{ id:'arroz-caldoso-de-marisco', c:'eu', lat:36.535, lon:-6.299, base:6, prep:35, cook:25, diff:2, tags:['sea','rice','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'rice',food:['#e0913a','#f0a878','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Arroz caldoso de marisco',en:'Soupy seafood rice'},
  p:{fr:'Cadix, Andalousie, Espagne',en:'Cádiz, Andalusia, Spain'},
  d:{fr:"Un riz de coquillages resté volontairement liquide, servi à la cuillère. Contrairement à la paella, l'arroz caldoso ne s'assèche jamais : il doit couler quand on penche l'assiette, et se mange dans les vingt minutes.",
     en:"A shellfish rice deliberately left soupy, eaten with a spoon. Unlike paella, arroz caldoso never dries: it must run when the plate is tilted, and is eaten within twenty minutes."},
  i:[['bomba_rice',400,'g'],['shrimp',500,'g'],['clams',500,'g'],['mussels',500,'g'],['monkfish',400,'g'],['onion',2,'pc'],['garlic',6,'clove'],['red_pepper',1,'pc'],['ripe_tomato',300,'g'],['smoked_paprika',1,'tbsp'],['saffron',1,'pinch'],['fish_broth',1.6,'l'],['olive_oil',100,'ml'],['parsley',4,'tbsp'],['salt',null,'']],
  s:{fr:["Décortiquez les crevettes et faites un fumet corsé avec les têtes et les carapaces, 25 minutes ; filtrez-le.","Faites un sofrito d'oignon, d'ail, de poivron et de tomate à l'huile d'olive, 20 minutes, jusqu'à ce qu'il fonce.","Ajoutez le paprika hors du feu, puis le riz, et laissez-le nacrer une minute.","Versez quatre volumes de fumet brûlant pour un de riz — le double d'une paella — avec le safran infusé.","Cuisez 16 minutes à découvert, ajoutez les coquillages et le poisson pour les 6 dernières, et servez immédiatement."],
     en:["Peel the prawns and make a strong stock with the heads and shells, 25 minutes; strain it.","Make a sofrito of onion, garlic, pepper and tomato in olive oil, 20 minutes, until it darkens.","Add the paprika off the heat, then the rice, and let it turn pearly for a minute.","Pour in four parts scalding stock to one of rice — twice a paella — with the infused saffron.","Cook uncovered for 16 minutes, add the shellfish and fish for the last 6, and serve at once."]} },

{ id:'kalops', c:'eu', lat:57.721, lon:12.940, base:6, prep:25, cook:150, diff:1, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#e8dcb8','#c9754a'],garnish:'#7fae6a'},
  n:{fr:'Kalops',en:'Kalops'},
  p:{fr:'Borås, Västergötland, Suède',en:'Borås, Västergötland, Sweden'},
  d:{fr:"Un ragoût de bœuf au piment de la Jamaïque, servi avec de la betterave au vinaigre. Le nom vient de l'anglais collops, tranches de viande : les marins suédois l'ont rapporté d'Écosse au XVIIIe siècle.",
     en:"A beef stew with allspice, served with pickled beetroot. The name comes from English 'collops', slices of meat: Swedish sailors brought it back from Scotland in the 18th century."},
  i:[['beef_chuck',1.2,'kg'],['onion',600,'g'],['allspice',15,'pc'],['bay_leaf',3,'pc'],['flour',40,'g'],['butter',80,'g'],['beef_stock',800,'ml'],['carrot',3,'pc'],['pickled_beets',300,'g'],['potato',1,'kg'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le bœuf en gros cubes, farinez-les légèrement et faites-les saisir au beurre en plusieurs fois.","Retirez la viande et faites blondir les oignons en épaisses lamelles dans la même graisse.","Remettez le bœuf, ajoutez le piment de la Jamaïque entier et le laurier, et mouillez du fond.","Laissez mijoter 2 heures à couvert, à tout petit feu : le ragoût ne doit jamais bouillir franchement.","Ajoutez la carotte pour les 30 dernières minutes. Servez avec des pommes vapeur et de la betterave au vinaigre."],
     en:["Cut the beef into large cubes, flour them lightly and sear them in butter in batches.","Lift out the meat and soften the thickly sliced onions in the same fat until golden.","Return the beef, add the whole allspice and the bay, and moisten with the stock.","Simmer covered for 2 hours over the gentlest heat: the stew should never come to a rolling boil.","Add the carrot for the last 30 minutes. Serve with steamed potatoes and pickled beetroot."]} },

{ id:'fiskesuppe-bergen', c:'eu', lat:60.393, lon:5.325, base:4, prep:25, cook:30, diff:2, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'soup',food:['#f4f0e6','#e8c46a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Soupe de poisson de Bergen',en:'Bergen fish soup'},
  p:{fr:'Bergen, Norvège',en:'Bergen, Norway'},
  d:{fr:"Une soupe blanche de poisson, liée à la crème et acidulée au vinaigre et au sucre. Cette pointe aigre-douce, héritée de la Hanse, surprend au premier abord et manque terriblement quand on l'ôte.",
     en:"A white fish soup, thickened with cream and sharpened with vinegar and sugar. That sweet-sour edge, inherited from the Hanseatic League, surprises at first and is sorely missed when removed."},
  i:[['cod_fillet',500,'g'],['salmon',300,'g'],['shrimp',200,'g'],['carrot',3,'pc'],['celery_root',1,'pc'],['leek',2,'pc'],['fish_broth',1,'l'],['heavy_cream',300,'ml'],['egg_yolk',2,'pc'],['white_wine_vinegar',3,'tbsp'],['sugar',2,'tsp'],['butter',60,'g'],['chives',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez tous les légumes en julienne fine et faites-les suer au beurre sans coloration.","Mouillez du fumet et laissez cuire 12 minutes : les légumes doivent rester croquants.","Battez les jaunes et la crème, tempérez d'une louche de bouillon chaud, puis liez la soupe hors du feu.","Acidulez au vinaigre et sucrez : goûtez et rectifiez, l'équilibre doit se sentir sans se nommer.","Glissez le poisson en cubes et laissez pocher 4 minutes hors du feu. Ajoutez les crevettes et la ciboulette au dernier moment."],
     en:["Cut all the vegetables into fine julienne and sweat them in butter without colouring.","Moisten with the stock and cook for 12 minutes: the vegetables should stay crisp.","Beat the yolks and cream, temper with a ladle of hot broth, then thicken the soup off the heat.","Sharpen with vinegar and sweeten: taste and adjust, the balance should be felt without being named.","Slide in the cubed fish and poach for 4 minutes off the heat. Add the prawns and chives at the last moment."]} },

{ id:'ploughmans-lunch', c:'eu', lat:51.147, lon:-2.717, base:4, prep:20, cook:0, diff:1, tags:['cheese','fast','fresh'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f0e8d0','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Ploughman’s lunch',en:'Ploughman’s lunch'},
  p:{fr:'Cheddar, Somerset, Angleterre',en:'Cheddar, Somerset, England'},
  d:{fr:"Du pain, du cheddar, du pickle et un oignon au vinaigre, posés sur une planche sans un seul plat chaud. Le nom sent le champ labouré mais date des années 1950 : le Cheese Bureau l'a inventé pour relancer les ventes de fromage dans les pubs après le rationnement.",
     en:"Bread, cheddar, pickle and a pickled onion, laid on a board with not a single hot dish. The name smells of ploughed fields but dates from the 1950s: the Cheese Bureau invented it to revive pub cheese sales after rationing."},
  i:[['cheddar_cheese',400,'g'],['bread',400,'g'],['pickled_onions',8,'pc'],['pickles',8,'pc'],['apple',2,'pc'],['butter',80,'g'],['ham',200,'g'],['lettuce',1,'pc'],['ripe_tomato',3,'pc'],['dijon_mustard',2,'tbsp'],['salt',null,'']],
  s:{fr:["Sortez le cheddar deux heures à l'avance : froid, il est cassant et sans goût, et c'est lui la pièce maîtresse.","Choisissez un cheddar fermier vieilli au moins douze mois, à la pâte qui s'effrite plutôt qu'elle ne se coupe.","Coupez-le en gros morceaux irréguliers, à la main autant qu'au couteau — la découpe régulière n'a pas sa place ici.","Disposez sur une planche le pain, le beurre, le fromage, le jambon, les oignons au vinaigre, les cornichons et la pomme en quartiers.","Ne dressez rien à l'avance : le pain sèche et la salade tombe. Un pickle brun et une pinte d'ale complètent l'assiette."],
     en:["Take the cheddar out two hours ahead: cold, it is brittle and tasteless, and it is the centrepiece.","Choose a farmhouse cheddar aged at least twelve months, with a paste that crumbles rather than cuts.","Break it into large uneven pieces, as much by hand as by knife — tidy slicing has no place here.","Set out on a board the bread, butter, cheese, ham, pickled onions, gherkins and quartered apple.","Assemble nothing in advance: the bread dries and the salad wilts. A brown pickle and a pint of ale finish the plate."]} },

{ id:'steak-and-kidney-pie', c:'eu', lat:51.513, lon:-0.098, base:6, prep:50, cook:180, diff:3, tags:['beef','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#c9924a','#6f4a2a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Steak and kidney pie',en:'Steak and kidney pie'},
  p:{fr:'Londres, Angleterre',en:'London, England'},
  d:{fr:"Un ragoût de paleron et de rognons de bœuf enfermé sous une croûte, arrosé de stout. Le rognon n'est pas là pour faire nombre : il donne au jus une profondeur ferreuse que la viande seule n'atteint jamais, et il en faut un quart du poids total.",
     en:"A stew of chuck and beef kidney sealed under a crust, moistened with stout. The kidney is not there to bulk it out: it gives the gravy an iron depth the beef alone never reaches, and it needs to be a quarter of the total weight."},
  i:[['beef_chuck',800,'g'],['beef_kidney',300,'g'],['onion',2,'pc'],['flour',60,'g'],['stout',400,'ml'],['beef_broth',300,'ml'],['worcestershire',2,'tbsp'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['butter',60,'g'],['puff_pastry',400,'g'],['egg_yolk',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les rognons 30 minutes dans du lait ou de l'eau vinaigrée, puis parez-les de leur graisse blanche centrale, qui donnerait un goût d'urine.","Farinez et saisissez le bœuf en cubes par petites quantités, dans une cocotte brûlante : entassé, il rendrait son eau au lieu de brunir.","Faites blondir l'oignon, remettez les viandes, déglacez à la stout et mouillez du bouillon avec le worcestershire et les herbes.","Laissez mijoter 2 h 30 à couvert, puis refroidissez complètement : une garniture chaude ferait fondre le feuilletage avant qu'il ne cuise.","Emplissez le moule, couvrez de pâte feuilletée, soudez, dorez, entaillez une cheminée et cuisez 35 minutes à 200 °C."],
     en:["Soak the kidney for 30 minutes in milk or vinegared water, then trim the white core fat, which would give a urinous taste.","Flour and sear the diced beef in small batches in a scalding pot: crowded, it would weep instead of browning.","Soften the onion, return the meats, deglaze with stout and moisten with broth, Worcestershire and herbs.","Simmer covered for 2½ hours, then cool completely: a hot filling would melt the puff pastry before it could bake.","Fill the dish, cover with pastry, seal, glaze, cut a vent and bake 35 minutes at 200°C."]} },

{ id:'beef-wellington', c:'eu', lat:51.507, lon:-0.142, base:6, prep:90, cook:40, diff:3, tags:['beef','festive','sunday'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#c9924a','#8f3b2a','#4f3a2a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Beef Wellington',en:'Beef Wellington'},
  p:{fr:'Londres, Angleterre',en:'London, England'},
  d:{fr:"Un filet de bœuf saisi, tapissé d'une duxelles de champignons et de jambon cru, puis enfermé dans un feuilletage. Tout le problème tient à l'humidité : la duxelles doit être desséchée jusqu'à ce qu'elle ne rende plus rien, sinon la pâte du dessous reste crue.",
     en:"A seared beef fillet lined with mushroom duxelles and cured ham, then sealed in puff pastry. The whole problem is moisture: the duxelles must be dried until it releases nothing more, or the pastry underneath stays raw."},
  i:[['beef_tenderloin',1,'kg'],['button_mushrooms',700,'g'],['prosciutto',12,'slice'],['shallot',3,'pc'],['puff_pastry',600,'g'],['dijon_mustard',2,'tbsp'],['brandy',50,'ml'],['thyme',4,'sprig'],['butter',60,'g'],['egg_yolk',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Saisissez le filet ficelé sur toutes ses faces à feu très vif, 4 minutes en tout, badigeonnez-le de moutarde et laissez-le refroidir.","Hachez les champignons au couteau, très fin, et faites-les dessécher à sec 25 minutes en remuant : ils doivent perdre les trois quarts de leur volume et ne plus grésiller.","Étalez le jambon cru en rectangle sur un film alimentaire, couvrez de duxelles, posez le filet et roulez très serré. Réfrigérez 1 heure.","Enveloppez ce boudin de pâte feuilletée, soudure dessous, dorez deux fois à vingt minutes d'intervalle et remettez au froid 30 minutes.","Cuisez 35 minutes à 200 °C jusqu'à 52 °C à cœur, puis reposez 15 minutes avant de trancher. Sans ce repos, tout le jus s'échappe et détrempe la pâte."],
     en:["Sear the tied fillet on all sides over fierce heat, 4 minutes in all, brush it with mustard and let it cool.","Chop the mushrooms very finely by knife and dry them out in a dry pan for 25 minutes, stirring: they must lose three-quarters of their volume and stop sizzling.","Lay the cured ham in a rectangle on cling film, cover with duxelles, set the fillet on it and roll very tightly. Chill for an hour.","Wrap this roll in puff pastry, seam underneath, glaze twice twenty minutes apart and chill again for 30 minutes.","Bake 35 minutes at 200°C to 52°C at the centre, then rest 15 minutes before carving. Without that rest, all the juice escapes and soaks the pastry."]} },

{ id:'melton-mowbray-pork-pie', c:'eu', lat:52.766, lon:-0.886, base:8, prep:90, cook:120, diff:3, tags:['pork','bake','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#c9924a','#e0a8a0','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Melton Mowbray pork pie',en:'Melton Mowbray pork pie'},
  p:{fr:'Melton Mowbray, Leicestershire, Angleterre',en:'Melton Mowbray, Leicestershire, England'},
  d:{fr:"Une tourte de porc haché gros, montée à la main sans moule, dont la gelée est coulée par le trou du dessus après cuisson. La viande n'est pas salpêtrée : c'est pourquoi elle reste grise et non rose, contrairement à toutes les autres tourtes anglaises.",
     en:"A pie of coarsely chopped pork, raised by hand without a tin, its jelly poured through the top hole after baking. The meat is not cured with nitrate: which is why it stays grey rather than pink, unlike every other English pie."},
  i:[['flour',450,'g'],['lard',180,'g'],['water',180,'ml'],['pork_shoulder',700,'g'],['pork_belly',300,'g'],['pork_bones',500,'g'],['gelatin',10,'g'],['sage',2,'tbsp'],['white_pepper',1,'tbsp'],['nutmeg',1,'pinch'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["Faites bouillir l'eau avec le saindoux et versez-les sur la farine salée : c'est une pâte à l'eau chaude, et elle ne se travaille que tiède.","Réservez un quart de pâte au chaud pour le couvercle et montez le reste à la main autour d'un bocal fariné, en remontant les parois par pincées.","Hachez le porc au couteau en morceaux de la taille d'un pois — le hachoir donnerait une pâte, et la tranche perdrait son grain.","Assaisonnez fortement de sel, de poivre blanc, de sauge et de muscade, tassez dans la croûte, posez le couvercle et percez un trou au centre.","Cuisez 30 minutes à 200 °C puis 1 h 30 à 160 °C. Coulez par le trou la gelée d'os tiède, et laissez prendre 24 heures au froid."],
     en:["Boil the water with the lard and pour it onto the salted flour: this is hot water crust, and it only works while warm.","Keep a quarter of the dough warm for the lid and raise the rest by hand around a floured jar, pinching the walls upward.","Chop the pork by knife into pea-sized pieces — a mincer would give a paste, and the slice would lose its grain.","Season heavily with salt, white pepper, sage and nutmeg, pack it into the crust, set the lid on and pierce a hole in the centre.","Bake 30 minutes at 200°C then 1½ hours at 160°C. Pour the warm bone jelly through the hole, and set for 24 hours in the cold."]} },

{ id:'toad-in-the-hole', c:'eu', lat:53.958, lon:-1.083, base:4, prep:20, cook:45, diff:2, tags:['pork','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e0b45a','#8f5a3a','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Toad in the hole',en:'Toad in the hole'},
  p:{fr:'York, Yorkshire, Angleterre',en:'York, Yorkshire, England'},
  d:{fr:"Des saucisses cuites dans une pâte à Yorkshire pudding qui gonfle autour d'elles. Le nom vient de ce que les saucisses affleurent la pâte comme des crapauds à la surface d'une mare ; la version d'origine, du XVIIIᵉ siècle, se faisait avec les restes de viande.",
     en:"Sausages baked in Yorkshire pudding batter that puffs up around them. The name comes from the sausages breaking the surface like toads in a pond; the original 18th-century version used up leftover meat."},
  i:[['pork_sausage',8,'pc'],['flour',150,'g'],['egg',4,'pc'],['whole_milk',250,'ml'],['beef_dripping',3,'tbsp'],['onion',2,'pc'],['beef_broth',300,'ml'],['dijon_mustard',1,'tbsp'],['thyme',3,'sprig'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Battez la farine, les œufs, le lait et le sel, et laissez reposer la pâte au moins 1 heure — froide et reposée, elle monte bien davantage.","Faites chauffer la graisse de bœuf dans le plat, au four à 220 °C, jusqu'à ce qu'elle fume : c'est le point décisif de la recette.","Faites colorer les saucisses à part, puis rangez-les dans la graisse fumante et versez la pâte d'un seul coup.","Enfournez 30 minutes sans jamais ouvrir la porte : la moindre entrée d'air froid fait retomber la pâte pour de bon.","Pendant ce temps, faites une sauce aux oignons fondus, au bouillon et à la moutarde. Servez dès la sortie du four."],
     en:["Beat the flour, eggs, milk and salt, and rest the batter at least an hour — cold and rested, it rises far more.","Heat the beef dripping in the dish at 220°C until it smokes: this is the decisive point of the recipe.","Brown the sausages separately, then set them in the smoking fat and pour in the batter all at once.","Bake 30 minutes without once opening the door: the least draught of cold air collapses the batter for good.","Meanwhile make a gravy of softened onions, broth and mustard. Serve straight from the oven."]} },

{ id:'bangers-and-mash', c:'eu', lat:51.523, lon:-0.157, base:4, prep:25, cook:35, diff:1, tags:['pork','comfort','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#8f5a3a','#f4f0e6','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bangers and mash',en:'Bangers and mash'},
  p:{fr:'Londres, Angleterre',en:'London, England'},
  d:{fr:"Des saucisses grillées sur une purée, noyées d'une sauce à l'oignon. Le mot banger date de la Grande Guerre : les saucisses étaient alors si allongées à l'eau qu'elles éclataient à la poêle avec un bruit d'explosion.",
     en:"Grilled sausages on mashed potato, flooded with onion gravy. The word banger dates from the Great War: sausages were then so padded out with water that they burst in the pan with a bang."},
  i:[['pork_sausage',8,'pc'],['potato',1,'kg'],['butter',150,'g'],['whole_milk',150,'ml'],['onion',500,'g'],['flour',2,'tbsp'],['beef_broth',400,'ml'],['worcestershire',1,'tbsp'],['dijon_mustard',1,'tbsp'],['sunflower_oil',20,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez les pommes de terre entières avec la peau, à l'eau salée : coupées, elles se gorgent d'eau et la purée devient collante.","Pelez-les brûlantes, passez-les au presse-purée — jamais au mixeur, qui rompt l'amidon et donne une colle — et montez-les au beurre puis au lait chaud.","Faites confire les oignons émincés 25 minutes à feu doux jusqu'à ce qu'ils soient bruns et sucrés.","Singez de farine, mouillez du bouillon, ajoutez le worcestershire et la moutarde, et laissez réduire 10 minutes.","Faites cuire les saucisses doucement 20 minutes en les tournant souvent, sans les piquer. Dressez sur la purée et nappez de sauce."],
     en:["Boil the potatoes whole in their skins in salted water: cut up, they take on water and the mash turns gluey.","Peel them scalding, pass them through a ricer — never a blender, which breaks the starch into glue — and beat in the butter then the hot milk.","Cook the sliced onions gently for 25 minutes until brown and sweet.","Dust with flour, moisten with broth, add the Worcestershire and mustard, and reduce for 10 minutes.","Cook the sausages slowly for 20 minutes, turning often, without pricking them. Set them on the mash and flood with gravy."]} },

{ id:'eton-mess', c:'eu', lat:51.489, lon:-0.608, base:4, prep:20, cook:0, diff:1, tags:['sweet','fast','fruit'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#c9402c','#f0e8d0','#e07a6a'],garnish:'#c9754a'},
  n:{fr:'Eton mess',en:'Eton mess'},
  p:{fr:'Eton, Berkshire, Angleterre',en:'Eton, Berkshire, England'},
  d:{fr:"Des fraises, de la crème fouettée et de la meringue brisée, mêlées sans ordre. Servi au collège d'Eton lors du match de cricket contre Harrow ; une légende tenace veut qu'un labrador se soit assis sur le dessert, ce qui expliquerait le désordre et le nom.",
     en:"Strawberries, whipped cream and broken meringue, tumbled together without order. Served at Eton College during the cricket match against Harrow; a persistent legend says a labrador sat on the pudding, which would explain both the mess and the name."},
  i:[['strawberries',600,'g'],['heavy_cream',400,'ml'],['egg_white',3,'pc'],['sugar',180,'g'],['powdered_sugar',40,'g'],['vanilla',1,'pc'],['lemon',1,'pc']],
  s:{fr:["Montez les blancs en neige et serrez-les avec le sucre versé en pluie, jusqu'à ce que la meringue soit lisse et brillante.","Cuisez-la 90 minutes à 100 °C, puis laissez-la sécher dans le four éteint, porte entrouverte : elle doit être cassante à cœur.","Écrasez un tiers des fraises en purée avec un peu de sucre glace et le jus de citron, et coupez les autres en morceaux.","Fouettez la crème sans la serrer : elle doit rester souple, une crème ferme rendrait le dessert lourd.","Brisez la meringue à la main en morceaux inégaux et mêlez le tout d'un geste, à peine. Servez dans les dix minutes, sinon la meringue fond."],
     en:["Whisk the whites to peaks and firm them with the sugar rained in, until the meringue is smooth and glossy.","Bake it 90 minutes at 100°C, then let it dry in the switched-off oven with the door ajar: it must be brittle right through.","Crush a third of the strawberries to a purée with a little icing sugar and the lemon juice, and cut the rest into pieces.","Whip the cream without tightening it: it must stay soft, a stiff cream would make the pudding heavy.","Break the meringue by hand into uneven pieces and fold everything once, barely. Serve within ten minutes, or the meringue dissolves."]} },

{ id:'eccles-cake', c:'eu', lat:53.483, lon:-2.334, base:12, prep:50, cook:20, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#4f3a2a','#f2dfa8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Eccles cake',en:'Eccles cake'},
  p:{fr:'Eccles, Grand Manchester, Angleterre',en:'Eccles, Greater Manchester, England'},
  d:{fr:"Un petit chausson de pâte feuilletée bourré de raisins de Corinthe, si serré que le fruit transparaît. On les surnomme dead fly pies ; les puritains les interdirent au XVIIᵉ siècle comme trop liés aux fêtes religieuses, ce qui n'a fait que les rendre plus populaires.",
     en:"A small puff-pastry parcel packed with currants, so tightly that the fruit shows through. They are nicknamed dead fly pies; the Puritans banned them in the 17th century as too tied to religious feasts, which only made them more popular."},
  i:[['puff_pastry',500,'g'],['currants',300,'g'],['butter',60,'g'],['brown_sugar',80,'g'],['orange_zest',50,'g'],['nutmeg',1,'tsp'],['allspice',0.5,'tsp'],['egg_white',1,'pc'],['sugar',40,'g']],
  s:{fr:["Faites fondre le beurre avec la cassonade, ajoutez les raisins, l'écorce d'orange et les épices, et laissez refroidir complètement.","Une garniture tiède ferait fondre le feuilletage à l'assemblage : c'est la seule règle absolue de la recette.","Découpez des disques de 10 cm, déposez une bonne cuillerée au centre et ramenez les bords vers le milieu comme une bourse.","Retournez le chausson soudure dessous et aplatissez-le doucement à la main jusqu'à voir les raisins par transparence.","Entaillez trois fois le dessus, badigeonnez de blanc d'œuf, sucrez et cuisez 20 minutes à 200 °C."],
     en:["Melt the butter with the brown sugar, add the currants, orange peel and spices, and cool completely.","A warm filling would melt the pastry as you assemble: that is the one absolute rule of the recipe.","Cut 10 cm discs, set a good spoonful in the centre and gather the edges to the middle like a purse.","Turn the parcel seam down and flatten it gently by hand until the currants show through.","Cut three slashes on top, brush with egg white, dust with sugar and bake 20 minutes at 200°C."]} },

{ id:'trifle', c:'eu', lat:51.455, lon:-2.588, base:8, prep:60, cook:15, diff:2, tags:['sweet','festive','fruit'],
  art:{v:'glass',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#e8c46a','#c9402c','#f4f0e6','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Trifle',en:'Trifle'},
  p:{fr:'Bristol, Angleterre',en:'Bristol, England'},
  d:{fr:"Un dessert monté en couches dans un saladier de verre : biscuit imbibé de xérès, fruits, crème anglaise et crème fouettée. La première recette avec des biscuits date de 1751 ; auparavant le trifle n'était qu'une crème parfumée, et c'est le xérès qui a tout changé.",
     en:"A pudding built in layers in a glass bowl: sponge soaked in sherry, fruit, custard and whipped cream. The first recipe with sponge dates from 1751; before that a trifle was merely a flavoured cream, and it was the sherry that changed everything."},
  i:[['sponge_cake',300,'g'],['sherry',150,'ml'],['raspberries',400,'g'],['strawberries',300,'g'],['whole_milk',500,'ml'],['egg_yolk',6,'pc'],['sugar',120,'g'],['cornstarch',30,'g'],['vanilla',1,'pc'],['heavy_cream',400,'ml'],['almonds',60,'g']],
  s:{fr:["Faites une crème anglaise épaissie à la fécule, et couvrez-la au contact pour qu'elle ne peau pas en refroidissant.","Tapissez le fond du saladier de biscuit et arrosez-le de xérès : il doit être imbibé mais non détrempé, sinon la couche s'affaisse.","Couvrez de fruits écrasés grossièrement avec un peu de sucre, sans les réduire en coulis.","Versez la crème anglaise complètement froide : tiède, elle se mêlerait aux couches et le trifle perdrait ses bandes nettes.","Terminez par la crème fouettée et les amandes grillées, et laissez prendre 6 heures au froid avant de servir à la cuillère, en plongeant jusqu'au fond."],
     en:["Make a custard thickened with cornstarch, and cover it in contact so it does not skin as it cools.","Line the base of the bowl with sponge and douse it with sherry: it must be soaked but not sodden, or the layer collapses.","Cover with roughly crushed fruit and a little sugar, without reducing it to a coulis.","Pour on the completely cold custard: warm, it would bleed into the layers and the trifle would lose its clean bands.","Finish with whipped cream and toasted almonds, and set for 6 hours in the cold before serving with a spoon, digging right to the bottom."]} },

{ id:'spotted-dick', c:'eu', lat:52.205, lon:0.121, base:6, prep:30, cook:120, diff:2, tags:['sweet','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'cake',food:['#f2dfa8','#4f3a2a','#e8c46a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Spotted dick',en:'Spotted dick'},
  p:{fr:'Cambridge, Angleterre',en:'Cambridge, England'},
  d:{fr:"Un pudding de suif aux raisins secs, cuit à la vapeur dans un linge et servi noyé de crème anglaise. Les taches sont les raisins ; quant à dick, le mot viendrait de dough, la pâte, prononcée à la mode du Nord — l'étymologie n'est pas tranchée et fait rire depuis deux siècles.",
     en:"A suet pudding studded with currants, steamed in a cloth and served drowned in custard. The spots are the fruit; as for dick, the word is said to come from dough said in a northern accent — the etymology is unsettled and has raised laughs for two centuries."},
  i:[['flour',250,'g'],['beef_suet',125,'g'],['currants',200,'g'],['sugar',80,'g'],['whole_milk',650,'ml'],['lemon_zest',1,'pc'],['baking_powder',2,'tsp'],['egg_yolk',5,'pc'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Mêlez à sec la farine, le suif râpé, le sucre, la levure, le sel et le zeste, puis ajoutez les raisins.","Versez le lait et rassemblez la pâte sans la travailler : un pudding trop pétri devient élastique et lourd.","Roulez-la en boudin dans un papier sulfurisé beurré puis dans un linge, en ménageant un pli au milieu — le pudding gonfle d'un bon tiers.","Ficelez les deux bouts et le centre, et faites cuire 2 heures à la vapeur, en rajoutant de l'eau bouillante et jamais froide.","Démoulez, tranchez épais et servez sous une crème anglaise chaude et fluide."],
     en:["Combine the flour, grated suet, sugar, baking powder, salt and zest, then add the currants.","Pour in the milk and bring the dough together without working it: an overworked pudding turns rubbery and heavy.","Roll it into a cylinder in buttered greaseproof paper then in a cloth, leaving a pleat down the middle — the pudding swells by a good third.","Tie both ends and the centre, and steam for 2 hours, topping up with boiling water and never cold.","Turn out, cut thick slices and serve under a hot, pourable custard."]} },

{ id:'scotch-pie', c:'eu', lat:55.953, lon:-3.189, base:8, prep:70, cook:50, diff:2, tags:['lamb','bake','street'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#c9924a','#8f5a3a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Scotch pie',en:'Scotch pie'},
  p:{fr:'Édimbourg, Écosse',en:'Edinburgh, Scotland'},
  d:{fr:"Une petite tourte de mouton haché à la pâte à l'eau chaude, aux bords droits qui dépassent du couvercle enfoncé. Ce rebord n'est pas un ornement : creux, il reçoit la purée, les haricots ou la sauce, et c'est ce qui permet de la manger debout dans un stade.",
     en:"A small mutton pie in hot water crust, with straight walls standing proud of a sunken lid. That rim is no ornament: hollow, it holds the mash, beans or gravy, which is what makes it edible standing up in a football ground."},
  i:[['flour',450,'g'],['lard',150,'g'],['water',180,'ml'],['ground_lamb',600,'g'],['onion',1,'pc'],['beef_broth',150,'ml'],['nutmeg',1,'tsp'],['white_pepper',2,'tsp'],['breadcrumbs',60,'g'],['mace',0.5,'tsp'],['salt',null,'']],
  s:{fr:["Portez l'eau et le saindoux à ébullition et versez-les d'un coup sur la farine salée ; travaillez à la cuillère puis à la main dès que possible.","Montez la pâte tiède autour d'un verre fariné, en parois droites qui dépassent de 1,5 cm : refroidie, elle casse au lieu de se former.","Mêlez le mouton haché à la chapelure, à l'oignon râpé, au bouillon, à la muscade, au macis et à beaucoup de poivre blanc.","Le poivre blanc et le macis sont ce qui distingue une scotch pie d'une tourte anglaise : ne les remplacez pas par du poivre noir.","Emplissez, posez un couvercle enfoncé de 1 cm, percez-le au centre et cuisez 45 minutes à 190 °C."],
     en:["Boil the water and lard and pour them at once onto the salted flour; work with a spoon then by hand as soon as you can.","Raise the warm dough around a floured glass, with straight walls standing 1.5 cm proud: once cold it cracks instead of shaping.","Mix the minced mutton with breadcrumbs, grated onion, broth, nutmeg, mace and plenty of white pepper.","White pepper and mace are what separate a Scotch pie from an English one: do not swap them for black pepper.","Fill, set a lid sunk 1 cm below the rim, pierce it in the centre and bake 45 minutes at 190°C."]} },

{ id:'shortbread-ecossais', c:'eu', lat:56.462, lon:-2.970, base:12, prep:30, cook:45, diff:1, tags:['sweet','bake','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f2dfa8','#e8dcb8','#f0e8d0','#e0b45a'],garnish:'#c9754a'},
  n:{fr:'Shortbread',en:'Shortbread'},
  p:{fr:'Dundee, Écosse',en:'Dundee, Scotland'},
  d:{fr:"Trois ingrédients dans la proportion un-deux-trois : une part de sucre, deux de beurre, trois de farine. Marie Stuart en raffolait, dit-on ; les pétales du moule rond rappellent les jupes des Douze Apôtres, et le biscuit vient du pain de la veille séché au four.",
     en:"Three ingredients in the proportion one-two-three: one part sugar, two butter, three flour. Mary Stuart is said to have loved it; the petals of the round mould recall the Twelve Apostles' skirts, and the biscuit descends from yesterday's bread dried in the oven."},
  i:[['flour',300,'g'],['rice_flour',60,'g'],['butter',250,'g'],['sugar',125,'g'],['salt',null,'']],
  s:{fr:["Travaillez le beurre froid et le sucre du bout des doigts, sans les crémer : un beurre monté ferait lever le biscuit, ce qu'on ne veut pas.","Ajoutez les farines et le sel et rassemblez la pâte en quelques gestes seulement — plus on la travaille, plus elle durcit.","La farine de riz n'est pas facultative : c'est elle qui donne le grain sableux qui craque sous la dent.","Tassez la pâte à 1,5 cm dans un moule, piquez-la à la fourchette et réfrigérez 30 minutes.","Cuisez 45 minutes à 150 °C : le shortbread doit rester pâle, à peine blond aux bords. Sucrez et découpez à la sortie, tant qu'il est souple."],
     en:["Rub the cold butter and sugar together with your fingertips, without creaming: aerated butter would make the biscuit rise, which is not wanted.","Add the flours and salt and bring the dough together in only a few movements — the more it is worked, the harder it sets.","The rice flour is not optional: it is what gives the sandy grain that snaps under the tooth.","Press the dough 1.5 cm thick into a tin, prick it with a fork and chill for 30 minutes.","Bake 45 minutes at 150°C: shortbread must stay pale, barely golden at the edges. Sugar and cut it as it comes out, while still soft."]} },

{ id:'stornoway-black-pudding', c:'eu', lat:58.209, lon:-6.389, base:6, prep:60, cook:90, diff:3, tags:['pork','slow','breakfast'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'grill',food:['#3a2a2a','#c9924a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Boudin de Stornoway',en:'Stornoway black pudding'},
  p:{fr:'Stornoway, Île de Lewis, Écosse',en:'Stornoway, Isle of Lewis, Scotland'},
  d:{fr:"Un boudin des Hébrides à l'avoine grossière et à la graisse de bœuf, protégé par une indication géographique depuis 2013. Il se distingue par sa proportion d'avoine, plus élevée qu'ailleurs, qui lui donne une texture friable plutôt que fondante.",
     en:"A Hebridean pudding with coarse oatmeal and beef suet, protected by a geographical indication since 2013. It stands apart for its higher proportion of oatmeal, which gives it a crumbly rather than a yielding texture."},
  i:[['pork_blood',1,'l'],['oatmeal',400,'g'],['beef_suet',400,'g'],['onion',400,'g'],['sausage_casings',null,''],['white_pepper',2,'tbsp'],['allspice',1,'tsp'],['coarse_salt',30,'g'],['butter',40,'g']],
  s:{fr:["Fouettez le sang dès la collecte avec un peu de sel pour l'empêcher de coaguler, puis passez-le au tamis fin.","Hachez l'oignon très finement et le suif en petits dés — de gros morceaux fondraient et laisseraient des trous.","Mêlez le tout à l'avoine grossière, salez, poivrez au poivre blanc et laissez gonfler 30 minutes : l'avoine boit une partie du sang.","Embossez sans serrer, à moitié seulement, car l'avoine gonfle encore à la cuisson et ferait éclater le boyau.","Pochez 1 h 30 à 80 °C, sans jamais bouillir, en piquant à l'aiguille au bout de 10 minutes. Se tranche épais et se poêle au beurre."],
     en:["Whisk the blood as soon as it is collected with a little salt to stop it setting, then pass it through a fine sieve.","Chop the onion very finely and dice the suet small — large pieces would melt away and leave holes.","Mix everything with the coarse oatmeal, salt, add white pepper and let it swell for 30 minutes: the oatmeal drinks part of the blood.","Fill the casings loosely, only half full, because the oatmeal swells further in cooking and would burst the skin.","Poach 1½ hours at 80°C, never boiling, pricking with a needle after 10 minutes. Cut thick and fry in butter."]} },

{ id:'stovies', c:'eu', lat:57.149, lon:-2.099, base:4, prep:20, cook:70, diff:1, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#e0b45a','#8f5a3a','#f2dfa8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Stovies',en:'Stovies'},
  p:{fr:'Aberdeen, Écosse',en:'Aberdeen, Scotland'},
  d:{fr:"Des pommes de terre étuvées lentement dans la graisse et le jus du rôti de la veille, jusqu'à ce qu'elles se défassent à moitié. Le mot vient du français étuver : c'est le plat du lundi, et chaque famille écossaise soutient que le sien est le seul vrai.",
     en:"Potatoes stewed slowly in the fat and juices of yesterday's roast, until half of them collapse. The word comes from the French étuver: it is the Monday dish, and every Scottish family maintains that theirs is the only true one."},
  i:[['potato',1.2,'kg'],['onion',400,'g'],['beef_dripping',80,'g'],['beef_chuck',400,'g'],['beef_broth',200,'ml'],['oatcakes',8,'pc'],['pickled_beets',200,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites fondre la graisse de rôti et faites-y blondir l'oignon en lamelles épaisses, 15 minutes.","Coupez les pommes de terre en morceaux inégaux : les petits se déferont en purée, les gros tiendront, et c'est ce mélange qu'on cherche.","Ajoutez-les avec la viande de la veille en dés, salez, poivrez, et versez juste un fond de bouillon.","Couvrez et laissez étuver 1 heure à feu très doux, sans remuer plus de deux fois : les stovies cuisent à la vapeur, elles ne bouillent pas.","Elles sont prêtes quand une croûte dorée se forme au fond. Servez avec des oatcakes et de la betterave au vinaigre."],
     en:["Melt the dripping and soften the thickly sliced onion in it for 15 minutes.","Cut the potatoes into uneven pieces: the small ones will collapse into purée, the large ones hold, and that mixture is what you want.","Add them with yesterday's meat, diced, season, and pour in only a shallow layer of broth.","Cover and stew for an hour over very low heat, stirring no more than twice: stovies steam, they do not boil.","They are ready when a golden crust forms on the base. Serve with oatcakes and pickled beetroot."]} },

{ id:'arbroath-smokie', c:'eu', lat:56.561, lon:-2.586, base:4, prep:40, cook:60, diff:3, tags:['sea','slow','fresh'],
  art:{v:'board',bg:'#26384a',plate:'#f4ecd8',style:'fish',food:['#c9924a','#8f6a4a','#f0e8d0','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Arbroath smokie',en:'Arbroath smokie'},
  p:{fr:'Arbroath, Angus, Écosse',en:'Arbroath, Angus, Scotland'},
  d:{fr:"Des églefins salés, liés par la queue et fumés à chaud dans un tonneau enterré couvert de toile de jute. L'appellation est protégée en Europe : seul un fumage dans un rayon de huit kilomètres autour d'Arbroath peut porter le nom.",
     en:"Haddock salted, tied in pairs by the tail and hot-smoked in a buried barrel covered with hessian. The name is protected across Europe: only smoking within eight kilometres of Arbroath may carry it."},
  i:[['smoked_haddock',4,'pc'],['coarse_salt',200,'g'],['butter',100,'g'],['heavy_cream',150,'ml'],['lemon',2,'pc'],['potato',800,'g'],['spring_onion',4,'pc'],['bread',300,'g'],['pepper',null,'']],
  s:{fr:["Videz et étêtez les églefins mais gardez-les entiers, en laissant la queue attachée.","Salez-les à sec 2 heures seulement : un salage long donnerait un poisson dur et le smokie doit rester moelleux.","Rincez, séchez une nuit au frais jusqu'à ce que la peau soit sèche au toucher — sans ce croûtage, la fumée n'accroche pas.","Liez-les par paires à la queue, suspendez-les au-dessus d'un feu de hêtre dans un tonneau couvert, et fumez à chaud 45 minutes : la chair doit cuire en même temps qu'elle fume.","Servez tiède, ouvert d'un coup de pouce le long de l'arête, avec du beurre, du citron et du pain. Il n'y a rien d'autre à faire."],
     en:["Gut and behead the haddock but keep them whole, leaving the tails joined.","Dry-salt them for only 2 hours: long salting would give a hard fish, and a smokie must stay tender.","Rinse and dry overnight in the cold until the skin is dry to the touch — without that pellicle the smoke will not take.","Tie them in pairs by the tail, hang them over a beech fire in a covered barrel, and hot-smoke for 45 minutes: the flesh must cook as it smokes.","Serve warm, opened with a thumb along the backbone, with butter, lemon and bread. There is nothing else to do."]} },

{ id:'scottish-tablet', c:'eu', lat:56.116, lon:-3.937, base:24, prep:20, cook:30, diff:3, tags:['sweet','fast','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tablet écossais',en:'Scottish tablet'},
  p:{fr:'Stirling, Écosse',en:'Stirling, Scotland'},
  d:{fr:"Un sucre de lait qui craque sous la dent puis fond, plus friable qu'un fudge et plus tendre qu'un caramel dur. Toute la différence tient au battage : on remue la masse hors du feu jusqu'à ce qu'elle grène, pour obtenir des cristaux minuscules au lieu d'une pâte lisse.",
     en:"A milk sugar that snaps then melts, more crumbly than fudge and softer than hard toffee. The whole difference lies in the beating: the mass is stirred off the heat until it grains, producing minute crystals instead of a smooth paste."},
  i:[['sugar',900,'g'],['whole_milk',250,'ml'],['butter',120,'g'],['condensed_milk',200,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Faites fondre le beurre dans le lait, ajoutez le sucre et remuez jusqu'à dissolution complète avant toute ébullition — un grain de sucre non fondu fait cristalliser tout le reste.","Portez à ébullition et cuisez 20 minutes jusqu'à 118 °C, en essuyant les parois d'un pinceau mouillé.","Ajoutez le lait concentré et poursuivez 5 minutes en remuant sans arrêt : le fond attache très vite.","Hors du feu, battez énergiquement à la cuillère de bois 8 minutes, jusqu'à ce que la masse épaississe, perde son brillant et fasse un bruit de sable.","Versez aussitôt dans un moule beurré et marquez les carrés à la lame au bout de 10 minutes, avant durcissement complet."],
     en:["Melt the butter in the milk, add the sugar and stir until fully dissolved before it boils — one undissolved grain crystallises the lot.","Bring to the boil and cook 20 minutes to 118°C, washing the sides down with a wet brush.","Add the condensed milk and continue 5 minutes, stirring constantly: the base catches very quickly.","Off the heat, beat hard with a wooden spoon for 8 minutes, until the mass thickens, loses its shine and sounds like sand.","Pour at once into a buttered tin and score the squares with a blade after 10 minutes, before it sets hard."]} },

{ id:'clootie-dumpling', c:'eu', lat:57.478, lon:-4.224, base:10, prep:40, cook:240, diff:3, tags:['sweet','slow','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ead4',style:'cake',food:['#6f4a2a','#8f5a3a','#e8dcb8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Clootie dumpling',en:'Clootie dumpling'},
  p:{fr:'Inverness, Écosse',en:'Inverness, Scotland'},
  d:{fr:"Un pudding aux fruits secs bouilli quatre heures dans un linge — le cloot — qui lui donne une peau brune caractéristique. Autrefois on y cachait une pièce et un dé à coudre pour dire l'avenir des enfants ; on le mange chaud à Noël, et froid, tranché et frit, au petit-déjeuner.",
     en:"A dried-fruit pudding boiled for four hours in a cloth — the cloot — which gives it its characteristic brown skin. A coin and a thimble were once hidden in it to tell the children's fortunes; it is eaten hot at Christmas, and cold, sliced and fried, for breakfast."},
  i:[['flour',350,'g'],['beef_suet',175,'g'],['currants',200,'g'],['sultanas',200,'g'],['brown_sugar',150,'g'],['black_treacle',2,'tbsp'],['cinnamon',2,'tsp'],['ginger',1,'tsp'],['baking_soda',1,'tsp'],['buttermilk',200,'ml'],['egg',1,'pc'],['salt',null,'']],
  s:{fr:["Ébouillantez le linge, essorez-le et farinez-le généreusement : c'est cette farine qui, en cuisant, formera la peau du pudding.","Mêlez tous les ingrédients secs, ajoutez le suif râpé, les fruits, la mélasse, l'œuf et le babeurre pour une pâte souple.","Déposez-la au centre du linge, refermez en aumônière en laissant du jeu, et ficelez : le pudding gonfle d'un quart.","Faites bouillir 4 heures dans une grande marmite, sur une soucoupe retournée pour que le linge ne touche pas le fond, en rajoutant de l'eau bouillante.","Démoulez et faites sécher 20 minutes au four à 150 °C pour raffermir la peau. Servez avec de la crème anglaise."],
     en:["Scald the cloth, wring it out and flour it generously: that flour is what will form the pudding's skin as it cooks.","Mix all the dry ingredients, add the grated suet, the fruit, treacle, egg and buttermilk for a soft batter.","Set it in the centre of the cloth, gather it into a purse leaving slack, and tie: the pudding swells by a quarter.","Boil for 4 hours in a large pot, on an upturned saucer so the cloth does not touch the base, topping up with boiling water.","Turn out and dry for 20 minutes in a 150°C oven to firm the skin. Serve with custard."]} },

{ id:'rumbledethumps', c:'eu', lat:55.601, lon:-2.786, base:6, prep:30, cook:45, diff:1, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#e8dcb8','#7fae5a','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Rumbledethumps',en:'Rumbledethumps'},
  p:{fr:'Melrose, Scottish Borders, Écosse',en:'Melrose, Scottish Borders, Scotland'},
  d:{fr:"Un gratin de pommes de terre écrasées, de chou et d'oignon, couvert de cheddar. Le nom dit le geste : rumble, remuer, et thump, écraser — les Borders ont leur version de ce que l'Irlande appelle colcannon et l'Angleterre bubble and squeak.",
     en:"A gratin of mashed potato, cabbage and onion under cheddar. The name says the action: rumble, to stir, and thump, to bash — the Borders have their version of what Ireland calls colcannon and England bubble and squeak."},
  i:[['potato',1,'kg'],['green_cabbage',600,'g'],['onion',2,'pc'],['butter',120,'g'],['cheddar_cheese',150,'g'],['chives',3,'tbsp'],['whole_milk',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez les pommes de terre en robe des champs, pelez-les chaudes et écrasez-les à la fourchette, grossièrement.","Faites revenir le chou finement émincé et l'oignon au beurre 12 minutes : ils doivent rester croquants, un chou bouilli rendrait de l'eau dans le gratin.","Mêlez le tout avec le beurre restant, le lait, la ciboulette, du sel et beaucoup de poivre, sans chercher la finesse.","Versez dans un plat beurré, égalisez à la fourchette en laissant des reliefs — ce sont eux qui gratineront.","Couvrez de cheddar râpé et enfournez 30 minutes à 190 °C, jusqu'à ce que le dessus soit brun et boursouflé."],
     en:["Boil the potatoes in their skins, peel them hot and crush them roughly with a fork.","Fry the finely shredded cabbage and onion in butter for 12 minutes: they must stay crisp, boiled cabbage would weep into the gratin.","Combine everything with the remaining butter, the milk, chives, salt and plenty of pepper, without aiming for smoothness.","Turn into a buttered dish and rough up the surface with a fork, leaving peaks — they are what will brown.","Cover with grated cheddar and bake 30 minutes at 190°C, until the top is brown and blistered."]} },

{ id:'aberdeen-rowie', c:'eu', lat:57.144, lon:-2.098, base:12, prep:180, cook:20, diff:3, tags:['bread','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Rowie d’Aberdeen',en:'Aberdeen rowie'},
  p:{fr:'Aberdeen, Écosse',en:'Aberdeen, Scotland'},
  d:{fr:"Un petit pain feuilleté au saindoux, plat, salé et gras, cousin brutal du croissant. Il fut conçu pour les pêcheurs de la mer du Nord : sa teneur en graisse et en sel le conserve des semaines en mer sans qu'il rancisse ni sèche.",
     en:"A flat, salty, greasy lard-laminated roll, the croissant's brutal cousin. It was devised for North Sea fishermen: its fat and salt content keeps it for weeks at sea without going rancid or stale."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['warm_water',300,'ml'],['lard',180,'g'],['butter',120,'g'],['sugar',20,'g'],['coarse_salt',12,'g']],
  s:{fr:["Pétrissez une pâte à pain simple avec la farine, la levure, l'eau, le sucre et le sel, et laissez-la lever 1 heure.","Travaillez ensemble le saindoux et le beurre en pommade, et divisez-les en trois parts.","Étalez la pâte, parsemez-la d'un tiers du corps gras en petites noisettes, pliez en trois et laissez reposer 40 minutes au froid.","Répétez deux fois : le rowie ne se fait pas d'un beurre en plaque comme un croissant, mais de graisse déposée par touches, ce qui donne son feuilletage irrégulier.","Découpez des carrés, aplatissez-les à la main sans les rouler, laissez pousser 45 minutes et cuisez 20 minutes à 200 °C. Ils doivent nager dans leur propre graisse à mi-cuisson."],
     en:["Knead a plain bread dough with the flour, yeast, water, sugar and salt, and prove it for an hour.","Cream the lard and butter together and divide into three parts.","Roll out the dough, dot it with a third of the fat in small nuggets, fold in three and rest 40 minutes in the cold.","Repeat twice: a rowie is not laminated with a sheet of butter like a croissant, but with fat dabbed on, which gives its irregular flaking.","Cut squares, flatten them by hand without rolling, prove 45 minutes and bake 20 minutes at 200°C. They should be swimming in their own fat halfway through."]} },

{ id:'glamorgan-sausage', c:'eu', lat:51.481, lon:-3.179, base:4, prep:30, cook:15, diff:1, tags:['cheese','veg','fry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'roll',food:['#e0b45a','#f2dfa8','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Saucisse du Glamorgan',en:'Glamorgan sausage'},
  p:{fr:'Cardiff, pays de Galles',en:'Cardiff, Wales'},
  d:{fr:"Une saucisse sans viande, faite de caerphilly, de poireau et de chapelure, panée et frite. Elle est attestée dès 1850, bien avant que le végétarisme ne devienne une idée : c'était simplement la saucisse des jours où l'on n'avait pas de cochon.",
     en:"A meatless sausage of Caerphilly cheese, leek and breadcrumbs, crumbed and fried. It is recorded from 1850, long before vegetarianism was an idea: it was simply the sausage for days when there was no pig."},
  i:[['caerphilly_cheese',200,'g'],['breadcrumbs',200,'g'],['leek',2,'pc'],['egg',3,'pc'],['dijon_mustard',1,'tbsp'],['parsley',3,'tbsp'],['thyme',2,'sprig'],['whole_milk',40,'ml'],['sunflower_oil',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Émincez le poireau très finement et faites-le suer 8 minutes sans coloration, puis laissez-le refroidir complètement.","Mêlez-le au fromage râpé, à 150 g de chapelure, aux herbes, à la moutarde, à deux jaunes d'œufs et au lait.","Salez peu : le caerphilly l'est déjà, et une saucisse trop salée ne se rattrape pas.","Façonnez des boudins de la taille d'un doigt et réfrigérez-les 1 heure — tièdes, ils se défont dans la poêle.","Passez-les au blanc d'œuf battu puis dans le reste de chapelure, et faites-les dorer 8 minutes à l'huile en les tournant sur toutes les faces."],
     en:["Slice the leek very finely and sweat it for 8 minutes without colour, then cool it completely.","Mix it with the grated cheese, 150 g of the breadcrumbs, the herbs, mustard, two egg yolks and the milk.","Salt lightly: Caerphilly already is, and an oversalted sausage cannot be rescued.","Shape finger-sized rolls and chill them for an hour — warm, they collapse in the pan.","Dip them in beaten egg white then in the remaining crumbs, and fry 8 minutes in oil, turning on every side."]} },

{ id:'welsh-cakes', c:'eu', lat:51.649, lon:-3.393, base:12, prep:30, cook:20, diff:1, tags:['sweet','fast','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#4f3a2a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Welsh cakes',en:'Welsh cakes'},
  p:{fr:'Pontypridd, pays de Galles',en:'Pontypridd, Wales'},
  d:{fr:"Des galettes aux raisins cuites sur une plaque de fonte, ni au four ni à la poêle. Les femmes de mineurs en glissaient dans les boîtes-repas : elles se mangent froides, tiennent une journée au fond d'une poche, et se cuisent sans four — ce qui comptait dans les corons.",
     en:"Currant cakes cooked on a cast-iron bakestone, neither baked nor fried. Miners' wives slipped them into lunch tins: they are eaten cold, survive a day in a pocket, and need no oven — which mattered in the terraces."},
  i:[['flour',300,'g'],['butter',150,'g'],['sugar',110,'g'],['currants',100,'g'],['egg',1,'pc'],['whole_milk',40,'ml'],['baking_powder',1,'tsp'],['nutmeg',0.5,'tsp'],['salt',null,'']],
  s:{fr:["Sablez le beurre froid dans la farine, la levure, le sel et la muscade, jusqu'à obtenir une semoule grossière.","Ajoutez le sucre et les raisins, puis l'œuf et juste assez de lait pour rassembler la pâte.","Abaissez à 8 mm et découpez des ronds de 6 cm : plus épais, le cœur reste cru ; plus fin, la galette sèche.","Chauffez une plaque de fonte sans matière grasse et faites cuire 3 minutes par face à feu moyen-doux.","Elles doivent être brun clair et encore souples au centre. Sucrez-les tièdes et laissez-les refroidir sur une grille."],
     en:["Rub the cold butter into the flour, baking powder, salt and nutmeg, to coarse crumbs.","Add the sugar and currants, then the egg and just enough milk to bring the dough together.","Roll to 8 mm and cut 6 cm rounds: thicker, the centre stays raw; thinner, the cake dries out.","Heat a cast-iron bakestone with no fat and cook 3 minutes a side over medium-low heat.","They should be light brown and still soft in the middle. Sugar them warm and cool on a rack."]} },

{ id:'faggots-gallois', c:'eu', lat:51.774, lon:-3.221, base:4, prep:40, cook:60, diff:2, tags:['pork','comfort','bake'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'stew',food:['#6f4a2a','#8f5a3a','#f4f0e6','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Faggots',en:'Faggots'},
  p:{fr:'Merthyr Tydfil, pays de Galles',en:'Merthyr Tydfil, Wales'},
  d:{fr:"Des boulettes de foie et de poitrine de porc enveloppées de crépine, cuites au four dans leur jus. Le plat des vallées minières galloises : la crépine fond entièrement et n'est là que pour tenir la boulette pendant la première demi-heure.",
     en:"Balls of pork liver and belly wrapped in caul fat, baked in their own gravy. The dish of the Welsh mining valleys: the caul melts away entirely and is there only to hold the ball together for the first half hour."},
  i:[['pork_liver',400,'g'],['pork_belly',400,'g'],['onion',2,'pc'],['breadcrumbs',150,'g'],['pig_caul',200,'g'],['sage',3,'tbsp'],['mace',0.5,'tsp'],['beef_broth',400,'ml'],['flour',2,'tbsp'],['peas',400,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper la crépine 20 minutes à l'eau tiède vinaigrée pour la détendre : sèche, elle se déchire au moindre geste.","Hachez le foie et la poitrine ensemble, ni trop fin ni trop gros, et mêlez-les à l'oignon suée, à la chapelure, à la sauge et au macis.","Formez des boulettes de la taille d'une balle de tennis et enveloppez chacune d'un carré de crépine, en repliant dessous.","Rangez-les serrées dans un plat — elles se soutiennent mutuellement — et enfournez 20 minutes à 200 °C pour les colorer.","Versez le bouillon lié à la farine, baissez à 170 °C et laissez 40 minutes de plus. Servez avec des petits pois écrasés."],
     en:["Soak the caul for 20 minutes in warm vinegared water to relax it: dry, it tears at the slightest handling.","Chop the liver and belly together, neither too fine nor too coarse, and mix with the sweated onion, breadcrumbs, sage and mace.","Shape balls the size of a tennis ball and wrap each in a square of caul, tucking it underneath.","Pack them tightly in a dish — they hold each other up — and bake 20 minutes at 200°C to colour them.","Pour over the flour-thickened broth, drop to 170°C and give them 40 minutes more. Serve with mushy peas."]} },

{ id:'teisen-lap', c:'eu', lat:51.585, lon:-3.766, base:8, prep:25, cook:35, diff:1, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#4f3a2a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Teisen lap',en:'Teisen lap'},
  p:{fr:'Aberdare, pays de Galles',en:'Aberdare, Wales'},
  d:{fr:"Un gâteau plat aux raisins de Corinthe, humide et dense, cuit dans une assiette plutôt que dans un moule. Teisen lap veut dire gâteau de la main : plat, il tenait dans la main du mineur et dans sa boîte, et sa faible hauteur l'empêchait de s'écraser.",
     en:"A flat, moist, dense currant cake baked on a plate rather than in a tin. Teisen lap means hand cake: flat, it fitted in a miner's hand and his tin, and its shallowness kept it from being crushed."},
  i:[['flour',225,'g'],['butter',110,'g'],['sugar',110,'g'],['currants',150,'g'],['egg',2,'pc'],['whole_milk',150,'ml'],['baking_powder',2,'tsp'],['nutmeg',1,'tsp'],['salt',null,'']],
  s:{fr:["Sablez le beurre dans la farine, la levure, le sel et la muscade, puis ajoutez le sucre et les raisins.","Battez les œufs avec le lait et versez-les d'un coup : la pâte doit être nettement plus liquide qu'une pâte à cake, presque coulante.","C'est cette humidité qui fait le teisen lap : trop ferme, il devient un simple gâteau aux raisins et sèche en un jour.","Versez dans une assiette à tarte beurrée sur 3 cm d'épaisseur seulement, et lissez le dessus.","Cuisez 35 minutes à 180 °C jusqu'à ce que le dessus soit doré et le centre encore souple. Se mange tiède ou froid, sans rien."],
     en:["Rub the butter into the flour, baking powder, salt and nutmeg, then add the sugar and currants.","Beat the eggs with the milk and pour them in at once: the batter must be far looser than a cake batter, almost pourable.","That wetness is what makes a teisen lap: too firm and it becomes an ordinary fruit cake and dries out in a day.","Pour into a buttered pie plate, only 3 cm deep, and smooth the top.","Bake 35 minutes at 180°C until the top is golden and the centre still yielding. Eaten warm or cold, with nothing."]} },

{ id:'ulster-fry', c:'eu', lat:54.597, lon:-5.930, base:4, prep:25, cook:30, diff:2, tags:['pork','breakfast','fry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#c9924a','#3a2a2a','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Ulster fry',en:'Ulster fry'},
  p:{fr:'Belfast, Irlande du Nord',en:'Belfast, Northern Ireland'},
  d:{fr:"Le petit-déjeuner frit de l'Ulster, qui se distingue du breakfast anglais par ses deux pains cuits sur la plaque : le soda farl et le potato bread. Pas de haricots, pas de champignons — la place est prise par les pains, et c'est ce qui en fait un plat d'Irlande du Nord.",
     en:"The Ulster fried breakfast, set apart from the English one by its two griddle breads: the soda farl and the potato bread. No beans, no mushrooms — the breads take their place, and that is what makes it Northern Irish."},
  i:[['smoked_bacon',8,'slice'],['pork_sausage',8,'pc'],['blood_sausage',8,'slice'],['egg',4,'pc'],['potato',500,'g'],['flour',200,'g'],['buttermilk',250,'ml'],['baking_soda',1,'tsp'],['butter',100,'g'],['ripe_tomato',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pour le potato bread, écrasez des pommes de terre chaudes avec 60 g de farine et du beurre fondu, abaissez à 1 cm et découpez des triangles.","Pour le soda farl, mêlez le reste de farine, le babeurre, le bicarbonate et le sel sans pétrir, aplatissez en disque et coupez-le en quatre.","Cuisez les deux pains sur une plaque sèche, 5 minutes par face : ils cuisent à la plaque et jamais au four, c'est là toute la différence.","Faites frire bacon, saucisses et boudin, et gardez la graisse rendue dans la poêle.","Faites revenir les pains dans cette graisse jusqu'à ce qu'ils croustillent, puis cuisez les œufs au plat et servez tout ensemble, sans attendre."],
     en:["For the potato bread, mash hot potatoes with 60 g of the flour and melted butter, roll to 1 cm and cut triangles.","For the soda farl, mix the remaining flour, buttermilk, bicarbonate and salt without kneading, flatten into a round and quarter it.","Cook both breads on a dry griddle, 5 minutes a side: they are griddled and never baked, and that is the whole difference.","Fry the bacon, sausages and black pudding, and keep the rendered fat in the pan.","Fry the breads in that fat until they crisp, then fry the eggs and serve everything together, without delay."]} },

{ id:'champ', c:'eu', lat:54.658, lon:-6.216, base:4, prep:20, cook:30, diff:1, tags:['veg','comfort','fast'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#7fae5a','#e8c46a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Champ',en:'Champ'},
  p:{fr:'Antrim, Irlande du Nord',en:'Antrim, Northern Ireland'},
  d:{fr:"Une purée à l'oignon vert et au lait, creusée d'un puits où fond une noix de beurre. On mange à la cuillère depuis l'extérieur en trempant chaque bouchée dans le beurre du centre ; à la différence du colcannon, il n'y entre ni chou ni chou frisé.",
     en:"Mashed potato with spring onion and milk, hollowed into a well where a knob of butter melts. You eat from the outside in, dipping each spoonful in the butter at the centre; unlike colcannon, no cabbage or kale goes in."},
  i:[['potato',1.2,'kg'],['spring_onion',10,'pc'],['whole_milk',300,'ml'],['butter',150,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez les pommes de terre entières avec leur peau, dans une eau largement salée.","Émincez les oignons verts, blanc et vert séparés, et faites-les infuser 10 minutes dans le lait chaud sans bouillir.","Cette infusion est tout le plat : jetés crus dans la purée, les oignons restent piquants et se détachent au lieu de la parfumer.","Pelez les pommes de terre brûlantes, passez-les au presse-purée et incorporez le lait infusé avec ses oignons, puis la moitié du beurre.","Dressez en dôme, creusez un puits au centre à la cuillère et déposez-y le beurre restant. Servez avant qu'il ne fonde complètement."],
     en:["Boil the potatoes whole in their skins, in generously salted water.","Slice the spring onions, whites and greens apart, and infuse them 10 minutes in hot milk without boiling.","That infusion is the whole dish: thrown in raw, the onions stay sharp and sit apart instead of scenting it.","Peel the potatoes scalding, rice them and beat in the infused milk with its onions, then half the butter.","Mound it up, hollow a well in the centre with a spoon and drop in the remaining butter. Serve before it melts away."]} },

{ id:'fifteens', c:'eu', lat:54.526, lon:-6.056, base:15, prep:25, cook:0, diff:1, tags:['sweet','fast','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#c9402c','#e8dcb8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Fifteens',en:'Fifteens'},
  p:{fr:'Lisburn, Irlande du Nord',en:'Lisburn, Northern Ireland'},
  d:{fr:"Un roulé sans cuisson dont la recette tient dans son nom : quinze biscuits digestive, quinze guimauves, quinze cerises confites. Le lait concentré lie le tout, la noix de coco l'enrobe, et l'on n'allume jamais le four.",
     en:"A no-bake roll whose recipe is its name: fifteen digestive biscuits, fifteen marshmallows, fifteen glacé cherries. Condensed milk binds it, coconut coats it, and the oven is never lit."},
  i:[['digestive_biscuits',15,'pc'],['marshmallows',15,'pc'],['glace_cherries',15,'pc'],['condensed_milk',200,'g'],['desiccated_coconut',100,'g']],
  s:{fr:["Écrasez les biscuits au rouleau, dans un sac, jusqu'à obtenir une chapelure grossière avec quelques éclats.","Coupez les guimauves et les cerises en quatre ; farinez le couteau de noix de coco pour que les guimauves n'y collent pas.","Mêlez le tout au lait concentré sucré : la masse doit être collante mais tenir en boule.","Roulez-la en boudin dans du film alimentaire, en serrant bien, puis roulez le boudin dans la noix de coco jusqu'à ce qu'il soit entièrement couvert.","Réfrigérez 4 heures au moins, puis coupez des tranches d'un centimètre avec un couteau essuyé entre chaque coupe."],
     en:["Crush the biscuits in a bag with a rolling pin, to coarse crumbs with a few larger shards.","Quarter the marshmallows and cherries; dust the knife with coconut so the marshmallows do not stick.","Mix everything with the condensed milk: the mass should be sticky but hold together in a ball.","Roll it into a log in cling film, tightly, then roll the log in coconut until entirely coated.","Chill at least 4 hours, then cut one-centimetre slices, wiping the knife between cuts."]} },

{ id:'yellowman', c:'eu', lat:55.204, lon:-6.253, base:20, prep:20, cook:20, diff:3, tags:['sweet','festive','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Yellowman',en:'Yellowman'},
  p:{fr:'Ballycastle, comté d’Antrim, Irlande du Nord',en:'Ballycastle, County Antrim, Northern Ireland'},
  d:{fr:"Un sucre d'orge alvéolé et cassant, vendu à la foire d'Ould Lammas de Ballycastle depuis 1606, où on le mange avec du dulse séché. Le bicarbonate jeté dans le sucre bouillant le fait mousser d'un coup : c'est ce sursaut qui donne les alvéoles.",
     en:"A brittle, honeycombed toffee sold at Ballycastle's Ould Lammas Fair since 1606, eaten there with dried dulse. Bicarbonate thrown into the boiling sugar makes it foam at once: that surge is what makes the honeycomb."},
  i:[['sugar',450,'g'],['golden_syrup',150,'g'],['butter',50,'g'],['white_vinegar',1,'tbsp'],['baking_soda',2,'tsp'],['water',60,'ml']],
  s:{fr:["Beurrez très largement un plat à bords hauts et tenez-le à portée de main : la suite ne laisse pas trois secondes.","Faites fondre le beurre, le sirop, le sucre, l'eau et le vinaigre à feu doux, sans remuer une fois le sucre dissous.","Portez à 149 °C, au grand cassé : trop bas, le yellowman reste collant ; trop haut, il devient amer.","Hors du feu, jetez le bicarbonate d'un coup et fouettez deux secondes seulement — la masse triple instantanément et déborde si le récipient est trop petit.","Versez sans étaler et laissez refroidir sans y toucher : lisser ferait retomber les bulles. Cassez au marteau quand c'est froid."],
     en:["Butter a deep tray very generously and keep it within reach: what follows leaves you no more than three seconds.","Melt the butter, syrup, sugar, water and vinegar over low heat, without stirring once the sugar has dissolved.","Take it to 149°C, hard crack: lower and the yellowman stays tacky; higher and it turns bitter.","Off the heat, throw in the bicarbonate all at once and whisk for two seconds only — the mass triples instantly and overflows a small pan.","Pour without spreading and let it cool untouched: smoothing it would collapse the bubbles. Break it with a hammer when cold."]} },

{ id:'dublin-bay-prawns', c:'eu', lat:53.309, lon:-6.135, base:4, prep:20, cook:10, diff:2, tags:['sea','fast','festive'],
  art:{v:'plate',bg:'#26485c',plate:'#f4f0e6',style:'other',food:['#e07a6a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Langoustines de la baie de Dublin',en:'Dublin Bay prawns'},
  p:{fr:'Howth, Dublin, Irlande',en:'Howth, Dublin, Ireland'},
  d:{fr:"Des langoustines grillées sous un beurre d'ail et de persil, pêchées dans la vase de la mer d'Irlande. Le nom vient des chalutiers qui les rapportaient à Dublin ; ailleurs on les appelle scampi ou cigales, mais c'est le même Nephrops norvegicus.",
     en:"Langoustines grilled under garlic and parsley butter, dredged from the mud of the Irish Sea. The name comes from the trawlers that landed them at Dublin; elsewhere they are scampi, but it is the same Nephrops norvegicus."},
  i:[['langoustines',1.2,'kg'],['butter',200,'g'],['garlic',6,'clove'],['parsley',5,'tbsp'],['lemon',2,'pc'],['white_wine',60,'ml'],['cayenne',1,'pinch'],['bread',300,'g'],['salt',null,'']],
  s:{fr:["Achetez-les vivantes et cuisinez-les le jour même : la langoustine morte se dégrade en quelques heures et devient cotonneuse.","Fendez-les en deux dans la longueur, du côté du dos, et retirez le boyau noir d'un coup de pointe.","Travaillez le beurre en pommade avec l'ail pilé, le persil, le zeste de citron, une pointe de cayenne et le vin blanc.","Déposez-en une noisette dans chaque demi-langoustine et passez-les 5 minutes sous un gril brûlant, chair vers le haut.","Elles sont cuites dès que la chair devient opaque : une minute de trop et elle se contracte. Servez avec du pain et le beurre du plat."],
     en:["Buy them alive and cook them the same day: a dead langoustine degrades within hours and turns woolly.","Split them lengthwise along the back, and lift out the dark gut with a knife point.","Cream the butter with the crushed garlic, parsley, lemon zest, a pinch of cayenne and the white wine.","Set a hazelnut of it in each half and give them 5 minutes under a fierce grill, flesh upward.","They are done the moment the flesh turns opaque: a minute more and it shrinks. Serve with bread and the butter from the dish."]} },

{ id:'barmbrack', c:'eu', lat:53.343, lon:-6.267, base:10, prep:150, cook:50, diff:2, tags:['bread','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#8f6a4a','#4f3a2a','#e8dcb8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Barmbrack',en:'Barmbrack'},
  p:{fr:'Dublin, Irlande',en:'Dublin, Ireland'},
  d:{fr:"Un pain levé aux fruits macérés dans le thé, servi à Halloween avec des objets cachés dans la mie. Une bague annonçait un mariage dans l'année, un pois la pauvreté, un chiffon un mauvais parti : la coutume se pratique encore, avec la bague seule.",
     en:"A yeasted fruit loaf whose fruit is steeped in tea, served at Halloween with objects hidden in the crumb. A ring meant marriage within the year, a pea poverty, a rag a bad match: the custom survives, with the ring alone."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['sultanas',200,'g'],['raisins',150,'g'],['orange_zest',80,'g'],['black_tea',300,'ml'],['brown_sugar',120,'g'],['butter',60,'g'],['egg',1,'pc'],['allspice',1,'tsp'],['cinnamon',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites infuser un thé noir très fort et versez-le brûlant sur les fruits secs ; laissez-les gonfler toute une nuit.","Égouttez-les le lendemain en gardant le liquide, tiédissez-le et délayez-y la levure.","Pétrissez la farine, le sucre, les épices, le sel, le beurre et l'œuf avec ce thé levuré, 12 minutes.","Incorporez les fruits à la fin, en pliant : ajoutés trop tôt, leur sucre gênerait la levée.","Laissez lever 1 h 30, façonnez un pain rond, laissez pousser 45 minutes et cuisez 50 minutes à 180 °C. Se tranche fin et se beurre."],
     en:["Brew a very strong black tea and pour it scalding over the dried fruit; let it swell overnight.","Drain them the next day keeping the liquid, warm it and dissolve the yeast in it.","Knead the flour, sugar, spices, salt, butter and egg with that yeasted tea for 12 minutes.","Fold in the fruit at the end: added too early, its sugar would hinder the rise.","Prove 1½ hours, shape a round loaf, prove 45 minutes and bake 50 minutes at 180°C. Sliced thin and buttered."]} },

{ id:'drisheen', c:'eu', lat:51.898, lon:-8.476, base:4, prep:40, cook:60, diff:3, tags:['beef','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'other',food:['#4f3a3a','#f4f0e6','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Drisheen',en:'Drisheen'},
  p:{fr:'Cork, Irlande',en:'Cork, Ireland'},
  d:{fr:"Un boudin de Cork au sang de mouton et au lait, sans céréale, dont la texture tient du flan plutôt que de la charcuterie. Il se vendait au marché anglais de Cork servi à la tasse ; on le mange avec du tripe, et la chair reste presque blanche sous une peau grise.",
     en:"A Cork pudding of sheep's blood and milk, with no cereal, whose texture is nearer a custard than a sausage. It was sold by the cup at the English Market; it is eaten with tripe, and the flesh stays almost pale under a grey skin."},
  i:[['sheep_blood',600,'ml'],['whole_milk',400,'ml'],['tansy',1,'tbsp'],['sausage_casings',null,''],['butter',60,'g'],['tripe',400,'g'],['onion',2,'pc'],['flour',2,'tbsp'],['bread',300,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Fouettez le sang au sortir de la bête avec du sel et passez-le deux fois au tamis fin : la moindre fibre gâterait la texture lisse.","Mêlez-le au lait tiède dans la proportion d'un tiers, salez, poivrez et parfumez à la tanaisie.","Emboissez très lâche, ou versez simplement dans des ramequins : le drisheen n'a pas besoin de boyau, il prend seul.","Pochez 45 minutes à 75 °C — au-delà, le sang tranche irrémédiablement et rend son eau.","Laissez refroidir, tranchez épais et poêlez au beurre. À Cork on le sert avec des tripes mijotées au lait et à l'oignon."],
     en:["Whisk the blood as it comes with salt and pass it twice through a fine sieve: the least fibre would spoil the smooth set.","Mix it with warm milk at a ratio of one to two, season, and scent with tansy.","Fill the casings very loosely, or simply pour into ramekins: drisheen needs no skin, it sets by itself.","Poach 45 minutes at 75°C — any hotter and the blood splits irrecoverably and weeps.","Cool, cut thick slices and fry in butter. In Cork it is served with tripe stewed in milk and onion."]} },

{ id:'waterford-blaa', c:'eu', lat:52.259, lon:-7.110, base:12, prep:150, cook:20, diff:2, tags:['bread','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f4f0e6','#f2dfa8','#f0e8d0','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Blaa de Waterford',en:'Waterford blaa'},
  p:{fr:'Waterford, Irlande',en:'Waterford, Ireland'},
  d:{fr:"Un petit pain blanc très farine, à croûte molle et pâle, protégé par une indication géographique depuis 2013. Il serait né des huguenots français installés à Waterford au XVIIᵉ siècle ; le nom viendrait de blanc, et il se mange dans les quatre heures.",
     en:"A very floury white roll with a soft, pale crust, protected by a geographical indication since 2013. It is said to come from French Huguenots settled in Waterford in the 17th century; the name from blanc, and it is eaten within four hours."},
  i:[['flour',600,'g'],['fresh_yeast',20,'g'],['warm_water',380,'ml'],['butter',30,'g'],['sugar',10,'g'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte souple et assez humide 12 minutes, et laissez-la lever 1 h 30.","Divisez en pâtons de 80 g et façonnez-les sans serrer : le blaa doit rester lâche pour garder sa mie cotonneuse.","Rangez-les sur la plaque en les faisant se toucher presque : c'est ce contact qui empêche la croûte de se former sur les côtés.","Farinez-les généreusement au tamis, deux fois, avant et après la seconde pousse de 45 minutes.","Cuisez 18 minutes à 220 °C. Ils doivent rester blancs : un blaa doré n'est plus un blaa, et il se mange le jour même."],
     en:["Knead a soft, fairly wet dough for 12 minutes, and prove it for 1½ hours.","Divide into 80 g pieces and shape them loosely: a blaa must stay slack to keep its cottony crumb.","Set them on the tray almost touching: that contact is what stops a crust forming on the sides.","Dust them generously through a sieve, twice, before and after the second 45-minute prove.","Bake 18 minutes at 220°C. They must stay white: a browned blaa is no longer a blaa, and it is eaten the same day."]} },

{ id:'irish-apple-cake', c:'eu', lat:52.664, lon:-8.623, base:8, prep:30, cook:50, diff:1, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f2dfa8','#e8c46a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Gâteau irlandais aux pommes',en:'Irish apple cake'},
  p:{fr:'Limerick, Irlande',en:'Limerick, Ireland'},
  d:{fr:"Un gâteau dense aux pommes acides couvert d'un crumble, servi chaud avec une crème anglaise. Il se faisait autrefois dans une cocotte de fonte suspendue au-dessus du feu de tourbe, avec des braises posées sur le couvercle pour cuire le dessus.",
     en:"A dense cake of sharp apples under a crumble top, served hot with custard. It was once made in a cast-iron pot hung over the turf fire, with embers set on the lid to cook the top."},
  i:[['flour',300,'g'],['butter',180,'g'],['sugar',180,'g'],['egg',2,'pc'],['apple',5,'pc'],['whole_milk',480,'ml'],['baking_powder',2,'tsp'],['cinnamon',1,'tsp'],['cloves',3,'pc'],['egg_yolk',4,'pc'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Prélevez 80 g de farine, 60 g de beurre et 60 g de sucre et sablez-les du bout des doigts pour le crumble ; réservez au froid.","Crémez le reste du beurre et du sucre, ajoutez les œufs un à un, puis la farine, la levure, la cannelle et le lait.","Pelez les pommes et coupez-les en gros quartiers, jamais en lamelles : de gros morceaux gardent leur acidité au cœur du gâteau.","Incorporez-les à la pâte, versez dans un moule, couvrez du crumble et parsemez de sucre.","Cuisez 50 minutes à 180 °C. Servez chaud, sous une crème anglaise faite avec le lait, les jaunes et la vanille."],
     en:["Take 80 g of the flour, 60 g of the butter and 60 g of the sugar and rub them to crumbs for the topping; chill.","Cream the remaining butter and sugar, add the eggs one at a time, then the flour, baking powder, cinnamon and milk.","Peel the apples and cut them into large wedges, never slices: big pieces keep their sharpness at the heart of the cake.","Fold them into the batter, turn into a tin, cover with the crumble and scatter sugar.","Bake 50 minutes at 180°C. Serve hot, under a custard made with the milk, yolks and vanilla."]} },

{ id:'irish-coffee', c:'eu', lat:52.611, lon:-9.107, base:4, prep:15, cook:0, diff:2, tags:['drink','fast','comfort'],
  art:{v:'glass',bg:'#2b2419',plate:'#f4f0e6',style:'drink',food:['#3a2a1a','#f4f0e6','#6f4a2a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Irish coffee',en:'Irish coffee'},
  p:{fr:'Foynes, comté de Limerick, Irlande',en:'Foynes, County Limerick, Ireland'},
  d:{fr:"Du café, du whiskey, du sucre et une crème qui flotte sans se mêler. Joe Sheridan l'inventa en 1943 pour réchauffer des passagers d'hydravion bloqués à Foynes ; quand on lui demanda si c'était du café brésilien, il répondit que c'était du café irlandais.",
     en:"Coffee, whiskey, sugar and a cream that floats without mixing. Joe Sheridan invented it in 1943 to warm flying-boat passengers stranded at Foynes; asked whether it was Brazilian coffee, he answered that it was Irish coffee."},
  i:[['coffee',400,'ml'],['irish_whiskey',160,'ml'],['brown_sugar',4,'tsp'],['heavy_cream',150,'ml']],
  s:{fr:["Fouettez la crème très légèrement, juste jusqu'à ce qu'elle nappe la cuillère : montée ferme, elle s'effondre en blocs au lieu de flotter.","Ébouillantez les verres à pied et videz-les : un verre froid casse et fait retomber la crème.","Versez le whiskey et le sucre au fond et remuez jusqu'à dissolution complète — c'est le sucre qui, en densifiant le café, permet à la crème de tenir.","Ajoutez le café brûlant et remuez encore une fois.","Versez la crème doucement sur le dos d'une cuillère posée à la surface. Ne remuez plus : on boit le café chaud à travers la crème froide."],
     en:["Whip the cream very lightly, just until it coats the spoon: whipped stiff, it collapses in lumps instead of floating.","Scald the stemmed glasses and empty them: a cold glass cracks and drops the cream.","Pour the whiskey and sugar into the base and stir until fully dissolved — it is the sugar that, by making the coffee denser, lets the cream hold.","Add the scalding coffee and stir once more.","Pour the cream gently over the back of a spoon held at the surface. Do not stir again: the hot coffee is drunk through the cold cream."]} },

{ id:'hakarl', c:'eu', lat:65.078, lon:-22.712, base:8, prep:120, cook:0, diff:3, tags:['sea','slow','festive'],
  art:{v:'board',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#e8dcc0','#f4f0e6','#c9a878','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Hákarl',en:'Hákarl'},
  p:{fr:'Bjarnarhöfn, Snæfellsnes, Islande',en:'Bjarnarhöfn, Snæfellsnes, Iceland'},
  d:{fr:"Du requin du Groenland fermenté trois mois puis séché quatre, servi en cubes avec un verre de brennivín. La chair fraîche est toxique — le requin n'a pas de reins et excrète l'urée par la peau — et c'est la fermentation, et elle seule, qui la rend comestible.",
     en:"Greenland shark fermented for three months then dried for four, served in cubes with a glass of brennivín. The fresh flesh is toxic — the shark has no kidneys and excretes urea through its skin — and fermentation alone makes it edible."},
  i:[['greenland_shark',3,'kg'],['coarse_salt',500,'g'],['rye_bread',300,'g'],['butter',80,'g']],
  s:{fr:["Découpez la chair en gros blocs et enfouissez-la dans une fosse de gravier et de sable, couverte de pierres.","Le poids des pierres presse les fluides hors de la chair : c'est l'expulsion de l'urée et de l'oxyde de triméthylamine, non le froid ni le sel, qui détoxifie le requin.","Laissez fermenter six à douze semaines selon la saison, puis déterrez les blocs et rincez-les.","Suspendez-les quatre mois dans un séchoir ouvert aux vents, jusqu'à ce qu'une croûte brune se forme.","Parez la croûte, coupez la chair pâle en cubes d'un centimètre et servez au cure-dent, avec du pain de seigle. Il ne se cuisine pas : il se prépare pendant sept mois et se mange tel quel."],
     en:["Cut the flesh into large blocks and bury it in a pit of gravel and sand, covered with stones.","The weight of the stones presses the fluids out of the flesh: it is the expulsion of urea and trimethylamine oxide, not cold or salt, that detoxifies the shark.","Ferment for six to twelve weeks depending on the season, then dig out the blocks and rinse them.","Hang them for four months in a shed open to the wind, until a brown crust forms.","Trim the crust, cut the pale flesh into one-centimetre cubes and serve on cocktail sticks, with rye bread. It is not cooked: it is prepared over seven months and eaten as it is."]} },

{ id:'rugbraud', c:'eu', lat:64.077, lon:-20.881, base:10, prep:30, cook:720, diff:2, tags:['bread','slow','comfort'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'roll',food:['#4f3a2a','#6f4a2a','#e8dcb8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Rúgbrauð',en:'Rúgbrauð'},
  p:{fr:'Laugarvatn, Islande',en:'Laugarvatn, Iceland'},
  d:{fr:"Un pain de seigle noir et sucré, cuit vingt-quatre heures enterré dans le sable chaud d'une source géothermique. On l'appelle hverabrauð, pain de source ; sans four à surveiller, il suffit de marquer l'endroit d'un piquet et de revenir le lendemain.",
     en:"A black, sweet rye bread baked for twenty-four hours buried in the hot sand of a geothermal spring. It is called hverabrauð, spring bread; with no oven to watch, you mark the spot with a stake and come back the next day."},
  i:[['rye_flour',500,'g'],['flour',200,'g'],['whole_milk',600,'ml'],['golden_syrup',150,'g'],['brown_sugar',100,'g'],['baking_powder',2,'tsp'],['baking_soda',1,'tsp'],['butter',100,'g'],['salt',null,'']],
  s:{fr:["Mêlez les farines, les levures et le sel, puis ajoutez le lait, le sirop et la cassonade : la pâte doit être coulante, presque une pâte à gâteau.","Versez dans un moule à cake ou un bidon métallique graissé, en n'emplissant qu'aux deux tiers.","Fermez hermétiquement : c'est l'étuvage en vase clos, sans évaporation, qui donne la mie humide et la couleur noire.","Enfouissez le récipient à 30 cm dans un sable géothermique à 90 °C — ou, à défaut, cuisez au bain-marie couvert 12 heures à 100 °C.","Démoulez le lendemain et laissez tiédir. Se tranche très fin, avec du beurre salé et du hareng ou de la truite fumée."],
     en:["Mix the flours, raising agents and salt, then add the milk, syrup and brown sugar: the batter should pour, almost like a cake mix.","Pour into a greased loaf tin or metal can, filling only two-thirds.","Seal it airtight: it is steaming in a closed vessel, with no evaporation, that gives the moist crumb and the black colour.","Bury the container 30 cm down in geothermal sand at 90°C — or failing that, bake covered in a bain-marie for 12 hours at 100°C.","Turn out the next day and let it cool. Sliced very thin, with salted butter and herring or smoked trout."]} },

{ id:'hardfiskur', c:'eu', lat:66.045, lon:-23.116, base:8, prep:60, cook:0, diff:2, tags:['sea','slow','fast'],
  art:{v:'board',bg:'#2c3440',plate:'#f4ead4',style:'fish',food:['#e8dcc0','#f0e8d0','#c9a878','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Harðfiskur',en:'Harðfiskur'},
  p:{fr:'Bolungarvík, Vestfirðir, Islande',en:'Bolungarvík, Westfjords, Iceland'},
  d:{fr:"De l'églefin séché au vent, sans sel ni fumée, déchiré à la main et beurré. C'était la monnaie de l'Islande médiévale : les loyers et les dîmes se payaient en poisson séché, et un homme se nourrissait de cela tout l'hiver.",
     en:"Haddock dried in the wind, without salt or smoke, torn by hand and buttered. It was medieval Iceland's currency: rents and tithes were paid in dried fish, and a man lived on it all winter."},
  i:[['haddock_fillets',2,'kg'],['butter',150,'g']],
  s:{fr:["Videz et étêtez les poissons, puis fendez-les le long de l'arête en laissant les deux filets réunis par la queue.","Ne salez pas : le harðfiskur est l'un des rares poissons séchés au monde qui ne le soit pas, et le sel empêcherait le vent de faire son travail.","Suspendez les paires à cheval sur des perches, dans un séchoir ouvert aux quatre vents, entre 0 et 5 °C.","Laissez sécher quatre à six semaines, à l'abri de la pluie et du soleil : au-dessus de 8 °C, le poisson se gâte avant de sécher.","Il est prêt quand il casse net et se déchire en lanières. Se mange tel quel, tartiné de beurre — jamais réhydraté."],
     en:["Gut and behead the fish, then split them along the backbone leaving the two fillets joined at the tail.","Do not salt: harðfiskur is one of the few dried fish in the world that is not, and salt would stop the wind doing its work.","Hang the pairs astride poles in a shed open to every wind, between 0 and 5°C.","Dry for four to six weeks, sheltered from rain and sun: above 8°C the fish spoils before it dries.","It is ready when it snaps cleanly and tears into strips. Eaten as it is, spread with butter — never rehydrated."]} },

{ id:'svid', c:'eu', lat:64.146, lon:-21.940, base:4, prep:60, cook:120, diff:3, tags:['lamb','slow','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'other',food:['#c9924a','#8f6a4a','#f4f0e6','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Svið',en:'Svið'},
  p:{fr:'Reykjavik, Islande',en:'Reykjavik, Iceland'},
  d:{fr:"Une demi-tête de mouton flambée, bouillie et servie entière, l'œil et la joue compris. Le plat du þorrablót, le festin de milieu d'hiver : dans une île sans bois ni céréale, on ne pouvait se permettre de jeter la tête d'un animal.",
     en:"Half a sheep's head singed, boiled and served whole, eye and cheek included. A dish of the þorrablót, the midwinter feast: on an island without timber or grain, no one could afford to throw away an animal's head."},
  i:[['sheep_head',2,'pc'],['coarse_salt',60,'g'],['bay_leaf',2,'pc'],['turnip',600,'g'],['potato',800,'g'],['butter',60,'g'],['whole_milk',100,'ml'],['pepper',null,'']],
  s:{fr:["Flambez les têtes au chalumeau pour brûler la laine, puis grattez-les au couteau et rincez à l'eau froide.","Fendez-les en deux dans la longueur, retirez la cervelle, et laissez-les dégorger 4 heures à l'eau froide salée.","Pochez-les 1 h 30 à petits frémissements avec le sel et le laurier, en écumant les premières minutes.","Un bouillon qui bout ferait éclater la peau et détacherait la joue, qui est le meilleur morceau.","Servez chaud avec une purée de rutabaga et des pommes de terre. Ce qui reste se presse en terrine et se mange froid, en sviðasulta."],
     en:["Singe the heads with a blowtorch to burn off the wool, then scrape them with a knife and rinse in cold water.","Split them lengthwise, remove the brain, and soak them 4 hours in cold salted water.","Poach them 1½ hours at a bare tremble with the salt and bay, skimming for the first few minutes.","A boiling broth would split the skin and loosen the cheek, which is the best part.","Serve hot with mashed swede and potatoes. What is left is pressed into a terrine and eaten cold, as sviðasulta."]} },

{ id:'slatur', c:'eu', lat:65.685, lon:-18.111, base:8, prep:120, cook:180, diff:3, tags:['lamb','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'other',food:['#4f3a3a','#c9a878','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Slátur',en:'Slátur'},
  p:{fr:'Akureyri, Islande',en:'Akureyri, Iceland'},
  d:{fr:"Deux boudins cousus dans la panse de mouton : le blóðmör au sang et le lifrarpylsa au foie. On les fait en famille à l'automne, à l'abattage ; ce qui n'est pas mangé aussitôt part au petit-lait aigre, où il se conserve un an.",
     en:"Two puddings sewn into sheep's stomach: blóðmör with blood and lifrarpylsa with liver. Families make them together in autumn at slaughter time; what is not eaten at once goes into sour whey, where it keeps a year."},
  i:[['sheep_blood',1,'l'],['lamb_liver',600,'g'],['sheep_suet',600,'g'],['rye_flour',300,'g'],['oats',300,'g'],['pork_stomach',4,'pc'],['coarse_salt',40,'g'],['turnip',600,'g'],['potato',800,'g'],['whole_milk',200,'ml']],
  s:{fr:["Découpez la panse en carrés, pliez-les en poche et cousez deux côtés à l'aiguille avec du fil de lin.","Pour le blóðmör, mêlez le sang tamisé, le suif en petits dés, le seigle, l'avoine et le sel ; pour le lifrarpylsa, remplacez le sang par le foie mixé au lait.","Emplissez les poches aux deux tiers seulement — les céréales gonflent beaucoup et feraient éclater la couture.","Cousez le dernier côté et pochez 2 h 30 à 85 °C, sans bouillir, en piquant chaque boudin après 20 minutes.","Servez chaud avec des pommes de terre et du rutabaga. Le reste se conserve dans du petit-lait aigre, où il devient súrsað."],
     en:["Cut the stomach into squares, fold them into pouches and sew two sides with linen thread.","For blóðmör, mix the sieved blood, diced suet, rye, oats and salt; for lifrarpylsa, replace the blood with liver blended with milk.","Fill the pouches only two-thirds — the cereals swell a great deal and would burst the seam.","Sew the last side and poach 2½ hours at 85°C, without boiling, pricking each pudding after 20 minutes.","Serve hot with potatoes and swede. The rest keeps in sour whey, where it becomes súrsað."]} },

{ id:'sursadir-hrutspungar', c:'eu', lat:63.784, lon:-20.276, base:8, prep:90, cook:120, diff:3, tags:['lamb','slow','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4f0e6',style:'other',food:['#e0c8b8','#f4f0e6','#c9a878','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Hrútspungar marinés',en:'Soured ram’s testicles'},
  p:{fr:'Vestmannaeyjar, Islande',en:'Vestmannaeyjar, Iceland'},
  d:{fr:"Des testicules de bélier bouillis, pressés en terrine puis conservés dans du petit-lait aigre. C'est l'une des pièces du plateau de þorramatur ; le petit-lait, seul agent de conservation d'une île sans sel ni épices, acidifie sans jamais saler.",
     en:"Ram's testicles boiled, pressed into a terrine then kept in sour whey. One of the pieces on the þorramatur platter; the whey, the only preservative on an island without salt or spice, acidifies without ever salting."},
  i:[['ram_testicles',1.5,'kg'],['sour_whey',2,'l'],['bay_leaf',2,'pc'],['rye_bread',300,'g'],['butter',80,'g'],['coarse_salt',20,'g']],
  s:{fr:["Retirez la membrane extérieure et faites dégorger les pièces 6 heures à l'eau froide, en la changeant trois fois.","Pochez-les 2 heures à frémissement avec le laurier, jusqu'à ce qu'une aiguille les traverse sans résistance.","Rangez-les serrées dans une terrine et pressez sous un poids 24 heures : c'est le pressage qui les soude en un bloc tranchable.","Immergez le bloc entièrement dans le petit-lait aigre et laissez-le acidifier deux à trois mois au frais.","Le petit-lait doit toujours recouvrir : une pièce qui affleure moisit. Servez en tranches fines sur du pain de seigle beurré."],
     en:["Remove the outer membrane and soak the pieces 6 hours in cold water, changing it three times.","Poach them 2 hours at a simmer with the bay, until a needle passes through without resistance.","Pack them tightly into a terrine and press under a weight for 24 hours: pressing is what welds them into a sliceable block.","Submerge the block completely in sour whey and let it acidify two to three months in the cold.","The whey must always cover it: a piece that breaks the surface moulds. Serve in thin slices on buttered rye bread."]} },

{ id:'laufabraud', c:'eu', lat:65.685, lon:-18.089, base:12, prep:150, cook:20, diff:3, tags:['bread','festive','fry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Laufabrauð',en:'Laufabrauð'},
  p:{fr:'Akureyri, Islande',en:'Akureyri, Iceland'},
  d:{fr:"Des disques de pâte aussi fins qu'une feuille, ciselés de motifs géométriques et frits, servis à Noël dans le Nord de l'Islande. La farine était si rare qu'on l'étirait au maximum : la finesse du pain n'était pas une prouesse, c'était une nécessité.",
     en:"Discs of dough as thin as a leaf, cut with geometric patterns and fried, served at Christmas in northern Iceland. Flour was so scarce that it was stretched to the limit: the thinness was not a feat, it was a necessity."},
  i:[['flour',500,'g'],['whole_milk',250,'ml'],['sugar',30,'g'],['baking_powder',1,'tsp'],['butter',40,'g'],['cardamom',1,'tsp'],['lamb_fat',800,'g'],['salt',null,'']],
  s:{fr:["Portez le lait au frémissement avec le beurre et versez-le brûlant sur la farine, le sucre, la levure, la cardamome et le sel.","Pétrissez énergiquement 10 minutes : la pâte doit être très ferme, presque dure — une pâte souple ne s'abaisse pas assez fin.","Divisez en boules et abaissez chacune jusqu'à voir le motif du plan de travail au travers, puis découpez un disque de 20 cm.","Ciselez les motifs au couteau ou au laufabrauðsjárn, en relevant chaque languette d'un côté : c'est ce relevage qui fait le dessin en relief.","Frites 20 secondes par face dans la graisse de mouton à 190 °C, puis pressées à plat sous une planche pendant qu'elles refroidissent."],
     en:["Bring the milk to a tremble with the butter and pour it scalding onto the flour, sugar, baking powder, cardamom and salt.","Knead hard for 10 minutes: the dough must be very firm, almost hard — a soft dough will not roll thin enough.","Divide into balls and roll each until you can see the worktop grain through it, then cut a 20 cm disc.","Cut the patterns with a knife or a laufabrauðsjárn, lifting each tab to one side: that lifting is what makes the raised design.","Fry 20 seconds a side in mutton fat at 190°C, then press flat under a board as they cool."]} },

{ id:'vinarterta', c:'eu', lat:64.145, lon:-21.926, base:12, prep:120, cook:40, diff:3, tags:['sweet','festive','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#f2dfa8','#4f3a2a','#e8dcb8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Vínarterta',en:'Vínarterta'},
  p:{fr:'Reykjavik, Islande',en:'Reykjavik, Iceland'},
  d:{fr:"Un gâteau de cinq à sept couches de biscuit sec séparées de compote de pruneaux à la cardamome. Il a presque disparu d'Islande mais survit intact au Manitoba, où les émigrants l'ont emporté vers 1875 : les Islandais du Canada le font encore comme au XIXᵉ siècle.",
     en:"A cake of five to seven layers of dry biscuit separated by cardamom prune compote. It has nearly vanished from Iceland but survives untouched in Manitoba, where emigrants took it around 1875: Canadian Icelanders still make it as they did in the 19th century."},
  i:[['flour',600,'g'],['butter',250,'g'],['sugar',300,'g'],['egg',3,'pc'],['whole_milk',60,'ml'],['baking_powder',2,'tsp'],['cardamom',2,'tsp'],['prunes',500,'g'],['vanilla',1,'pc'],['cinnamon',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites mijoter les pruneaux dénoyautés dans l'eau 30 minutes, écrasez-les avec 100 g de sucre, la cardamome et la cannelle, et laissez refroidir : la compote doit être épaisse, presque une pâte.","Crémez le beurre et le sucre restant, ajoutez les œufs, le lait, puis la farine et la levure pour une pâte ferme.","Divisez en cinq parts égales, étalez chacune en disque de 22 cm et cuisez 10 minutes à 180 °C. Elles doivent rester pâles et sèches.","Empilez les disques en les tartinant de compote, en pressant légèrement à chaque étage.","Enveloppez le gâteau et laissez-le reposer une semaine avant de le trancher : les couches sèches doivent boire l'humidité de la compote, sinon le gâteau se brise au couteau."],
     en:["Simmer the stoned prunes in water for 30 minutes, crush them with 100 g of the sugar, the cardamom and cinnamon, and cool: the compote must be thick, almost a paste.","Cream the butter and remaining sugar, add the eggs, milk, then the flour and baking powder for a firm dough.","Divide into five equal parts, roll each into a 22 cm disc and bake 10 minutes at 180°C. They must stay pale and dry.","Stack the discs, spreading compote between them and pressing lightly at each layer.","Wrap the cake and let it rest a week before slicing: the dry layers must drink the moisture from the compote, or the cake shatters under the knife."]} },

{ id:'kleinur', c:'eu', lat:64.143, lon:-21.927, base:12, prep:60, cook:20, diff:2, tags:['sweet','fry','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#c9924a','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Kleinur',en:'Kleinur'},
  p:{fr:'Reykjavik, Islande',en:'Reykjavik, Iceland'},
  d:{fr:"Des losanges de pâte à la cardamome, torsadés en passant une pointe dans une fente, et frits dans la graisse de mouton. On les trouve dans toute la Scandinavie, mais l'Islande les fait au lait aigre et les frit dans le suif, ce qui leur donne un goût que le beurre ne remplace pas.",
     en:"Cardamom dough diamonds, twisted by passing one tip through a slit, and fried in mutton fat. They exist across Scandinavia, but Iceland makes them with soured milk and fries them in tallow, which gives a flavour butter does not replace."},
  i:[['flour',500,'g'],['sugar',120,'g'],['butter',80,'g'],['egg',2,'pc'],['buttermilk',200,'ml'],['baking_powder',2,'tsp'],['baking_soda',0.5,'tsp'],['cardamom',2,'tsp'],['lemon_zest',1,'pc'],['lamb_fat',1,'kg'],['salt',null,'']],
  s:{fr:["Sablez le beurre dans la farine, le sucre, les levures, la cardamome et le sel, puis liez avec les œufs et le babeurre.","Laissez reposer la pâte 1 heure au froid : c'est le repos qui empêche les kleinur de gonfler en beignets ronds.","Abaissez à 5 mm, découpez des losanges de 8 cm et fendez chacun au centre sur deux centimètres.","Passez une pointe du losange dans la fente et tirez doucement : la torsade doit tenir seule, sans être serrée.","Frites 90 secondes par face à 180 °C dans la graisse de mouton. Elles doivent être brun foncé — pâles, elles sont crues au cœur."],
     en:["Rub the butter into the flour, sugar, raising agents, cardamom and salt, then bind with the eggs and buttermilk.","Rest the dough an hour in the cold: that rest is what stops kleinur puffing into round doughnuts.","Roll to 5 mm, cut 8 cm diamonds and slit each in the centre for two centimetres.","Pass one tip of the diamond through the slit and pull gently: the twist must hold by itself, without being tight.","Fry 90 seconds a side at 180°C in mutton fat. They should be dark brown — pale, they are raw inside."]} },

{ id:'pylsur', c:'eu', lat:64.148, lon:-21.939, base:4, prep:15, cook:10, diff:1, tags:['street','fast','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9754a','#e0b45a','#f4f0e6','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Pylsur',en:'Pylsur'},
  p:{fr:'Reykjavik, Islande',en:'Reykjavik, Iceland'},
  d:{fr:"Le hot-dog islandais, à la saucisse d'agneau, servi avec de l'oignon frit sous la saucisse et de l'oignon cru par-dessus. On le commande eina með öllu, une avec tout ; l'ordre des garnitures n'est pas négociable, et l'oignon frit va au fond du pain.",
     en:"The Icelandic hot dog, made with lamb sausage, served with fried onion under the sausage and raw onion on top. You order it eina með öllu, one with everything; the order of the toppings is not negotiable, and the crisp onion goes at the bottom of the bun."},
  i:[['lamb_sausage',4,'pc'],['hot_dog_buns',4,'pc'],['onion',3,'pc'],['flour',2,'tbsp'],['frying_oil',400,'ml'],['ketchup',4,'tbsp'],['mustard',4,'tbsp'],['mayonnaise',4,'tbsp'],['pickles',4,'pc'],['salt',null,'']],
  s:{fr:["Émincez un oignon en fines lamelles, farinez-les et faites-les frire à 170 °C jusqu'à ce qu'elles brunissent ; égouttez-les sur papier.","Hachez les deux autres oignons crus en tout petits dés et gardez-les au froid.","Pochez les saucisses 7 minutes dans l'eau frémissante — jamais bouillante, qui ferait éclater la peau — et réchauffez les pains à la vapeur au-dessus.","Étalez d'abord l'oignon frit au fond du pain, posez la saucisse dessus : ainsi il reste croustillant au lieu de se détremper.","Terminez par le ketchup doux, la moutarde brune sucrée, la rémoulade aux cornichons et l'oignon cru. Se mange debout, dans la minute."],
     en:["Slice one onion thinly, flour it and fry at 170°C until brown; drain on paper.","Chop the other two onions raw into very small dice and keep them cold.","Poach the sausages 7 minutes in barely simmering water — never boiling, which would burst the skin — and steam the buns above them.","Spread the crisp onion in the base of the bun first, then lay the sausage on it: that way it stays crisp instead of going soggy.","Finish with sweet ketchup, sweet brown mustard, gherkin remoulade and raw onion. Eaten standing, within the minute."]} },

{ id:'escudella-andorrana', c:'eu', lat:42.5063, lon:1.5218, base:8, prep:60, cook:210, diff:2, tags:['pork','soup','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'soup',food:['#e8dcb8','#c9924a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Escudella andorrane',en:'Andorran escudella'},
  p:{fr:'Andorre-la-Vieille, Andorre',en:'Andorra la Vella, Andorra'},
  d:{fr:"Le pot-au-feu des Pyrénées catalanes, servi en deux temps : d'abord le bouillon avec ses pâtes, ensuite les viandes et les légumes sur un plat. Au centre trône la pilota, une grosse boulette de viande hachée que chaque famille assaisonne à sa façon et qu'on ne partage qu'au dernier moment.",
     en:"The pot-au-feu of the Catalan Pyrenees, served in two acts: first the broth with its pasta, then the meats and vegetables on a platter. At the centre sits the pilota, a large meatball each family seasons its own way and which is only divided at the last moment."},
  i:[['beef_shank',600,'g'],['pork_ribs',500,'g'],['chicken',600,'g'],['botifarra',300,'g'],['salted_pork',200,'g'],['chickpeas',300,'g'],['potato',600,'g'],['carrot',4,'pc'],['cabbage',400,'g'],['celery',2,'pc'],['ground_pork',300,'g'],['egg',2,'pc'],['breadcrumbs',80,'g'],['garlic',4,'clove'],['parsley',4,'tbsp'],['pasta_shells',200,'g'],['cinnamon',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les pois chiches une nuit dans une eau tiède salée, et mettez-les à cuire dans un filet à part : sans cela ils se perdraient dans la marmite.","Mettez les viandes à l'eau froide et montez lentement en écumant sans relâche pendant le premier quart d'heure — c'est là, et seulement là, que le bouillon devient clair.","Laissez frémir 2 heures avec la carotte et le céleri, sans jamais faire bouillir : un bouillon agité devient trouble et ne se rattrape pas.","Formez la pilota avec le porc haché, les œufs, la chapelure, l'ail, le persil et une pointe de cannelle ; roulez-la en gros ovale, farinez-la et posez-la doucement dans le bouillon pour la dernière heure.","Ajoutez chou et pommes de terre en fin de cuisson. Servez d'abord la soupe avec les pâtes cuites dedans, puis la carn d'olla sur un plat, la pilota tranchée au centre."],
     en:["Soak the chickpeas overnight in warm salted water, and cook them in a separate net: otherwise they would be lost in the pot.","Start the meats in cold water and bring them up slowly, skimming without pause for the first fifteen minutes — that is when, and only when, the broth turns clear.","Let it tremble for 2 hours with the carrot and celery, never boiling: an agitated broth clouds and cannot be recovered.","Shape the pilota from the minced pork, eggs, breadcrumbs, garlic, parsley and a pinch of cinnamon; roll it into a large oval, flour it and lower it gently into the broth for the last hour.","Add the cabbage and potatoes at the end. Serve the soup first, with the pasta cooked in it, then the carn d'olla on a platter, the pilota sliced at the centre."]} },

{ id:'trinxat-de-la-cerdanya', c:'eu', lat:42.5427, lon:1.7333, base:4, prep:25, cook:45, diff:1, tags:['pork','veg','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#7fae5a','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Trinxat de la Cerdagne',en:'Cerdanya trinxat'},
  p:{fr:'Pas de la Casa, Encamp, Andorre',en:'Pas de la Casa, Encamp, Andorra'},
  d:{fr:"Un écrasé de chou d'hiver et de pommes de terre, poêlé dans la graisse de lard jusqu'à ce qu'il prenne croûte. Trinxar veut dire hacher : on n'emploie que le chou frisé cueilli après les premières gelées, qui perd son amertume et devient sucré.",
     en:"A crush of winter cabbage and potato, fried in bacon fat until it takes a crust. Trinxar means to chop: only curly kale picked after the first frosts is used, which loses its bitterness and turns sweet."},
  i:[['green_cabbage',800,'g'],['potato',600,'g'],['smoked_bacon',200,'g'],['garlic',6,'clove'],['lard',60,'g'],['olive_oil',40,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire ensemble le chou grossièrement coupé et les pommes de terre en gros morceaux, à l'eau salée, 25 minutes.","Égouttez-les longuement et pressez-les contre la passoire : le trinxat rate toujours pour la même raison, un excès d'eau.","Écrasez-les à la fourchette avec l'ail pilé — grossièrement, il doit rester des morceaux reconnaissables, jamais une purée lisse.","Faites rissoler le lard en dés dans le saindoux jusqu'à ce qu'il croustille, retirez-le et versez l'écrasé dans la graisse chaude.","Tassez en galette et laissez prendre 8 minutes sans y toucher, puis retournez d'un coup à l'aide d'une assiette. Couronnez du lard croustillant."],
     en:["Boil the roughly cut cabbage and the potatoes in large pieces together in salted water for 25 minutes.","Drain them at length and press them against the colander: trinxat always fails for the same reason, too much water.","Crush them with a fork along with the pounded garlic — roughly, recognisable pieces must remain, never a smooth purée.","Fry the diced bacon in the lard until crisp, lift it out and tip the crush into the hot fat.","Press it into a cake and let it set for 8 minutes untouched, then flip it in one movement using a plate. Crown it with the crisp bacon."]} },

{ id:'conill-amb-tomaquet', c:'eu', lat:42.4637, lon:1.4913, base:4, prep:30, cook:90, diff:2, tags:['slow','sunday','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9532c','#8f5a3a','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Lapin à la tomate',en:'Rabbit with tomato'},
  p:{fr:'Sant Julià de Lòria, Andorre',en:'Sant Julià de Lòria, Andorra'},
  d:{fr:"Du lapin de clapier mijoté dans un sofregit de tomate longuement confit, avec une picada d'amandes et de foie pour lier la sauce. La picada est le geste catalan par excellence : elle n'épaissit pas par la farine mais par le pilage, et elle s'ajoute toujours dans les dix dernières minutes.",
     en:"Hutch rabbit stewed in a long-cooked tomato sofregit, with an almond and liver picada to bind the sauce. The picada is the Catalan gesture par excellence: it thickens not by flour but by pounding, and always goes in during the last ten minutes."},
  i:[['rabbit',1.5,'kg'],['ripe_tomato',800,'g'],['onion',3,'pc'],['garlic',8,'clove'],['almonds',60,'g'],['hazelnuts',40,'g'],['white_wine',200,'ml'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['olive_oil',100,'ml'],['bread',2,'slice'],['parsley',4,'tbsp'],['dark_chocolate',10,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez le lapin en morceaux, réservez le foie, et faites-le dorer à l'huile d'olive de tous côtés avant de le retirer.","Faites le sofregit dans la même huile : oignon râpé 20 minutes, puis tomate râpée 25 minutes de plus, jusqu'à ce qu'il ne reste plus d'eau et que la masse soit brique et brillante.","Un sofregit pressé reste acide : c'est la seule étape qu'on ne peut pas raccourcir.","Remettez le lapin, déglacez au vin blanc, ajoutez les herbes et mouillez à hauteur ; laissez mijoter 1 heure à couvert.","Pilez au mortier l'ail, les amandes, les noisettes, le pain frit, le foie sauté et le chocolat, délayez d'un peu de sauce et versez pour les dix dernières minutes."],
     en:["Joint the rabbit, keep the liver aside, and brown it all over in olive oil before lifting it out.","Make the sofregit in the same oil: grated onion for 20 minutes, then grated tomato for 25 more, until no water is left and the mass is brick-red and glossy.","A hurried sofregit stays acidic: it is the one step that cannot be shortened.","Return the rabbit, deglaze with white wine, add the herbs and moisten to cover; simmer covered for an hour.","Pound the garlic, almonds, hazelnuts, fried bread, sautéed liver and chocolate in a mortar, slake with a little sauce and stir it in for the last ten minutes."]} },

{ id:'xai-rostat-de-muntanya', c:'eu', lat:42.5722, lon:1.4847, base:6, prep:30, cook:150, diff:2, tags:['lamb','slow','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a3a','#c9754a','#e8d8b8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Agneau rôti de montagne',en:'Mountain roast lamb'},
  p:{fr:'Arinsal, La Massana, Andorre',en:'Arinsal, La Massana, Andorra'},
  d:{fr:"Un quartier d'agneau de la vallée rôti lentement sur un lit de pommes de terre, au vin blanc et au thym du Coma Pedrosa. L'agneau andorran monte en estive à quinze cents mètres et se nourrit de plantes aromatiques : sa graisse en garde le goût, et c'est pourquoi on l'assaisonne si peu.",
     en:"A quarter of valley lamb roasted slowly on a bed of potatoes, with white wine and thyme from the Coma Pedrosa. Andorran lamb summers at fifteen hundred metres on aromatic plants: its fat keeps the taste, which is why so little seasoning goes on it."},
  i:[['lamb_shoulder',2,'kg'],['potato',1.2,'kg'],['onion',3,'pc'],['garlic',12,'clove'],['white_wine',300,'ml'],['thyme',6,'sprig'],['rosemary',3,'sprig'],['lard',60,'g'],['olive_oil',80,'ml'],['bay_leaf',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Frottez l'agneau de saindoux, de sel et d'ail pilé douze heures à l'avance, et sortez-le du froid une heure avant d'enfourner.","Tapissez le plat de terre d'oignons et de pommes de terre en rondelles épaisses, arrosez d'huile et posez la viande dessus.","Enfournez 20 minutes à 230 °C pour saisir la croûte, puis descendez à 160 °C.","Arrosez toutes les vingt minutes du jus et du vin blanc versé par le bord du plat, jamais sur la viande — un arrosage direct ramollit la croûte qu'on vient de faire.","Comptez 2 heures en tout et laissez reposer 15 minutes hors du four avant de découper. Les pommes de terre auront bu tout le jus."],
     en:["Rub the lamb with lard, salt and crushed garlic twelve hours ahead, and take it out of the cold an hour before it goes in the oven.","Line an earthenware dish with onion and thickly sliced potato, moisten with oil and set the meat on top.","Roast 20 minutes at 230°C to seize the crust, then drop to 160°C.","Baste every twenty minutes with the juices and the white wine poured down the side of the dish, never over the meat — direct basting softens the crust you have just made.","Allow 2 hours in all and rest it 15 minutes out of the oven before carving. The potatoes will have drunk every drop."]} },

{ id:'truites-a-l-andorrana', c:'eu', lat:42.5559, lon:1.5330, base:4, prep:20, cook:15, diff:1, tags:['sea','fast','fresh'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ecd8',style:'fish',food:['#e0a8a0','#f0e8d0','#c9924a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Truites à l’andorrane',en:'Andorran-style trout'},
  p:{fr:'Ordino, Andorre',en:'Ordino, Andorra'},
  d:{fr:"Des truites du Valira farcies de lard et poêlées, dorées au beurre noisette et à l'ail. La rivière descend des cirques d'Ordino en eau glacée : la truite y grandit lentement, sa chair est ferme et n'a besoin ni de marinade ni de sauce.",
     en:"Valira trout stuffed with bacon and pan-fried, browned in nut butter and garlic. The river comes down from the Ordino cirques in freezing water: trout grow slowly there, and the firm flesh needs neither marinade nor sauce."},
  i:[['trout',4,'pc'],['smoked_bacon',8,'slice'],['flour',60,'g'],['butter',100,'g'],['garlic',6,'clove'],['lemon',2,'pc'],['parsley',4,'tbsp'],['almonds',60,'g'],['olive_oil',40,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Videz les truites sans les écailler — la truite de rivière n'a pratiquement pas d'écailles — et essuyez l'intérieur sans le rincer.","Salez la cavité, glissez-y deux tranches de lard et une branche de persil, et refermez d'un pique en bois.","Farinez-les légèrement en tapotant pour ôter l'excédent : une farine épaisse forme une gangue au lieu d'une peau croustillante.","Poêlez 4 minutes par face à l'huile chaude, puis retirez-les et jetez l'huile.","Faites mousser le beurre avec l'ail émincé et les amandes effilées jusqu'à ce qu'il sente la noisette, versez sur les truites et arrosez de citron."],
     en:["Gut the trout without scaling them — river trout barely have scales — and wipe the cavity without rinsing it.","Salt the inside, slip in two slices of bacon and a sprig of parsley, and close with a wooden pick.","Flour them lightly, tapping off the excess: thick flour makes a shell instead of a crisp skin.","Fry 4 minutes a side in hot oil, then lift them out and discard the oil.","Foam the butter with sliced garlic and flaked almonds until it smells of hazelnuts, pour over the trout and squeeze lemon over."]} },

{ id:'canelons-a-l-andorrana', c:'eu', lat:42.4936, lon:1.5083, base:6, prep:70, cook:40, diff:3, tags:['pork','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#c9924a','#e0b45a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Canelons à l’andorrane',en:'Andorran cannelloni'},
  p:{fr:'Santa Coloma, Andorre-la-Vieille, Andorre',en:'Santa Coloma, Andorra la Vella, Andorra'},
  d:{fr:"Des cannellonis farcis des restes du rôti de Noël, couverts de béchamel et gratinés. Ils se mangent le 26 décembre, jour de Sant Esteve : la farce n'est pas préparée pour eux, elle est ce qui reste de la veille, et c'est là toute la logique du plat.",
     en:"Cannelloni filled with the leftovers of the Christmas roast, covered in béchamel and gratinated. They are eaten on 26 December, Sant Esteve: the filling is not made for them, it is what is left from the day before, and that is the whole logic of the dish."},
  i:[['cannelloni',24,'pc'],['pork_shoulder',300,'g'],['chicken',300,'g'],['beef_chuck',200,'g'],['chicken_liver',150,'g'],['onion',2,'pc'],['brandy',50,'ml'],['whole_milk',800,'ml'],['flour',70,'g'],['butter',80,'g'],['gruyere_cheese',150,'g'],['nutmeg',1,'pinch'],['olive_oil',40,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Hachez ensemble les viandes cuites de la veille et les foies sautés, deux fois au hachoir : la farce doit être fine et homogène.","Faites suer l'oignon, ajoutez la farce, flambez au cognac et mouillez d'une louche de béchamel pour la lier.","Cuisez les plaques ou les tubes à l'eau salée en les gardant très fermes, et étalez-les sur un linge humide sans les superposer.","Garnissez et roulez serré, puis rangez les canelons côte à côte, soudure dessous, dans un plat beurré.","Nappez de béchamel jusqu'à les recouvrir entièrement — un cannelloni qui affleure sèche et durcit — parsemez de fromage et gratinez 25 minutes à 200 °C."],
     en:["Mince yesterday's cooked meats with the sautéed livers, twice through the mincer: the filling must be fine and even.","Sweat the onion, add the filling, flame with brandy and moisten with a ladle of béchamel to bind it.","Cook the sheets or tubes in salted water keeping them very firm, and spread them on a damp cloth without overlapping.","Fill and roll tightly, then lay the canelons side by side, seam down, in a buttered dish.","Coat with béchamel until they are entirely covered — a cannelloni that breaks the surface dries and hardens — scatter cheese and gratinate 25 minutes at 200°C."]} },

{ id:'coca-massegada', c:'eu', lat:42.5040, lon:1.5240, base:8, prep:100, cook:25, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Coca massegada',en:'Coca massegada'},
  p:{fr:'Andorre-la-Vieille, Andorre',en:'Andorra la Vella, Andorra'},
  d:{fr:"Une coca plate au saindoux et à l'anis, pétrie longuement puis étalée à la main et couverte de sucre et de pignons. Massegar veut dire pétrir sans fin : c'est le travail de la pâte, et non un levain, qui lui donne sa mie serrée et sa longue conservation.",
     en:"A flat coca with lard and anise, kneaded at length then stretched by hand and covered with sugar and pine nuts. Massegar means to knead without end: it is the working of the dough, not a leaven, that gives it its tight crumb and long keeping."},
  i:[['flour',500,'g'],['lard',150,'g'],['sugar',180,'g'],['egg',3,'pc'],['fresh_yeast',15,'g'],['warm_water',150,'ml'],['anise_seeds',1,'tbsp'],['pine_nuts',80,'g'],['lemon_zest',1,'pc'],['anisette',30,'ml'],['salt',null,'']],
  s:{fr:["Délayez la levure dans l'eau tiède et laissez-la mousser, puis pétrissez-la avec la farine, deux œufs, 80 g de sucre, le zeste, l'anisette et le sel.","Ajoutez le saindoux mou par petits morceaux et pétrissez vingt bonnes minutes, jusqu'à ce que la pâte devienne lisse et élastique sous la main.","C'est ce pétrissage prolongé qui fait la coca : bâclé, on obtient un gâteau friable au lieu d'une pâte qui se déchire en filaments.","Laissez lever 1 heure, puis étalez à la main en un rectangle d'un centimètre à peine, sans rouleau, en tirant depuis le centre.","Dorez à l'œuf, couvrez de sucre et de pignons, laissez pousser 30 minutes et cuisez 25 minutes à 190 °C."],
     en:["Dissolve the yeast in warm water and let it foam, then knead it with the flour, two eggs, 80 g of the sugar, the zest, anisette and salt.","Add the soft lard in small pieces and knead a good twenty minutes, until the dough turns smooth and elastic under the hand.","That long kneading is what makes a coca: skimp it and you get a crumbly cake instead of a dough that tears into strands.","Prove for an hour, then stretch by hand into a rectangle barely a centimetre thick, with no rolling pin, pulling from the centre.","Glaze with egg, cover with sugar and pine nuts, prove 30 minutes and bake 25 minutes at 190°C."]} },

{ id:'bringuera-andorrana', c:'eu', lat:42.5676, lon:1.5981, base:6, prep:90, cook:60, diff:3, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'grill',food:['#6f4a3a','#c9924a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Bringuera',en:'Bringuera'},
  p:{fr:'Canillo, Andorre',en:'Canillo, Andorra'},
  d:{fr:"Une saucisse andorrane au foie de porc et au poumon, séchée quelques semaines puis pochée ou grillée. Elle naît de la matança, l'abattage de décembre : les abats ne se conservant pas, on les embosse aussitôt, et la bringuera se mange avant les charcuteries nobles.",
     en:"An Andorran sausage of pork liver and lung, dried a few weeks then poached or grilled. It is born of the matança, the December killing: offal does not keep, so it is cased at once, and the bringuera is eaten before the noble charcuterie."},
  i:[['pork_liver',600,'g'],['pork_lung',400,'g'],['pork_belly',600,'g'],['garlic',8,'clove'],['sweet_paprika',2,'tbsp'],['black_peppercorns',2,'tbsp'],['sausage_casings',null,''],['coarse_salt',50,'g'],['white_wine',150,'ml'],['potato',800,'g'],['cabbage',600,'g']],
  s:{fr:["Pochez le foie et le poumon 20 minutes à l'eau salée pour les raffermir : crus, ils passent mal au hachoir et rendent une bouillie.","Hachez-les avec la poitrine à la grille moyenne, et mêlez-les à l'ail pilé, au paprika, au poivre, au sel et au vin blanc.","Laissez reposer la farce 12 heures au froid pour que le sel pénètre, et goûtez-en une boulette poêlée avant d'embosser.","Embossez sans serrer, liez en fers à cheval et piquez les bulles d'air à l'aiguille.","Séchez trois semaines à 12 °C, puis pochez 40 minutes à 80 °C ou grillez sur les braises. Servez avec du chou et des pommes de terre."],
     en:["Poach the liver and lung 20 minutes in salted water to firm them: raw, they clog the mincer and give a mush.","Mince them with the belly on the medium plate, and mix with crushed garlic, paprika, pepper, salt and white wine.","Rest the mixture 12 hours in the cold so the salt penetrates, and taste a fried patty before casing.","Fill the casings loosely, tie into horseshoes and prick out the air bubbles with a needle.","Dry for three weeks at 12°C, then poach 40 minutes at 80°C or grill over coals. Serve with cabbage and potatoes."]} },

{ id:'donja-llonganissa-dolca', c:'eu', lat:42.5100, lon:1.5340, base:8, prep:120, cook:0, diff:3, tags:['pork','slow','sweet'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'other',food:['#8f3b2a','#6f2a2a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Donja',en:'Donja'},
  p:{fr:'Escaldes-Engordany, Andorre',en:'Escaldes-Engordany, Andorra'},
  d:{fr:"Une longanisse andorrane sucrée au miel de montagne, séchée deux mois et mangée en tranches fines. Le sucre n'est pas une fantaisie : dans une vallée sans sel de mer, le miel aidait à la conservation autant qu'il parfumait, et la donja se sert au dessert autant qu'à l'apéritif.",
     en:"A sweet Andorran longaniza made with mountain honey, dried two months and eaten in thin slices. The sugar is no whim: in a valley without sea salt, honey helped preserve as much as it flavoured, and donja is served at dessert as readily as before a meal."},
  i:[['pork_shoulder',1.5,'kg'],['pork_fat',500,'g'],['honey',150,'g'],['coarse_salt',45,'g'],['black_peppercorns',2,'tbsp'],['cinnamon',1,'tsp'],['white_wine',100,'ml'],['sausage_casings',null,''],['garlic',4,'clove']],
  s:{fr:["Taillez la viande et le gras au couteau en dés d'un demi-centimètre, jamais au hachoir : la donja se reconnaît à son grain visible à la coupe.","Mêlez-les au sel, au poivre concassé, à la cannelle, à l'ail pilé, au vin blanc et au miel légèrement tiédi.","Laissez macérer 24 heures au froid en remuant deux fois : le miel doit être entièrement absorbé, sinon il suinte au séchage.","Embossez fermement dans des boyaux fins, liez tous les vingt centimètres et piquez soigneusement toutes les poches d'air.","Séchez deux mois à 12 °C et 75 % d'humidité, jusqu'à perdre un tiers du poids. Une fleur blanche en surface est normale ; une moisissure verte se brosse au vinaigre."],
     en:["Cut the meat and fat by knife into half-centimetre dice, never by mincer: a donja is known by the visible grain of its slice.","Mix them with salt, cracked pepper, cinnamon, crushed garlic, white wine and lightly warmed honey.","Macerate 24 hours in the cold, stirring twice: the honey must be entirely absorbed, or it weeps during drying.","Fill thin casings firmly, tie every twenty centimetres and prick out every air pocket carefully.","Dry two months at 12°C and 75% humidity, until it has lost a third of its weight. White bloom on the surface is normal; green mould is brushed off with vinegar."]} },

{ id:'bull-negre-andorra', c:'eu', lat:42.5449, lon:1.5148, base:6, prep:90, cook:120, diff:3, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'other',food:['#3a2a2a','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Bull negre',en:'Bull negre'},
  p:{fr:'Anyós, La Massana, Andorre',en:'Anyós, La Massana, Andorra'},
  d:{fr:"Un gros boudin de sang embossé dans le gros intestin, tranché large et poêlé. Bull vient de bouilli : contrairement aux boudins secs, il ne se conserve pas et se mange dans la semaine de la matança, avec des haricots de montagne.",
     en:"A fat blood pudding cased in the large intestine, cut in wide slices and fried. Bull comes from boiled: unlike dry puddings it does not keep, and is eaten within the week of the matança, with mountain beans."},
  i:[['pork_blood',1.5,'l'],['pork_fat',600,'g'],['pork_head',1,'pc'],['onion',500,'g'],['black_peppercorns',2,'tbsp'],['cinnamon',1,'tsp'],['coarse_salt',40,'g'],['pork_stomach',2,'pc'],['white_beans',400,'g'],['garlic',6,'clove'],['olive_oil',60,'ml']],
  s:{fr:["Pochez la tête de porc 2 heures, désossez-la à chaud et taillez les chairs et les couennes en petits dés.","Faites fondre l'oignon dans le gras rendu 40 minutes, à feu très doux, jusqu'à ce qu'il soit blond et sans eau.","Mêlez le sang tamisé, les chairs, l'oignon et les épices ; la masse doit être assez lâche pour couler lentement de la louche.","Embossez dans le gros boyau en n'emplissant qu'aux deux tiers et liez fermement les deux bouts.","Pochez 1 h 30 à 80 °C en piquant à l'aiguille au bout de 15 minutes ; une piqûre qui laisse sortir un jus clair indique que c'est cuit. Se tranche épais et se poêle."],
     en:["Poach the pig's head 2 hours, bone it while hot and dice the meat and rinds small.","Melt the onion in the rendered fat for 40 minutes over very low heat, until pale and dry.","Combine the sieved blood, the meat, the onion and the spices; the mass should be loose enough to fall slowly from the ladle.","Case it in the large intestine, filling only two-thirds, and tie both ends firmly.","Poach 1½ hours at 80°C, pricking with a needle after 15 minutes; a prick that runs clear means it is done. Cut thick and fry."]} },

{ id:'bisbe-blanc', c:'eu', lat:42.5967, lon:1.5203, base:8, prep:120, cook:180, diff:3, tags:['pork','slow','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4f0e6',style:'other',food:['#e0c8b8','#f4f0e6','#c9924a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Bisbe blanc',en:'Bisbe blanc'},
  p:{fr:'Llorts, Ordino, Andorre',en:'Llorts, Ordino, Andorra'},
  d:{fr:"Le grand boudin blanc de la matança andorrane, farci de langue, de couennes et de viandes maigres, sans une goutte de sang. Il porte le nom d'évêque à cause de sa taille et de sa blancheur ; on le réservait au repas qui clôturait l'abattage, et il se coupe en tranches d'un centimètre.",
     en:"The great white pudding of the Andorran matança, filled with tongue, rinds and lean meat, without a drop of blood. It is called a bishop for its size and whiteness; it was kept for the meal that closed the killing, and is cut in centimetre slices."},
  i:[['pork_tongue',2,'pc'],['pork_shoulder',800,'g'],['pork_rinds',400,'g'],['pork_fat',300,'g'],['pork_stomach',1,'pc'],['black_peppercorns',2,'tbsp'],['nutmeg',1,'tsp'],['garlic',6,'clove'],['coarse_salt',45,'g'],['white_wine',150,'ml'],['bay_leaf',3,'pc']],
  s:{fr:["Pochez les langues 1 heure, pelez-les à chaud — la peau se retire d'un seul tenant tant qu'elles sont brûlantes — et taillez-les en gros dés.","Faites cuire les couennes 1 heure jusqu'à ce qu'elles soient tendres, et hachez-les grossièrement avec l'épaule et le gras.","Mêlez le tout au sel, au poivre concassé, à la muscade, à l'ail et au vin blanc, et laissez reposer une nuit.","Emplissez la panse aux trois quarts et cousez-la à l'aiguille en points serrés, en chassant l'air à mesure.","Pochez 3 heures à 80 °C, puis pressez sous une planche 24 heures au froid : c'est le pressage qui rend la tranche compacte et régulière."],
     en:["Poach the tongues for an hour, peel them hot — the skin comes away in one piece while they are scalding — and cut them into large dice.","Cook the rinds an hour until tender, and chop them coarsely with the shoulder and fat.","Mix everything with the salt, cracked pepper, nutmeg, garlic and white wine, and rest overnight.","Fill the stomach three-quarters full and sew it with close stitches, expelling the air as you go.","Poach 3 hours at 80°C, then press under a board for 24 hours in the cold: pressing is what makes the slice compact and even."]} },

{ id:'formatge-de-tupi', c:'eu', lat:42.5900, lon:1.5450, base:8, prep:40, cook:0, diff:2, tags:['cheese','slow','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Formatge de tupí',en:'Tupí cheese'},
  p:{fr:'Vall de Sorteny, Ordino, Andorre',en:'Vall de Sorteny, Ordino, Andorra'},
  d:{fr:"Des restes de fromages de brebis broyés, arrosés d'eau-de-vie et laissés fermenter des mois dans un pot de terre. Le tupí est le pot lui-même : on ne le vide jamais entièrement, on rajoute du fromage par-dessus, et certains pots de famille tournent depuis des générations.",
     en:"Leftover ewe's cheeses crushed, doused with brandy and left to ferment for months in an earthenware pot. The tupí is the pot itself: it is never emptied, more cheese goes on top, and some family pots have been running for generations."},
  i:[['sheep_cheese',600,'g'],['brandy',150,'ml'],['olive_oil',50,'ml'],['garlic',2,'clove'],['black_peppercorns',1,'tbsp'],['bread',400,'g']],
  s:{fr:["Prenez des fromages de brebis secs et durs, ceux dont plus personne ne veut : le tupí est précisément fait pour eux.","Ôtez la croûte, râpez-les grossièrement et écrasez-les au pilon avec l'ail et le poivre jusqu'à obtenir une pâte grumeleuse.","Tassez dans un pot de grès en chassant l'air à chaque couche, et couvrez d'un doigt d'eau-de-vie.","L'eau-de-vie doit toujours affleurer : c'est elle qui empêche la moisissure de prendre pendant que la fermentation travaille en dessous.","Couvrez d'un linge et d'un couvercle non hermétique, et laissez à la cave deux à quatre mois. Remuez chaque semaine. Se tartine sur du pain grillé, en très petite quantité."],
     en:["Take dry, hard ewe's cheeses, the ones nobody wants any more: tupí is made precisely for them.","Cut off the rind, grate them coarsely and pound them with the garlic and pepper to a lumpy paste.","Pack into a stoneware pot, expelling air at each layer, and cover with a finger of brandy.","The brandy must always sit on top: it is what keeps mould off while fermentation works underneath.","Cover with a cloth and a loose lid, and leave in the cellar two to four months. Stir weekly. Spread on toast, in very small quantities."]} },

{ id:'borra-andorrana', c:'eu', lat:42.5766, lon:1.6673, base:6, prep:20, cook:50, diff:1, tags:['veg','soup','comfort'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f0e4c8',style:'soup',food:['#e8dcb8','#c9a878','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Borra',en:'Borra'},
  p:{fr:'Soldeu, Canillo, Andorre',en:'Soldeu, Canillo, Andorra'},
  d:{fr:"Une soupe épaisse de farine grillée et de lait, à laquelle on casse un œuf au dernier moment. C'était le déjeuner des bergers avant de monter aux estives : elle ne coûte rien, se fait en un quart d'heure et tient au corps jusqu'au soir.",
     en:"A thick soup of toasted flour and milk, with an egg broken into it at the last moment. It was the shepherds' breakfast before going up to the summer pastures: it costs nothing, takes a quarter of an hour and holds a body until evening."},
  i:[['flour',150,'g'],['whole_milk',1,'l'],['lard',80,'g'],['egg',6,'pc'],['sugar',2,'tbsp'],['cinnamon',1,'tsp'],['bread',200,'g'],['salt',null,'']],
  s:{fr:["Faites fondre le saindoux et jetez-y la farine ; remuez sans arrêt à feu doux jusqu'à ce qu'elle prenne une couleur noisette et sente le pain grillé.","Ce grillage dure une bonne dizaine de minutes : c'est lui qui fait toute la saveur de la borra, une farine blanche ne donne qu'une colle fade.","Versez le lait chaud en filet en fouettant vigoureusement, pour ne pas laisser une seule motte.","Laissez épaissir 20 minutes à feu très doux en remuant souvent — le fond attache en un instant.","Cassez les œufs dans la soupe frémissante et laissez-les prendre 3 minutes sans remuer. Sucrez et cannellez, ou salez selon l'heure du jour."],
     en:["Melt the lard and throw in the flour; stir constantly over low heat until it turns hazelnut brown and smells of toast.","That toasting takes a good ten minutes: it is where all the flavour of borra comes from, white flour gives only a bland paste.","Pour in the hot milk in a stream, whisking hard, so that not a single lump forms.","Let it thicken for 20 minutes over very low heat, stirring often — the base catches in an instant.","Break the eggs into the simmering soup and let them set for 3 minutes without stirring. Sugar and cinnamon, or salt, depending on the hour."]} },

{ id:'cargols-a-la-llauna', c:'eu', lat:42.4700, lon:1.5000, base:4, prep:120, cook:25, diff:2, tags:['fresh','grill','festive'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#c9a878','#e8dcb8','#7fae5a','#e0b45a'],garnish:'#6fbf8f'},
  n:{fr:'Cargols a la llauna',en:'Cargols a la llauna'},
  p:{fr:'Aixirivall, Sant Julià de Lòria, Andorre',en:'Aixirivall, Sant Julià de Lòria, Andorra'},
  d:{fr:"Des escargots grillés à sec sur une plaque de tôle, ouverture vers le haut, et trempés dans un aïoli. La llauna est la tôle elle-même : posée sur les braises, elle chauffe assez fort pour que l'escargot cuise dans son propre jus sans une goutte de graisse.",
     en:"Snails grilled dry on a sheet of tin, mouth upward, and dipped in aioli. The llauna is the tin itself: set over coals, it heats fiercely enough for the snail to cook in its own juice without a drop of fat."},
  i:[['snails',60,'pc'],['garlic',8,'clove'],['egg_yolk',2,'pc'],['olive_oil',250,'ml'],['lemon',1,'pc'],['sweet_paprika',1,'tsp'],['cayenne',1,'pinch'],['parsley',3,'tbsp'],['bread',300,'g'],['coarse_salt',2,'tbsp'],['pepper',null,'']],
  s:{fr:["Faites jeûner les escargots une semaine dans une caisse aérée, puis dégorgez-les 2 heures au gros sel et rincez-les jusqu'à ce que l'eau soit claire.","Rangez-les sur la tôle ouverture vers le haut, bien serrés, et salez-les d'une pincée de gros sel chacun.","Posez la tôle sur les braises : ils bavent quelques minutes, puis la bave sèche et l'escargot se rétracte — c'est le signe qu'ils sont à mi-cuisson.","Comptez 20 minutes en tout et n'arrosez de rien : toute matière grasse noierait le goût et ferait fumer la tôle.","Pendant ce temps, montez un aïoli à l'ail pilé et à l'huile versée en filet. Servez les escargots brûlants, à la pique, avec l'aïoli et du pain."],
     en:["Fast the snails a week in an airy box, then purge them 2 hours in coarse salt and rinse until the water runs clear.","Set them on the tin mouth upward, packed tight, and give each a pinch of coarse salt.","Put the tin over the coals: they froth for a few minutes, then the froth dries and the snail retracts — the sign they are half done.","Allow 20 minutes in all and baste with nothing: any fat would drown the flavour and make the tin smoke.","Meanwhile make an aioli with pounded garlic and oil trickled in. Serve the snails scalding, on picks, with the aioli and bread."]} },

{ id:'torro-d-andorra', c:'eu', lat:42.5075, lon:1.5195, base:12, prep:60, cook:20, diff:3, tags:['sweet','festive','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Torró d’Andorre',en:'Andorran torró'},
  p:{fr:'Andorre-la-Vieille, Andorre',en:'Andorra la Vella, Andorra'},
  d:{fr:"Un nougat de miel de montagne et de noisettes, plus foncé et plus rustique que celui d'Alicante. Les colporteurs andorrans le vendaient dans toute la Catalogne à Noël ; le miel de bruyère des vallées hautes lui donne une amertume que le sucre seul n'atteint pas.",
     en:"A nougat of mountain honey and hazelnuts, darker and rougher than the Alicante kind. Andorran pedlars sold it across Catalonia at Christmas; the heather honey of the high valleys gives it a bitterness sugar alone never reaches."},
  i:[['honey',400,'g'],['sugar',200,'g'],['egg_white',2,'pc'],['hazelnuts',400,'g'],['almonds',150,'g'],['rice_paper',4,'sheet'],['lemon_zest',1,'pc'],['cinnamon',1,'tsp']],
  s:{fr:["Faites torréfier les noisettes 12 minutes à 160 °C et frottez-les dans un linge pour ôter les peaux : une peau oubliée rend le nougat amer par endroits.","Faites cuire le miel seul 20 minutes à feu doux pour évaporer son eau, puis ajoutez le sucre et montez à 140 °C.","Montez les blancs en neige ferme et versez le miel brûlant en filet mince, sans cesser de fouetter : versé d'un coup, il cuirait les blancs en grumeaux.","Continuez de battre 15 minutes au bain-marie, jusqu'à ce qu'une goutte jetée dans l'eau froide durcisse aussitôt.","Incorporez les fruits secs tièdes, versez entre deux feuilles de papier azyme et pressez sous un poids 24 heures avant de couper."],
     en:["Roast the hazelnuts 12 minutes at 160°C and rub them in a cloth to remove the skins: one skin left makes the nougat bitter in patches.","Cook the honey alone for 20 minutes over low heat to drive off its water, then add the sugar and take it to 140°C.","Whisk the whites to firm peaks and pour in the scalding honey in a thin stream, whisking without pause: poured at once it would scramble them.","Keep beating 15 minutes over a bain-marie, until a drop thrown into cold water hardens immediately.","Fold in the warm nuts, pour between two sheets of rice paper and press under a weight for 24 hours before cutting."]} },

{ id:'mato-amb-mel', c:'eu', lat:42.5361, lon:1.5836, base:4, prep:180, cook:20, diff:2, tags:['cheese','sweet','fresh'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8c46a','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Mató au miel',en:'Mató with honey'},
  p:{fr:'Encamp, Andorre',en:'Encamp, Andorra'},
  d:{fr:"Un fromage frais caillé sans sel, servi noyé de miel de montagne et de noix. Le mató ne se sale jamais et ne s'affine pas : il se mange dans les deux jours, et c'est son absence totale de sel qui laisse toute la place au miel.",
     en:"A fresh unsalted curd cheese, served drowned in mountain honey and walnuts. Mató is never salted and never aged: it is eaten within two days, and its complete lack of salt is what leaves all the room to the honey."},
  i:[['whole_milk',2,'l'],['rennet',5,'drizzle'],['honey',150,'g'],['walnuts',100,'g'],['lemon',1,'pc']],
  s:{fr:["Chauffez le lait cru à 35 °C exactement : plus chaud, la présure travaille trop vite et le caillé devient caoutchouteux.","Ajoutez la présure, remuez dix secondes puis laissez immobile 45 minutes, sans jamais toucher au récipient — la moindre secousse brise le caillé en formation.","Tranchez le caillé en quadrillage de 2 cm et laissez-le se raffermir 15 minutes.","Prélevez-le à l'écumoire et déposez-le dans des faisselles ; laissez égoutter 2 heures, sans presser.","Démoulez, arrosez généreusement de miel et parsemez de cerneaux de noix. Ne salez sous aucun prétexte."],
     en:["Heat the raw milk to exactly 35°C: any hotter and the rennet works too fast and the curd turns rubbery.","Add the rennet, stir for ten seconds then leave it absolutely still for 45 minutes, never touching the vessel — the least jolt breaks the forming curd.","Cut the curd in a 2 cm grid and let it firm up for 15 minutes.","Lift it out with a skimmer into moulds; drain for 2 hours, without pressing.","Turn out, pour honey over generously and scatter walnut halves. Do not salt under any circumstances."]} },

{ id:'coques-d-oli-i-anis', c:'eu', lat:42.5450, lon:1.4790, base:10, prep:90, cook:20, diff:1, tags:['sweet','bake','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Coques à l’huile et à l’anis',en:'Oil and anise coques'},
  p:{fr:'Pal, La Massana, Andorre',en:'Pal, La Massana, Andorra'},
  d:{fr:"De fines galettes sucrées à l'huile d'olive et à l'anis, cuites sans levure et croquantes comme du verre. On les faisait pour les fêtes patronales des villages : elles se transportent sans se briser dans un torchon et se gardent un mois entier.",
     en:"Thin sweet biscuits of olive oil and anise, baked without leaven and crisp as glass. They were made for the village patron saints' days: they travel unbroken in a cloth and keep for a whole month."},
  i:[['flour',400,'g'],['olive_oil',150,'ml'],['sugar',150,'g'],['anisette',60,'ml'],['anise_seeds',1,'tbsp'],['lemon_zest',1,'pc'],['white_wine',60,'ml'],['salt',null,'']],
  s:{fr:["Faites tiédir l'huile d'olive avec les graines d'anis et le zeste, et laissez infuser une heure avant de filtrer.","Mêlez-la à la farine, à 80 g de sucre, à l'anisette, au vin blanc et au sel, et rassemblez la pâte sans la pétrir.","Laissez-la reposer 30 minutes : détendue, elle s'abaisse deux fois plus fin.","Étalez au rouleau jusqu'à 2 mm et découpez des ovales à la main plutôt qu'à l'emporte-pièce, pour garder des bords irréguliers.","Saupoudrez du sucre restant et cuisez 12 minutes à 190 °C. Sortez-les dès qu'elles blondissent aux bords : une coque brune est amère."],
     en:["Warm the olive oil with the anise seeds and zest, and infuse for an hour before straining.","Mix it with the flour, 80 g of the sugar, the anisette, white wine and salt, and bring the dough together without kneading.","Rest it for 30 minutes: relaxed, it rolls twice as thin.","Roll to 2 mm and cut ovals by hand rather than with a cutter, to keep uneven edges.","Sprinkle with the remaining sugar and bake 12 minutes at 190°C. Take them out as soon as the edges go gold: a browned coca is bitter."]} },

{ id:'civet-d-isard', c:'eu', lat:42.5900, lon:1.6600, base:6, prep:60, cook:210, diff:3, tags:['slow','festive','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#4f3a2a','#6f2a2a','#8f5a3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Civet d’isard',en:'Pyrenean chamois civet'},
  p:{fr:'Vall d’Incles, Canillo, Andorre',en:'Vall d’Incles, Canillo, Andorra'},
  d:{fr:"L'isard des Pyrénées mariné trois jours au vin rouge puis mijoté longuement, la sauce liée au sang. L'animal vit au-dessus de deux mille mètres et sa chair est maigre et nerveuse : sans la marinade et sans le lard qui la nourrit, elle resterait sèche.",
     en:"Pyrenean chamois marinated three days in red wine then long stewed, the sauce bound with blood. The animal lives above two thousand metres and its flesh is lean and sinewy: without the marinade and the bacon that feeds it, it would stay dry."},
  i:[['venison',1.8,'kg'],['red_wine',1,'l'],['pork_blood',150,'ml'],['smoked_bacon',250,'g'],['onion',3,'pc'],['carrot',3,'pc'],['garlic',8,'clove'],['juniper_berries',12,'pc'],['bay_leaf',3,'pc'],['thyme',4,'sprig'],['dark_chocolate',20,'g'],['red_wine_vinegar',3,'tbsp'],['flour',40,'g'],['olive_oil',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner la viande en gros morceaux trois jours au froid, dans le vin, les légumes, le genièvre et les herbes, en la retournant chaque jour.","Égouttez et épongez la viande à fond : une viande mouillée bout au lieu de saisir, et le civet perd sa couleur sombre.","Saisissez-la par petites quantités, singez de farine, remettez la marinade filtrée et les légumes, et laissez mijoter 3 heures à couvert.","Recueillez le sang additionné de vinaigre — le vinaigre l'empêche de coaguler — et ne l'ajoutez qu'au tout dernier moment, hors du feu.","Le sang ne doit jamais bouillir, sinon la sauce grène irrémédiablement. Ajoutez le chocolat, remuez et servez aussitôt."],
     en:["Marinate the meat in large pieces for three days in the cold, in the wine, vegetables, juniper and herbs, turning it daily.","Drain and pat the meat thoroughly dry: wet meat boils instead of searing, and the civet loses its dark colour.","Sear it in small batches, dust with flour, return the strained marinade and the vegetables, and simmer covered for 3 hours.","Collect the blood mixed with vinegar — the vinegar stops it setting — and add it only at the very last moment, off the heat.","The blood must never boil, or the sauce grains irrecoverably. Add the chocolate, stir and serve at once."]} },

{ id:'truita-de-riu-amb-pernil', c:'eu', lat:42.5710, lon:1.5340, base:4, prep:20, cook:12, diff:1, tags:['sea','fast','pork'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ecd8',style:'fish',food:['#e0a8a0','#c9754a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Truite au jambon de montagne',en:'Trout with mountain ham'},
  p:{fr:'Sornàs, Ordino, Andorre',en:'Sornàs, Ordino, Andorra'},
  d:{fr:"Une truite enveloppée d'une tranche de jambon sec et poêlée, sans autre assaisonnement. Le jambon fait office de gras, de sel et de croûte à la fois : c'est le plat des vallées où le poisson et le cochon étaient les deux seules ressources sûres de l'année.",
     en:"A trout wrapped in a slice of dry-cured ham and pan-fried, with no other seasoning. The ham does the work of fat, salt and crust all at once: the dish of valleys where fish and pig were the only two reliable resources of the year."},
  i:[['trout',4,'pc'],['serrano_ham',8,'slice'],['olive_oil',60,'ml'],['garlic',4,'clove'],['lemon',2,'pc'],['parsley',3,'tbsp'],['pepper',null,'']],
  s:{fr:["Videz les truites et essuyez-les ; ne les salez surtout pas, le jambon s'en charge et une double salaison serait immangeable.","Glissez une gousse d'ail écrasée et un brin de persil dans chaque ventre.","Enroulez deux tranches de jambon en spirale autour de chaque poisson, en les faisant se chevaucher légèrement.","Poêlez à l'huile chaude 5 minutes par face, en commençant par la soudure du jambon pour qu'elle se colle en cuisant.","Le jambon doit être croustillant et la chair juste opaque à l'arête. Poivrez, citronnez et servez sans attendre."],
     en:["Gut the trout and wipe them; on no account salt them, the ham does that and a double salting would be inedible.","Slip a crushed garlic clove and a sprig of parsley into each belly.","Wind two slices of ham in a spiral around each fish, overlapping slightly.","Fry in hot oil 5 minutes a side, starting on the seam of the ham so that it seals as it cooks.","The ham should be crisp and the flesh just opaque at the bone. Pepper, squeeze lemon and serve at once."]} },

{ id:'bunyols-de-quaresma', c:'eu', lat:42.5085, lon:1.5365, base:8, prep:90, cook:25, diff:2, tags:['sweet','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Bunyols de carême',en:'Lenten bunyols'},
  p:{fr:'Escaldes-Engordany, Andorre',en:'Escaldes-Engordany, Andorra'},
  d:{fr:"De petits beignets levés à l'anis et au zeste, frits et roulés dans le sucre, mangés pendant le carême. Ils sont maigres au sens religieux : ni beurre ni saindoux, seulement de l'huile — et c'est justement pour cela qu'on avait le droit d'en manger.",
     en:"Small yeasted fritters with anise and zest, fried and rolled in sugar, eaten through Lent. They are lean in the religious sense: no butter, no lard, only oil — and that is precisely why they were permitted."},
  i:[['flour',500,'g'],['fresh_yeast',25,'g'],['whole_milk',200,'ml'],['egg',3,'pc'],['sugar',150,'g'],['olive_oil',80,'ml'],['anisette',40,'ml'],['lemon_zest',1,'pc'],['orange_zest',1,'pc'],['frying_oil',1.5,'l'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède et laissez-la mousser un quart d'heure avant de rien ajouter d'autre.","Pétrissez avec la farine, les œufs, 60 g de sucre, les zestes, l'anisette, l'huile d'olive et le sel, 12 minutes.","Laissez lever 1 h 30 : la pâte doit être molle et collante, on la travaille les mains huilées et jamais farinées.","Formez des anneaux en perçant chaque boule d'un doigt huilé et laissez-les pousser 30 minutes sur un linge.","Frites 2 minutes par face à 170 °C — pas plus chaud, sinon ils brunissent avant que le centre soit cuit. Roulez-les tièdes dans le sucre restant."],
     en:["Dissolve the yeast in warm milk and let it foam for a quarter of an hour before adding anything else.","Knead with the flour, eggs, 60 g of the sugar, the zests, anisette, olive oil and salt for 12 minutes.","Prove for 1½ hours: the dough should be soft and sticky, worked with oiled hands and never floured ones.","Form rings by piercing each ball with an oiled finger and let them rise 30 minutes on a cloth.","Fry 2 minutes a side at 170°C — no hotter, or they brown before the centre cooks. Roll them warm in the remaining sugar."]} },

{ id:'vi-calent-de-muntanya', c:'eu', lat:42.5757, lon:1.6503, base:6, prep:10, cook:20, diff:1, tags:['drink','fast','comfort'],
  art:{v:'glass',bg:'#2b2419',plate:'#f4f0e6',style:'drink',food:['#6f2a2a','#8f3b2a','#e0b45a','#c9754a'],garnish:'#c9754a'},
  n:{fr:'Vin chaud de montagne',en:'Mountain mulled wine'},
  p:{fr:'El Tarter, Canillo, Andorre',en:'El Tarter, Canillo, Andorra'},
  d:{fr:"Du vin rouge chauffé au miel, à la cannelle et à l'écorce d'orange, servi aux refuges après la descente. Toute la difficulté tient à la température : au-delà de 78 °C l'alcool s'évapore, et il ne reste qu'un sirop chaud sans caractère.",
     en:"Red wine warmed with honey, cinnamon and orange peel, served in the refuges after the descent. The whole difficulty is temperature: above 78°C the alcohol evaporates and nothing is left but a warm, characterless syrup."},
  i:[['red_wine',1.5,'l'],['honey',150,'g'],['cinnamon',3,'stick'],['orange',2,'pc'],['lemon',1,'pc'],['cloves',8,'pc'],['star_anise',3,'pc'],['brandy',80,'ml'],['sugar',60,'g']],
  s:{fr:["Prélevez les zestes d'orange et de citron au couteau économe, en évitant le blanc de la peau qui apporterait de l'amertume.","Piquez une orange entière de clous de girofle et mettez-la dans le vin froid avec les zestes, la cannelle et l'anis étoilé.","Montez lentement à 70 °C et maintenez-y 20 minutes sans jamais frémir : c'est une infusion, pas une cuisson.","Ajoutez le miel et le sucre hors du feu et remuez jusqu'à dissolution, puis l'eau-de-vie en dernier.","Filtrez et servez brûlant dans des verres épais préalablement ébouillantés, sinon ils se fendent."],
     en:["Pare the orange and lemon zest with a peeler, avoiding the white pith which would bring bitterness.","Stud a whole orange with cloves and put it in the cold wine with the zests, cinnamon and star anise.","Bring slowly to 70°C and hold it there for 20 minutes without ever letting it tremble: this is an infusion, not cooking.","Add the honey and sugar off the heat and stir until dissolved, then the brandy last.","Strain and serve scalding in thick glasses scalded beforehand, otherwise they crack."]} },

{ id:'pescaito-frito', c:'eu', lat:36.719, lon:-4.393, base:4, prep:30, cook:15, diff:2, tags:['sea','fry','street'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ecd8',style:'fish',food:['#e8c46a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Pescaíto frito',en:'Pescaíto frito'},
  p:{fr:'El Palo, Málaga, Andalousie, Espagne',en:'El Palo, Málaga, Andalusia, Spain'},
  d:{fr:"Une friture de petits poissons enrobés de farine de blé dur et jetés dans l'huile d'olive brûlante. La friture andalouse ne panne pas et n'utilise ni œuf ni chapelure : la farine seule forme une pellicule si fine qu'on voit la peau du poisson au travers.",
     en:"A fry of small fish coated in durum flour and dropped into scalding olive oil. Andalusian frying uses neither egg nor breadcrumb: flour alone makes a film so thin the fish's skin shows through it."},
  i:[['anchovies',400,'g'],['red_mullet',400,'g'],['squid',300,'g'],['semolina_flour',300,'g'],['olive_oil',1.5,'l'],['lemon',3,'pc'],['coarse_salt',2,'tbsp'],['parsley',3,'tbsp']],
  s:{fr:["Salez les poissons entiers une demi-heure avant, puis épongez-les : le sel tire l'eau de surface, et c'est cette eau qui ferait éclabousser l'huile.","Farinez-les dans un tamis à farine de semoule et secouez-les fortement — un excès de farine se détache dans l'huile et la brûle.","Portez l'huile d'olive à 190 °C : plus froide, le poisson la boit ; plus chaude, la farine noircit avant que la chair soit cuite.","Frites par petites poignées, 90 secondes seulement, en ne remplissant jamais plus du tiers de la friteuse.","Égouttez debout dans une passoire plutôt qu'à plat sur du papier, pour que la vapeur ne ramollisse pas le dessous. Salez et citronnez à table."],
     en:["Salt the whole fish half an hour ahead, then blot them: salt draws out the surface water, and it is that water that makes oil spit.","Flour them in a sieve of semolina flour and shake them hard — excess flour falls off into the oil and burns it.","Bring the olive oil to 190°C: cooler, the fish drinks it; hotter, the flour blackens before the flesh cooks.","Fry in small handfuls, 90 seconds only, never filling more than a third of the pan.","Drain upright in a colander rather than flat on paper, so steam does not soften the underside. Salt and lemon at the table."]} },

{ id:'tortillitas-de-camarones', c:'eu', lat:36.462, lon:-6.198, base:4, prep:40, cook:15, diff:2, tags:['sea','fry','street'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ecd8',style:'flat',food:['#e0b45a','#f2dfa8','#e07a6a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Tortillitas de camarones',en:'Shrimp fritters'},
  p:{fr:'San Fernando, Cadix, Andalousie, Espagne',en:'San Fernando, Cádiz, Andalusia, Spain'},
  d:{fr:"Des galettes dentelées de crevettes minuscules, faites d'une pâte à la farine de pois chiche et à l'eau de mer. Les camarones se mangent entiers, carapace comprise ; la pâte doit être si liquide qu'elle s'étale d'elle-même dans l'huile.",
     en:"Lace-edged fritters of minute shrimps, made from a batter of chickpea flour and seawater. The camarones are eaten whole, shell and all; the batter must be so thin that it spreads by itself in the oil."},
  i:[['small_shrimp',300,'g'],['chickpea_flour',100,'g'],['flour',100,'g'],['spring_onion',4,'pc'],['parsley',5,'tbsp'],['water',400,'ml'],['olive_oil',700,'ml'],['sweet_paprika',1,'tsp'],['salt',null,'']],
  s:{fr:["Mêlez les deux farines, l'oignon vert et le persil hachés très fin, et le paprika.","Versez l'eau froide en fouettant jusqu'à obtenir une pâte de la consistance d'une crème liquide — bien plus fluide qu'une pâte à crêpes.","Ajoutez les crevettes crues entières et laissez reposer 1 heure au froid : la pâte doit détendre, et les crevettes rendre un peu de leur eau salée.","Salez peu, voire pas du tout, si vous avez employé de l'eau de mer comme à San Fernando.","Versez une louche dans l'huile à 190 °C sans l'étaler : elle doit se répandre seule en un disque dentelé. 90 secondes par face, et servez immédiatement."],
     en:["Mix the two flours, the very finely chopped spring onion and parsley, and the paprika.","Whisk in cold water to the consistency of pouring cream — far thinner than pancake batter.","Add the raw whole shrimps and rest for an hour in the cold: the batter must relax, and the shrimps give up a little of their salty water.","Salt lightly, or not at all, if you have used seawater as they do in San Fernando.","Pour a ladleful into oil at 190°C without spreading it: it should run out by itself into a lacy disc. 90 seconds a side, and serve at once."]} },

{ id:'ajo-blanco', c:'eu', lat:36.828, lon:-4.205, base:4, prep:30, cook:0, diff:1, tags:['veg','soup','fresh'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'soup',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Ajo blanco',en:'Ajo blanco'},
  p:{fr:'Almáchar, Málaga, Andalousie, Espagne',en:'Almáchar, Málaga, Andalusia, Spain'},
  d:{fr:"Une soupe froide d'amandes, d'ail et de pain, servie avec des grains de raisin muscat. Elle précède le gazpacho de plusieurs siècles : c'est la soupe d'al-Andalus, faite avant que la tomate n'arrive d'Amérique, et l'ail y remplace le piment.",
     en:"A cold soup of almonds, garlic and bread, served with muscat grapes. It predates gazpacho by centuries: it is the soup of al-Andalus, made before the tomato arrived from America, and garlic stands in for the pepper."},
  i:[['almonds',200,'g'],['bread',150,'g'],['garlic',2,'clove'],['olive_oil',150,'ml'],['sherry_vinegar',3,'tbsp'],['water',800,'ml'],['grapes',200,'g'],['salt',null,'']],
  s:{fr:["Ébouillantez les amandes 1 minute et pincez-les pour ôter les peaux : une seule peau oubliée pique la soupe de brun et d'amertume.","Faites tremper la mie de pain rassis dans un peu d'eau, puis pressez-la à peine — elle doit rester humide.","Mixez longuement amandes, pain, ail et sel avec un tiers de l'eau, au moins 4 minutes, jusqu'à ce que la texture soit parfaitement lisse.","Versez l'huile d'olive en filet, moteur tournant, comme pour une mayonnaise : c'est cette émulsion qui donne la blancheur et l'onctuosité.","Détendez avec le reste d'eau glacée, acidulez au vinaigre de Xérès et laissez 3 heures au réfrigérateur. Servez avec du raisin muscat pelé."],
     en:["Blanch the almonds for a minute and pinch off the skins: one skin left specks the soup brown and bitter.","Soak the stale crumb in a little water, then barely press it — it must stay wet.","Blend the almonds, bread, garlic and salt at length with a third of the water, at least 4 minutes, until perfectly smooth.","Trickle in the olive oil with the motor running, as for mayonnaise: that emulsion is what gives the whiteness and the body.","Loosen with the rest of the iced water, sharpen with sherry vinegar and chill for 3 hours. Serve with peeled muscat grapes."]} },

{ id:'flamenquin-cordobes', c:'eu', lat:37.888, lon:-4.779, base:4, prep:45, cook:15, diff:2, tags:['pork','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'roll',food:['#c9924a','#e0b45a','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Flamenquín',en:'Flamenquín'},
  p:{fr:'Andújar, Cordoue, Andalousie, Espagne',en:'Andújar, Córdoba, Andalusia, Spain'},
  d:{fr:"Un rouleau d'escalope de porc enroulée autour de jambon serrano, pané et frit. Le nom viendrait de la couleur dorée, rappelant les cheveux blonds des Flamands de la cour de Charles Quint ; il se mange froid en tapa autant que chaud en assiette.",
     en:"A roll of pork escalope wrapped around serrano ham, crumbed and fried. The name is said to come from the golden colour, recalling the fair hair of the Flemings at Charles V's court; it is eaten cold as a tapa as readily as hot on a plate."},
  i:[['pork_loin',600,'g'],['serrano_ham',8,'slice'],['egg',3,'pc'],['breadcrumbs',250,'g'],['flour',100,'g'],['olive_oil',800,'ml'],['garlic',2,'clove'],['parsley',3,'tbsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le filet en escalopes et aplatissez-les entre deux films jusqu'à 3 mm, en frappant du plat et non du tranchant du maillet.","Poivrez mais ne salez pas : le jambon serrano apporte tout le sel nécessaire.","Posez une tranche de jambon sur chaque escalope et roulez très serré, en chassant l'air ; réfrigérez 30 minutes pour que le rouleau tienne.","Farinez, passez à l'œuf battu puis à la chapelure, et recommencez œuf et chapelure une seconde fois — c'est cette double panure qui empêche le rouleau de s'ouvrir.","Frites 5 minutes à 170 °C en les roulant dans l'huile, et égouttez debout. Se coupent en biseau."],
     en:["Cut the loin into escalopes and beat them between two films to 3 mm, striking with the flat and not the edge of the mallet.","Pepper but do not salt: the serrano ham brings all the salt needed.","Lay a slice of ham on each escalope and roll very tightly, expelling the air; chill 30 minutes so the roll holds.","Flour, dip in beaten egg then breadcrumbs, and repeat egg and crumb a second time — that double coating is what stops the roll opening.","Fry 5 minutes at 170°C, rolling them in the oil, and drain upright. Cut on the bias."]} },

{ id:'espetos-de-sardinas', c:'eu', lat:36.719, lon:-4.383, base:4, prep:30, cook:10, diff:2, tags:['sea','grill','street'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'skewer',food:['#8f8f7a','#c9924a','#e8dcc0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Espetos de sardines',en:'Sardine espetos'},
  p:{fr:'Pedregalejo, Málaga, Andalousie, Espagne',en:'Pedregalejo, Málaga, Andalusia, Spain'},
  d:{fr:"Six sardines embrochées sur une canne et plantées en biais devant un feu de bois, dans une vieille barque emplie de sable. Elles ne se font qu'aux mois sans R, de mai à août, quand la sardine est grasse : maigre, elle se dessèche avant d'avoir cuit.",
     en:"Six sardines threaded on a cane and planted at an angle before a wood fire, in an old boat filled with sand. They are made only in the months without an R, May to August, when sardines are fat: lean, they dry out before they are done."},
  i:[['sardines',24,'pc'],['coarse_salt',150,'g'],['olive_oil',60,'ml'],['lemon',3,'pc'],['bread',400,'g']],
  s:{fr:["Ne videz ni n'écaillez les sardines : les viscères parfument la chair pendant la cuisson et l'écaille protège la peau du feu.","Embrochez-les par le flanc, sous l'arête centrale, six par canne, en les alignant toutes tête dans le même sens.","Salez généreusement au gros sel une demi-heure avant, en insistant sur la peau, et laissez-les à l'air.","Plantez la canne dans le sable en biais, à trente centimètres des braises, face ventre vers le feu d'abord.","Comptez 4 minutes de ce côté puis retournez la canne entière : la sardine est cuite quand l'œil blanchit et que la peau se fend. Ne la retournez jamais deux fois."],
     en:["Neither gut nor scale the sardines: the viscera scent the flesh as it cooks and the scales protect the skin from the fire.","Thread them through the flank, under the backbone, six to a cane, all heads facing the same way.","Salt generously with coarse salt half an hour ahead, working it into the skin, and leave them in the open air.","Plant the cane at an angle in the sand, thirty centimetres from the coals, belly side to the fire first.","Give them 4 minutes on that side then turn the whole cane: a sardine is done when the eye whitens and the skin splits. Never turn it twice."]} },

{ id:'cazon-en-adobo', c:'eu', lat:36.532, lon:-6.293, base:4, prep:30, cook:15, diff:2, tags:['sea','fry','street'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4ecd8',style:'other',food:['#e0b45a','#f2dfa8','#c9924a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Cazón en adobo',en:'Cazón en adobo'},
  p:{fr:'Cadix, Andalousie, Espagne',en:'Cádiz, Andalusia, Spain'},
  d:{fr:"Des cubes d'aiguillat marinés au vinaigre, à l'ail et au cumin, puis farinés et frits. L'adobo n'est pas un assaisonnement mais une conservation : le vinaigre gardait le poisson deux jours avant l'invention du froid, et le cumin est un héritage direct d'al-Andalus.",
     en:"Cubes of dogfish marinated in vinegar, garlic and cumin, then floured and fried. The adobo is not a seasoning but a preservation: vinegar kept the fish two days before refrigeration, and the cumin is a direct inheritance from al-Andalus."},
  i:[['dogfish',800,'g'],['sherry_vinegar',150,'ml'],['garlic',6,'clove'],['cumin',1,'tbsp'],['oregano',1,'tbsp'],['sweet_paprika',1,'tbsp'],['bay_leaf',2,'pc'],['semolina_flour',200,'g'],['olive_oil',800,'ml'],['water',100,'ml'],['salt',null,'']],
  s:{fr:["Taillez le cazón en cubes de 3 cm en ôtant le cartilage central, qui se retire d'un seul tenant.","Pilez l'ail avec le cumin, l'origan, le paprika et le sel, puis délayez au vinaigre et à l'eau.","Faites mariner le poisson 4 heures au moins, 12 idéalement : moins longtemps, l'adobo ne pénètre pas ; plus longtemps, le vinaigre cuit la chair et la rend farineuse.","Égouttez sans rincer, épongez, et farinez à la semoule fine juste avant de frire.","Frites 3 minutes à 180 °C, par petites quantités. Servez brûlant, sans citron : l'acidité est déjà dans le poisson."],
     en:["Cut the cazón into 3 cm cubes, removing the central cartilage, which comes away in one piece.","Pound the garlic with the cumin, oregano, paprika and salt, then slake with the vinegar and water.","Marinate the fish at least 4 hours, ideally 12: less and the adobo does not penetrate; longer and the vinegar cooks the flesh and turns it mealy.","Drain without rinsing, blot, and flour with fine semolina just before frying.","Fry 3 minutes at 180°C, in small batches. Serve scalding, without lemon: the acidity is already in the fish."]} },

{ id:'polea-andaluza', c:'eu', lat:37.389, lon:-5.984, base:4, prep:15, cook:30, diff:1, tags:['sweet','comfort','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Poleá andalouse',en:'Andalusian poleá'},
  p:{fr:'Séville, Andalousie, Espagne',en:'Seville, Andalusia, Spain'},
  d:{fr:"Une bouillie de farine, de lait et d'anis, couverte de croûtons frits et de cannelle. C'est le dessert des années de disette, quand il n'y avait ni œufs ni sucre en quantité ; les Sévillans continuent d'en manger par nostalgie et le servent à la Toussaint.",
     en:"A porridge of flour, milk and anise, covered with fried croutons and cinnamon. It is the pudding of the hungry years, when there were neither eggs nor sugar to spare; Sevillians still eat it out of nostalgia and serve it at All Saints."},
  i:[['flour',120,'g'],['whole_milk',1,'l'],['sugar',150,'g'],['anise_seeds',1,'tbsp'],['lemon_zest',1,'pc'],['cinnamon',2,'tsp'],['bread',200,'g'],['olive_oil',150,'ml'],['salt',null,'']],
  s:{fr:["Faites infuser le lait avec les graines d'anis, le zeste et un bâton de cannelle 15 minutes sans bouillir, puis filtrez.","Délayez la farine dans un verre de lait froid avant de rien verser de chaud : c'est le seul moyen sûr d'éviter les grumeaux.","Versez le lait infusé chaud sur la farine délayée en fouettant, puis remettez sur feu doux avec le sucre.","Remuez sans arrêt 20 minutes, en raclant les angles de la casserole : la poleá attache instantanément dès qu'on cesse.","Faites frire des dés de pain à l'huile d'olive, égouttez-les, et posez-les sur la bouillie tiède avec de la cannelle. Ils doivent rester croquants."],
     en:["Infuse the milk with the anise seeds, zest and a cinnamon stick for 15 minutes without boiling, then strain.","Slake the flour in a glass of cold milk before anything hot goes in: the only sure way to avoid lumps.","Pour the hot infused milk onto the slaked flour, whisking, then return to low heat with the sugar.","Stir without pause for 20 minutes, scraping the corners of the pan: poleá catches the instant you stop.","Fry bread dice in olive oil, drain them, and set them on the warm porridge with cinnamon. They must stay crisp."]} },

{ id:'pringa', c:'eu', lat:37.392, lon:-5.994, base:4, prep:20, cook:0, diff:1, tags:['pork','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#6f4a2a','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Pringá',en:'Pringá'},
  p:{fr:'Séville, Andalousie, Espagne',en:'Seville, Andalusia, Spain'},
  d:{fr:"Les viandes du cocido écrasées à la fourchette et tassées dans un petit pain rond. Pringar veut dire tremper : c'est un plat de récupération devenu la tapa la plus demandée de Séville, et il ne s'écrase jamais au robot.",
     en:"The meats from a cocido crushed with a fork and packed into a small round roll. Pringar means to dip: a leftovers dish that has become Seville's most-ordered tapa, and it is never crushed in a machine."},
  i:[['pork_belly',200,'g'],['blood_sausage',150,'g'],['chorizo',150,'g'],['beef_chuck',200,'g'],['bread_roll',4,'pc'],['garlic',2,'clove'],['olive_oil',20,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Prenez les viandes d'un cocido déjà cuit, encore tièdes : froides, la graisse fige et l'écrasement devient impossible.","Retirez les peaux du chorizo et du boudin, et ôtez les os et les cartilages du lard.","Écrasez le tout à la fourchette sur une planche, en travaillant chaque viande séparément avant de les mêler : elles n'ont pas la même résistance.","La texture doit rester filandreuse et grumeleuse — c'est la différence entre une pringá et une rillette.","Poivrez, ajoutez une pointe d'ail écrasé, et tassez généreusement dans un petit pain à peine chaud. Se mange sans couverts."],
     en:["Take the meats from an already-cooked cocido, still warm: cold, the fat sets and crushing becomes impossible.","Skin the chorizo and the black pudding, and remove any bone and gristle from the belly.","Crush everything with a fork on a board, working each meat separately before combining: they do not yield alike.","The texture must stay stringy and lumpy — that is the difference between a pringá and a potted meat.","Pepper, add a touch of crushed garlic, and pack it generously into a barely warm roll. Eaten with no cutlery."]} },

{ id:'pa-amb-tomaquet', c:'eu', lat:41.386, lon:2.170, base:4, prep:10, cook:5, diff:1, tags:['veg','fast','fresh'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9402c','#e0b45a','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pa amb tomàquet',en:'Pa amb tomàquet'},
  p:{fr:'Barcelone, Catalogne, Espagne',en:'Barcelona, Catalonia, Spain'},
  d:{fr:"Du pain grillé frotté de tomate mûre, arrosé d'huile d'olive et salé. On ne pose jamais la tomate en rondelles : on la coupe en deux et on la frotte jusqu'à ce qu'il n'en reste que la peau dans la main, pour que la pulpe entre dans la mie.",
     en:"Toasted bread rubbed with ripe tomato, dressed with olive oil and salted. The tomato is never laid on in slices: it is halved and rubbed until only the skin is left in your hand, so the pulp goes into the crumb."},
  i:[['rustic_bread',8,'slice'],['ripe_tomato',4,'pc'],['garlic',2,'clove'],['olive_oil',80,'ml'],['coarse_salt',1,'tbsp']],
  s:{fr:["Choisissez un pain de campagne à mie serrée et à croûte épaisse : un pain trop aéré se déchire sous le frottement.","Grillez les tranches des deux côtés jusqu'à ce qu'elles soient dorées mais souples au centre.","Frottez très légèrement d'une gousse d'ail coupée — l'ail est facultatif, et à Barcelone beaucoup s'en passent.","Coupez la tomate en deux et frottez la chair sur la mie chaude en pressant, jusqu'à ce que la tranche soit rouge et humide.","Arrosez d'huile d'olive en filet et salez au gros sel. Se mange dans les cinq minutes, sinon le pain se détrempe."],
     en:["Choose a country loaf with a tight crumb and a thick crust: too airy a bread tears under the rubbing.","Toast the slices on both sides until golden but still soft in the middle.","Rub very lightly with a cut garlic clove — the garlic is optional, and many in Barcelona go without.","Halve the tomato and rub the cut flesh onto the hot crumb, pressing, until the slice is red and damp.","Trickle over olive oil and salt with coarse salt. Eaten within five minutes, or the bread goes soggy."]} },

{ id:'botifarra-amb-mongetes', c:'eu', lat:41.930, lon:2.255, base:4, prep:20, cook:30, diff:1, tags:['pork','legume','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#8f5a3a','#e8dcb8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Botifarra amb mongetes',en:'Botifarra with beans'},
  p:{fr:'Vic, Catalogne, Espagne',en:'Vic, Catalonia, Spain'},
  d:{fr:"Une saucisse catalane grillée avec des haricots blancs sautés dans sa propre graisse. Les mongetes del ganxet, à peau si fine qu'elle disparaît sous la dent, ne se cultivent que dans un rayon de cinquante kilomètres autour de Vic et de Barcelone.",
     en:"A Catalan sausage grilled with white beans sautéed in its own fat. Mongetes del ganxet, whose skin is so fine it vanishes under the tooth, grow only within fifty kilometres of Vic and Barcelona."},
  i:[['botifarra',4,'pc'],['white_beans',500,'g'],['garlic',6,'clove'],['olive_oil',60,'ml'],['parsley',3,'tbsp'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots une nuit et cuisez-les 1 h 30 à petits frémissements avec le laurier, sans sel — le sel durcit la peau.","Ne salez qu'en fin de cuisson, et laissez-les refroidir dans leur eau : c'est ainsi qu'ils gardent leur forme.","Piquez les botifarres de deux coups d'aiguille seulement et faites-les cuire 15 minutes à la poêle, à feu doux, en les tournant souvent.","Retirez-les, gardez toute la graisse rendue et faites-y blondir l'ail émincé sans le brûler.","Jetez les haricots égouttés dans cette graisse et sautez-les 5 minutes en les remuant par mouvements de poêle, jamais à la cuillère qui les briserait. Persillez."],
     en:["Soak the beans overnight and cook them 1½ hours at a bare simmer with the bay, unsalted — salt hardens the skin.","Salt only at the end, and let them cool in their liquid: that is how they keep their shape.","Prick the botifarres just twice with a needle and cook them 15 minutes in a pan over low heat, turning often.","Lift them out, keep every drop of rendered fat and turn the sliced garlic pale gold in it without burning.","Tip the drained beans into that fat and sauté 5 minutes, moving them by shaking the pan, never with a spoon which would break them. Add parsley."]} },

{ id:'canelons-de-sant-esteve', c:'eu', lat:41.383, lon:2.181, base:6, prep:80, cook:40, diff:3, tags:['beef','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#c9924a','#e0b45a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Canelons de Sant Esteve',en:'Sant Esteve cannelloni'},
  p:{fr:'Barcelone, Catalogne, Espagne',en:'Barcelona, Catalonia, Spain'},
  d:{fr:"Les cannellonis du 26 décembre, farcis des restes de l'escudella de la veille et gratinés à la béchamel. Les cuisiniers italiens venus travailler à Barcelone au XIXᵉ siècle ont apporté la pâte ; les Catalans y ont mis ce qu'ils avaient, et la tradition est née d'un besoin domestique.",
     en:"The cannelloni of 26 December, filled with the remains of the previous day's escudella and gratinated under béchamel. Italian cooks who came to work in Barcelona in the 19th century brought the pasta; Catalans filled it with what they had, and the tradition was born of a household need."},
  i:[['cannelloni',24,'pc'],['beef_chuck',300,'g'],['pork_shoulder',300,'g'],['chicken',250,'g'],['chicken_liver',120,'g'],['onion',2,'pc'],['ripe_tomato',200,'g'],['brandy',60,'ml'],['whole_milk',900,'ml'],['flour',80,'g'],['butter',90,'g'],['gruyere_cheese',150,'g'],['nutmeg',1,'pinch'],['pine_nuts',50,'g'],['olive_oil',50,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites un sofregit d'oignon et de tomate râpée, 40 minutes à feu doux, jusqu'à ce qu'il n'en reste qu'une pâte brique.","Hachez les viandes cuites de la veille et les foies sautés deux fois au hachoir, ajoutez-les au sofregit et flambez au cognac.","Liez la farce d'une louche de béchamel et laissez-la refroidir complètement : chaude, elle déchire la pâte au roulage.","Cuisez les plaques al dente, étalez-les sur un linge humide, garnissez et roulez serré, soudure dessous.","Nappez de béchamel muscadée jusqu'à recouvrir, parsemez de fromage et de pignons, et gratinez 25 minutes à 200 °C."],
     en:["Make a sofregit of onion and grated tomato, 40 minutes over low heat, until only a brick-red paste remains.","Mince yesterday's cooked meats and the sautéed livers twice, add them to the sofregit and flame with brandy.","Bind the filling with a ladle of béchamel and cool it completely: warm, it tears the pasta as you roll.","Cook the sheets al dente, spread them on a damp cloth, fill and roll tightly, seam down.","Coat with nutmegged béchamel until covered, scatter cheese and pine nuts, and gratinate 25 minutes at 200°C."]} },

{ id:'gilda', c:'eu', lat:43.321, lon:-1.985, base:4, prep:15, cook:0, diff:1, tags:['sea','fast','street'],
  art:{v:'plate',bg:'#28331f',plate:'#f4f0e6',style:'skewer',food:['#7fae5a','#4f6f3a','#f0e8d0','#8f8f7a'],garnish:'#6fbf8f'},
  n:{fr:'Gilda',en:'Gilda'},
  p:{fr:'Saint-Sébastien, Pays basque, Espagne',en:'San Sebastián, Basque Country, Spain'},
  d:{fr:"Une olive, un piment vert au vinaigre et un anchois enfilés sur un cure-dent, arrosés d'huile. Créée au bar Casa Vallés en 1946, elle porte le nom du film de Rita Hayworth : verde, salada y un poco picante — verte, salée et un peu piquante, comme l'héroïne.",
     en:"An olive, a pickled green chilli and an anchovy on a cocktail stick, dressed with oil. Created at Casa Vallés in 1946, it is named after the Rita Hayworth film: verde, salada y un poco picante — green, salty and a little spicy, like the heroine."},
  i:[['guindilla_peppers',12,'pc'],['anchovy_fillets',8,'pc'],['green_olives',8,'pc'],['olive_oil',40,'ml']],
  s:{fr:["Choisissez des piments guindilla de Ibarra au vinaigre, longs et pâles : ils ne sont presque pas piquants, seulement acides.","Égouttez-les et épongez-les, ainsi que les anchois, sinon le vinaigre coule sur les doigts à la première bouchée.","Ôtez les queues des piments et pliez chacun en deux ou en trois selon sa longueur.","Enfilez sur le cure-dent dans cet ordre : olive, piment plié, anchois enroulé, piment plié, olive. L'ordre importe : l'anchois doit être au centre, protégé par le vinaigre.","Arrosez d'un filet d'huile d'olive et servez aussitôt, à température ambiante. Une gilda froide n'a aucun goût."],
     en:["Choose pickled Ibarra guindilla peppers, long and pale: they are barely hot, only sour.","Drain and blot them, and the anchovies too, or vinegar runs down your fingers at the first bite.","Pull off the pepper stalks and fold each in two or three depending on its length.","Thread onto the stick in this order: olive, folded pepper, coiled anchovy, folded pepper, olive. The order matters: the anchovy must sit in the centre, shielded by the vinegar.","Trickle over olive oil and serve at once, at room temperature. A cold gilda has no flavour at all."]} },

{ id:'talo-con-chistorra', c:'eu', lat:43.134, lon:-2.075, base:4, prep:25, cook:20, diff:2, tags:['pork','street','bread'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e8c46a','#c9402c','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Talo con chistorra',en:'Talo con chistorra'},
  p:{fr:'Tolosa, Pays basque, Espagne',en:'Tolosa, Basque Country, Spain'},
  d:{fr:"Une galette de maïs cuite sur la plaque, roulée autour d'une chistorra grillée. Le talo était le pain quotidien du Pays basque avant que le blé n'y devienne courant ; il ne subsiste que dans les fêtes de village, où on le prépare devant les gens.",
     en:"A maize flatbread cooked on a griddle, rolled around a grilled chistorra. Talo was the daily bread of the Basque Country before wheat became common there; it survives only at village festivals, made in front of the crowd."},
  i:[['corn_flour',300,'g'],['warm_water',250,'ml'],['chistorra',400,'g'],['sheep_cheese',150,'g'],['salt',null,'']],
  s:{fr:["Mêlez la farine de maïs, le sel et l'eau très chaude, et travaillez à la cuillère puis à la main dès que possible : l'eau doit être bouillante, une eau tiède ne prend pas la farine.","Pétrissez 5 minutes en une boule souple et laissez reposer 15 minutes sous un linge humide.","Aplatissez des boules entre deux films en disques de 2 mm : sans gluten, la pâte se déchire, et il faut la rapiécer du bout des doigts.","Cuisez sur une plaque très chaude et sèche, 2 minutes par face — la galette gonfle un peu et se marque de taches brunes.","Grillez la chistorra, posez-la sur le talo brûlant avec un copeau de fromage de brebis, roulez et mangez à la main sans attendre."],
     en:["Mix the maize flour, salt and very hot water, working with a spoon then by hand as soon as you can: the water must be boiling, warm water will not take the flour.","Knead 5 minutes into a supple ball and rest it 15 minutes under a damp cloth.","Flatten balls between two films into 2 mm discs: without gluten the dough tears, and you patch it with your fingertips.","Cook on a very hot dry griddle, 2 minutes a side — the flatbread puffs a little and blisters brown.","Grill the chistorra, lay it on the scalding talo with a shaving of ewe's cheese, roll it and eat with your hands at once."]} },

{ id:'bocadillo-de-calamares', c:'eu', lat:40.415, lon:-3.707, base:4, prep:30, cook:15, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Bocadillo de calamares',en:'Calamari sandwich'},
  p:{fr:'Plaza Mayor, Madrid, Espagne',en:'Plaza Mayor, Madrid, Spain'},
  d:{fr:"Des anneaux de calmar frits entassés dans un petit pain, sans sauce ni garniture. Madrid est à trois cents kilomètres de la mer : le bocadillo est né de la gare de fret, où le poisson arrivait de nuit, et la ville en a fait son emblème le plus improbable.",
     en:"Fried squid rings piled into a roll, with no sauce and no garnish. Madrid is three hundred kilometres from the sea: the bocadillo was born at the freight station where fish arrived overnight, and the city made it its most improbable emblem."},
  i:[['squid',800,'g'],['whole_milk',300,'ml'],['flour',200,'g'],['olive_oil',1,'l'],['bread_roll',4,'pc'],['lemon',2,'pc'],['garlic',2,'clove'],['salt',null,'']],
  s:{fr:["Nettoyez les calmars et coupez-les en anneaux d'un centimètre exactement : plus fins ils sèchent, plus épais ils restent crus au centre.","Faites-les tremper 2 heures dans le lait — c'est le seul attendrissement que Madrid pratique, et il change tout sur un calmar de congélation.","Égouttez-les, épongez-les puis farinez-les dans un sac secoué, et tamisez l'excédent.","Frites à 190 °C, 90 secondes, par petites poignées : au-delà de deux minutes la chair se rétracte et devient élastique.","Fendez le pain sans le beurrer et entassez les anneaux brûlants. Un quartier de citron à part, jamais de sauce."],
     en:["Clean the squid and cut it into rings exactly a centimetre wide: thinner they dry out, thicker they stay raw in the middle.","Soak them 2 hours in milk — the only tenderising Madrid practises, and it transforms frozen squid.","Drain, blot, then flour them in a shaken bag, and sieve off the excess.","Fry at 190°C for 90 seconds, in small handfuls: beyond two minutes the flesh shrinks and turns elastic.","Split the roll without buttering it and pile in the scalding rings. A wedge of lemon on the side, never a sauce."]} },

{ id:'callos-a-la-madrilena', c:'eu', lat:40.417, lon:-3.703, base:6, prep:120, cook:240, diff:3, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9532c','#8f5a3a','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Callos à la madrilène',en:'Madrid-style tripe'},
  p:{fr:'Madrid, Espagne',en:'Madrid, Spain'},
  d:{fr:"Des tripes de bœuf mijotées avec du chorizo, du boudin et du museau, dans une sauce rouge de paprika. La gélatine du pied de veau lie la sauce sans farine : c'est à cela qu'on reconnaît des callos réussis, ils collent aux lèvres.",
     en:"Beef tripe stewed with chorizo, black pudding and snout, in a red paprika sauce. The gelatine from the calf's foot binds the sauce without flour: that is how good callos are known, they stick to the lips."},
  i:[['tripe',1.5,'kg'],['veal_foot',1,'pc'],['pork_snout',400,'g'],['chorizo',250,'g'],['blood_sausage',200,'g'],['serrano_ham',150,'g'],['onion',2,'pc'],['garlic',8,'clove'],['sweet_paprika',2,'tbsp'],['hot_paprika',1,'tsp'],['white_vinegar',100,'ml'],['bay_leaf',3,'pc'],['cloves',4,'pc'],['olive_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Frottez les tripes au gros sel et au vinaigre, rincez-les sept ou huit fois, jusqu'à ce que l'eau soit parfaitement claire — c'est long et c'est indispensable.","Blanchissez-les 15 minutes, jetez l'eau, puis remettez-les à cuire 3 heures avec le pied de veau, le museau, le laurier et les clous de girofle.","Le pied de veau n'est pas un ingrédient de goût : il apporte la gélatine qui liera la sauce, et sans lui les callos restent liquides.","Faites un sofrito d'oignon et d'ail, ajoutez le jambon, le paprika doux et fort hors du feu — brûlé, le paprika devient amer en trois secondes.","Réunissez tripes, sofrito, chorizo et boudin, et laissez mijoter 1 heure de plus. Reposez une nuit et réchauffez : ils sont meilleurs le lendemain."],
     en:["Scrub the tripe with coarse salt and vinegar, rinsing seven or eight times, until the water runs perfectly clear — it takes a while and it is essential.","Blanch 15 minutes, throw the water away, then cook 3 hours with the calf's foot, snout, bay and cloves.","The calf's foot is not there for flavour: it brings the gelatine that will bind the sauce, and without it callos stay thin.","Make a sofrito of onion and garlic, add the ham, and the sweet and hot paprika off the heat — burnt, paprika turns bitter in three seconds.","Combine tripe, sofrito, chorizo and black pudding, and simmer an hour more. Rest overnight and reheat: they are better the next day."]} },

{ id:'huevos-estrellados', c:'eu', lat:40.412, lon:-3.712, base:4, prep:20, cook:25, diff:1, tags:['pork','fast','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#e8c46a','#f4f0e6','#e0b45a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Huevos estrellados',en:'Broken eggs and chips'},
  p:{fr:'Madrid, Espagne',en:'Madrid, Spain'},
  d:{fr:"Des œufs frits cassés sur un lit de frites, écrasés à la fourchette à table pour que le jaune coule partout. Estrellar veut dire fracasser : le geste fait partie du plat, et il revient au client, jamais au cuisinier.",
     en:"Fried eggs broken over a bed of chips, crushed with a fork at the table so the yolk runs everywhere. Estrellar means to smash: the gesture is part of the dish, and it belongs to the customer, never the cook."},
  i:[['potato',1,'kg'],['egg',8,'pc'],['serrano_ham',150,'g'],['olive_oil',1,'l'],['coarse_salt',1,'tbsp'],['pepper',null,'']],
  s:{fr:["Taillez les pommes de terre en bâtonnets épais et faites-les d'abord confire 12 minutes à 140 °C dans l'huile d'olive, sans qu'elles colorent.","Sortez-les, laissez-les tiédir vingt minutes, puis replongez-les à 190 °C pour les dorer — les deux bains ne sont pas négociables.","Frites une seule fois, elles seraient molles à l'intérieur et se déferaient sous le jaune d'œuf.","Faites frire les œufs dans la même huile très chaude, en arrosant le blanc à la cuillère, jusqu'à ce que les bords soient dentelés et le jaune encore liquide.","Posez-les sur les frites, ajoutez le jambon en lamelles, salez au gros sel et cassez tout à la fourchette devant les convives."],
     en:["Cut the potatoes into thick batons and first confit them 12 minutes at 140°C in olive oil, without letting them colour.","Lift them out, let them cool for twenty minutes, then return them at 190°C to brown — the two baths are not negotiable.","Fried once only, they would be soft inside and would collapse under the yolk.","Fry the eggs in the same very hot oil, spooning it over the white, until the edges are lacy and the yolk still liquid.","Set them on the chips, add the ham in strips, salt with coarse salt and smash everything with a fork in front of your guests."]} },

{ id:'torreznos-de-soria', c:'eu', lat:41.764, lon:-2.465, base:4, prep:20, cook:90, diff:2, tags:['pork','slow','fry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'grill',food:['#c9924a','#e0b45a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Torreznos de Soria',en:'Soria torreznos'},
  p:{fr:'Soria, Castille-et-León, Espagne',en:'Soria, Castile and León, Spain'},
  d:{fr:"Des lardons de poitrine à la couenne soufflée en bulles régulières, croustillante comme du verre. Le torrezno de Soria est le seul d'Espagne à porter une marque de garantie ; le secret n'est pas dans la friture mais dans les trois jours de séchage qui la précèdent.",
     en:"Belly pork with rind blown into even bubbles, crisp as glass. The Soria torrezno is the only one in Spain with a guarantee mark; the secret is not in the frying but in the three days of drying that precede it."},
  i:[['pork_belly',1,'kg'],['coarse_salt',80,'g'],['olive_oil',500,'ml'],['water',200,'ml']],
  s:{fr:["Salez la poitrine à sec, couenne comprise, et laissez-la 24 heures au froid ; rincez et séchez-la ensuite trois jours à l'air frais.","Cette dessiccation de la couenne est tout le secret : humide, elle ne fera jamais de bulles et restera coriace.","Taillez des bandes de 3 cm et posez-les couenne vers le bas dans une poêle froide avec un doigt d'eau.","Chauffez doucement : l'eau s'évapore, la graisse fond et remplace le liquide sans que la couenne brûle. Comptez 45 minutes à feu très doux, couenne toujours dessous.","Montez enfin l'huile à 190 °C : la couenne éclate en bulles en une trentaine de secondes. Sortez-les aussitôt et salez."],
     en:["Dry-salt the belly, rind included, and leave it 24 hours in the cold; rinse then dry it for three days in cool air.","That drying of the rind is the whole secret: damp, it will never bubble and stays leathery.","Cut 3 cm strips and lay them rind down in a cold pan with a finger of water.","Heat gently: the water evaporates, the fat renders and replaces the liquid without the rind burning. Allow 45 minutes over very low heat, rind always down.","Finally take the oil to 190°C: the rind bursts into bubbles in about thirty seconds. Lift them out at once and salt."]} },

{ id:'all-i-pebre', c:'eu', lat:39.336, lon:-0.335, base:4, prep:30, cook:40, diff:2, tags:['sea','stew','comfort'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e4c8',style:'stew',food:['#c9532c','#e0913a','#e8dcb8','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'All i pebre',en:'All i pebre'},
  p:{fr:'Albufera, Valence, Espagne',en:'Albufera, Valencia, Spain'},
  d:{fr:"Des anguilles de la lagune mijotées à l'ail, au paprika et à l'amande, dans une casserole de terre. Le plat des pêcheurs de l'Albufera : il n'y entre ni tomate ni oignon, seulement de l'ail — le nom, ail et poivre, énonce la recette entière.",
     en:"Lagoon eels stewed with garlic, paprika and almond in an earthenware pot. The dish of the Albufera fishermen: no tomato, no onion, only garlic — the name, garlic and pepper, states the whole recipe."},
  i:[['eel',1,'kg'],['garlic',12,'clove'],['sweet_paprika',2,'tbsp'],['cayenne',1,'tsp'],['almonds',60,'g'],['potato',600,'g'],['olive_oil',120,'ml'],['bread',1,'slice'],['parsley',3,'tbsp'],['salt',null,'']],
  s:{fr:["Faites tronçonner les anguilles par le poissonnier et rincez-les longuement : leur mucus doit partir entièrement, sinon la sauce reste gluante.","Faites blondir dans la casserole de terre l'ail entier en chemise, les amandes et la tranche de pain, puis retirez-les.","Pilez-les au mortier avec le persil et un peu d'eau pour obtenir la picada.","Hors du feu, jetez le paprika dans l'huile chaude et remuez deux secondes avant d'ajouter aussitôt l'eau : c'est le geste critique, un paprika brûlé rend le plat amer.","Cuisez les pommes de terre en rondelles 15 minutes dans ce bouillon, ajoutez les anguilles et la picada, et laissez frémir 12 minutes sans jamais remuer — on secoue la casserole."],
     en:["Have the eels cut into sections by the fishmonger and rinse them at length: all their mucus must go, or the sauce stays slimy.","In the earthenware pot, turn the whole unpeeled garlic, the almonds and the slice of bread golden, then lift them out.","Pound them in a mortar with the parsley and a little water to make the picada.","Off the heat, throw the paprika into the hot oil and stir for two seconds before adding the water immediately: this is the critical gesture, burnt paprika makes the dish bitter.","Cook sliced potatoes 15 minutes in that broth, add the eels and the picada, and simmer 12 minutes without ever stirring — you shake the pot instead."]} },

{ id:'esgarraet', c:'eu', lat:39.470, lon:-0.376, base:4, prep:60, cook:40, diff:1, tags:['sea','fresh','veg'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'salad',food:['#c9402c','#e0913a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Esgarraet',en:'Esgarraet'},
  p:{fr:'Valence, Espagne',en:'Valencia, Spain'},
  d:{fr:"Des poivrons rouges rôtis déchirés à la main et mêlés à la morue crue dessalée, à l'ail et à l'huile. Esgarrar veut dire déchirer : le couteau est proscrit, parce que la lame coupe les fibres au lieu de les séparer et que le poivron rend alors son eau.",
     en:"Roasted red peppers torn by hand and mixed with raw desalted cod, garlic and oil. Esgarrar means to tear: the knife is banned, because a blade cuts the fibres instead of separating them and the pepper then weeps."},
  i:[['red_pepper',4,'pc'],['salt_cod',250,'g'],['garlic',3,'clove'],['olive_oil',120,'ml'],['black_olives',80,'g'],['bread',300,'g']],
  s:{fr:["Rôtissez les poivrons entiers 40 minutes à 200 °C en les retournant, jusqu'à ce que la peau cloque et noircisse par plaques.","Enfermez-les 20 minutes dans un sac fermé : la vapeur décolle la peau, qui s'enlève ensuite d'un seul geste.","Pelez-les sans les passer sous l'eau — l'eau emporterait tout le jus concentré par le rôtissage — et déchirez-les en lanières à la main.","Dessalez la morue 24 heures en changeant l'eau quatre fois, épongez-la et effilochez-la crue, en gros filaments.","Mêlez le tout à l'ail émincé finement et à l'huile d'olive, et laissez macérer 6 heures au frais. Se sert froid, avec du pain."],
     en:["Roast the whole peppers 40 minutes at 200°C, turning them, until the skin blisters and blackens in patches.","Shut them in a sealed bag for 20 minutes: the steam lifts the skin, which then comes away in one movement.","Peel them without running them under water — water would carry off all the juice the roasting concentrated — and tear them into strips by hand.","Desalt the cod for 24 hours, changing the water four times, blot it and shred it raw into coarse strands.","Mix everything with finely sliced garlic and olive oil, and macerate 6 hours in the cold. Served cold, with bread."]} },

{ id:'arroz-al-horno', c:'eu', lat:38.987, lon:-0.522, base:6, prep:40, cook:50, diff:2, tags:['rice','bake','pork'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#e0b45a','#8f5a3a','#c9402c','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Arroz al horno',en:'Baked rice'},
  p:{fr:'Xàtiva, Valence, Espagne',en:'Xàtiva, Valencia, Spain'},
  d:{fr:"Un riz cuit au four dans une cazuela de terre, couronné d'une tête d'ail entière et de rondelles de pomme de terre. Il se faisait le lendemain du cocido, avec son bouillon : la tête d'ail plantée au centre n'est pas un décor, elle se presse dans le riz à table.",
     en:"Rice baked in an earthenware cazuela, crowned with a whole head of garlic and slices of potato. It was made the day after the cocido with its broth: the head of garlic planted in the centre is no ornament, it is squeezed into the rice at the table."},
  i:[['bomba_rice',400,'g'],['pork_ribs',400,'g'],['blood_sausage',200,'g'],['chickpeas',200,'g'],['potato',400,'g'],['ripe_tomato',2,'pc'],['garlic',1,'pc'],['sweet_paprika',1,'tbsp'],['saffron',1,'pinch'],['pork_broth',900,'ml'],['olive_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Faites dorer les côtes de porc dans la cazuela avec l'huile, puis les rondelles de pomme de terre et les tomates coupées en deux ; réservez le tout.","Jetez le riz dans l'huile parfumée et remuez 2 minutes pour le nacrer, puis le paprika hors du feu.","Versez le bouillon bouillant dans la proportion exacte de deux volumes et quart pour un de riz : ce riz-là ne se remue plus et ne se rectifie pas.","Répartissez viandes, pommes de terre, pois chiches et boudin, et plantez la tête d'ail entière au centre.","Enfournez 45 minutes à 200 °C sans jamais toucher au plat. Le riz doit être sec, chaque grain détaché, et une croûte légère s'être formée sur le dessus."],
     en:["Brown the pork ribs in the cazuela with the oil, then the potato slices and the halved tomatoes; set everything aside.","Tip the rice into the scented oil and stir 2 minutes to pearl it, then add the paprika off the heat.","Pour in boiling broth in the exact ratio of two and a quarter parts to one of rice: this rice is not stirred again and cannot be corrected.","Distribute the meats, potatoes, chickpeas and black pudding, and plant the whole head of garlic in the centre.","Bake 45 minutes at 200°C without once touching the dish. The rice must be dry, every grain separate, with a light crust formed on top."]} },

{ id:'horchata-de-chufa', c:'eu', lat:39.501, lon:-0.351, base:6, prep:1440, cook:0, diff:2, tags:['drink','fresh','sweet'],
  art:{v:'glass',bg:'#33291f',plate:'#f4f0e6',style:'drink',food:['#f4f0e6','#f0e8d0','#e8dcb8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Horchata de chufa',en:'Tiger nut horchata'},
  p:{fr:'Alboraya, Valence, Espagne',en:'Alboraya, Valencia, Spain'},
  d:{fr:"Un lait de souchet, blanc et sucré, bu glacé avec des fartons trempés dedans. Le souchet est un tubercule que les Arabes ont apporté à Valence ; il ne pousse en Europe que sur quatre cents hectares au nord de la ville, et l'horchata industrielle n'a rien à voir avec la fraîche.",
     en:"A tiger nut milk, white and sweet, drunk iced with fartons dipped in it. The chufa is a tuber the Arabs brought to Valencia; in Europe it grows on barely four hundred hectares north of the city, and industrial horchata has nothing to do with the fresh kind."},
  i:[['tiger_nuts',500,'g'],['water',2,'l'],['sugar',150,'g'],['cinnamon',1,'stick'],['lemon_zest',1,'pc']],
  s:{fr:["Lavez les souchets à grande eau en frottant, puis faites-les tremper 12 heures : secs, ils sont durs comme du gravier et le mixeur ne les entame pas.","Rincez-les à nouveau et mixez-les avec un tiers de l'eau, longuement, jusqu'à une purée grumeleuse.","Ajoutez le reste de l'eau, le zeste et la cannelle, et laissez macérer 3 heures au froid.","Filtrez à travers un linge fin en tordant fortement : c'est ce pressage, et non le mixage, qui extrait la matière grasse et donne le velouté.","Sucrez, remuez jusqu'à dissolution et servez très froid, presque givré. Se garde deux jours au maximum et se sépare : on la secoue avant de verser."],
     en:["Wash the tiger nuts under plenty of water, scrubbing, then soak them 12 hours: dry, they are hard as gravel and no blender touches them.","Rinse them again and blend with a third of the water, at length, to a gritty purée.","Add the rest of the water, the zest and cinnamon, and macerate 3 hours in the cold.","Strain through a fine cloth, twisting hard: it is that pressing, not the blending, that extracts the fat and gives the velvet.","Sweeten, stir until dissolved and serve very cold, almost frosted. It keeps two days at most and separates: shake before pouring."]} },

{ id:'agua-de-valencia', c:'eu', lat:39.474, lon:-0.376, base:6, prep:15, cook:0, diff:1, tags:['drink','fast','fruit'],
  art:{v:'glass',bg:'#33291f',plate:'#f4f0e6',style:'drink',food:['#e8a032','#f2c46a','#f0e8d0','#e0b45a'],garnish:'#c9754a'},
  n:{fr:'Agua de Valencia',en:'Agua de Valencia'},
  p:{fr:'Valence, Espagne',en:'Valencia, Spain'},
  d:{fr:"Du jus d'orange, du cava, de la vodka et du gin, servi en pichet. Créé au Café Madrid en 1959 pour un groupe de Basques qui réclamaient autre chose que le cava habituel ; le patron leur servit cela en disant que c'était de l'eau de Valence, et le nom est resté.",
     en:"Orange juice, cava, vodka and gin, served by the jug. Created at the Café Madrid in 1959 for a group of Basques who wanted something other than the usual cava; the owner served them this saying it was water from Valencia, and the name stuck."},
  i:[['orange',10,'pc'],['cava',750,'ml'],['vodka',80,'ml'],['gin',80,'ml'],['sugar',60,'g']],
  s:{fr:["Pressez les oranges le jour même : un jus de la veille perd son parfum et prend un goût amer d'écorce.","Filtrez-le à travers une passoire large pour retenir les pépins mais laisser passer la pulpe, qui donne le corps.","Faites dissoudre le sucre dans le jus à froid en remuant longuement, avant d'ajouter quoi que ce soit d'alcoolisé.","Ajoutez la vodka et le gin, remuez, puis mettez au réfrigérateur une heure : tout doit être glacé avant l'étape suivante.","Versez le cava en dernier, doucement, le long de la paroi du pichet, et ne remuez qu'une fois d'un mouvement lent. Servez sans glaçons, qui délaveraient tout."],
     en:["Squeeze the oranges the same day: yesterday's juice loses its scent and takes on a bitter peel taste.","Strain it through a wide sieve to hold back the pips but let the pulp through, which gives the body.","Dissolve the sugar in the cold juice, stirring at length, before any alcohol goes in.","Add the vodka and gin, stir, then chill for an hour: everything must be freezing before the next step.","Pour the cava in last, gently, down the side of the jug, and stir only once, slowly. Serve without ice, which would water it down."]} },

{ id:'tarta-de-santiago', c:'eu', lat:42.881, lon:-8.545, base:8, prep:30, cook:40, diff:1, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f4f0e6','#f2dfa8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Tarta de Santiago',en:'Tarta de Santiago'},
  p:{fr:'Saint-Jacques-de-Compostelle, Galice, Espagne',en:'Santiago de Compostela, Galicia, Spain'},
  d:{fr:"Un gâteau d'amandes sans farine ni levure, marqué de la croix de Saint-Jacques au sucre glace. Il n'y entre que trois ingrédients : c'est la quantité d'œuf, et l'air qu'on y fouette, qui font toute la légèreté d'un gâteau autrement compact.",
     en:"An almond cake with neither flour nor leaven, marked with the cross of Saint James in icing sugar. Only three ingredients go in: it is the quantity of egg, and the air whisked into it, that gives all the lightness to an otherwise dense cake."},
  i:[['ground_almonds',250,'g'],['sugar',250,'g'],['egg',5,'pc'],['lemon_zest',1,'pc'],['cinnamon',1,'tsp'],['powdered_sugar',40,'g'],['butter',20,'g'],['salt',null,'']],
  s:{fr:["Fouettez les œufs entiers avec le sucre au moins 10 minutes, jusqu'à ce que le mélange triple de volume et forme un ruban qui tient trois secondes.","Sans farine ni levure, cette aération est la seule chose qui empêchera le gâteau d'être un palet dense.","Incorporez la poudre d'amande, le zeste et la cannelle à la spatule, en soulevant, en une vingtaine de gestes.","Versez dans un moule beurré de 24 cm et cuisez 40 minutes à 175 °C : la pointe doit ressortir juste sèche.","Laissez refroidir, posez un pochoir de la croix de Santiago sur le dessus et sucrez au sucre glace avant de le retirer d'un geste vertical."],
     en:["Whisk the whole eggs with the sugar for at least 10 minutes, until the mixture triples and ribbons for three seconds.","With no flour and no leaven, that aeration is the only thing keeping the cake from being a dense disc.","Fold in the ground almonds, zest and cinnamon with a spatula, lifting, in some twenty movements.","Pour into a buttered 24 cm tin and bake 40 minutes at 175°C: a skewer should come out just dry.","Cool, set a stencil of the cross of Santiago on top and dust with icing sugar before lifting it straight up."]} },

{ id:'caldo-gallego', c:'eu', lat:42.766, lon:-7.505, base:6, prep:30, cook:150, diff:1, tags:['pork','soup','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'soup',food:['#4f6f3a','#e8dcb8','#7fae5a','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Caldo gallego',en:'Caldo gallego'},
  p:{fr:'Lugo, Galice, Espagne',en:'Lugo, Galicia, Spain'},
  d:{fr:"Une soupe de grelos, de haricots blancs et de pomme de terre, enrichie d'unto — du saindoux rance affiné. L'unto est ce qui distingue un vrai caldo d'une soupe de légumes : sa légère rancidité, recherchée, donne un fond que ni le lard ni l'huile ne remplacent.",
     en:"A soup of turnip tops, white beans and potato, enriched with unto — aged rancid lard. Unto is what separates a real caldo from a vegetable soup: its slight rancidity, deliberately sought, gives a depth neither bacon nor oil replaces."},
  i:[['white_beans',300,'g'],['turnip_tops',600,'g'],['potato',700,'g'],['salted_pork',300,'g'],['chorizo',150,'g'],['lard',60,'g'],['pork_bones',400,'g'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper les haricots et le lard salé séparément, une nuit chacun, en changeant l'eau du lard deux fois.","Mettez les haricots, les os et le lard à l'eau froide et laissez frémir 1 heure, en écumant au début.","Ajoutez le saindoux et les pommes de terre cassées à la cuillère plutôt que coupées — la cassure libère l'amidon et épaissit le bouillon d'elle-même.","Lavez les grelos et blanchissez-les 3 minutes à part si la saison est avancée : après la floraison ils deviennent amers et gâteraient toute la marmite.","Réunissez tout et laissez cuire 40 minutes de plus. Salez à la fin seulement, et laissez reposer une heure avant de servir."],
     en:["Soak the beans and the salt pork separately, overnight each, changing the pork's water twice.","Start the beans, bones and pork in cold water and simmer for an hour, skimming at the beginning.","Add the lard and the potatoes broken with a spoon rather than cut — breaking releases the starch and thickens the broth by itself.","Wash the turnip tops and blanch them 3 minutes separately if the season is late: after flowering they turn bitter and would spoil the whole pot.","Bring everything together and cook 40 minutes more. Salt only at the end, and rest an hour before serving."]} },

{ id:'pimientos-de-padron', c:'eu', lat:42.737, lon:-8.660, base:4, prep:10, cook:8, diff:1, tags:['veg','fast','street'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#4f8f4a','#7fae5a','#e8dcb8','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Pimientos de Padrón',en:'Padrón peppers'},
  p:{fr:'Padrón, Galice, Espagne',en:'Padrón, Galicia, Spain'},
  d:{fr:"De petits poivrons verts frits entiers à l'huile d'olive et salés au gros sel. Le dicton local dit : uns pican e outros non, les uns piquent et les autres pas — un sur dix environ, et rien ne permet de le deviner avant de mordre.",
     en:"Small green peppers fried whole in olive oil and salted with coarse salt. The local saying goes uns pican e outros non, some are hot and some are not — about one in ten, and nothing tells you before you bite."},
  i:[['padron_peppers',400,'g'],['olive_oil',150,'ml'],['coarse_salt',2,'tbsp']],
  s:{fr:["Choisissez de petits poivrons, quatre à cinq centimètres : au-delà, ils sont plus âgés, plus fibreux et beaucoup plus souvent piquants.","Lavez-les et séchez-les avec soin : la moindre goutte d'eau fait exploser l'huile brûlante.","Ne les équeutez pas — la queue sert à les tenir pour les manger — mais percez chacun d'un coup de pointe pour éviter qu'il n'éclate.","Faites-les sauter à feu vif dans l'huile chaude 5 minutes, en secouant la poêle sans arrêt, jusqu'à ce que la peau cloque et brunisse par plaques.","Égouttez sur du papier et salez au gros sel pendant qu'ils sont brûlants : le sel n'accroche pas sur un poivron refroidi."],
     en:["Choose small peppers, four to five centimetres: larger ones are older, more fibrous and far more often hot.","Wash and dry them carefully: the least drop of water makes the scalding oil explode.","Do not remove the stalks — they are the handle for eating — but pierce each one with a knife point so it does not burst.","Toss them over high heat in hot oil for 5 minutes, shaking the pan constantly, until the skin blisters and browns in patches.","Drain on paper and salt with coarse salt while scalding: salt does not stick to a cooled pepper."]} },

{ id:'cachopo', c:'eu', lat:43.362, lon:-5.845, base:4, prep:40, cook:20, diff:2, tags:['beef','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'flat',food:['#c9924a','#e0b45a','#f4f0e6','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Cachopo',en:'Cachopo'},
  p:{fr:'Oviedo, Asturies, Espagne',en:'Oviedo, Asturias, Spain'},
  d:{fr:"Deux escalopes de veau soudées autour de jambon et de fromage, panées et frites, larges comme une assiette. Il se commande pour deux et se partage : un cachopo d'une seule personne n'existe pas dans les cartes asturiennes.",
     en:"Two veal escalopes sealed around ham and cheese, crumbed and fried, as wide as a plate. It is ordered for two and shared: a single-portion cachopo does not exist on Asturian menus."},
  i:[['veal_escalope',800,'g'],['serrano_ham',8,'slice'],['cabrales_cheese',200,'g'],['egg',4,'pc'],['breadcrumbs',300,'g'],['flour',120,'g'],['sunflower_oil',1,'l'],['potato',800,'g'],['garlic',2,'clove'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites aplatir les escalopes par le boucher jusqu'à 4 mm, en deux morceaux de taille identique.","Poivrez l'intérieur mais ne salez pas : jambon et fromage apportent déjà tout le sel.","Disposez le jambon puis le fromage en laissant deux centimètres libres tout autour, et posez la seconde escalope dessus.","Soudez les bords en pressant fermement du bout des doigts, puis en pinçant : un cachopo qui s'ouvre vide son fromage dans l'huile.","Farinez, passez à l'œuf et à la chapelure deux fois, puis frites 6 minutes à 170 °C — feu doux et long, pour que le cœur fonde avant que la croûte ne brûle."],
     en:["Have the butcher beat the escalopes to 4 mm, in two pieces of identical size.","Pepper the inside but do not salt: ham and cheese already bring all the salt.","Lay the ham then the cheese leaving two centimetres clear all round, and set the second escalope on top.","Seal the edges pressing firmly with your fingertips, then pinching: a cachopo that opens empties its cheese into the oil.","Flour, egg and crumb twice, then fry 6 minutes at 170°C — low and long, so the centre melts before the crust burns."]} },

{ id:'sobao-pasiego', c:'eu', lat:43.143, lon:-3.766, base:12, prep:30, cook:25, diff:2, tags:['sweet','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Sobao pasiego',en:'Sobao pasiego'},
  p:{fr:'Vega de Pas, Cantabrie, Espagne',en:'Vega de Pas, Cantabria, Spain'},
  d:{fr:"Un petit gâteau au beurre cuit dans une caissette de papier, dense et humide, dont le beurre représente le tiers du poids. Il est né des restes de pain sucré que les paysannes du Pas retravaillaient au beurre ; sobar veut dire pétrir longuement à la main.",
     en:"A small butter cake baked in a paper case, dense and moist, in which butter is a third of the weight. It grew out of leftover sweet bread that the Pas valley women reworked with butter; sobar means to knead long by hand."},
  i:[['butter',250,'g'],['sugar',250,'g'],['egg',4,'pc'],['flour',250,'g'],['baking_powder',1,'tsp'],['lemon_zest',1,'pc'],['rum',20,'ml'],['honey',1,'tbsp'],['salt',null,'']],
  s:{fr:["Sortez le beurre trois heures à l'avance : il doit être en pommade parfaite, ni fondu ni ferme, sinon rien n'émulsionne.","Travaillez-le au fouet avec le sucre au moins 8 minutes, jusqu'à ce qu'il blanchisse et double presque de volume.","Ajoutez les œufs un à un en attendant que chacun soit entièrement absorbé : versés ensemble, ils font trancher la masse.","Incorporez la farine tamisée avec la levure, le zeste, le miel, le rhum et le sel, en pliant sans travailler.","Emplissez les caissettes de papier aux trois quarts et cuisez 22 minutes à 200 °C. Le dessus doit être brun foncé et le centre encore humide."],
     en:["Take the butter out three hours ahead: it must be perfectly soft, neither melted nor firm, or nothing emulsifies.","Beat it with the sugar for at least 8 minutes, until it pales and nearly doubles.","Add the eggs one at a time, waiting for each to be fully absorbed: poured in together they split the mixture.","Fold in the sifted flour and baking powder, the zest, honey, rum and salt, without working it.","Fill the paper cases three-quarters full and bake 22 minutes at 200°C. The top should be dark brown and the centre still moist."]} },

{ id:'quesada-pasiega', c:'eu', lat:43.297, lon:-3.868, base:8, prep:25, cook:45, diff:1, tags:['sweet','bake','cheese'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Quesada pasiega',en:'Quesada pasiega'},
  p:{fr:'Vallée du Pas, Cantabrie, Espagne',en:'Pas valley, Cantabria, Spain'},
  d:{fr:"Un flan au lait caillé, au beurre et à la cannelle, cuit en plaque basse jusqu'à ce que le dessus brunisse. Elle se faisait avec le lait qui avait tourné : c'est un dessert d'économie, et le lait frais ne donne jamais la même acidité en arrière-plan.",
     en:"A custard of curdled milk, butter and cinnamon, baked shallow until the top browns. It was made from milk that had turned: a thrift pudding, and fresh milk never gives the same acidity in the background."},
  i:[['fresh_cheese',600,'g'],['sugar',250,'g'],['egg',4,'pc'],['flour',120,'g'],['butter',120,'g'],['whole_milk',150,'ml'],['cinnamon',2,'tsp'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Égouttez le fromage frais 2 heures dans une passoire : trop humide, la quesada ne prend pas et reste liquide au centre.","Écrasez-le à la fourchette avec le sucre, puis ajoutez les œufs un à un et le beurre fondu tiède.","Incorporez la farine tamisée, le lait, la cannelle, le zeste et le sel ; l'appareil doit couler du fouet en ruban épais.","Versez dans un plat rectangulaire beurré, sur 3 cm d'épaisseur au maximum — c'est une quesada, pas un gâteau, et la faible hauteur fait toute sa texture.","Cuisez 45 minutes à 180 °C jusqu'à ce que le dessus soit brun foncé. Laissez refroidir complètement avant de couper en carrés."],
     en:["Drain the fresh cheese 2 hours in a colander: too wet, the quesada does not set and stays liquid in the middle.","Crush it with a fork with the sugar, then add the eggs one at a time and the warm melted butter.","Fold in the sifted flour, the milk, cinnamon, zest and salt; the batter should ribbon thickly off the whisk.","Pour into a buttered rectangular tin, 3 cm deep at most — this is a quesada, not a cake, and its shallowness makes its texture.","Bake 45 minutes at 180°C until the top is dark brown. Cool completely before cutting into squares."]} },

{ id:'morcilla-de-burgos', c:'eu', lat:42.344, lon:-3.697, base:6, prep:90, cook:60, diff:3, tags:['pork','slow','rice'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'grill',food:['#3a2a2a','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Morcilla de Burgos',en:'Burgos morcilla'},
  p:{fr:'Burgos, Castille-et-León, Espagne',en:'Burgos, Castile and León, Spain'},
  d:{fr:"Un boudin au riz, à l'oignon et au sang, dont le riz représente près du quart. Il ne se lie ni à la chapelure ni à la farine : les grains gonflent dans le sang et se voient distinctement à la coupe, ce qui distingue Burgos de tous les autres boudins d'Espagne.",
     en:"A blood pudding with rice and onion, in which rice is nearly a quarter of the whole. It is bound with neither crumb nor flour: the grains swell in the blood and show distinctly in the slice, which sets Burgos apart from every other Spanish pudding."},
  i:[['pork_blood',1,'l'],['long_grain_rice',400,'g'],['onion',1.5,'kg'],['pork_fat',400,'g'],['sweet_paprika',2,'tbsp'],['black_peppercorns',1,'tbsp'],['oregano',1,'tbsp'],['sausage_casings',null,''],['coarse_salt',40,'g']],
  s:{fr:["Faites confire l'oignon très finement émincé dans le gras, 1 heure à feu doux, jusqu'à ce qu'il devienne translucide et perde toute son eau.","Cuisez le riz à moitié seulement, 8 minutes, et rafraîchissez-le : entièrement cuit, il éclaterait dans le boudin.","Mêlez l'oignon tiède, le riz, les épices et le sel, puis versez le sang tamisé en remuant.","Embossez en n'emplissant qu'à moitié — le riz double encore de volume en pochant, et un boyau plein éclate à coup sûr.","Pochez 45 minutes à 80 °C, sans jamais bouillir, en piquant à l'aiguille au bout de 10 minutes. Se tranche épais et se poêle ou se grille."],
     en:["Confit the very finely sliced onion in the fat for an hour over low heat, until translucent and entirely dry.","Cook the rice only halfway, 8 minutes, and refresh it: fully cooked, it would burst inside the pudding.","Combine the warm onion, the rice, the spices and salt, then pour in the sieved blood, stirring.","Fill the casings only half full — the rice doubles again while poaching, and a full skin bursts without fail.","Poach 45 minutes at 80°C, never boiling, pricking with a needle after 10 minutes. Cut thick and fry or grill."]} },

{ id:'botillo-del-bierzo', c:'eu', lat:42.617, lon:-6.412, base:6, prep:30, cook:180, diff:2, tags:['pork','slow','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'other',food:['#8f3b2a','#c9924a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Botillo du Bierzo',en:'Botillo del Bierzo'},
  p:{fr:'Bembibre, León, Espagne',en:'Bembibre, León, Spain'},
  d:{fr:"Un gros boyau farci de côtes, de queue et d'os de porc, fumé puis bouilli trois heures. On le sert entier au centre de la table et on l'ouvre d'un coup de couteau : les morceaux gardent leur os, et c'est à la main qu'on les mange.",
     en:"A large casing stuffed with pork ribs, tail and bones, smoked then boiled for three hours. It is served whole in the middle of the table and opened with a single cut: the pieces keep their bones, and they are eaten with the fingers."},
  i:[['pork_ribs',800,'g'],['pork_tail',300,'g'],['pork_shoulder',400,'g'],['sweet_paprika',3,'tbsp'],['garlic',10,'clove'],['pork_stomach',1,'pc'],['coarse_salt',40,'g'],['cabbage',800,'g'],['potato',1,'kg'],['chorizo',200,'g'],['oregano',1,'tbsp']],
  s:{fr:["Taillez les côtes et la queue en tronçons avec leurs os : c'est l'os qui donne au botillo son goût et sa gélatine, et un botillo désossé n'est plus un botillo.","Frottez toutes les pièces d'ail pilé, de paprika, d'origan et de sel, et laissez macérer 24 heures au froid.","Emplissez le boyau à la main en tassant fermement, liez-le et suspendez-le à sécher trois jours.","Fumez-le au chêne une semaine, à froid, puis piquez-le en cinq ou six endroits avant de le pocher — sans ces piqûres il éclate dans la marmite.","Pochez 3 heures à petits frémissements en changeant l'eau une fois, et faites cuire chou, chorizo et pommes de terre dans le second bouillon."],
     en:["Cut the ribs and tail into sections with their bones: the bone gives a botillo its flavour and its gelatine, and a boned botillo is no longer one.","Rub every piece with crushed garlic, paprika, oregano and salt, and macerate 24 hours in the cold.","Pack the casing by hand, pressing firmly, tie it and hang it to dry for three days.","Cold-smoke over oak for a week, then prick it in five or six places before poaching — without those pricks it bursts in the pot.","Poach 3 hours at a bare simmer, changing the water once, and cook the cabbage, chorizo and potatoes in the second broth."]} },

{ id:'patatas-revolconas', c:'eu', lat:40.657, lon:-4.700, base:4, prep:20, cook:40, diff:1, tags:['pork','comfort','veg'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#c9532c','#e0913a','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Patatas revolconas',en:'Patatas revolconas'},
  p:{fr:'Ávila, Castille-et-León, Espagne',en:'Ávila, Castile and León, Spain'},
  d:{fr:"Une purée de pommes de terre écrasée au paprika, orange vif, couronnée de torreznos croustillants. Revolcar veut dire vautrer : on ne monte pas la purée, on la roule dans la graisse pimentée jusqu'à ce qu'elle en soit tout imprégnée.",
     en:"A mash of potato crushed with paprika, bright orange, crowned with crisp torreznos. Revolcar means to wallow: the mash is not whipped, it is rolled in the paprika fat until it is soaked through."},
  i:[['potato',1,'kg'],['pork_belly',300,'g'],['sweet_paprika',2,'tbsp'],['hot_paprika',1,'tsp'],['garlic',6,'clove'],['bay_leaf',2,'pc'],['cumin',1,'tsp'],['olive_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Cuisez les pommes de terre entières avec la peau, le laurier et le sel, et gardez un verre de leur eau de cuisson.","Faites rissoler les lardons de poitrine jusqu'à ce qu'ils croustillent, retirez-les et gardez toute la graisse.","Faites blondir l'ail dans cette graisse, puis retirez la poêle du feu avant d'y jeter les paprikas et le cumin : sur le feu, ils brûlent en deux secondes et deviennent amers.","Pelez les pommes de terre chaudes et écrasez-les directement dans la poêle avec une fourchette, en les roulant dans la graisse rouge.","Détendez d'un peu d'eau de cuisson, salez et couronnez de lardons croustillants au moment de servir."],
     en:["Boil the potatoes whole in their skins with bay and salt, and keep a glass of the cooking water.","Fry the belly lardons until crisp, lift them out and keep every drop of fat.","Turn the garlic golden in that fat, then take the pan off the heat before adding the paprikas and cumin: over the flame they burn in two seconds and turn bitter.","Peel the potatoes hot and crush them straight into the pan with a fork, rolling them in the red fat.","Loosen with a little cooking water, salt and crown with the crisp lardons at the moment of serving."]} },

{ id:'migas-manchegas', c:'eu', lat:38.995, lon:-1.858, base:6, prep:30, cook:45, diff:2, tags:['pork','comfort','bread'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#e0b45a','#c9924a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Migas manchegas',en:'Migas manchegas'},
  p:{fr:'Albacete, Castille-La Manche, Espagne',en:'Albacete, Castile-La Mancha, Spain'},
  d:{fr:"Du pain rassis émietté et humecté, sauté longuement à l'huile et à l'ail jusqu'à ce que chaque miette se détache. C'est le petit-déjeuner des bergers de la Manche : ils partaient avec le pain de la semaine, et la pluie de la veille servait à l'humecter.",
     en:"Stale bread crumbled and dampened, fried at length with oil and garlic until every crumb separates. It was the breakfast of La Mancha shepherds: they set out with the week's bread, and the previous night's rain served to dampen it."},
  i:[['rustic_bread',600,'g'],['garlic',10,'clove'],['chorizo',200,'g'],['pork_belly',200,'g'],['olive_oil',150,'ml'],['sweet_paprika',1,'tbsp'],['water',150,'ml'],['grapes',200,'g'],['salt',null,'']],
  s:{fr:["Émiettez le pain de deux jours au couteau en morceaux de la taille d'un grain de maïs — jamais au robot, qui donne de la poudre.","Aspergez-le d'eau salée, mêlez à la main, enveloppez-le dans un linge humide et laissez-le une nuit entière.","Le pain doit être souple mais non détrempé : trop d'eau et les migas se collent en bouillie, pas assez et elles restent dures.","Faites frire l'ail en chemise, le chorizo et le lard dans l'huile, retirez-les et jetez le paprika hors du feu.","Versez les miettes et remuez sans arrêt 30 minutes à feu moyen, en les soulevant à la spatule : elles doivent finir dorées, sèches et parfaitement détachées. Servez avec du raisin."],
     en:["Crumble two-day-old bread with a knife into pieces the size of a maize grain — never in a processor, which gives powder.","Sprinkle it with salted water, mix by hand, wrap it in a damp cloth and leave it overnight.","The bread must be supple but not sodden: too much water and the migas clag into mush, too little and they stay hard.","Fry the unpeeled garlic, chorizo and belly in the oil, lift them out and add the paprika off the heat.","Tip in the crumbs and stir constantly for 30 minutes over medium heat, lifting with a spatula: they must end golden, dry and perfectly separate. Serve with grapes."]} },

{ id:'caldereta-extremena', c:'eu', lat:39.458, lon:-5.881, base:6, prep:40, cook:150, diff:2, tags:['lamb','slow','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9532c','#e8dcb8','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Caldereta d’Estrémadure',en:'Extremaduran caldereta'},
  p:{fr:'Trujillo, Estrémadure, Espagne',en:'Trujillo, Extremadura, Spain'},
  d:{fr:"Un ragoût d'agneau de lait lié à une picada de foie, de pain et d'amandes, cuit dans un chaudron sur le feu. Les bergers de la transhumance la préparaient avec la bête qui s'était blessée en route : rien n'y entre qui ne se transporte pas à dos de mulet.",
     en:"A milk-lamb stew bound with a picada of liver, bread and almonds, cooked in a cauldron over the fire. Transhumance shepherds made it with whichever beast had injured itself on the road: nothing goes in that a mule cannot carry."},
  i:[['lamb_shoulder',1.5,'kg'],['lamb_liver',200,'g'],['onion',3,'pc'],['garlic',10,'clove'],['red_pepper',2,'pc'],['sweet_paprika',2,'tbsp'],['bay_leaf',3,'pc'],['white_wine',250,'ml'],['bread',2,'slice'],['almonds',60,'g'],['olive_oil',120,'ml'],['cloves',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites saisir l'agneau en gros morceaux avec os dans l'huile brûlante, par petites quantités, jusqu'à ce qu'il soit bien coloré.","Faites revenir l'oignon, l'ail et le poivron dans la même huile, ajoutez le paprika hors du feu et remettez la viande.","Mouillez au vin blanc et à l'eau à hauteur, ajoutez le laurier et les clous, et laissez mijoter 2 heures à couvert.","Faites sauter le foie d'agneau et frire le pain, puis pilez-les au mortier avec les amandes, l'ail cru et un peu de sauce.","Versez cette picada 20 minutes avant la fin : c'est elle qui lie et donne le goût, et elle ne doit surtout pas bouillir longtemps, sinon le foie devient granuleux."],
     en:["Sear the lamb in large bone-in pieces in scalding oil, in small batches, until well coloured.","Fry the onion, garlic and pepper in the same oil, add the paprika off the heat and return the meat.","Moisten with white wine and water to cover, add the bay and cloves, and simmer covered for 2 hours.","Sauté the lamb's liver and fry the bread, then pound them in a mortar with the almonds, raw garlic and a little sauce.","Add this picada 20 minutes before the end: it is what binds and what gives the flavour, and it must on no account boil long, or the liver turns grainy."]} },

{ id:'zorongollo', c:'eu', lat:39.472, lon:-6.379, base:4, prep:60, cook:45, diff:1, tags:['veg','fresh','sunday'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'salad',food:['#c9402c','#e0913a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Zorongollo',en:'Zorongollo'},
  p:{fr:'Cáceres, Estrémadure, Espagne',en:'Cáceres, Extremadura, Spain'},
  d:{fr:"Une salade tiède de poivrons rouges rôtis, de tomate et d'œuf dur, à l'huile d'Estrémadure. Le poivron se pèle sans jamais passer sous l'eau : c'est le jus recueilli pendant le rôtissage qui fait l'assaisonnement, et le rincer reviendrait à jeter le plat.",
     en:"A warm salad of roasted red peppers, tomato and hard-boiled egg, with Extremaduran oil. The pepper is peeled without ever going under water: the juice collected during roasting is the dressing, and rinsing it would be throwing the dish away."},
  i:[['red_pepper',6,'pc'],['ripe_tomato',3,'pc'],['egg',3,'pc'],['garlic',3,'clove'],['olive_oil',120,'ml'],['sherry_vinegar',2,'tbsp'],['cumin',1,'tsp'],['bread',300,'g'],['salt',null,'']],
  s:{fr:["Rôtissez poivrons et tomates entiers 45 minutes à 200 °C, en les retournant à mi-cuisson, jusqu'à ce que la peau se boursoufle et se détache.","Enfermez-les 20 minutes sous un torchon ou dans un sac clos, le temps que la vapeur décolle les peaux.","Pelez-les au-dessus d'un saladier pour recueillir chaque goutte de jus, et déchirez la chair en lanières à la main.","Filtrez le jus, mêlez-le à l'huile, au vinaigre, à l'ail pilé, au cumin et au sel : voilà toute la vinaigrette.","Ajoutez les œufs durs hachés et laissez macérer 2 heures à température ambiante — jamais au réfrigérateur, le froid éteint le goût du poivron."],
     en:["Roast the whole peppers and tomatoes 45 minutes at 200°C, turning them halfway, until the skin blisters and lifts.","Shut them under a cloth or in a sealed bag for 20 minutes, while the steam frees the skins.","Peel them over a bowl to catch every drop of juice, and tear the flesh into strips by hand.","Strain the juice and mix it with the oil, vinegar, crushed garlic, cumin and salt: that is the whole dressing.","Add the chopped hard-boiled eggs and macerate 2 hours at room temperature — never in the fridge, cold kills the flavour of the pepper."]} },

{ id:'migas-aragonesas', c:'eu', lat:40.344, lon:-1.107, base:6, prep:30, cook:40, diff:2, tags:['pork','comfort','bread'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#e0b45a','#8f5a3a','#c9532c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Migas aragonaises',en:'Aragonese migas'},
  p:{fr:'Teruel, Aragon, Espagne',en:'Teruel, Aragon, Spain'},
  d:{fr:"Des miettes de pain sautées au jambon de Teruel et au raisin, plus grasses et plus grosses que celles de la Manche. En Aragon on les coupe en dés plutôt qu'en miettes, et on les sert avec du chocolat chaud au petit-déjeuner — l'usage surprend, il est pourtant ancien.",
     en:"Bread crumbs fried with Teruel ham and grapes, fattier and coarser than the La Mancha kind. In Aragon they are cut into dice rather than crumbs, and served with hot chocolate at breakfast — the custom surprises, but it is old."},
  i:[['rustic_bread',600,'g'],['serrano_ham',200,'g'],['pork_belly',150,'g'],['garlic',8,'clove'],['grapes',250,'g'],['olive_oil',120,'ml'],['sweet_paprika',1,'tbsp'],['water',150,'ml'],['salt',null,'']],
  s:{fr:["Coupez le pain rassis en dés d'un demi-centimètre plutôt que de l'émietter : c'est la coupe aragonaise, et elle donne une bouchée plus franche.","Humectez d'eau salée en aspergeant à la main, mêlez, et laissez reposer sous un linge de six à douze heures.","Faites rissoler l'ail en chemise, le lard et le jambon en dés dans l'huile, et retirez-les.","Jetez les dés de pain dans la graisse et remuez sans arrêt 25 minutes à feu moyen — c'est un exercice de bras, il n'y a pas de raccourci.","Ajoutez le paprika hors du feu, remettez viandes et raisin frais, et servez brûlant. Le raisin apporte l'acidité qui coupe la graisse."],
     en:["Cut the stale bread into half-centimetre dice rather than crumbling it: that is the Aragonese cut, and it gives a firmer mouthful.","Dampen with salted water sprinkled by hand, mix, and rest under a cloth for six to twelve hours.","Fry the unpeeled garlic, the belly and the diced ham in the oil, and lift them out.","Tip the bread dice into the fat and stir without pause for 25 minutes over medium heat — this is an arm exercise, there is no shortcut.","Add the paprika off the heat, return the meats and the fresh grapes, and serve scalding. The grapes bring the acidity that cuts the fat."]} },

{ id:'bacalao-ajoarriero', c:'eu', lat:42.813, lon:-1.645, base:4, prep:40, cook:40, diff:2, tags:['sea','stew','comfort'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e4c8',style:'stew',food:['#c9532c','#f0e8d0','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Bacalao al ajoarriero',en:'Bacalao al ajoarriero'},
  p:{fr:'Pampelune, Navarre, Espagne',en:'Pamplona, Navarre, Spain'},
  d:{fr:"De la morue effilochée mijotée avec de l'ail, du poivron choricero et de la tomate. Le nom vient des arrieros, les muletiers qui transportaient la morue salée à travers l'Espagne : ils la cuisinaient sur la route, avec l'ail qu'ils avaient toujours sur eux.",
     en:"Shredded salt cod stewed with garlic, choricero pepper and tomato. The name comes from the arrieros, the muleteers who carried salt cod across Spain: they cooked it on the road, with the garlic they always carried."},
  i:[['salt_cod',600,'g'],['choricero_peppers',4,'pc'],['garlic',10,'clove'],['onion',2,'pc'],['ripe_tomato',400,'g'],['green_pepper',1,'pc'],['olive_oil',120,'ml'],['cayenne',1,'pinch'],['potato',400,'g'],['salt',null,'']],
  s:{fr:["Dessalez la morue 36 heures au réfrigérateur en changeant l'eau cinq fois, puis effilochez-la crue à la main, en filaments.","Faites tremper les poivrons choriceros 2 heures à l'eau chaude et grattez la pulpe à la cuillère : c'est elle, et non le paprika, qui donne la couleur et le goût.","Faites confire l'oignon et le poivron vert 30 minutes à feu doux, puis ajoutez l'ail émincé sans le laisser brunir.","Ajoutez la tomate râpée et la pulpe de choricero, et laissez réduire 20 minutes jusqu'à une pâte épaisse.","Incorporez la morue et remuez en mouvements de poêle plutôt qu'à la cuillère : la gélatine de la peau lie la sauce d'elle-même. 10 minutes, et pas une de plus."],
     en:["Desalt the cod 36 hours in the fridge, changing the water five times, then shred it raw by hand into strands.","Soak the choricero peppers 2 hours in hot water and scrape the pulp with a spoon: it, not paprika, gives the colour and the flavour.","Confit the onion and green pepper 30 minutes over low heat, then add the sliced garlic without letting it brown.","Add the grated tomato and the choricero pulp, and reduce for 20 minutes to a thick paste.","Fold in the cod and move it by shaking the pan rather than with a spoon: the gelatine from the skin binds the sauce by itself. 10 minutes, and not one more."]} },

{ id:'tumbet-mallorqui', c:'eu', lat:39.570, lon:2.650, base:4, prep:50, cook:60, diff:2, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#c9402c','#7fae5a','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Tumbet majorquin',en:'Mallorcan tumbet'},
  p:{fr:'Palma, Majorque, Baléares, Espagne',en:'Palma, Mallorca, Balearics, Spain'},
  d:{fr:"Des couches de pommes de terre, d'aubergines et de poivrons frits séparément, noyées de sauce tomate. Chaque légume est frit à part parce qu'ils n'ont ni le même temps de cuisson ni la même façon de boire l'huile : c'est long, et c'est la définition même du plat.",
     en:"Layers of potato, aubergine and pepper fried separately, flooded with tomato sauce. Each vegetable is fried alone because none shares the same cooking time or the same way of drinking oil: it is slow, and it is the very definition of the dish."},
  i:[['potato',600,'g'],['eggplant',600,'g'],['red_pepper',3,'pc'],['ripe_tomato',800,'g'],['garlic',6,'clove'],['olive_oil',400,'ml'],['bay_leaf',2,'pc'],['sugar',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez les aubergines en rondelles, salez-les et laissez-les dégorger 45 minutes dans une passoire, puis épongez-les à fond.","Cette étape n'est pas facultative : une aubergine non dégorgée boit trois fois plus d'huile et rend son eau dans le plat.","Frites séparément, dans le même bain d'huile : d'abord les pommes de terre, puis les poivrons, enfin les aubergines — de la plus neutre à la plus parfumée.","Faites une sauce tomate longue, 40 minutes, avec l'ail, le laurier et une pointe de sucre, et passez-la au tamis.","Montez les couches dans un plat de terre en salant chacune, nappez de sauce et enfournez 20 minutes à 180 °C. Se mange tiède ou froid, jamais brûlant."],
     en:["Slice the aubergines, salt them and let them drain 45 minutes in a colander, then blot them thoroughly.","This step is not optional: an undrained aubergine drinks three times the oil and weeps into the dish.","Fry each vegetable separately in the same oil: potatoes first, then peppers, aubergines last — from the most neutral to the most scented.","Make a long tomato sauce, 40 minutes, with the garlic, bay and a pinch of sugar, and pass it through a sieve.","Build the layers in an earthenware dish, salting each, coat with sauce and bake 20 minutes at 180°C. Eaten warm or cold, never scalding."]} },

{ id:'gofio-escaldado', c:'eu', lat:28.093, lon:-17.110, base:4, prep:15, cook:20, diff:1, tags:['veg','fast','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9a878','#e8dcb8','#8f6a4a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Gofio escaldado',en:'Gofio escaldado'},
  p:{fr:'La Gomera, Canaries, Espagne',en:'La Gomera, Canary Islands, Spain'},
  d:{fr:"De la farine de céréales grillées ébouillantée d'un bouillon de poisson, battue en purée épaisse et mangée à la cuillère. Le gofio est l'héritage des Guanches, les habitants des Canaries avant la conquête : ils torréfiaient l'orge avant de la moudre, et l'usage n'a jamais cessé.",
     en:"Toasted grain flour scalded with fish broth, beaten to a thick purée and eaten with a spoon. Gofio is the inheritance of the Guanches, the Canaries' people before the conquest: they toasted barley before grinding it, and the practice has never stopped."},
  i:[['gofio',250,'g'],['fish_broth',600,'ml'],['garlic',3,'clove'],['mint',1,'bunch'],['cilantro',1,'bunch'],['onion',1,'pc'],['olive_oil',40,'ml'],['salt',null,'']],
  s:{fr:["Préparez un bouillon de têtes et d'arêtes de poisson, filtré et bien corsé : le gofio ne se fait à l'eau que dans les périodes de misère.","Pilez au mortier l'ail, la menthe, la coriandre et un peu de sel jusqu'à obtenir une pâte verte.","Versez le bouillon bouillant sur le gofio d'un seul coup, en fouettant énergiquement dès le contact : versé lentement, il fait des grumeaux que rien ne défait.","Travaillez 5 minutes à la cuillère de bois : la pâte doit se détacher des parois et former un ruban lourd.","Incorporez le pilon d'herbes, dressez en dôme et creusez le dessus à la cuillère pour y verser un filet d'huile et de l'oignon cru émincé."],
     en:["Make a broth from fish heads and bones, strained and full-flavoured: gofio is made with water only in years of hardship.","Pound the garlic, mint, coriander and a little salt in a mortar to a green paste.","Pour the boiling broth onto the gofio all at once, whisking hard from the moment they meet: poured slowly it lumps beyond rescue.","Work it 5 minutes with a wooden spoon: the paste must come away from the sides and fall in a heavy ribbon.","Fold in the herb paste, mound it up and hollow the top with a spoon to hold a trickle of oil and some raw sliced onion."]} },

{ id:'mojo-picon', c:'eu', lat:28.684, lon:-17.764, base:6, prep:25, cook:0, diff:1, tags:['veg','spicy','fast'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'other',food:['#c9402c','#8f3b2a','#e0913a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Mojo picón',en:'Mojo picón'},
  p:{fr:'La Palma, Canaries, Espagne',en:'La Palma, Canary Islands, Spain'},
  d:{fr:"Une sauce rouge d'ail, de piment palmero, de cumin et de paprika, montée à l'huile et au vinaigre. Il existe un mojo pour chaque chose : le rouge pour la viande et les papas, le vert à la coriandre pour le poisson, et l'on ne les intervertit pas.",
     en:"A red sauce of garlic, palmero chilli, cumin and paprika, mounted with oil and vinegar. There is a mojo for everything: red for meat and potatoes, green with coriander for fish, and they are not swapped."},
  i:[['dried_chili',4,'pc'],['garlic',8,'clove'],['cumin',1,'tbsp'],['sweet_paprika',1,'tbsp'],['white_vinegar',80,'ml'],['olive_oil',200,'ml'],['bread',1,'slice'],['coarse_salt',1,'tbsp']],
  s:{fr:["Faites tremper les piments secs 30 minutes à l'eau chaude, ouvrez-les et grattez la pulpe à la cuillère en jetant graines et peaux.","Pilez au mortier l'ail avec le gros sel : le sel sert d'abrasif, et l'ail se réduit en crème au lieu de sauter dans les coins.","Ajoutez le cumin, le paprika et la pulpe de piment, et continuez à piler jusqu'à obtenir une pâte homogène.","Versez le vinaigre puis l'huile en filet mince, sans cesser de tourner le pilon dans le même sens — c'est une émulsion, elle tranche si l'on va trop vite.","Ajoutez une mie de pain trempée si le mojo reste trop liquide. Laissez reposer 24 heures : il est mauvais le premier jour et excellent le second."],
     en:["Soak the dried chillies 30 minutes in hot water, open them and scrape the pulp with a spoon, discarding seeds and skins.","Pound the garlic with the coarse salt in a mortar: the salt acts as an abrasive, and the garlic turns to cream instead of leaping into the corners.","Add the cumin, paprika and chilli pulp, and keep pounding to an even paste.","Pour in the vinegar then the oil in a thin stream, turning the pestle always the same way — this is an emulsion, and it splits if you hurry.","Add a soaked crumb of bread if the mojo stays thin. Rest it 24 hours: it is poor on the first day and excellent on the second."]} },

{ id:'bienmesabe-canario', c:'eu', lat:28.291, lon:-16.629, base:6, prep:30, cook:25, diff:2, tags:['sweet','comfort','fruit'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Bienmesabe canarien',en:'Canarian bienmesabe'},
  p:{fr:'Tenerife, Canaries, Espagne',en:'Tenerife, Canary Islands, Spain'},
  d:{fr:"Une crème épaisse d'amandes, de jaunes d'œufs et de sirop, parfumée au citron et à la cannelle. Le nom veut dire cela me sait bon : il vient d'al-Andalus par Antequera, et les couvents canariens l'ont adopté au XVIIᵉ siècle en le rendant plus dense.",
     en:"A thick cream of almonds, egg yolks and syrup, scented with lemon and cinnamon. The name means it tastes good to me: it came from al-Andalus by way of Antequera, and Canarian convents adopted it in the 17th century, making it denser."},
  i:[['ground_almonds',300,'g'],['sugar',350,'g'],['water',250,'ml'],['egg_yolk',8,'pc'],['lemon_zest',1,'pc'],['cinnamon',1,'stick'],['rum',30,'ml'],['sponge_cake',200,'g']],
  s:{fr:["Portez l'eau et le sucre à 105 °C avec le zeste et la cannelle, puis retirez du feu et laissez descendre à 50 °C.","Incorporez la poudre d'amande au sirop tiède et remettez sur feu très doux 10 minutes en remuant.","Battez les jaunes à part, versez-y une louche de la préparation chaude en fouettant, puis reversez le tout dans la casserole.","Ce tempérage n'est pas une précaution superflue : les jaunes versés directement dans le sirop chaud cuisent en grumeaux irrécupérables.","Cuisez 10 minutes en dessous de 80 °C, sans jamais bouillir, jusqu'à ce que la crème nappe la cuillère. Parfumez au rhum et servez froid sur du biscuit."],
     en:["Bring the water and sugar to 105°C with the zest and cinnamon, then take it off and let it fall to 50°C.","Stir the ground almonds into the warm syrup and return to very low heat for 10 minutes, stirring.","Beat the yolks separately, pour a ladle of the hot mixture onto them whisking, then return everything to the pan.","This tempering is no idle precaution: yolks poured straight into hot syrup scramble into lumps beyond recovery.","Cook 10 minutes below 80°C, never boiling, until the cream coats the spoon. Scent with rum and serve cold over sponge."]} },

{ id:'tajarin-al-tartufo', c:'eu', lat:44.700, lon:8.036, base:4, prep:70, cook:3, diff:3, tags:['noodles','festive','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'noodle',food:['#e8c46a','#f2dfa8','#8f6a4a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tajarin à la truffe blanche',en:'Tajarin with white truffle'},
  p:{fr:'Alba, Piémont, Italie',en:'Alba, Piedmont, Italy'},
  d:{fr:"Des tagliolini très fins à trente jaunes d'œufs au kilo, servis au beurre et râpés de truffe blanche d'Alba. La pâte est jaune presque orange : elle ne contient pas un seul blanc, et c'est cette richesse qui lui permet d'être coupée aussi fin sans se rompre.",
     en:"Very fine tagliolini made with thirty egg yolks to the kilo, served in butter and shaved with white Alba truffle. The dough is almost orange: it contains not a single white, and that richness is what lets it be cut so fine without breaking."},
  i:[['flour_00',400,'g'],['egg_yolk',20,'pc'],['butter',150,'g'],['white_truffle',40,'g'],['parmesan',80,'g'],['semolina',60,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine et les jaunes 15 minutes : la pâte est très sèche au début et paraît impossible, elle se lisse à force de travail.","Enveloppez-la et laissez-la reposer 1 heure — sans repos, elle se rétracte à l'abaisse et ne descend jamais assez fin.","Abaissez au rouleau jusqu'à voir la main au travers, farinez à la semoule, roulez la feuille sur elle-même et coupez au couteau des rubans d'un millimètre.","Cuisez 90 secondes seulement dans une eau largement salée : ces pâtes-là sont cuites presque avant d'être tombées au fond.","Faites juste fondre le beurre sans le colorer, liez les tajarin avec une cuillerée d'eau de cuisson, et râpez la truffe à table, jamais avant."],
     en:["Knead the flour and yolks for 15 minutes: the dough is very dry at first and seems impossible, it smooths out with work.","Wrap it and rest it an hour — without rest it shrinks back as you roll and never goes thin enough.","Roll until you can see your hand through it, dust with semolina, roll the sheet on itself and cut one-millimetre ribbons with a knife.","Cook 90 seconds only in generously salted water: these noodles are done almost before they reach the bottom.","Melt the butter without colouring it, bind the tajarin with a spoonful of cooking water, and shave the truffle at the table, never before."]} },

{ id:'agnolotti-del-plin', c:'eu', lat:44.616, lon:8.036, base:4, prep:120, cook:3, diff:3, tags:['noodles','festive','sunday'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'noodle',food:['#e8c46a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Agnolotti del plin',en:'Agnolotti del plin'},
  p:{fr:'Langhe, Piémont, Italie',en:'Langhe, Piedmont, Italy'},
  d:{fr:"De minuscules raviolis fermés d'un pincement du pouce et de l'index — le plin — farcis de trois rôtis. On les sert traditionnellement sur une serviette, sans sauce du tout, pour qu'aucune humidité ne masque le goût de la farce.",
     en:"Tiny ravioli closed with a pinch of thumb and forefinger — the plin — filled with three roasted meats. They are traditionally served on a napkin, with no sauce at all, so that no moisture masks the taste of the filling."},
  i:[['flour_00',400,'g'],['egg',4,'pc'],['egg_yolk',4,'pc'],['veal',250,'g'],['pork_loin',250,'g'],['rabbit',250,'g'],['spinach',300,'g'],['parmesan',100,'g'],['butter',120,'g'],['white_wine',150,'ml'],['rosemary',3,'sprig'],['nutmeg',1,'pinch'],['sage',6,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites rôtir les trois viandes ensemble au beurre et au romarin, déglacez au vin blanc et laissez-les refroidir dans leur jus.","Hachez-les deux fois au hachoir fin avec les épinards blanchis et pressés, et liez au parmesan, aux jaunes et à la muscade.","Abaissez la pâte très fin et déposez des noisettes de farce tous les deux centimètres sur une seule bande.","Repliez la pâte par-dessus, chassez l'air, puis pincez entre deux tas : ce pincement est le plin, et il soude la pâte sans humecter.","Coupez à la roulette et cuisez 2 minutes. Servez au beurre de sauge, ou sur une serviette avec quelques gouttes du jus de rôti, comme dans les Langhe."],
     en:["Roast the three meats together in butter and rosemary, deglaze with white wine and let them cool in their juices.","Mince them twice on the fine plate with blanched, pressed spinach, and bind with parmesan, yolks and nutmeg.","Roll the dough very thin and set hazelnuts of filling every two centimetres along a single strip.","Fold the dough over, expel the air, then pinch between each mound: that pinch is the plin, and it seals without dampening.","Cut with a wheel and cook for 2 minutes. Serve in sage butter, or on a napkin with a few drops of the roasting juices, as in the Langhe."]} },

{ id:'gianduiotto', c:'eu', lat:45.070, lon:7.687, base:24, prep:60, cook:20, diff:3, tags:['sweet','festive','fast'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'other',food:['#6f4a2a','#8f5a3a','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Gianduiotto',en:'Gianduiotto'},
  p:{fr:'Turin, Piémont, Italie',en:'Turin, Piedmont, Italy'},
  d:{fr:"Un chocolat en lingot allongé, aux noisettes du Piémont, né du blocus continental de 1806. Le cacao manquant et coûtant cher, les chocolatiers turinois le coupèrent de pâte de noisette : la pénurie a produit le chocolat le plus copié du monde.",
     en:"An elongated chocolate ingot made with Piedmont hazelnuts, born of the continental blockade of 1806. With cocoa scarce and dear, Turin chocolatiers cut it with hazelnut paste: a shortage produced the most copied chocolate in the world."},
  i:[['hazelnuts',300,'g'],['dark_chocolate',200,'g'],['powdered_sugar',200,'g'],['cocoa_butter',50,'g'],['vanilla',1,'pc']],
  s:{fr:["Torréfiez les noisettes 15 minutes à 160 °C et frottez-les dans un linge : il ne doit pas rester une seule peau, qui rendrait la pâte amère et rêche.","Mixez-les longuement, dix minutes au moins, en raclant les parois : elles passent par le stade poudre, puis pâte, puis huile — c'est cette dernière qu'il faut atteindre.","Faites fondre le chocolat et le beurre de cacao à 45 °C, puis descendez à 27 °C en remuant sur un marbre avant de remonter à 31 °C.","Ce tempérage n'est pas facultatif : sans lui le gianduiotto blanchit en quelques jours et fond entre les doigts.","Mêlez pâte de noisette, chocolat tempéré et sucre glace, puis moulez en lingots à trois faces ou dressez-les à la poche. Laissez cristalliser 12 heures à 16 °C."],
     en:["Roast the hazelnuts 15 minutes at 160°C and rub them in a cloth: not one skin must remain, or the paste turns bitter and gritty.","Blend them at length, ten minutes at least, scraping the sides: they pass through powder, then paste, then oil — that last stage is the one to reach.","Melt the chocolate and cocoa butter to 45°C, then bring it down to 27°C stirring on marble before raising it to 31°C.","This tempering is not optional: without it the gianduiotto blooms within days and melts between the fingers.","Combine hazelnut paste, tempered chocolate and icing sugar, then mould into three-sided ingots or pipe them. Crystallise 12 hours at 16°C."]} },

{ id:'fonduta-valdostana', c:'eu', lat:45.737, lon:7.320, base:4, prep:720, cook:20, diff:3, tags:['cheese','comfort','festive'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f4ecd8',style:'other',food:['#e8c46a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Fonduta valdôtaine',en:'Valle d’Aosta fonduta'},
  p:{fr:'Aoste, Val d’Aoste, Italie',en:'Aosta, Aosta Valley, Italy'},
  d:{fr:"De la fontine fondue au lait et liée aux jaunes d'œufs, servie en crème et non filante. Contrairement aux fondues suisse et savoyarde, elle ne contient ni vin ni fécule : c'est un appareil aux œufs, plus proche d'une sauce que d'un caquelon.",
     en:"Fontina melted in milk and bound with egg yolks, served as a cream and not as a stringy mass. Unlike the Swiss and Savoyard fondues it holds neither wine nor starch: it is an egg custard, nearer to a sauce than to a pot."},
  i:[['fontina',400,'g'],['whole_milk',300,'ml'],['egg_yolk',4,'pc'],['butter',60,'g'],['white_truffle',20,'g'],['rustic_bread',400,'g'],['polenta',200,'g'],['pepper',null,'']],
  s:{fr:["Taillez la fontine en lamelles fines et faites-la tremper dans le lait 12 heures au réfrigérateur : sans ce trempage elle ne fond jamais uniformément.","Le lendemain, faites fondre le beurre au bain-marie et ajoutez le fromage avec son lait.","Remuez au fouet sans arrêt jusqu'à ce que le mélange devienne homogène ; ne dépassez jamais 70 °C, au-delà le fromage se sépare en fils et en huile.","Ajoutez les jaunes un à un, hors du feu, en fouettant vivement après chacun.","Remettez 3 minutes au bain-marie jusqu'à ce que la crème nappe la cuillère, poivrez et servez sur du pain grillé ou de la polenta, avec de la truffe blanche râpée."],
     en:["Slice the fontina thinly and soak it in the milk for 12 hours in the fridge: without that soaking it never melts evenly.","The next day, melt the butter in a bain-marie and add the cheese with its milk.","Whisk without pause until the mixture is even; never go above 70°C, beyond which the cheese separates into strings and oil.","Add the yolks one at a time, off the heat, whisking briskly after each.","Return to the bain-marie for 3 minutes until the cream coats the spoon, pepper and serve over toast or polenta, with shaved white truffle."]} },

{ id:'focaccia-genovese', c:'eu', lat:44.407, lon:8.934, base:8, prep:180, cook:20, diff:2, tags:['bread','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Focaccia génoise',en:'Genoese focaccia'},
  p:{fr:'Gênes, Ligurie, Italie',en:'Genoa, Liguria, Italy'},
  d:{fr:"Une focaccia basse et grasse, creusée de trous profonds où stagnent l'huile et la saumure. À Gênes on la trempe dans le cappuccino au petit-déjeuner ; les trous ne sont pas décoratifs, ils retiennent la saumure qui empêche la pâte de sécher au four.",
     en:"A low, oily focaccia dimpled with deep holes where oil and brine pool. In Genoa it is dipped in cappuccino at breakfast; the holes are not decorative, they hold the brine that keeps the dough from drying in the oven."},
  i:[['flour',500,'g'],['warm_water',330,'ml'],['fresh_yeast',15,'g'],['olive_oil',120,'ml'],['malt_extract',1,'tsp'],['coarse_salt',12,'g'],['water',80,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, l'eau tiède, la levure, le malt, 40 ml d'huile et le sel pendant 12 minutes : la pâte doit être souple et légèrement collante.","Laissez lever 1 heure, puis étalez-la à la main dans un plaque huilée sur 1,5 cm et laissez-la se détendre 45 minutes.","Enfoncez les doigts bien à plat jusqu'au fond du plat, en tenant la main verticale : les trous doivent traverser la pâte, pas seulement la marquer.","Battez ensemble l'eau restante, le gros sel et le reste d'huile pour faire la salamoia, et versez-la sur toute la surface.","Laissez pousser 45 minutes de plus — la saumure sera à moitié absorbée — et cuisez 18 minutes à 230 °C. Elle doit rester souple et luisante."],
     en:["Knead the flour, warm water, yeast, malt, 40 ml of oil and salt for 12 minutes: the dough should be supple and slightly tacky.","Prove for an hour, then spread it by hand in an oiled tray to 1.5 cm and let it relax for 45 minutes.","Push your fingers straight down to the bottom of the tray, hand held vertical: the holes must go through the dough, not merely mark it.","Beat the remaining water, coarse salt and remaining oil into a salamoia, and pour it over the whole surface.","Prove 45 minutes more — the brine will be half absorbed — and bake 18 minutes at 230°C. It must stay soft and glossy."]} },

{ id:'cotoletta-alla-milanese', c:'eu', lat:45.464, lon:9.190, base:4, prep:25, cook:15, diff:2, tags:['beef','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'flat',food:['#c9924a','#e0b45a','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Cotoletta alla milanese',en:'Cotoletta alla milanese'},
  p:{fr:'Milan, Lombardie, Italie',en:'Milan, Lombardy, Italy'},
  d:{fr:"Une côte de veau avec son os, panée et frite au beurre clarifié, épaisse comme un doigt. Elle ne s'aplatit pas : la véritable milanese garde l'épaisseur de la côte, et c'est la version viennoise, plus tardive, qui se bat au maillet.",
     en:"A veal cutlet on the bone, crumbed and fried in clarified butter, a finger thick. It is not flattened: the true milanese keeps the thickness of the chop, and it is the later Viennese version that is beaten with a mallet."},
  i:[['veal_chop',4,'pc'],['egg',3,'pc'],['breadcrumbs',250,'g'],['butter',250,'g'],['lemon',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Demandez des côtes de veau de deux centimètres avec le manche, et ne les aplatissez surtout pas.","Clarifiez le beurre : faites-le fondre doucement, écumez la mousse et versez en laissant le petit-lait au fond. Le beurre entier brûlerait bien avant la fin de la cuisson.","Battez les œufs sans les saler — le sel liquéfie l'œuf et la panure glisse — et trempez-y la côte entière, os compris.","Pressez fermement dans la chapelure fine des deux côtés, en appuyant du plat de la main pour qu'elle adhère.","Faites cuire 6 minutes par face dans le beurre clarifié mousseux, à feu moyen, en arrosant à la cuillère. Salez à la sortie, citron à table."],
     en:["Ask for two-centimetre veal chops with the bone, and on no account flatten them.","Clarify the butter: melt it gently, skim the foam and pour it off leaving the whey behind. Whole butter would burn long before the cooking ends.","Beat the eggs without salting them — salt thins the egg and the crumb slides off — and dip the whole chop, bone included.","Press firmly into fine breadcrumbs on both sides, pushing with the flat of your hand so they grip.","Cook 6 minutes a side in the foaming clarified butter over medium heat, spooning it over. Salt on coming out, lemon at the table."]} },

{ id:'panettone', c:'eu', lat:45.472, lon:9.181, base:12, prep:2400, cook:55, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f2dfa8','#4f3a2a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Panettone',en:'Panettone'},
  p:{fr:'Milan, Lombardie, Italie',en:'Milan, Lombardy, Italy'},
  d:{fr:"Un pain de Noël au levain naturel, aux raisins et aux écorces confites, qui lève trente-six heures. Il se refroidit suspendu la tête en bas, planté de deux broches : sa mie est si aérée et si fragile qu'elle s'affaisserait sous son propre poids.",
     en:"A Christmas bread raised on natural leaven, with raisins and candied peel, proved over thirty-six hours. It cools hanging upside down on two skewers: its crumb is so airy and so fragile that it would collapse under its own weight."},
  i:[['flour_00',500,'g'],['sourdough_starter',150,'g'],['sugar',150,'g'],['butter',200,'g'],['egg_yolk',8,'pc'],['raisins',200,'g'],['candied_orange',100,'g'],['candied_citron',80,'g'],['honey',20,'g'],['vanilla',1,'pc'],['orange_zest',1,'pc'],['water',150,'ml'],['salt',null,'']],
  s:{fr:["Rafraîchissez le levain trois fois dans la journée, à quatre heures d'intervalle : il doit tripler en trois heures et sentir le lait, jamais le vinaigre.","Faites un premier pétrissage le soir avec la moitié de la farine, du sucre, du beurre et des jaunes, et laissez lever 12 heures à 26 °C jusqu'à tripler.","Le lendemain, ajoutez le reste des ingrédients et pétrissez 25 minutes ; incorporez le beurre en dernier, petit à petit, puis les fruits à la main.","Laissez pousser 6 heures dans le moule de papier, jusqu'à ce que la pâte affleure le bord — jamais avant, sous peine de mie serrée.","Incisez une croix, posez une noix de beurre au centre et cuisez 55 minutes à 160 °C. Piquez deux broches à la base et suspendez-le retourné 12 heures."],
     en:["Refresh the starter three times in a day, four hours apart: it must triple in three hours and smell of milk, never of vinegar.","Make a first dough in the evening with half the flour, sugar, butter and yolks, and prove 12 hours at 26°C until tripled.","Next day add the remaining ingredients and knead 25 minutes; work in the butter last, little by little, then the fruit by hand.","Prove 6 hours in the paper mould, until the dough reaches the rim — never sooner, on pain of a tight crumb.","Cut a cross, set a knob of butter in the centre and bake 55 minutes at 160°C. Skewer it at the base and hang it upside down for 12 hours."]} },

{ id:'gorgonzola-e-polenta', c:'eu', lat:45.529, lon:9.404, base:4, prep:20, cook:50, diff:1, tags:['cheese','comfort','slow'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#e8c46a','#f4f0e6','#7f8fa0','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Polenta au gorgonzola',en:'Polenta with gorgonzola'},
  p:{fr:'Gorgonzola, Lombardie, Italie',en:'Gorgonzola, Lombardy, Italy'},
  d:{fr:"Une polenta jaune couverte de gorgonzola doux qui fond dessus, plat des bourgs de la plaine du Pô. Le gorgonzola doux ne se cuit pas : posé sur la polenta brûlante, il coule tout seul, et une cuisson au four le ferait tourner à l'huile.",
     en:"Yellow polenta covered with sweet gorgonzola melting over it, the dish of the Po plain towns. Sweet gorgonzola is not cooked: laid on scalding polenta it runs by itself, and an oven would turn it to oil."},
  i:[['polenta',300,'g'],['water',1.5,'l'],['gorgonzola',300,'g'],['butter',80,'g'],['parmesan',60,'g'],['walnuts',60,'g'],['coarse_salt',15,'g'],['pepper',null,'']],
  s:{fr:["Portez l'eau salée à ébullition et versez la semoule de maïs en pluie très fine d'une main, en fouettant vigoureusement de l'autre.","Passez ensuite à la cuillère de bois et remuez 45 minutes à feu doux, toujours dans le même sens, en raclant les parois.","Une polenta cuite moins de quarante minutes garde un goût de cru que ni le beurre ni le fromage ne masquent.","Elle est prête quand elle se détache du chaudron d'un bloc et qu'une croûte se forme au fond ; incorporez alors le beurre et le parmesan.","Versez brûlante dans les assiettes, posez le gorgonzola en gros morceaux dessus et parsemez de noix. Ne remuez pas : le fromage doit couler seul."],
     en:["Bring the salted water to the boil and rain in the maize meal very finely with one hand, whisking hard with the other.","Then switch to a wooden spoon and stir for 45 minutes over low heat, always the same way, scraping the sides.","Polenta cooked for less than forty minutes keeps a raw taste that neither butter nor cheese hides.","It is ready when it comes away from the pot in one block and a crust forms on the base; then beat in the butter and parmesan.","Pour it scalding into the plates, set the gorgonzola on top in large pieces and scatter walnuts. Do not stir: the cheese must run by itself."]} },

{ id:'baccala-mantecato', c:'eu', lat:45.438, lon:12.336, base:6, prep:60, cook:40, diff:3, tags:['sea','street','comfort'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Baccalà mantecato',en:'Baccalà mantecato'},
  p:{fr:'Venise, Vénétie, Italie',en:'Venice, Veneto, Italy'},
  d:{fr:"Du stockfish battu à l'huile jusqu'à devenir une mousse blanche, servi sur du pain grillé. Les Vénitiens emploient le stockfish séché à l'air, et non la morue salée : la confusion de vocabulaire est vieille de cinq siècles et vient d'un naufrage aux îles Lofoten en 1432.",
     en:"Stockfish beaten with oil into a white foam, served on toast. Venetians use air-dried stockfish, not salt cod: the confusion of terms is five centuries old and dates from a shipwreck in the Lofoten islands in 1432."},
  i:[['stockfish',600,'g'],['olive_oil',250,'ml'],['garlic',2,'clove'],['whole_milk',300,'ml'],['bay_leaf',2,'pc'],['parsley',3,'tbsp'],['polenta',200,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper le stockfish trois jours entiers à l'eau courante ou en changeant l'eau quatre fois par jour : c'est du bois sec, et rien ne raccourcit ce délai.","Pochez-le 30 minutes dans un mélange de lait et d'eau avec le laurier, sans bouillir, puis laissez-le tiédir dans son bouillon.","Retirez peau et arêtes avec soin, en travaillant à la main : une seule arête ruine la texture du mantecato.","Placez la chair dans un cul-de-poule et battez à la cuillère de bois en versant l'huile en filet, comme pour une mayonnaise, 20 minutes durant.","La chair doit blanchir et tripler de volume. Ajoutez un peu de bouillon si elle serre trop. Servez sur des croûtons de polenta grillée."],
     en:["Soak the stockfish for three full days under running water or changing the water four times a day: it is dry wood, and nothing shortens that.","Poach it 30 minutes in milk and water with the bay, without boiling, then let it cool in its liquid.","Remove skin and bones carefully, working by hand: a single bone ruins the texture of a mantecato.","Put the flesh in a bowl and beat with a wooden spoon while trickling in the oil, as for mayonnaise, for a full 20 minutes.","The flesh must whiten and triple in volume. Add a little of the poaching liquid if it tightens too much. Serve on grilled polenta croutons."]} },

{ id:'spritz-veneziano', c:'eu', lat:45.434, lon:12.339, base:4, prep:10, cook:0, diff:1, tags:['drink','fast','fresh'],
  art:{v:'glass',bg:'#33291f',plate:'#f4f0e6',style:'drink',food:['#e8621f','#f2a04a','#f0e8d0','#7fae5a'],garnish:'#c9754a'},
  n:{fr:'Spritz vénitien',en:'Venetian spritz'},
  p:{fr:'Venise, Vénétie, Italie',en:'Venice, Veneto, Italy'},
  d:{fr:"Du vin blanc, un amer et de l'eau gazeuse, servi avec une olive et une rondelle d'orange. Le nom vient de l'allemand spritzen, asperger : les soldats autrichiens de la Vénétie du XIXᵉ siècle coupaient d'eau les vins locaux, qu'ils trouvaient trop forts.",
     en:"White wine, a bitter and soda, served with an olive and a slice of orange. The name comes from German spritzen, to spray: 19th-century Austrian soldiers in the Veneto watered down the local wines, which they found too strong."},
  i:[['prosecco',300,'ml'],['aperol',200,'ml'],['sparkling_water',100,'ml'],['orange',1,'pc'],['green_olives',4,'pc'],['ice',12,'pc']],
  s:{fr:["Refroidissez les verres à pied au congélateur dix minutes : un verre tiède fait fondre la glace et déséquilibre tout en deux minutes.","Emplissez-les de glaçons jusqu'en haut — beaucoup de glace fond moins vite que peu de glace, contrairement à ce qu'on croit.","Respectez la proportion vénitienne de trois, deux, un : trois parts de prosecco, deux d'amer, une d'eau gazeuse.","Versez d'abord le prosecco puis l'amer, qui est plus lourd et descend en traînée orange à travers le verre ; remuez une seule fois.","Terminez par l'eau gazeuse, une demi-rondelle d'orange sur le bord et une olive verte piquée. À Venise, l'olive est obligatoire."],
     en:["Chill the stemmed glasses in the freezer for ten minutes: a warm glass melts the ice and unbalances everything within two minutes.","Fill them with ice to the top — plenty of ice melts more slowly than a little, contrary to what people think.","Keep the Venetian proportion of three, two, one: three parts prosecco, two of bitter, one of soda.","Pour the prosecco first then the bitter, which is heavier and falls through the glass in an orange trail; stir just once.","Finish with the soda, half a slice of orange on the rim and a green olive on a stick. In Venice the olive is compulsory."]} },

{ id:'bigoli-in-salsa', c:'eu', lat:45.441, lon:12.315, base:4, prep:70, cook:15, diff:2, tags:['noodles','sea','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'noodle',food:['#c9a878','#8f6a4a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Bigoli in salsa',en:'Bigoli in salsa'},
  p:{fr:'Venise, Vénétie, Italie',en:'Venice, Veneto, Italy'},
  d:{fr:"De gros spaghettis de blé complet servis avec une sauce d'oignons fondus et d'anchois, sans une once de fromage. C'est un plat de jours maigres : ni viande, ni œuf, ni parmesan, et Venise le mange encore le Vendredi saint et la veille de Noël.",
     en:"Thick wholemeal spaghetti served with a sauce of melted onion and anchovy, without a scrap of cheese. It is a fast-day dish: no meat, no egg, no parmesan, and Venice still eats it on Good Friday and Christmas Eve."},
  i:[['whole_wheat_flour',400,'g'],['water',180,'ml'],['onion',600,'g'],['salted_anchovies',12,'pc'],['olive_oil',120,'ml'],['white_wine',100,'ml'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine complète et l'eau tiède 15 minutes en une pâte très ferme, et laissez-la reposer 1 heure.","Passez-la au bigolaro, ou à défaut à la filière la plus large d'une machine à pâtes : les bigoli doivent être rugueux, c'est ce qui retient la sauce.","Émincez les oignons très finement et faites-les fondre dans l'huile 45 minutes à feu très doux, en ajoutant un peu d'eau dès qu'ils accrochent.","Dessalez les anchois, ôtez l'arête, et écrasez-les dans les oignons chauds : ils doivent se dissoudre entièrement, il ne faut plus en voir un seul morceau.","Déglacez au vin blanc, poivrez, et liez les bigoli cuits 8 minutes avec un peu d'eau de cuisson. Jamais de fromage, sous aucun prétexte."],
     en:["Knead the wholemeal flour and warm water for 15 minutes into a very firm dough, and rest it an hour.","Extrude it through a bigolaro, or failing that the widest die of a pasta machine: bigoli must be rough, that is what holds the sauce.","Slice the onions very finely and melt them in the oil for 45 minutes over very low heat, adding a little water whenever they catch.","Desalt the anchovies, remove the bone, and crush them into the hot onions: they must dissolve entirely, not one piece should remain visible.","Deglaze with white wine, pepper, and bind the bigoli, cooked 8 minutes, with a little of their water. Never cheese, under any circumstances."]} },

{ id:'tagliatelle-al-ragu', c:'eu', lat:44.494, lon:11.343, base:6, prep:60, cook:240, diff:3, tags:['noodles','slow','sunday'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'noodle',food:['#8f5a3a','#c9924a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tagliatelle al ragù',en:'Tagliatelle al ragù'},
  p:{fr:'Bologne, Émilie-Romagne, Italie',en:'Bologna, Emilia-Romagna, Italy'},
  d:{fr:"Le ragù déposé en 1982 à la chambre de commerce de Bologne, servi sur des tagliatelle et jamais sur des spaghettis. La recette officielle prescrit huit millimètres de largeur pour la pâte crue et interdit l'ail, les herbes et toute tomate autre qu'un peu de concentré.",
     en:"The ragù registered in 1982 with the Bologna chamber of commerce, served on tagliatelle and never on spaghetti. The official recipe prescribes eight millimetres of width for the raw pasta and forbids garlic, herbs and any tomato beyond a little purée."},
  i:[['ground_beef',400,'g'],['pancetta',150,'g'],['onion',1,'pc'],['carrot',1,'pc'],['celery',1,'pc'],['tomato_paste',3,'tbsp'],['white_wine',150,'ml'],['whole_milk',200,'ml'],['beef_broth',400,'ml'],['flour_00',400,'g'],['egg',4,'pc'],['butter',40,'g'],['parmesan',100,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites fondre la pancetta hachée puis le soffritto d'oignon, carotte et céleri très finement coupés, 25 minutes à feu doux.","Ajoutez le bœuf haché grossièrement et laissez-le colorer sans le remuer trop, jusqu'à ce qu'il ne reste plus d'eau au fond.","Déglacez au vin blanc, ajoutez le concentré et laissez mijoter 3 heures à découvert, en mouillant de bouillon à mesure.","Versez le lait dans la dernière heure : c'est lui qui attendrit la viande et arrondit l'acidité, et son absence se remarque immédiatement.","Pour les pâtes, pétrissez farine et œufs 15 minutes, abaissez très fin, roulez la feuille et coupez des rubans de 8 mm. Cuisez 2 minutes et liez au beurre et au parmesan."],
     en:["Render the chopped pancetta then the soffritto of very finely cut onion, carrot and celery, 25 minutes over low heat.","Add the coarsely minced beef and let it colour without stirring too much, until no water remains in the base.","Deglaze with white wine, add the purée and simmer 3 hours uncovered, moistening with broth as it goes.","Pour in the milk during the last hour: it is what tenderises the meat and rounds the acidity, and its absence is noticed at once.","For the pasta, knead flour and eggs 15 minutes, roll very thin, roll up the sheet and cut 8 mm ribbons. Cook 2 minutes and bind with butter and parmesan."]} },

{ id:'lasagne-alla-bolognese', c:'eu', lat:44.498, lon:11.353, base:8, prep:120, cook:250, diff:3, tags:['noodles','bake','sunday'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#8f5a3a','#f4f0e6','#4f6f3a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Lasagne alla bolognese',en:'Lasagne alla bolognese'},
  p:{fr:'Bologne, Émilie-Romagne, Italie',en:'Bologna, Emilia-Romagna, Italy'},
  d:{fr:"Des feuilles de pâte verte aux épinards alternées de ragù et de béchamel, en huit couches au moins. La pâte de Bologne est verte, pas jaune : l'épinard n'apporte presque aucun goût, mais il colore et rend la feuille plus souple à l'abaisse.",
     en:"Green spinach pasta sheets alternated with ragù and béchamel, in at least eight layers. Bologna's pasta is green, not yellow: the spinach adds almost no flavour, but it colours and makes the sheet more supple to roll."},
  i:[['flour_00',400,'g'],['egg',3,'pc'],['spinach',200,'g'],['ground_beef',500,'g'],['pancetta',150,'g'],['onion',1,'pc'],['carrot',1,'pc'],['celery',1,'pc'],['tomato_paste',3,'tbsp'],['white_wine',150,'ml'],['whole_milk',1,'l'],['flour',80,'g'],['butter',150,'g'],['parmesan',200,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Préparez le ragù la veille : il est meilleur reposé, et une nuit permet à la graisse de remonter et d'être retirée.","Blanchissez les épinards, pressez-les à fond et hachez-les au couteau avant de les pétrir avec la farine et les œufs.","Abaissez très fin, découpez des rectangles et pochez-les 45 secondes ; rafraîchissez-les et étalez-les sur des linges sans les superposer.","Montez huit couches en commençant et en finissant par la béchamel, avec très peu de garniture par étage : une lasagne se juge au nombre de feuilles, non à l'épaisseur du ragù.","Cuisez 35 minutes à 190 °C, puis 10 minutes de repos hors du four avant de couper : chaude, la lasagne coule dans l'assiette."],
     en:["Make the ragù the day before: it is better rested, and overnight lets the fat rise so it can be lifted off.","Blanch the spinach, press it thoroughly dry and chop it by knife before kneading it with the flour and eggs.","Roll very thin, cut rectangles and blanch them 45 seconds; refresh and lay them on cloths without overlapping.","Build eight layers beginning and ending with béchamel, with very little filling per layer: a lasagne is judged by its number of sheets, not the thickness of its ragù.","Bake 35 minutes at 190°C, then rest 10 minutes out of the oven before cutting: hot, a lasagne runs across the plate."]} },

{ id:'panzanella', c:'eu', lat:43.771, lon:11.256, base:4, prep:40, cook:0, diff:1, tags:['veg','fresh','bread'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'salad',food:['#c9402c','#7fae5a','#f0e8d0','#e0b45a'],garnish:'#6fbf8f'},
  n:{fr:'Panzanella',en:'Panzanella'},
  p:{fr:'Florence, Toscane, Italie',en:'Florence, Tuscany, Italy'},
  d:{fr:"Une salade de pain toscan rassis trempé, de tomates et d'oignon rouge, à l'huile et au vinaigre. Le pain de Toscane se fait sans sel : c'est pour cela qu'il rassit vite et sans moisir, et qu'on a inventé tant de plats pour le recycler.",
     en:"A salad of soaked stale Tuscan bread, tomatoes and red onion, with oil and vinegar. Tuscan bread is made without salt: which is why it goes stale fast without moulding, and why so many dishes were invented to use it up."},
  i:[['rustic_bread',400,'g'],['ripe_tomato',700,'g'],['red_onion',1,'pc'],['cucumber',1,'pc'],['basil',1,'bunch'],['olive_oil',100,'ml'],['red_wine_vinegar',40,'ml'],['water',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Employez un pain sans sel d'au moins deux jours : un pain frais devient de la colle et un pain salé déséquilibre l'assaisonnement.","Coupez-le en gros morceaux et trempez-les 10 minutes dans l'eau additionnée d'un peu de vinaigre.","Pressez-les ensuite fortement entre les mains, puis émiettez-les : ils doivent être humides mais non détrempés, et surtout pas en purée.","Faites dégorger l'oignon rouge émincé 20 minutes dans l'eau froide pour lui ôter son mordant, et salez les tomates à part pour recueillir leur jus.","Mêlez tout avec le jus des tomates, l'huile, le vinaigre et le basilic déchiré, et laissez reposer 1 heure à température ambiante avant de servir."],
     en:["Use unsalted bread at least two days old: fresh bread turns to glue and salted bread unbalances the seasoning.","Cut it into large pieces and soak them 10 minutes in the water with a little vinegar added.","Then press them hard between your hands and crumble them: they must be damp but not sodden, and on no account puréed.","Soak the sliced red onion 20 minutes in cold water to take off its bite, and salt the tomatoes separately to collect their juice.","Combine everything with the tomato juice, oil, vinegar and torn basil, and rest an hour at room temperature before serving."]} },

{ id:'cantucci-di-prato', c:'eu', lat:43.880, lon:11.097, base:20, prep:40, cook:40, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Cantucci de Prato',en:'Prato cantucci'},
  p:{fr:'Prato, Toscane, Italie',en:'Prato, Tuscany, Italy'},
  d:{fr:"Des biscuits aux amandes cuits deux fois, si durs qu'on les trempe dans le vin santo. Biscotto veut dire cuit deux fois : la seconde cuisson dessèche entièrement la mie, et c'est ce qui leur permet de se garder plusieurs mois dans une boîte.",
     en:"Almond biscuits baked twice, so hard that they are dipped in vin santo. Biscotto means twice cooked: the second baking dries the crumb entirely, and that is what lets them keep for months in a tin."},
  i:[['flour',400,'g'],['sugar',300,'g'],['egg',4,'pc'],['almonds',300,'g'],['baking_powder',1,'tsp'],['orange_zest',1,'pc'],['vanilla',1,'pc'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["N'émondez pas les amandes et ne les grillez pas : les cantucci de Prato les emploient crues et entières, avec leur peau.","Battez les œufs et le sucre, ajoutez la farine, la levure, le zeste et le sel, et incorporez les amandes en dernier à la main.","La pâte est très collante : farinez le plan de travail généreusement et façonnez des boudins plats de 5 cm de large, sans chercher à les lisser.","Dorez au jaune et cuisez 25 minutes à 180 °C, puis sortez-les et laissez-les tiédir dix minutes exactement.","Tranchez en biais à 1,5 cm pendant qu'ils sont encore tièdes — froids, ils s'émiettent — et recuisez les tranches 12 minutes à 150 °C, à plat."],
     en:["Do not blanch or toast the almonds: Prato cantucci use them raw and whole, skins on.","Beat the eggs and sugar, add the flour, baking powder, zest and salt, and fold in the almonds last by hand.","The dough is very sticky: flour the worktop generously and shape flat logs 5 cm wide, without trying to smooth them.","Glaze with yolk and bake 25 minutes at 180°C, then take them out and let them cool for exactly ten minutes.","Slice on the bias at 1.5 cm while still warm — cold, they shatter — and bake the slices flat for another 12 minutes at 150°C."]} },

{ id:'lampredotto', c:'eu', lat:43.770, lon:11.254, base:4, prep:30, cook:180, diff:2, tags:['beef','street','slow'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9a878','#8f6a4a','#4f6f3a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Lampredotto',en:'Lampredotto'},
  p:{fr:'Florence, Toscane, Italie',en:'Florence, Tuscany, Italy'},
  d:{fr:"La caillette de bœuf mijotée puis servie dans un petit pain trempé dans son bouillon, avec deux sauces vertes et piquantes. Les lampredottai de Florence tiennent leurs carrioles depuis le XVᵉ siècle ; le nom vient de la lamproie, que la caillette rappelle par sa forme.",
     en:"Beef abomasum stewed then served in a roll dipped in its own broth, with two sauces, green and hot. Florence's lampredottai have kept their carts since the 15th century; the name comes from the lamprey, which the tripe resembles in shape."},
  i:[['tripe',1,'kg'],['onion',2,'pc'],['carrot',2,'pc'],['celery',2,'pc'],['ripe_tomato',300,'g'],['parsley',1,'bunch'],['garlic',4,'clove'],['capers',2,'tbsp'],['anchovy_fillets',3,'pc'],['bread_roll',4,'pc'],['olive_oil',120,'ml'],['red_chili',3,'pc'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rincez la caillette longuement à l'eau froide et blanchissez-la 10 minutes, puis jetez cette première eau.","Remettez-la à cuire 3 heures avec oignon, carotte, céleri, tomate et laurier, à petits frémissements — un bouillon agité durcit la tripe.","Elle est prête quand une lame la traverse sans effort. Laissez-la refroidir dans son bouillon, puis tranchez-la finement.","Préparez la salsa verde en pilant persil, ail, câpres, anchois et huile, et une salsa piccante au piment et à l'huile.","Fendez le petit pain, trempez le chapeau dans le bouillon brûlant — trempé, jamais sec — garnissez de lampredotto et des deux sauces."],
     en:["Rinse the abomasum at length in cold water and blanch it 10 minutes, then throw that first water away.","Cook it again for 3 hours with onion, carrot, celery, tomato and bay, at a bare simmer — an agitated broth toughens tripe.","It is ready when a blade passes through without effort. Cool it in its broth, then slice it thinly.","Make the salsa verde by pounding parsley, garlic, capers, anchovies and oil, and a salsa piccante of chilli and oil.","Split the roll, dip the top in the scalding broth — dipped, never dry — fill with lampredotto and both sauces."]} },

{ id:'suppli', c:'eu', lat:41.891, lon:12.472, base:6, prep:60, cook:20, diff:2, tags:['rice','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e0b45a','#f4f0e6','#c9402c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Supplì',en:'Supplì'},
  p:{fr:'Rome, Latium, Italie',en:'Rome, Lazio, Italy'},
  d:{fr:"Des croquettes de risotto à la tomate au cœur de mozzarella, frites, qu'on rompt en deux pour voir le fil de fromage s'étirer. On les appelle supplì al telefono à cause de ce fil, qui rappelle le cordon d'un combiné ; sans lui, la croquette est ratée.",
     en:"Croquettes of tomato risotto with a mozzarella centre, fried, broken in two to see the cheese pull into a thread. They are called supplì al telefono because of that thread, like a handset cord; without it the croquette has failed."},
  i:[['arborio_rice',400,'g'],['ripe_tomato',400,'g'],['ground_beef',200,'g'],['mozzarella',250,'g'],['parmesan',80,'g'],['egg',4,'pc'],['breadcrumbs',300,'g'],['onion',1,'pc'],['white_wine',80,'ml'],['beef_broth',1,'l'],['butter',60,'g'],['olive_oil',1,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites un risotto à la tomate et à la viande, mais mouillez-le un peu moins que d'habitude : il doit être serré, presque sec.","Étalez-le sur une plaque et laissez-le refroidir complètement, au moins 4 heures — un risotto tiède ne se façonne pas.","Coupez la mozzarella en bâtonnets et laissez-les égoutter une heure sur du papier : c'est l'eau de la mozzarella qui fait éclater les supplì.","Formez des ovales autour de chaque bâtonnet, en veillant à ce que le fromage soit entièrement enrobé de riz.","Passez à l'œuf puis à la chapelure et frites 4 minutes à 175 °C. Laissez reposer deux minutes avant de rompre, sinon le fromage coule au lieu de filer."],
     en:["Make a tomato and meat risotto, but moisten it a little less than usual: it must be tight, almost dry.","Spread it on a tray and cool it completely, at least 4 hours — warm risotto cannot be shaped.","Cut the mozzarella into batons and drain them an hour on paper: it is the mozzarella's water that bursts supplì.","Shape ovals around each baton, making sure the cheese is entirely enclosed in rice.","Egg, then crumb, and fry 4 minutes at 175°C. Rest two minutes before breaking, or the cheese runs instead of pulling."]} },

{ id:'carciofi-alla-giudia', c:'eu', lat:41.892, lon:12.478, base:4, prep:40, cook:20, diff:3, tags:['veg','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#c9924a','#e0b45a','#8f6a4a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Carciofi alla giudia',en:'Carciofi alla giudia'},
  p:{fr:'Ghetto de Rome, Latium, Italie',en:'Roman Ghetto, Lazio, Italy'},
  d:{fr:"Un artichaut entier frit deux fois jusqu'à s'ouvrir en fleur, les feuilles extérieures craquantes comme des chips. C'est le plat du ghetto de Rome, où les Juifs romains furent confinés trois siècles ; l'artichaut romanesco, sans foin, ne se trouve que de février à avril.",
     en:"A whole artichoke fried twice until it opens like a flower, the outer leaves as crisp as crisps. It is the dish of the Roman Ghetto where Roman Jews were confined for three centuries; the romanesco artichoke, choke-free, is found only from February to April."},
  i:[['artichoke',8,'pc'],['lemon',3,'pc'],['olive_oil',1.5,'l'],['coarse_salt',2,'tbsp'],['pepper',null,'']],
  s:{fr:["Tournez les artichauts en spirale au couteau, en retirant les feuilles dures jusqu'aux feuilles claires, et parez la queue en la laissant longue.","Plongez-les au fur et à mesure dans l'eau citronnée : un artichaut coupé noircit en trois minutes.","Écrasez-les tête en bas sur le plan de travail pour ouvrir les feuilles, salez et poivrez entre elles.","Première friture à 130 °C, 10 minutes, tête en bas : elle cuit le cœur sans colorer. Sortez-les et laissez-les égoutter tête en bas 20 minutes.","Seconde friture à 180 °C, 3 minutes, en arrosant : les feuilles s'ouvrent et brunissent. Aspergez d'un peu d'eau froide à la fin, la vapeur les fait éclore d'un coup."],
     en:["Turn the artichokes in a spiral with a knife, taking off the tough leaves down to the pale ones, and trim the stem leaving it long.","Drop them into lemon water as you go: a cut artichoke blackens within three minutes.","Press them head down on the worktop to open the leaves, and season between them.","First frying at 130°C, 10 minutes, head down: it cooks the heart without colouring. Lift them out and drain head down for 20 minutes.","Second frying at 180°C, 3 minutes, spooning oil over: the leaves open and brown. Flick a little cold water in at the end, and the steam makes them bloom at once."]} },

{ id:'pastiera-napoletana', c:'eu', lat:40.851, lon:14.268, base:10, prep:90, cook:80, diff:3, tags:['sweet','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Pastiera napolitaine',en:'Neapolitan pastiera'},
  p:{fr:'Naples, Campanie, Italie',en:'Naples, Campania, Italy'},
  d:{fr:"Une tarte de Pâques au blé cuit, à la ricotta et à la fleur d'oranger, striée de sept bandes de pâte. Elle se prépare le Jeudi saint et se mange le dimanche : il lui faut trois jours pour que les parfums se lient, et elle est franchement meilleure le troisième.",
     en:"An Easter tart of cooked wheat, ricotta and orange blossom, latticed with seven strips of pastry. It is made on Maundy Thursday and eaten on Sunday: it needs three days for the scents to marry, and it is frankly better on the third."},
  i:[['flour',400,'g'],['butter',180,'g'],['sugar',450,'g'],['egg',7,'pc'],['cooked_wheat',400,'g'],['whole_milk',250,'ml'],['ricotta',500,'g'],['candied_citron',100,'g'],['candied_orange',100,'g'],['orange_blossom_water',3,'tbsp'],['cinnamon',1,'tsp'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire le blé avec le lait, un peu de beurre et le zeste, 30 minutes à feu doux, jusqu'à ce qu'il devienne crémeux : c'est cette crème de blé, et non les grains entiers, qui fait la pastiera.","Préparez une pâte sablée au saindoux ou au beurre, sans la travailler, et laissez-la reposer 2 heures au froid.","Passez la ricotta au tamis et battez-la longuement avec le sucre, puis ajoutez les jaunes un à un, les fruits confits, la fleur d'oranger et la cannelle.","Incorporez enfin les blancs montés en neige souple : ils allègent une garniture autrement compacte.","Garnissez le moule, disposez sept bandes de pâte en losanges et cuisez 1 h 20 à 170 °C. Laissez refroidir dans le four éteint et attendez deux jours."],
     en:["Cook the wheat with the milk, a little butter and the zest for 30 minutes over low heat, until creamy: it is that wheat cream, not whole grains, that makes a pastiera.","Make a rich shortcrust with lard or butter, without working it, and rest it 2 hours in the cold.","Sieve the ricotta and beat it at length with the sugar, then add the yolks one at a time, the candied fruit, orange blossom water and cinnamon.","Finally fold in the whites whisked to soft peaks: they lighten an otherwise dense filling.","Fill the tin, lay seven pastry strips in a lattice and bake 1 hour 20 at 170°C. Cool in the switched-off oven and wait two days."]} },

{ id:'baba-al-rum', c:'eu', lat:40.848, lon:14.257, base:8, prep:180, cook:25, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9924a','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Babà au rhum',en:'Rum babà'},
  p:{fr:'Naples, Campanie, Italie',en:'Naples, Campania, Italy'},
  d:{fr:"Une brioche en forme de champignon imbibée d'un sirop au rhum jusqu'à en dégoutter. Elle est arrivée à Naples par les cuisiniers français des Bourbons au XVIIIᵉ siècle ; les Napolitains l'ont adoptée si complètement que sei nu babà, tu es un babà, est devenu un compliment.",
     en:"A mushroom-shaped brioche soaked in rum syrup until it drips. It came to Naples with the French cooks of the Bourbons in the 18th century; Neapolitans adopted it so completely that sei nu babà, you are a babà, became a compliment."},
  i:[['flour_00',350,'g'],['egg',6,'pc'],['butter',120,'g'],['fresh_yeast',15,'g'],['sugar',400,'g'],['water',1,'l'],['rum',250,'ml'],['orange',1,'pc'],['lemon',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, la levure et trois œufs 10 minutes, puis ajoutez les autres œufs un à un en attendant l'absorption complète.","Incorporez le beurre mou en dernier et pétrissez encore 15 minutes : la pâte doit être si élastique qu'elle se laisse étirer en voile sans se rompre.","Laissez lever 2 heures, garnissez les moules au tiers seulement et laissez pousser jusqu'au bord, environ 1 heure.","Cuisez 25 minutes à 180 °C puis laissez sécher les babàs une nuit à l'air libre : un babà frais ne boit pas, un babà rassis boit tout.","Portez l'eau, le sucre et les zestes à ébullition, laissez tiédir à 60 °C, ajoutez le rhum et plongez les babàs. Retournez-les et pressez-les doucement à la spatule."],
     en:["Knead the flour, yeast and three eggs for 10 minutes, then add the other eggs one at a time, waiting for full absorption.","Work in the softened butter last and knead 15 minutes more: the dough must be so elastic it stretches to a veil without tearing.","Prove 2 hours, fill the moulds only a third full and let them rise to the rim, about an hour.","Bake 25 minutes at 180°C then let the babàs dry overnight in the open air: a fresh babà will not drink, a stale one drinks everything.","Boil the water, sugar and zests, let it fall to 60°C, add the rum and submerge the babàs. Turn them and press gently with a spatula."]} },

{ id:'ragu-napoletano', c:'eu', lat:40.836, lon:14.249, base:8, prep:60, cook:360, diff:3, tags:['beef','slow','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f2a2a','#6f2a2a','#c9532c','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Ragù napolitain',en:'Neapolitan ragù'},
  p:{fr:'Naples, Campanie, Italie',en:'Naples, Campania, Italy'},
  d:{fr:"De gros morceaux de viande mijotés six heures dans la tomate, dont la sauce assaisonne les pâtes et la viande sert de second plat. Rien à voir avec le ragù bolonais : la viande n'est pas hachée, et le napolitain dit que la sauce doit pippiare, glouglouter à peine, pendant tout ce temps.",
     en:"Large pieces of meat stewed six hours in tomato, the sauce dressing the pasta and the meat serving as a second course. Nothing to do with Bolognese ragù: the meat is not minced, and Neapolitans say the sauce must pippiare, barely burble, throughout."},
  i:[['beef_chuck',800,'g'],['pork_ribs',600,'g'],['pancetta',150,'g'],['onion',600,'g'],['tomato_puree',1.5,'l'],['tomato_paste',3,'tbsp'],['red_wine',300,'ml'],['garlic',4,'clove'],['parsley',4,'tbsp'],['pine_nuts',40,'g'],['raisins',40,'g'],['olive_oil',100,'ml'],['basil',1,'bunch'],['ziti',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites des braciole : aplatissez le paleron, garnissez de pancetta, d'ail, de persil, de pignons et de raisins, roulez et ficelez.","Faites-les dorer avec les côtes de porc dans l'huile, puis retirez-les et faites fondre l'oignon en lamelles épaisses 40 minutes.","Remettez les viandes, déglacez au vin rouge et laissez-le s'évaporer entièrement avant d'ajouter le concentré, puis la purée de tomate.","Laissez pippiare 6 heures à feu minimal, à demi couvert, en remuant à la cuillère de bois toutes les demi-heures pour que rien n'attache.","La sauce doit passer du rouge vif au brun sombre : c'est le seul indicateur fiable. Servez sur des ziti brisés à la main, la viande ensuite."],
     en:["Make braciole: flatten the chuck, fill with pancetta, garlic, parsley, pine nuts and raisins, roll and tie.","Brown them with the pork ribs in oil, then lift them out and melt thickly sliced onion for 40 minutes.","Return the meats, deglaze with red wine and let it evaporate entirely before adding the purée, then the tomato passata.","Let it pippiare for 6 hours over minimal heat, half covered, stirring with a wooden spoon every half hour so nothing catches.","The sauce must turn from bright red to dark brown: that is the only reliable indicator. Serve on hand-broken ziti, the meat afterwards."]} },

{ id:'frittura-di-paranza', c:'eu', lat:40.828, lon:14.246, base:4, prep:25, cook:10, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'fish',food:['#e8c46a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Frittura di paranza',en:'Frittura di paranza'},
  p:{fr:'Naples, Campanie, Italie',en:'Naples, Campania, Italy'},
  d:{fr:"Une friture de tout petits poissons du golfe, farinés et jetés entiers dans l'huile. La paranza est le bateau qui pêche au filet traînant : on ne choisit pas ce qu'on frit, on frit ce qui remonte, et la composition change chaque jour.",
     en:"A fry of the gulf's smallest fish, floured and thrown whole into the oil. The paranza is the trawler: you do not choose what you fry, you fry what came up, and the mix changes daily."},
  i:[['anchovies',300,'g'],['red_mullet',300,'g'],['baby_squid',300,'g'],['small_shrimp',200,'g'],['semolina_flour',300,'g'],['olive_oil',1.5,'l'],['lemon',3,'pc'],['coarse_salt',2,'tbsp'],['parsley',3,'tbsp']],
  s:{fr:["Ne videz que les poissons de plus de dix centimètres : les plus petits se mangent entiers, et les vider les ferait se défaire.","Épongez tout soigneusement puis farinez à la semoule fine dans un tamis, en secouant fort.","Séparez les espèces : le calmar demande deux minutes, l'anchois quarante secondes, et les frire ensemble ruinerait les uns ou les autres.","Portez l'huile à 190 °C et frites par petites poignées, jamais plus d'une poignée à la fois, pour que la température ne chute pas.","Égouttez dans une passoire, jamais sur du papier posé à plat, et salez à la sortie. Se mange dans les cinq minutes, au cornet."],
     en:["Gut only the fish over ten centimetres: the smallest are eaten whole, and gutting would make them fall apart.","Blot everything carefully then flour with fine semolina in a sieve, shaking hard.","Keep the species apart: squid needs two minutes, anchovy forty seconds, and frying them together ruins one or the other.","Take the oil to 190°C and fry in small handfuls, never more than one at a time, so the temperature does not fall.","Drain in a colander, never on paper laid flat, and salt as they come out. Eaten within five minutes, from a paper cone."]} },

{ id:'focaccia-barese', c:'eu', lat:41.117, lon:16.872, base:8, prep:150, cook:25, diff:2, tags:['bread','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9402c','#e0b45a','#3a2a1a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Focaccia barese',en:'Focaccia barese'},
  p:{fr:'Bari, Pouilles, Italie',en:'Bari, Apulia, Italy'},
  d:{fr:"Une focaccia à la pomme de terre, couverte de tomates cerises pressées et d'olives noires. La pomme de terre écrasée dans la pâte n'est pas une originalité : elle retient l'eau et garde la focaccia moelleuse deux jours, ce que la farine seule ne fait pas.",
     en:"A potato focaccia covered with crushed cherry tomatoes and black olives. The mashed potato in the dough is no eccentricity: it holds water and keeps the focaccia soft for two days, which flour alone cannot do."},
  i:[['semolina_flour',300,'g'],['flour',200,'g'],['potato',200,'g'],['fresh_yeast',15,'g'],['warm_water',350,'ml'],['olive_oil',120,'ml'],['cherry_tomato',400,'g'],['black_olives',150,'g'],['oregano',1,'tbsp'],['coarse_salt',12,'g'],['salt',null,'']],
  s:{fr:["Cuisez la pomme de terre entière, pelez-la chaude et écrasez-la au presse-purée : froide, elle formerait des grumeaux dans la pâte.","Pétrissez-la avec les deux farines, la levure, l'eau tiède, 40 ml d'huile et le sel, 12 minutes. La pâte doit rester très molle, presque coulante.","Laissez lever 1 h 30, versez dans un plat rond largement huilé et étalez du bout des doigts sans la travailler.","Pressez les tomates cerises coupées en deux dans la pâte, face coupée vers le haut, en les enfonçant à moitié, et parsemez d'olives entières non dénoyautées.","Salez au gros sel, arrosez d'huile, laissez pousser 45 minutes et cuisez 25 minutes à 230 °C. Le fond doit être frit dans l'huile, pas simplement cuit."],
     en:["Boil the potato whole, peel it hot and rice it: cold, it would lump in the dough.","Knead it with both flours, the yeast, warm water, 40 ml of oil and salt for 12 minutes. The dough must stay very soft, almost pourable.","Prove 1½ hours, tip into a generously oiled round tin and spread with your fingertips without working it.","Press the halved cherry tomatoes into the dough cut side up, sinking them halfway, and scatter whole unstoned olives.","Salt with coarse salt, moisten with oil, prove 45 minutes and bake 25 minutes at 230°C. The base should be fried in oil, not merely baked."]} },

{ id:'tiella-barese', c:'eu', lat:41.126, lon:16.867, base:6, prep:50, cook:60, diff:2, tags:['sea','bake','rice'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'rice',food:['#e8dcb8','#f0e8d0','#7fae5a','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Tiella barese',en:'Tiella barese'},
  p:{fr:'Bari, Pouilles, Italie',en:'Bari, Apulia, Italy'},
  d:{fr:"Des couches de pommes de terre, de riz et de moules crues cuites ensemble au four, sans un bouillon préalable. Le riz cuit dans l'eau que rendent les moules et les pommes de terre : c'est la seule cuisson possible, et elle interdit d'ouvrir le four avant la fin.",
     en:"Layers of potato, rice and raw mussels baked together, with no broth made first. The rice cooks in the water released by the mussels and the potatoes: it is the only possible method, and it forbids opening the oven before the end."},
  i:[['mussels',1.5,'kg'],['potato',800,'g'],['arborio_rice',250,'g'],['onion',2,'pc'],['cherry_tomato',300,'g'],['pecorino',80,'g'],['garlic',4,'clove'],['parsley',5,'tbsp'],['olive_oil',120,'ml'],['water',300,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ouvrez les moules crues au couteau, en gardant chacune sur sa demi-coquille et en recueillant toute leur eau : ne les faites surtout pas cuire pour les ouvrir.","Filtrez cette eau au linge fin : c'est l'assaisonnement principal du plat, et elle contient déjà tout le sel nécessaire.","Huilez la tiella, tapissez le fond d'oignon puis d'une couche de pommes de terre en rondelles de 3 mm.","Rangez les moules sur leur coquille, versez le riz cru sec par-dessus en le répartissant à la main, puis les tomates, l'ail, le persil et le pecorino.","Terminez par une seconde couche de pommes de terre, versez l'eau des moules complétée d'eau claire jusqu'à affleurer, et cuisez 55 minutes à 190 °C sans jamais ouvrir."],
     en:["Open the mussels raw with a knife, keeping each on its half shell and collecting every drop of their liquor: on no account cook them open.","Strain that liquor through fine cloth: it is the dish's main seasoning, and it already holds all the salt needed.","Oil the tiella, line the base with onion then a layer of 3 mm potato slices.","Arrange the mussels on their shells, scatter the dry raw rice over by hand, then the tomatoes, garlic, parsley and pecorino.","Finish with a second layer of potato, pour in the mussel liquor made up with clear water to just cover, and bake 55 minutes at 190°C without ever opening the door."]} },

{ id:'panzerotto-barese', c:'eu', lat:41.121, lon:16.860, base:8, prep:120, cook:20, diff:2, tags:['cheese','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9402c','#f4f0e6','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Panzerotto',en:'Panzerotto'},
  p:{fr:'Bari, Pouilles, Italie',en:'Bari, Apulia, Italy'},
  d:{fr:"Un chausson de pâte à pizza farci de tomate et de mozzarella, frit et non cuit au four. Il se mange debout et brûlant, en tenant la pointe vers le bas : le premier coup de dent libère une vapeur qui a ébouillanté des générations de Bariens.",
     en:"A pizza-dough turnover filled with tomato and mozzarella, fried rather than baked. It is eaten standing and scalding, held point down: the first bite releases a jet of steam that has scalded generations of Bari children."},
  i:[['flour',500,'g'],['fresh_yeast',10,'g'],['warm_water',300,'ml'],['olive_oil',30,'ml'],['mozzarella',300,'g'],['tomato_puree',300,'ml'],['oregano',1,'tbsp'],['frying_oil',1.5,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez une pâte à pizza souple et laissez-la lever lentement 4 heures, ou une nuit au froid : une pâte trop jeune boit l'huile.","Égouttez la mozzarella coupée en dés au moins 3 heures sur du papier, et faites réduire la purée de tomate jusqu'à ce qu'elle soit épaisse.","L'humidité est l'unique ennemi : une garniture mouillée fait éclater le panzerotto dans l'huile bouillante.","Découpez des disques de 15 cm, garnissez une moitié en laissant deux centimètres de bord libre, refermez et soudez à la fourchette en pressant fort.","Frites à 175 °C, 3 minutes en les retournant une fois, jusqu'à ce qu'ils gonflent et brunissent. Égouttez debout et mangez aussitôt."],
     en:["Knead a supple pizza dough and prove it slowly for 4 hours, or overnight in the cold: too young a dough drinks oil.","Drain the diced mozzarella at least 3 hours on paper, and reduce the tomato purée until thick.","Moisture is the only enemy: a wet filling bursts the panzerotto in the boiling oil.","Cut 15 cm discs, fill one half leaving a two-centimetre border, fold and seal with a fork, pressing hard.","Fry at 175°C for 3 minutes, turning once, until they puff and brown. Drain upright and eat at once."]} },

{ id:'peperoni-cruschi', c:'eu', lat:40.148, lon:16.286, base:4, prep:20, cook:5, diff:2, tags:['veg','fast','spicy'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'other',food:['#8f2a2a','#c9402c','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Peperoni cruschi',en:'Peperoni cruschi'},
  p:{fr:'Senise, Basilicate, Italie',en:'Senise, Basilicata, Italy'},
  d:{fr:"Des poivrons doux séchés au soleil puis frits trois secondes, croustillants comme des chips et sucrés. Crusco veut dire croquant en dialecte lucanien ; le poivron de Senise a la peau si fine qu'il sèche entier en quinze jours sans jamais moisir.",
     en:"Sweet peppers sun-dried then fried for three seconds, crisp as crisps and sweet. Crusco means crunchy in Lucanian dialect; the Senise pepper has skin so thin that it dries whole in a fortnight without ever moulding."},
  i:[['dried_sweet_peppers',20,'pc'],['olive_oil',300,'ml'],['coarse_salt',1,'tbsp'],['bread',300,'g'],['salt_cod',200,'g'],['garlic',3,'clove']],
  s:{fr:["Essuyez les poivrons séchés avec un linge sec — jamais d'eau — et ôtez la queue et les graines en les secouant.","Chauffez l'huile à 160 °C exactement, et vérifiez avec un petit morceau : il doit gonfler et changer de couleur en deux secondes.","Plongez les poivrons trois secondes, pas davantage : à la quatrième ils noircissent et deviennent amers, et rien ne les rattrape.","Sortez-les à l'écumoire et posez-les debout sur du papier : ils durcissent en refroidissant, et c'est en refroidissant qu'ils craquent.","Salez et servez tels quels, ou émiettez-les sur de la morue et du pain frit à l'ail, comme en Basilicate."],
     en:["Wipe the dried peppers with a dry cloth — never water — and shake out the stalk and seeds.","Heat the oil to exactly 160°C, and test with a small piece: it should swell and change colour in two seconds.","Plunge the peppers for three seconds, no longer: at the fourth they blacken and turn bitter, beyond rescue.","Lift them out with a skimmer and stand them on paper: they harden as they cool, and it is in cooling that they crisp.","Salt and serve as they are, or crumble them over salt cod and garlic-fried bread, as they do in Basilicata."]} },

{ id:'fileja-alla-nduja', c:'eu', lat:38.676, lon:16.101, base:4, prep:70, cook:20, diff:2, tags:['noodles','spicy','pork'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'noodle',food:['#c9402c','#8f2a2a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Fileja à la nduja',en:'Fileja with nduja'},
  p:{fr:'Vibo Valentia, Calabre, Italie',en:'Vibo Valentia, Calabria, Italy'},
  d:{fr:"Des pâtes roulées à la main autour d'une tige de fer, servies avec la nduja fondue dans la tomate. La nduja se dissout entièrement à la chaleur : elle n'est pas un morceau de charcuterie qu'on ajoute, elle devient la sauce elle-même.",
     en:"Pasta rolled by hand around an iron rod, served with nduja melted into tomato. Nduja dissolves entirely in the heat: it is not a piece of charcuterie added to the dish, it becomes the sauce itself."},
  i:[['semolina_flour',400,'g'],['water',200,'ml'],['nduja',150,'g'],['tomato_puree',600,'ml'],['onion',1,'pc'],['garlic',3,'clove'],['olive_oil',60,'ml'],['pecorino',80,'g'],['basil',1,'bunch'],['salt',null,'']],
  s:{fr:["Pétrissez la semoule et l'eau tiède 15 minutes en une pâte très ferme, et laissez-la reposer 30 minutes sous un bol.","Roulez des boudins gros comme un crayon, coupez des tronçons de 8 cm et enroulez chacun autour d'une tige de fer ou d'une aiguille à tricoter.","Retirez la tige en faisant rouler la pâte sur la table : il doit rester un tube creux et irrégulier, jamais lisse.","Faites revenir l'oignon dans l'huile, ajoutez la nduja et écrasez-la à la cuillère jusqu'à ce qu'elle fonde entièrement et colore l'huile en rouge.","Ajoutez la tomate et laissez cuire 20 minutes. Liez les fileja cuites 8 minutes avec un peu d'eau de cuisson et servez au pecorino."],
     en:["Knead the semolina and warm water for 15 minutes into a very firm dough, and rest it 30 minutes under a bowl.","Roll pencil-thick ropes, cut 8 cm lengths and wind each around an iron rod or knitting needle.","Withdraw the rod by rolling the pasta on the table: what remains should be a hollow, irregular tube, never smooth.","Fry the onion in oil, add the nduja and crush it with a spoon until it melts entirely and turns the oil red.","Add the tomato and cook 20 minutes. Bind the fileja, cooked 8 minutes, with a little of their water and serve with pecorino."]} },

{ id:'cannoli-siciliani', c:'eu', lat:37.490, lon:14.062, base:12, prep:120, cook:20, diff:3, tags:['sweet','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9924a','#f4f0e6','#4f3a2a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Cannoli siciliens',en:'Sicilian cannoli'},
  p:{fr:'Caltanissetta, Sicile, Italie',en:'Caltanissetta, Sicily, Italy'},
  d:{fr:"Des tubes de pâte frits garnis de ricotta de brebis sucrée, garnis seulement à la commande. Une coque garnie à l'avance ramollit en vingt minutes : à Palerme, un pâtissier qui remplit ses cannoli d'avance perd sa réputation en une saison.",
     en:"Fried pastry tubes filled with sweetened sheep's ricotta, filled only to order. A shell filled in advance goes soft within twenty minutes: in Palermo a pastry cook who fills his cannoli ahead loses his name in a season."},
  i:[['flour',300,'g'],['sugar',350,'g'],['lard',30,'g'],['marsala',80,'ml'],['egg',1,'pc'],['cocoa_powder',1,'tbsp'],['sheep_ricotta',800,'g'],['candied_orange',80,'g'],['dark_chocolate',80,'g'],['pistachios',60,'g'],['frying_oil',1.5,'l'],['powdered_sugar',40,'g'],['cinnamon',1,'tsp'],['salt',null,'']],
  s:{fr:["Égouttez la ricotta 24 heures dans un linge sous un poids : c'est la seule étape qui décide de la réussite, et elle ne se raccourcit pas.","Pétrissez la farine, 40 g de sucre, le saindoux, le cacao, le marsala et le sel en une pâte très ferme, et laissez-la reposer 2 heures.","Abaissez-la à 1 mm — on doit lire à travers — découpez des ovales et enroulez-les autour des tubes métalliques, en soudant à l'œuf battu.","Frites 2 minutes à 180 °C : la coque doit boursoufler en petites cloques, signe que la pâte était assez fine. Laissez refroidir avant de retirer les tubes.","Travaillez la ricotta au tamis avec le sucre restant, sans la fouetter, et garnissez à la poche au dernier moment, en garnissant par les deux bouts."],
     en:["Drain the ricotta 24 hours in a cloth under a weight: it is the one step that decides success, and it cannot be shortened.","Knead the flour, 40 g of the sugar, the lard, cocoa, marsala and salt into a very firm dough, and rest it 2 hours.","Roll it to 1 mm — you should be able to read through it — cut ovals and wrap them around metal tubes, sealing with beaten egg.","Fry 2 minutes at 180°C: the shell must blister into small bubbles, the sign the dough was thin enough. Cool before sliding off the tubes.","Sieve the ricotta with the remaining sugar, without whipping it, and pipe it in at the last moment, filling from both ends."]} },

{ id:'granita-al-limone', c:'eu', lat:38.194, lon:15.554, base:6, prep:240, cook:0, diff:2, tags:['sweet','fresh','fruit'],
  art:{v:'glass',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8f0d0','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Granita al limone',en:'Lemon granita'},
  p:{fr:'Messine, Sicile, Italie',en:'Messina, Sicily, Italy'},
  d:{fr:"Un sorbet gratté au citron, servi au petit-déjeuner avec une brioche col tuppo. Les Siciliens la mangent le matin, en trempant la brioche dedans ; la texture doit être crémeuse et non granuleuse, malgré le nom, et c'est le grattage régulier qui la donne.",
     en:"A scraped lemon ice, eaten at breakfast with a brioche col tuppo. Sicilians eat it in the morning, dipping the brioche in; the texture must be creamy and not gritty, despite the name, and regular scraping is what gives it."},
  i:[['lemon',8,'pc'],['sugar',250,'g'],['water',750,'ml'],['lemon_zest',2,'pc'],['salt',null,'']],
  s:{fr:["Faites un sirop avec l'eau, le sucre et les zestes prélevés sans blanc, portez à frémissement et laissez refroidir complètement avec les zestes dedans.","Filtrez, ajoutez le jus de citron fraîchement pressé et une minuscule pincée de sel, qui relève l'acidité sans se sentir.","Respectez la proportion : un cinquième de jus, quatre cinquièmes de sirop. Plus de jus et la granita gèle en bloc dur.","Versez sur 3 cm dans un bac plat et mettez au congélateur ; grattez à la fourchette toutes les vingt minutes, en insistant sur les bords qui prennent en premier.","Comptez cinq ou six grattages sur trois heures. Servez aussitôt, avec une brioche tiède — une granita qui attend redevient un bloc."],
     en:["Make a syrup with the water, sugar and zest pared without pith, bring to a tremble and cool completely with the zest in it.","Strain, add freshly squeezed lemon juice and a minute pinch of salt, which lifts the acidity without being tasted.","Keep the proportion: one part juice to four of syrup. More juice and the granita freezes into a hard block.","Pour 3 cm deep into a flat tray and freeze; scrape with a fork every twenty minutes, working the edges which set first.","Allow five or six scrapings over three hours. Serve at once with a warm brioche — a granita that waits becomes a block again."]} },

{ id:'cassata-siciliana', c:'eu', lat:38.116, lon:13.361, base:10, prep:180, cook:20, diff:3, tags:['sweet','festive','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#7fae5a','#f4f0e6','#e8c46a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Cassata sicilienne',en:'Sicilian cassata'},
  p:{fr:'Palerme, Sicile, Italie',en:'Palermo, Sicily, Italy'},
  d:{fr:"Un gâteau de ricotta chemisé de pâte d'amande verte et couvert de fruits confits, glacé au sucre. Il vient des couvents palermitains ; le vert de la pâte d'amande imite le manteau des religieuses, et les fruits confits disposés en couronne rappellent les mosaïques normandes.",
     en:"A ricotta cake lined with green marzipan and covered with candied fruit, iced with sugar. It comes from Palermo's convents; the green marzipan imitates the nuns' habit, and the candied fruit laid in a crown recalls Norman mosaics."},
  i:[['sponge_cake',400,'g'],['sheep_ricotta',800,'g'],['sugar',400,'g'],['ground_almonds',300,'g'],['powdered_sugar',300,'g'],['dark_chocolate',100,'g'],['candied_orange',150,'g'],['candied_citron',150,'g'],['marsala',80,'ml'],['pistachios',60,'g'],['lemon',2,'pc'],['water',80,'ml']],
  s:{fr:["Égouttez la ricotta 24 heures sous un poids, puis passez-la deux fois au tamis fin sans jamais la fouetter : fouettée, elle rend son eau et la cassata coule.","Mêlez-la au sucre, aux pépites de chocolat et à un peu de fruits confits en dés, et réfrigérez.","Faites la pâte d'amande avec la poudre d'amande, le sucre glace, l'eau et le colorant vert obtenu de pistaches mixées ; abaissez-la à 5 mm.","Chemisez un moule à bords inclinés en alternant des bandes de pâte d'amande et de biscuit imbibé de marsala, en les serrant l'une contre l'autre.","Garnissez de ricotta, fermez d'une couche de biscuit, pressez et réfrigérez 12 heures. Démoulez, glacez au sucre glace et à l'eau, et couronnez de fruits confits entiers."],
     en:["Drain the ricotta 24 hours under a weight, then pass it twice through a fine sieve without ever whipping it: whipped, it weeps and the cassata runs.","Mix it with the sugar, chocolate chips and a little diced candied fruit, and chill.","Make the marzipan with ground almonds, icing sugar, water and green colour from blended pistachios; roll it to 5 mm.","Line a sloping-sided mould alternating strips of marzipan and marsala-soaked sponge, pressed tight against each other.","Fill with the ricotta, close with a layer of sponge, press and chill 12 hours. Turn out, ice with icing sugar and water, and crown with whole candied fruit."]} },

{ id:'panelle', c:'eu', lat:38.115, lon:13.365, base:6, prep:60, cook:20, diff:2, tags:['veg','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#e0b45a','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Panelle',en:'Panelle'},
  p:{fr:'Palerme, Sicile, Italie',en:'Palermo, Sicily, Italy'},
  d:{fr:"Des galettes de farine de pois chiche frites, servies dans un petit pain au sésame. Elles sont un héritage arabe direct : le pois chiche moulu est arrivé en Sicile au IXᵉ siècle, et la panella reste l'en-cas de rue le moins cher de Palerme.",
     en:"Fried chickpea-flour wafers, served in a sesame roll. They are a direct Arab inheritance: ground chickpea reached Sicily in the 9th century, and the panella remains Palermo's cheapest street food."},
  i:[['chickpea_flour',300,'g'],['water',900,'ml'],['parsley',4,'tbsp'],['frying_oil',1,'l'],['sesame_roll',6,'pc'],['lemon',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Délayez la farine de pois chiche dans l'eau froide en fouettant, puis passez au chinois : un seul grumeau devient une bosse dure dans la panelle.","Portez sur feu moyen et remuez sans arrêt 20 minutes à la cuillère de bois, toujours dans le même sens.","La pâte est prête quand elle se détache des parois d'un bloc et qu'une cuillère y tient debout.","Versez-la brûlante sur un marbre huilé et étalez-la à la spatule sur 3 mm, aussi vite que possible : elle fige en une minute.","Découpez des rectangles une fois froide et frites-les 3 minutes à 180 °C, jusqu'à ce qu'elles boursouflent. Servez dans un pain au sésame, avec du citron."],
     en:["Whisk the chickpea flour into cold water, then pass it through a fine sieve: a single lump becomes a hard bump in the panella.","Set it over medium heat and stir without pause for 20 minutes with a wooden spoon, always the same way.","The batter is ready when it comes away from the sides in one block and a spoon stands up in it.","Pour it scalding onto an oiled marble and spread it with a spatula to 3 mm, as fast as you can: it sets within a minute.","Cut rectangles once cold and fry 3 minutes at 180°C, until they blister. Serve in a sesame roll, with lemon."]} },

{ id:'pasta-con-le-sarde', c:'eu', lat:38.120, lon:13.358, base:4, prep:50, cook:30, diff:2, tags:['noodles','sea','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'noodle',food:['#e8dcb8','#7fae5a','#c9924a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Pasta con le sarde',en:'Pasta con le sarde'},
  p:{fr:'Palerme, Sicile, Italie',en:'Palermo, Sicily, Italy'},
  d:{fr:"Des bucatini aux sardines fraîches, au fenouil sauvage, aux raisins secs et aux pignons. Le sucré-salé est arabe, le fenouil sauvage est sicilien : la légende attribue le plat au cuisinier du général Euphémios, débarqué en 827, qui n'avait sur place que du poisson et des herbes.",
     en:"Bucatini with fresh sardines, wild fennel, raisins and pine nuts. The sweet-and-savoury is Arab, the wild fennel Sicilian: legend gives the dish to the cook of general Euphemios, landed in 827, who had only fish and herbs to hand."},
  i:[['sardines',600,'g'],['wild_fennel',400,'g'],['bucatini',400,'g'],['raisins',60,'g'],['pine_nuts',60,'g'],['onion',1,'pc'],['salted_anchovies',4,'pc'],['saffron',1,'pinch'],['breadcrumbs',80,'g'],['olive_oil',100,'ml'],['salt',null,'']],
  s:{fr:["Faites bouillir le fenouil sauvage 15 minutes dans une grande eau salée, égouttez-le en gardant l'eau, et hachez-le.","Cette eau de cuisson servira à cuire les pâtes : c'est elle qui porte le goût du fenouil dans tout le plat, et la jeter serait perdre la moitié de la recette.","Levez les filets de sardines, faites blondir l'oignon, ajoutez les anchois dessalés et écrasez-les jusqu'à dissolution complète.","Ajoutez les sardines, les raisins gonflés, les pignons et le safran, et laissez cuire 10 minutes sans trop remuer pour garder des morceaux.","Cuisez les bucatini dans l'eau du fenouil, mélangez, et couvrez de chapelure grillée à sec — jamais de fromage, la Sicile ne le tolère pas sur le poisson."],
     en:["Boil the wild fennel 15 minutes in plenty of salted water, drain it keeping the water, and chop it.","That cooking water will cook the pasta: it carries the fennel through the whole dish, and throwing it away would lose half the recipe.","Fillet the sardines, soften the onion, add the desalted anchovies and crush them until they dissolve entirely.","Add the sardines, plumped raisins, pine nuts and saffron, and cook 10 minutes without stirring much, to keep pieces whole.","Cook the bucatini in the fennel water, combine, and cover with dry-toasted breadcrumbs — never cheese, Sicily does not allow it on fish."]} },

{ id:'porceddu-sardo', c:'eu', lat:40.122, lon:9.130, base:8, prep:60, cook:210, diff:3, tags:['pork','slow','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#c9754a','#8f5a3a','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Porceddu',en:'Porceddu'},
  p:{fr:'Barbagia, Sardaigne, Italie',en:'Barbagia, Sardinia, Italy'},
  d:{fr:"Un cochon de lait embroché et rôti debout devant un feu de myrte et de lentisque, sans autre assaisonnement que le sel. On le sert traditionnellement enfoui dans des branches de myrte fraîches pendant une demi-heure : la vapeur du myrte le parfume mieux qu'aucune marinade.",
     en:"A suckling pig spitted and roasted upright before a fire of myrtle and mastic, seasoned with nothing but salt. It is traditionally served buried in fresh myrtle branches for half an hour: the myrtle steam scents it better than any marinade."},
  i:[['suckling_pig',6,'kg'],['coarse_salt',150,'g'],['myrtle_branches',2,'kg'],['lard',100,'g'],['bay_leaf',6,'pc']],
  s:{fr:["Fendez le cochon, embrochez-le sur une tige de bois vert et plantez la broche en biais dans le sol, devant le feu et non au-dessus.","La cuisson se fait au rayonnement, jamais à la flamme directe : la graisse qui tombe dans le feu enflammerait la peau.","Comptez 3 heures en tournant la broche d'un quart de tour toutes les vingt minutes, et ne salez qu'à mi-cuisson.","Badigeonnez la peau d'une couenne de lard piquée au bout d'un bâton, ce qui la nourrit et la fait dorer uniformément.","Découpez-le et enfouissez les morceaux sous un tapis de myrte frais dans une caisse close, une demi-heure, avant de servir tiède."],
     en:["Split the pig, spit it on a green wood pole and plant the spit at an angle in the ground, in front of the fire and never over it.","Cooking is by radiant heat, never direct flame: fat falling into the fire would set the skin alight.","Allow 3 hours, turning the spit a quarter turn every twenty minutes, and salt only halfway through.","Baste the skin with a rind of pork fat on the end of a stick, which feeds it and browns it evenly.","Carve it and bury the pieces under a bed of fresh myrtle in a closed box for half an hour, before serving warm."]} },

{ id:'pane-carasau', c:'eu', lat:40.317, lon:9.330, base:10, prep:180, cook:20, diff:3, tags:['bread','bake','slow'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#f2dfa8','#e8dcb8','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Pane carasau',en:'Pane carasau'},
  p:{fr:'Barbagia, Sardaigne, Italie',en:'Barbagia, Sardinia, Italy'},
  d:{fr:"Des feuilles de pain de semoule si fines qu'on les appelle papier à musique, cuites deux fois. La première cuisson les fait gonfler en ballon ; on les fend alors en deux disques qu'on recuit séparément, et ils se gardent un an — c'était le pain des bergers partis six mois.",
     en:"Sheets of semolina bread so thin they are called music paper, baked twice. The first baking blows them into a balloon; they are then split into two discs and baked again separately, and they keep for a year — the bread of shepherds gone six months."},
  i:[['semolina_flour',600,'g'],['warm_water',350,'ml'],['fresh_yeast',10,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la semoule fine, l'eau tiède, la levure et le sel 20 minutes : la pâte doit être très ferme et parfaitement lisse.","Laissez lever 2 heures, divisez en boules de 100 g et abaissez chacune en disque de 1 mm, en farinant à la semoule.","Enfournez à 300 °C au moins, sur une pierre brûlante : le disque doit gonfler en ballon en moins de deux minutes. À four plus doux, il sèche sans se séparer.","Sortez-le aussitôt et fendez-le au couteau sur tout le pourtour pour obtenir deux disques, en vous protégeant de la vapeur.","Empilez les disques sous une planche pour les aplatir, puis recuisez-les 2 minutes chacun jusqu'à ce qu'ils dorent et craquent."],
     en:["Knead the fine semolina, warm water, yeast and salt for 20 minutes: the dough must be very firm and perfectly smooth.","Prove 2 hours, divide into 100 g balls and roll each into a 1 mm disc, dusting with semolina.","Bake at 300°C at least, on a scalding stone: the disc must balloon within two minutes. In a cooler oven it dries without separating.","Take it out at once and cut round the edge with a knife to get two discs, protecting yourself from the steam.","Stack the discs under a board to flatten them, then bake each again for 2 minutes until golden and brittle."]} },

{ id:'malloreddus-alla-campidanese', c:'eu', lat:39.436, lon:8.960, base:4, prep:70, cook:60, diff:2, tags:['noodles','pork','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'noodle',food:['#c9532c','#e0b45a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Malloreddus alla campidanese',en:'Malloreddus alla campidanese'},
  p:{fr:'Campidano, Sardaigne, Italie',en:'Campidano, Sardinia, Italy'},
  d:{fr:"De petits gnocchis de semoule au safran, striés sur un panier d'osier, avec une sauce de saucisse fraîche et de tomate. Malloreddus veut dire petits veaux en sarde : les femmes les façonnaient en forme de bêtes pour les fêtes, sur des paniers appelés ciuliris.",
     en:"Small saffron semolina gnocchi, ridged on a wicker basket, with a sauce of fresh sausage and tomato. Malloreddus means little calves in Sardinian: women shaped them like beasts for feast days, on baskets called ciuliris."},
  i:[['semolina_flour',400,'g'],['warm_water',200,'ml'],['saffron',1,'pinch'],['fresh_sausage',400,'g'],['tomato_puree',700,'ml'],['onion',1,'pc'],['pecorino',120,'g'],['basil',1,'bunch'],['olive_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Faites infuser le safran dans l'eau tiède 20 minutes : il doit teindre l'eau d'un jaune profond avant d'aller dans la pâte.","Pétrissez avec la semoule et le sel 15 minutes en une pâte ferme, et laissez-la reposer 30 minutes.","Roulez des boudins fins, coupez des tronçons d'un centimètre et écrasez chacun contre l'osier du panier avec le pouce, en le faisant rouler.","Les stries ne sont pas décoratives : elles retiennent la sauce, et un malloreddu lisse la laisse glisser dans l'assiette.","Faites une sauce en émiettant la saucisse crue dans l'oignon, sans la hacher, et laissez mijoter 45 minutes avec la tomate. Liez les pâtes cuites 12 minutes et couvrez de pecorino."],
     en:["Infuse the saffron in the warm water for 20 minutes: it must dye the water deep yellow before it goes into the dough.","Knead with the semolina and salt for 15 minutes into a firm dough, and rest it 30 minutes.","Roll thin ropes, cut one-centimetre pieces and press each against the wicker of the basket with your thumb, rolling it.","The ridges are not decorative: they hold the sauce, and a smooth malloreddu lets it slide into the plate.","Make the sauce by crumbling the raw sausage into the onion, without chopping it, and simmer 45 minutes with the tomato. Bind the pasta, cooked 12 minutes, and cover with pecorino."]} },

{ id:'gnocco-fritto', c:'eu', lat:44.647, lon:10.925, base:6, prep:90, cook:20, diff:2, tags:['bread','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#e0a8a0','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Gnocco fritto',en:'Gnocco fritto'},
  p:{fr:'Modène, Émilie-Romagne, Italie',en:'Modena, Emilia-Romagna, Italy'},
  d:{fr:"Des losanges de pâte à pain frits dans le saindoux, qui gonflent en coussins creux, servis avec de la charcuterie. Le saindoux n'est pas remplaçable par de l'huile : c'est lui qui donne le goût, et à Modène on le met aussi dans la pâte.",
     en:"Diamonds of bread dough fried in lard, which puff into hollow cushions, served with charcuterie. Lard cannot be replaced by oil: it is what gives the flavour, and in Modena it goes into the dough as well."},
  i:[['flour',500,'g'],['whole_milk',250,'ml'],['fresh_yeast',12,'g'],['lard',600,'g'],['prosciutto',200,'g'],['salami',150,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, le lait tiède, la levure, 50 g de saindoux et le sel 12 minutes, et laissez lever 1 h 30.","Abaissez la pâte à 3 mm exactement : plus épaisse elle reste crue au centre, plus fine elle ne gonfle pas.","Découpez des losanges de 8 cm à la roulette et laissez-les reposer 15 minutes à découvert, pour qu'ils sèchent en surface.","Faites fondre le reste de saindoux et portez-le à 180 °C ; plongez deux ou trois losanges à la fois, pas plus.","Ils gonflent en dix secondes : arrosez-les de graisse à la louche pour qu'ils se remplissent d'air, retournez-les et sortez-les à 30 secondes. Servez brûlants avec la charcuterie."],
     en:["Knead the flour, warm milk, yeast, 50 g of lard and salt for 12 minutes, and prove 1½ hours.","Roll the dough to exactly 3 mm: thicker it stays raw inside, thinner it does not puff.","Cut 8 cm diamonds with a wheel and rest them uncovered for 15 minutes, so the surface dries.","Melt the remaining lard and take it to 180°C; drop in two or three diamonds at a time, no more.","They puff within ten seconds: ladle fat over them so they fill with air, turn them and lift them out at 30 seconds. Serve scalding with the charcuterie."]} },

{ id:'torta-al-testo', c:'eu', lat:43.112, lon:12.389, base:6, prep:60, cook:20, diff:1, tags:['bread','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8dcb8','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Torta al testo',en:'Torta al testo'},
  p:{fr:'Pérouse, Ombrie, Italie',en:'Perugia, Umbria, Italy'},
  d:{fr:"Un pain plat sans levure cuit sur un disque de pierre ou de fonte, fendu et garni de charcuterie ou d'herbes sautées. Le testo est la pierre elle-même : chauffée dans la cheminée, elle cuit le pain par contact et par masse, sans four — c'est un pain de maison sans boulanger.",
     en:"An unleavened flatbread cooked on a stone or cast-iron disc, split and filled with charcuterie or sautéed greens. The testo is the stone itself: heated in the hearth, it cooks the bread by contact and mass, with no oven — a household bread needing no baker."},
  i:[['flour',500,'g'],['water',250,'ml'],['olive_oil',40,'ml'],['baking_soda',1,'tsp'],['prosciutto',200,'g'],['pecorino',150,'g'],['swiss_chard',400,'g'],['garlic',3,'clove'],['salt',null,'']],
  s:{fr:["Mêlez la farine, le bicarbonate et le sel, ajoutez l'eau et l'huile et pétrissez 8 minutes en une pâte souple mais non collante.","Laissez-la reposer 30 minutes sous un linge : sans repos, elle se rétracte à l'abaisse et cuit en galette dure.","Divisez en deux et étalez des disques d'un centimètre, du diamètre exact de votre testo ou de votre poêle en fonte.","Chauffez le testo à sec, très chaud, et cuisez 8 minutes par face en piquant les cloques à la fourchette dès qu'elles apparaissent.","Fendez la torta brûlante à l'horizontale et garnissez de charcuterie, de pecorino ou de blettes sautées à l'ail. Se mange dans la demi-heure."],
     en:["Mix the flour, bicarbonate and salt, add the water and oil and knead 8 minutes into a supple but non-sticky dough.","Rest it 30 minutes under a cloth: without rest it shrinks back as you roll and bakes into a hard disc.","Divide in two and roll one-centimetre discs, the exact diameter of your testo or cast-iron pan.","Heat the testo dry and very hot, and cook 8 minutes a side, pricking the blisters with a fork as they appear.","Split the scalding torta horizontally and fill with charcuterie, pecorino or chard sautéed with garlic. Eaten within the half hour."]} },

{ id:'gricia', c:'eu', lat:42.663, lon:13.132, base:4, prep:15, cook:15, diff:2, tags:['noodles','pork','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'noodle',food:['#f4f0e6','#c9924a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Gricia',en:'Gricia'},
  p:{fr:'Grisciano, Latium, Italie',en:'Grisciano, Lazio, Italy'},
  d:{fr:"Des pâtes au guanciale et au pecorino, sans tomate ni œuf : la matrice dont dérivent l'amatriciana et la carbonara. On l'appelle parfois amatriciana blanche ; elle est en réalité plus ancienne, née avant que la tomate n'atteigne les Apennins.",
     en:"Pasta with guanciale and pecorino, no tomato and no egg: the mother from which amatriciana and carbonara derive. It is sometimes called white amatriciana; in truth it is older, born before the tomato reached the Apennines."},
  i:[['rigatoni',400,'g'],['guanciale',200,'g'],['pecorino',150,'g'],['black_peppercorns',2,'tbsp'],['salt',null,'']],
  s:{fr:["Taillez le guanciale en lardons épais d'un demi-centimètre, en gardant la couenne pour la retirer après.","Faites-le fondre à sec dans une poêle froide, à feu doux, 10 minutes : il doit rendre sa graisse lentement et devenir croustillant sans brûler.","Concassez le poivre au mortier et faites-le griller 30 secondes dans la graisse rendue, hors du feu : c'est ce qui réveille son parfum.","Cuisez les pâtes très al dente et transférez-les dans la poêle avec deux louches d'eau de cuisson.","Hors du feu, ajoutez le pecorino râpé en trois fois en remuant vivement : versé d'un coup sur une poêle chaude, il file et forme des grumeaux irrécupérables."],
     en:["Cut the guanciale into half-centimetre lardons, keeping the rind on to remove it afterwards.","Render it dry in a cold pan over low heat for 10 minutes: it must give up its fat slowly and crisp without burning.","Crack the pepper in a mortar and toast it 30 seconds in the rendered fat, off the heat: that is what wakes its scent.","Cook the pasta very al dente and transfer it to the pan with two ladles of its water.","Off the heat, add the grated pecorino in three goes, stirring briskly: tipped in at once onto a hot pan it strings and forms lumps beyond rescue."]} },

{ id:'spaghetti-alla-chitarra', c:'eu', lat:42.351, lon:14.167, base:4, prep:70, cook:90, diff:3, tags:['noodles','sunday','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'noodle',food:['#c9532c','#e8dcb8','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Spaghetti alla chitarra',en:'Spaghetti alla chitarra'},
  p:{fr:'Chieti, Abruzzes, Italie',en:'Chieti, Abruzzo, Italy'},
  d:{fr:"Des spaghettis carrés découpés en pressant la pâte sur un cadre de bois tendu de cordes, la chitarra. La section carrée n'est pas un détail : les arêtes vives accrochent la sauce comme aucun spaghetti rond ne le fait, et l'instrument date du début du XIXᵉ siècle.",
     en:"Square-sectioned spaghetti cut by pressing the dough onto a wooden frame strung with wires, the chitarra. The square section is no detail: the sharp edges grip sauce as no round spaghetti does, and the instrument dates from the early 19th century."},
  i:[['semolina_flour',300,'g'],['flour_00',100,'g'],['egg',4,'pc'],['ground_beef',200,'g'],['ground_lamb',200,'g'],['ground_pork',200,'g'],['tomato_puree',800,'ml'],['onion',1,'pc'],['red_wine',100,'ml'],['pecorino',100,'g'],['olive_oil',60,'ml'],['red_chili',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez les farines et les œufs 15 minutes en une pâte ferme, et laissez-la reposer 1 heure sous un bol.","Abaissez des feuilles de l'épaisseur exacte de l'écartement des cordes — deux millimètres — car c'est cette épaisseur qui donne la section carrée.","Posez la feuille sur la chitarra et passez le rouleau dessus en appuyant : les cordes tranchent, et les spaghettis tombent dans le cadre.","Faites les pallottine, de minuscules boulettes des trois viandes hachées, grosses comme une noisette, et faites-les dorer avant de les mettre dans la sauce.","Laissez mijoter la sauce 1 heure, cuisez les pâtes 3 minutes et liez. Servez au pecorino d'Abruzzes."],
     en:["Knead the flours and eggs for 15 minutes into a firm dough, and rest it an hour under a bowl.","Roll sheets to exactly the thickness of the wire spacing — two millimetres — because that thickness is what gives the square section.","Lay the sheet on the chitarra and run the pin over it, pressing: the wires cut, and the spaghetti fall into the frame.","Make pallottine, minute meatballs of the three minced meats, hazelnut-sized, and brown them before they go into the sauce.","Simmer the sauce for an hour, cook the pasta 3 minutes and combine. Serve with Abruzzo pecorino."]} },

{ id:'barbajuans', c:'eu', lat:43.7312, lon:7.4206, base:6, prep:70, cook:20, diff:2, tags:['veg','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#7fae5a','#f2dfa8','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Barbajuans',en:'Barbajuans'},
  p:{fr:'Monaco-Ville, Monaco',en:'Monaco-Ville, Monaco'},
  d:{fr:"Des raviolis frits farcis de blettes, de ricotta et de parmesan, plat national de la Principauté. On les mange le 27 janvier pour la Sainte-Dévote ; le nom viendrait de l'oncle Jean, barba Juan en ligure, à qui la légende attribue l'idée de frire les restes de farce à ravioli.",
     en:"Fried ravioli filled with chard, ricotta and parmesan, the Principality's national dish. They are eaten on 27 January for Saint Dévote; the name is said to come from uncle John, barba Juan in Ligurian, credited by legend with the idea of frying leftover ravioli filling."},
  i:[['swiss_chard',400,'g'],['ricotta',200,'g'],['parmesan',80,'g'],['onion',1,'pc'],['egg',3,'pc'],['flour',300,'g'],['olive_oil',40,'ml'],['leek',1,'pc'],['nutmeg',1,'pinch'],['frying_oil',1,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, un œuf, l'huile d'olive, une pincée de sel et un peu d'eau tiède 10 minutes, et laissez reposer la pâte 1 heure sous un linge.","Séparez les côtes des feuilles de blettes : seules les feuilles entrent dans la farce, les côtes serviront ailleurs.","Faites-les tomber à la poêle avec l'oignon et le poireau émincés, puis pressez-les à fond entre les mains — une farce humide fait éclater le barbajuan dans l'huile.","Hachez-les au couteau et liez à la ricotta égouttée, au parmesan, aux œufs restants et à la muscade.","Abaissez la pâte à 1 mm, déposez des noisettes de farce, refermez en carrés dentelés à la roulette et frites 3 minutes à 175 °C. Se mangent tièdes, à la main."],
     en:["Knead the flour, one egg, the olive oil, a pinch of salt and a little warm water for 10 minutes, and rest the dough an hour under a cloth.","Separate the stems from the chard leaves: only the leaves go into the filling, the stems will serve elsewhere.","Wilt them in a pan with the sliced onion and leek, then press them thoroughly dry between your hands — a wet filling bursts the barbajuan in the oil.","Chop them by knife and bind with the drained ricotta, parmesan, remaining eggs and nutmeg.","Roll the dough to 1 mm, set hazelnuts of filling on it, close into squares cut with a fluted wheel and fry 3 minutes at 175°C. Eaten warm, with the fingers."]} },

{ id:'stocafi-monegasque', c:'eu', lat:43.7345, lon:7.4222, base:6, prep:90, cook:180, diff:3, tags:['sea','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#c9532c','#f0e8d0','#3a2a1a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Stocafi à la monégasque',en:'Monegasque stocafi'},
  p:{fr:'La Condamine, Monaco',en:'La Condamine, Monaco'},
  d:{fr:"Du stockfish mijoté trois heures dans la tomate, les olives de Nice et l'eau-de-vie, plat des pêcheurs du port. Le stockfish n'est pas de la morue salée mais de la morue séchée au vent, dure comme du bois : elle demande cinq jours de trempage avant qu'on puisse la couper.",
     en:"Stockfish stewed three hours in tomato, Nice olives and brandy, the dish of the harbour fishermen. Stockfish is not salt cod but wind-dried cod, hard as wood: it needs five days of soaking before it can be cut at all."},
  i:[['stockfish',800,'g'],['ripe_tomato',1,'kg'],['black_olives',150,'g'],['onion',2,'pc'],['garlic',4,'clove'],['olive_oil',120,'ml'],['bay_leaf',3,'pc'],['thyme',4,'sprig'],['brandy',60,'ml'],['potato',600,'g'],['white_wine',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper le stockfish cinq jours à l'eau courante ou en changeant l'eau matin et soir : c'est long, et aucun raccourci ne fonctionne.","Détaillez-le en gros morceaux en gardant la peau, qui apporte la gélatine liant la sauce.","Faites un sofrito d'oignon et d'ail à l'huile d'olive, ajoutez la tomate concassée et laissez réduire 30 minutes jusqu'à une pâte épaisse.","Flambez au marc, mouillez de vin blanc, ajoutez le poisson, les herbes et les olives, et laissez mijoter 2 h 30 sans jamais remuer à la cuillère.","Secouez la marmite plutôt que de remuer : le stockfish s'effiloche au moindre coup de cuillère. Ajoutez les pommes de terre la dernière demi-heure."],
     en:["Soak the stockfish for five days under running water or changing the water morning and evening: it takes time, and no shortcut works.","Cut it into large pieces keeping the skin, which brings the gelatine that binds the sauce.","Make a sofrito of onion and garlic in olive oil, add the crushed tomato and reduce for 30 minutes to a thick paste.","Flame with marc, moisten with white wine, add the fish, herbs and olives, and simmer 2½ hours without ever stirring with a spoon.","Shake the pot instead of stirring: stockfish shreds at the first touch of a spoon. Add the potatoes for the last half hour."]} },

{ id:'fougasse-monegasque', c:'eu', lat:43.7318, lon:7.4222, base:10, prep:150, cook:30, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#8f6a4a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Fougasse monégasque',en:'Monegasque fougasse'},
  p:{fr:'Monaco-Ville, Monaco',en:'Monaco-Ville, Monaco'},
  d:{fr:"Une brioche plate à l'anis et à la fleur d'oranger, semée de noix, d'amandes et de grains d'anis rouges et blancs. Elle clôt les treize desserts du réveillon monégasque ; les grains colorés reprennent les couleurs du drapeau, et l'on ne la coupe pas — on la rompt.",
     en:"A flat brioche with anise and orange blossom, strewn with walnuts, almonds and red and white aniseed comfits. It closes the thirteen desserts of the Monegasque Christmas Eve; the coloured comfits echo the flag, and it is not cut — it is broken."},
  i:[['flour',500,'g'],['sugar',100,'g'],['butter',100,'g'],['fresh_yeast',20,'g'],['egg',3,'pc'],['walnuts',80,'g'],['almonds',80,'g'],['anise_seeds',1,'tbsp'],['orange_blossom_water',3,'tbsp'],['rum',30,'ml'],['whole_milk',120,'ml'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède avec une cuillerée de sucre et laissez-la mousser un quart d'heure.","Pétrissez avec la farine, deux œufs, le sucre, le sel, l'anis, la fleur d'oranger et le rhum 15 minutes, puis incorporez le beurre mou.","Laissez lever 1 h 30, puis aplatissez la pâte à la main en un ovale de 2 cm — jamais au rouleau, qui chasserait l'air.","Entaillez le dessus de trois coups en éventail, dorez à l'œuf et couvrez de noix et d'amandes concassées.","Laissez pousser 45 minutes et cuisez 30 minutes à 180 °C. Parsemez d'anis dragéifié dès la sortie, tant que la surface colle encore."],
     en:["Dissolve the yeast in warm milk with a spoonful of sugar and let it foam for a quarter of an hour.","Knead with the flour, two eggs, sugar, salt, anise, orange blossom water and rum for 15 minutes, then work in the softened butter.","Prove 1½ hours, then flatten the dough by hand into a 2 cm oval — never with a pin, which would drive out the air.","Cut three fan-shaped slashes on top, glaze with egg and cover with chopped walnuts and almonds.","Prove 45 minutes and bake 30 minutes at 180°C. Scatter the aniseed comfits as it comes out, while the surface is still tacky."]} },

{ id:'brandamincium', c:'eu', lat:43.7305, lon:7.4232, base:6, prep:60, cook:40, diff:3, tags:['sea','comfort','slow'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Brandamincium',en:'Brandamincium'},
  p:{fr:'Monaco-Ville, Monaco',en:'Monaco-Ville, Monaco'},
  d:{fr:"L'ancêtre monégasque de la brandade, morue pilée au mortier avec du lait et de l'huile jusqu'à devenir une pommade. Le nom latinisant est attesté au Rocher dès le Moyen Âge ; contrairement à la brandade nîmoise, il ne comporte ni pomme de terre ni crème.",
     en:"The Monegasque ancestor of brandade, cod pounded in a mortar with milk and oil into an ointment. The Latinate name is recorded on the Rock from the Middle Ages; unlike the Nîmes brandade it contains neither potato nor cream."},
  i:[['salt_cod',600,'g'],['whole_milk',300,'ml'],['olive_oil',150,'ml'],['garlic',3,'clove'],['bay_leaf',1,'pc'],['white_pepper',1,'tsp'],['bread',300,'g'],['lemon',1,'pc'],['nutmeg',1,'pinch']],
  s:{fr:["Dessalez la morue 36 heures au réfrigérateur, peau vers le haut, en changeant l'eau cinq fois.","Pochez-la 10 minutes dans le lait additionné du laurier, sans jamais bouillir, puis égouttez-la en gardant le lait.","Retirez la peau et toutes les arêtes à la main, en émiettant la chair : une seule arête ruine la texture.","Pilez au mortier avec l'ail, puis montez en versant l'huile tiède et le lait chaud alternativement, en filet, comme pour une mayonnaise.","Cette alternance est tout le procédé : versé trop vite, l'un ou l'autre fait trancher la pommade. Poivrez au poivre blanc et servez tiède, sur du pain grillé."],
     en:["Desalt the cod 36 hours in the fridge, skin up, changing the water five times.","Poach it 10 minutes in the milk with the bay, never boiling, then drain it keeping the milk.","Remove the skin and every bone by hand, flaking the flesh: a single bone ruins the texture.","Pound in a mortar with the garlic, then mount it by pouring in the warm oil and hot milk alternately, in thin streams, as for a mayonnaise.","That alternation is the whole method: poured too fast, either one splits the ointment. Season with white pepper and serve warm, on toast."]} },

{ id:'bouillabaisse-monegasque', c:'eu', lat:43.7250, lon:7.4180, base:6, prep:50, cook:45, diff:3, tags:['sea','soup','festive'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4efe3',style:'soup',food:['#d97327','#e0913a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Bouillabaisse monégasque',en:'Monegasque bouillabaisse'},
  p:{fr:'Fontvieille, Monaco',en:'Fontvieille, Monaco'},
  d:{fr:"Une soupe de poissons de roche du Larvotto, plus légère que la marseillaise et sans pomme de terre. Monaco n'ajoute ni safran en excès ni orange : le bouillon reste clair, et les moules qu'on y joint sont une liberté que Marseille n'accorderait jamais.",
     en:"A rockfish soup from the Larvotto, lighter than the Marseille version and without potato. Monaco adds neither excess saffron nor orange: the broth stays clear, and the mussels added to it are a liberty Marseille would never permit."},
  i:[['rockfish',1.5,'kg'],['mussels',400,'g'],['ripe_tomato',400,'g'],['fennel',1,'bunch'],['onion',2,'pc'],['garlic',6,'clove'],['saffron',1,'pinch'],['olive_oil',100,'ml'],['bread',300,'g'],['egg_yolk',2,'pc'],['cayenne',1,'pinch'],['orange_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Videz et écaillez les poissons de roche, gardez les têtes, et faites-les revenir 10 minutes à l'huile avec l'oignon, le fenouil et l'ail.","Mouillez d'eau bouillante — jamais froide, qui figerait les chairs et troublerait le bouillon — et cuisez 25 minutes à petits frémissements.","Passez au moulin à légumes en pressant les arêtes, puis au chinois fin : le bouillon doit être velouté et sans une seule esquille.","Faites la rouille en pilant l'ail, un jaune d'œuf, une pointe de cayenne et la mie de pain trempée dans le bouillon, montée à l'huile.","Pochez les poissons entiers 8 minutes dans le bouillon, ajoutez les moules pour la dernière minute, et servez le bouillon d'abord, les poissons ensuite."],
     en:["Gut and scale the rockfish, keep the heads, and fry them 10 minutes in oil with the onion, fennel and garlic.","Moisten with boiling water — never cold, which would seize the flesh and cloud the broth — and cook 25 minutes at a bare simmer.","Pass through a food mill pressing the bones, then through a fine chinois: the broth must be velvety and free of a single splinter.","Make the rouille by pounding garlic, an egg yolk, a pinch of cayenne and bread crumb soaked in the broth, mounted with oil.","Poach the whole fish 8 minutes in the broth, add the mussels for the last minute, and serve the broth first, the fish after."]} },

{ id:'salade-monegasque', c:'eu', lat:43.7396, lon:7.4276, base:4, prep:35, cook:20, diff:1, tags:['fresh','rice','fast'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4f0e6',style:'salad',food:['#f4f0e6','#c9402c','#7fae5a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Salade monégasque',en:'Monegasque salad'},
  p:{fr:'Monte-Carlo, Monaco',en:'Monte-Carlo, Monaco'},
  d:{fr:"Une salade de riz froid aux anchois, aux haricots verts et à l'œuf dur, née dans les cuisines de l'Hôtel de Paris dans les années 1920. Le riz est ce qui la sépare de la niçoise : Monaco l'a introduit pour en faire un plat de buffet qui tient une soirée entière.",
     en:"A cold rice salad with anchovies, green beans and hard-boiled egg, born in the kitchens of the Hôtel de Paris in the 1920s. The rice is what separates it from the niçoise: Monaco introduced it to make a buffet dish that holds a whole evening."},
  i:[['long_grain_rice',200,'g'],['ripe_tomato',3,'pc'],['green_beans',150,'g'],['anchovy_fillets',8,'pc'],['egg',3,'pc'],['black_olives',80,'g'],['red_pepper',1,'pc'],['lemon',1,'pc'],['olive_oil',80,'ml'],['basil',1,'bunch'],['spring_onion',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez le riz dans une grande eau salée, égouttez-le et rafraîchissez-le aussitôt à l'eau froide pour arrêter la cuisson et ôter l'amidon.","Étalez-le sur un plateau et arrosez-le d'un filet d'huile pendant qu'il est encore tiède : c'est le seul moment où il l'absorbe.","Ébouillantez les haricots verts 4 minutes puis plongez-les dans l'eau glacée : ils doivent rester vert vif et croquer.","Salez les tomates coupées en quartiers et laissez-les dégorger vingt minutes dans une passoire, sinon leur eau délave la salade.","Réunissez tous les éléments au dernier moment avec le jus de citron et l'huile, et déchirez le basilic à la main. Servez frais mais non glacé."],
     en:["Cook the rice in plenty of salted water, drain it and refresh it at once under cold water to stop the cooking and rinse off the starch.","Spread it on a tray and trickle oil over while it is still warm: that is the only moment it absorbs any.","Blanch the green beans for 4 minutes then plunge them into iced water: they must stay bright green and snap.","Salt the quartered tomatoes and let them drain for twenty minutes in a colander, or their water washes out the salad.","Combine everything at the last moment with the lemon juice and oil, and tear the basil by hand. Serve cool but not chilled."]} },

{ id:'beignets-de-fleurs-de-courgettes', c:'eu', lat:43.7258, lon:7.4192, base:4, prep:30, cook:15, diff:2, tags:['veg','fry','fresh'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#e8c46a','#f2dfa8','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Beignets de fleurs de courgettes',en:'Courgette flower fritters'},
  p:{fr:'Fontvieille, Monaco',en:'Fontvieille, Monaco'},
  d:{fr:"Des fleurs de courgette farcies de ricotta aux herbes, trempées dans une pâte à la bière et frites. On ne cueille que les fleurs mâles, celles portées sur une tige nue : les femelles portent la courgette naissante, et les prendre reviendrait à sacrifier la récolte.",
     en:"Courgette flowers filled with herbed ricotta, dipped in beer batter and fried. Only the male flowers are picked, those on a bare stalk: the female ones carry the forming courgette, and taking them would sacrifice the crop."},
  i:[['zucchini_flowers',16,'pc'],['ricotta',150,'g'],['parmesan',50,'g'],['basil',1,'bunch'],['mint',1,'bunch'],['flour',120,'g'],['egg',1,'pc'],['beer',150,'ml'],['frying_oil',1,'l'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cueillez ou achetez les fleurs le jour même : passé une nuit, elles se referment et se flétrissent sans remède.","Ouvrez délicatement chaque fleur et retirez le pistil, qui est amer, sans déchirer les pétales.","Travaillez la ricotta bien égouttée avec le parmesan, le basilic et la menthe hachés, et garnissez à la poche sans emplir plus des deux tiers.","Préparez la pâte à la dernière minute avec la farine, l'œuf et la bière très froide, en la laissant volontairement grumeleuse — une pâte lisse et reposée donne une croûte lourde.","Trempez les fleurs en tenant la tige et frites-les 2 minutes à 180 °C, sans les retourner plus d'une fois. Salez et citronnez à la sortie."],
     en:["Pick or buy the flowers the same day: after a night they close and wilt beyond rescue.","Open each flower gently and remove the pistil, which is bitter, without tearing the petals.","Work the well-drained ricotta with the parmesan and chopped basil and mint, and pipe it in without filling more than two-thirds.","Make the batter at the last minute with the flour, egg and very cold beer, deliberately leaving it lumpy — a smooth, rested batter gives a heavy crust.","Dip the flowers holding them by the stalk and fry 2 minutes at 180°C, turning them once only. Salt and squeeze lemon as they come out."]} },

{ id:'omelette-plate-aux-herbes', c:'eu', lat:43.7402, lon:7.4288, base:4, prep:15, cook:8, diff:2, tags:['fast','fresh','veg'],
  art:{v:'plate',bg:'#28331f',plate:'#f4f0e6',style:'flat',food:['#e8c46a','#7fae5a','#f2dfa8','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Omelette plate aux herbes',en:'Flat herb omelette'},
  p:{fr:'Monte-Carlo, Monaco',en:'Monte-Carlo, Monaco'},
  d:{fr:"Une omelette cuite à plat, sans pliage, parsemée d'herbes fraîches et de parmesan. C'est l'omelette des croupiers, qu'on servait entre deux services de nuit : elle se mange tiède ou froide, se coupe en parts, et supporte l'attente mieux qu'une omelette baveuse.",
     en:"An omelette cooked flat, never folded, scattered with fresh herbs and parmesan. It is the croupiers' omelette, served between night shifts: it is eaten warm or cold, cut in wedges, and stands waiting better than a runny one."},
  i:[['egg',8,'pc'],['parsley',4,'tbsp'],['chervil',3,'tbsp'],['chives',4,'tbsp'],['parmesan',40,'g'],['butter',30,'g'],['olive_oil',20,'ml'],['lettuce',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Hachez les herbes au couteau juste avant de battre les œufs : hachées d'avance, elles noircissent et perdent leur parfum en un quart d'heure.","Battez les œufs à la fourchette et non au fouet, une trentaine de coups seulement : trop battus, ils gonflent puis retombent.","Ajoutez les herbes, le parmesan, du sel et du poivre, et laissez reposer cinq minutes le temps que les bulles remontent.","Chauffez le beurre et l'huile dans une poêle de 24 cm jusqu'à ce que le beurre mousse sans colorer, et versez d'un coup.","Cuisez 5 minutes à feu doux sans remuer, puis retournez d'un coup à l'aide d'une assiette et laissez 2 minutes de l'autre côté. Se sert tiède, avec une salade."],
     en:["Chop the herbs just before beating the eggs: chopped in advance they blacken and lose their scent within a quarter of an hour.","Beat the eggs with a fork rather than a whisk, some thirty strokes only: overbeaten, they rise and then collapse.","Add the herbs, parmesan, salt and pepper, and rest five minutes while the bubbles rise.","Heat the butter and oil in a 24 cm pan until the butter foams without colouring, and pour in all at once.","Cook 5 minutes over low heat without stirring, then flip it in one movement using a plate and give it 2 minutes on the other side. Served warm, with salad."]} },

{ id:'poulpe-a-la-monegasque', c:'eu', lat:43.7244, lon:7.4172, base:4, prep:40, cook:120, diff:2, tags:['sea','slow','comfort'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'stew',food:['#8f2a2a','#c9532c','#e0a8a0','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Poulpe à la monégasque',en:'Monegasque octopus'},
  p:{fr:'Fontvieille, Monaco',en:'Fontvieille, Monaco'},
  d:{fr:"Du poulpe mijoté deux heures au vin rouge, à la tomate et aux olives violettes, plat des familles de pêcheurs de la digue. Le poulpe se contracte violemment au contact de la chaleur : on le plonge trois fois dans l'eau bouillante avant de le cuire, pour que les tentacules s'enroulent au lieu de durcir.",
     en:"Octopus stewed two hours in red wine, tomato and violet olives, the dish of the fishing families of the breakwater. Octopus contracts violently on meeting heat: it is dipped three times in boiling water before cooking, so the tentacles curl instead of toughening."},
  i:[['octopus',1.2,'kg'],['red_wine',500,'ml'],['ripe_tomato',400,'g'],['onion',2,'pc'],['garlic',5,'clove'],['black_olives',120,'g'],['bay_leaf',3,'pc'],['thyme',3,'sprig'],['olive_oil',80,'ml'],['orange_zest',1,'pc'],['potato',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Congelez le poulpe 48 heures puis décongelez-le : le gel brise les fibres et remplace le battage sur les rochers que faisaient les pêcheurs.","Portez une grande eau à ébullition et trempez le poulpe trois fois par la tête, cinq secondes à chaque fois, avant de l'y laisser.","Faites-le blanchir 20 minutes, égouttez-le et détaillez les tentacules en tronçons de trois centimètres.","Faites un sofrito d'oignon, d'ail et de tomate, ajoutez le poulpe, le vin rouge, le zeste d'orange et les herbes, et laissez mijoter 1 h 30 à couvert.","Ne salez qu'à la fin : le poulpe rend beaucoup d'eau de mer, et salé trop tôt le plat devient immangeable. Ajoutez olives et pommes de terre pour la dernière demi-heure."],
     en:["Freeze the octopus for 48 hours then thaw it: freezing breaks the fibres and stands in for the beating on the rocks the fishermen used to give it.","Bring a large pot to the boil and dip the octopus by the head three times, five seconds each, before leaving it in.","Blanch it 20 minutes, drain it and cut the tentacles into three-centimetre lengths.","Make a sofrito of onion, garlic and tomato, add the octopus, red wine, orange zest and herbs, and simmer 1½ hours covered.","Salt only at the end: octopus releases a great deal of seawater, and salted too early the dish becomes inedible. Add olives and potatoes for the last half hour."]} },

{ id:'rougets-a-la-monegasque', c:'eu', lat:43.7338, lon:7.4200, base:4, prep:30, cook:20, diff:2, tags:['sea','fast','fresh'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ecd8',style:'fish',food:['#c9402c','#e0a8a0','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Rougets à la monégasque',en:'Monegasque red mullet'},
  p:{fr:'La Condamine, Monaco',en:'La Condamine, Monaco'},
  d:{fr:"Des rougets barbets flambés au pastis et cuits au fenouil sauvage cueilli sur la Tête de Chien. Le rouget est le seul poisson qu'on cuisine sans le vider : son foie, qui reste dedans, fond dans le jus et le parfume — c'est pour cela qu'on l'appelle la bécasse de mer.",
     en:"Red mullet flamed with pastis and cooked with wild fennel gathered on the Tête de Chien. Mullet is the one fish cooked ungutted: its liver, left inside, melts into the juices and scents them — which is why it is called the woodcock of the sea."},
  i:[['red_mullet',8,'pc'],['fennel',1,'pc'],['pastis',50,'ml'],['cherry_tomato',200,'g'],['olive_oil',80,'ml'],['lemon',2,'pc'],['parsley',4,'tbsp'],['garlic',3,'clove'],['flour',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Écaillez les rougets sans les vider et écaillez-les à rebrousse-poil, du côté de la queue vers la tête, sous un filet d'eau.","Ne retirez surtout pas le foie : c'est lui qui fait le plat, et un rouget vidé perd tout son intérêt.","Émincez le fenouil très fin et faites-le fondre 15 minutes à l'huile d'olive avec l'ail, sans coloration.","Farinez à peine les rougets et saisissez-les 3 minutes par face à feu vif, puis flambez au pastis en inclinant la poêle.","Ajoutez le fenouil, les tomates cerises et un trait d'eau, couvrez et laissez 4 minutes. Écrasez le foie dans le jus au moment de servir."],
     en:["Scale the mullet without gutting them, working against the grain from tail to head under running water.","On no account remove the liver: it is what makes the dish, and a gutted mullet loses all its point.","Slice the fennel very finely and melt it in olive oil with the garlic for 15 minutes, without colour.","Flour the mullet barely and sear them 3 minutes a side over high heat, then flame with pastis, tilting the pan.","Add the fennel, cherry tomatoes and a splash of water, cover and give them 4 minutes. Crush the liver into the juices as you serve."]} },

{ id:'epaule-agneau-monegasque', c:'eu', lat:43.7300, lon:7.4218, base:6, prep:60, cook:150, diff:3, tags:['lamb','slow','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a3a','#7fae5a','#e8d8b8','#c9754a'],garnish:'#7fae6a'},
  n:{fr:'Épaule d’agneau à la monégasque',en:'Monegasque stuffed lamb shoulder'},
  p:{fr:'Monaco-Ville, Monaco',en:'Monaco-Ville, Monaco'},
  d:{fr:"Une épaule désossée farcie de blettes et de riz, rôtie et servie avec des haricots blancs. C'est le plat de Pâques du Rocher, tel qu'on le sert au Palais ; la farce au riz est monégasque et non provençale, et elle gonfle en cuisant, ce qui oblige à ne pas trop la tasser.",
     en:"A boned shoulder stuffed with chard and rice, roasted and served with white beans. It is the Rock's Easter dish, as served at the Palace; the rice stuffing is Monegasque rather than Provençal, and it swells as it cooks, so it must not be packed too tight."},
  i:[['lamb_shoulder',1.5,'kg'],['swiss_chard',300,'g'],['long_grain_rice',100,'g'],['garlic',8,'clove'],['rosemary',4,'sprig'],['white_beans',300,'g'],['onion',2,'pc'],['egg',2,'pc'],['parmesan',60,'g'],['white_wine',250,'ml'],['olive_oil',60,'ml'],['bay_leaf',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots la veille et cuisez-les 1 h 30 avec le laurier, sans sel, dans une eau qui ne bout jamais franchement.","Cuisez le riz à moitié seulement, 7 minutes, et rafraîchissez-le : entièrement cuit, il éclaterait dans la farce.","Faites tomber les blettes hachées avec l'oignon, pressez-les à fond et liez-les au riz, aux œufs et au parmesan.","Étalez l'épaule désossée à plat, garnissez sans tasser — la farce gonfle d'un bon quart — roulez et bridez à la ficelle tous les trois centimètres.","Saisissez 20 minutes à 220 °C, puis 2 heures à 160 °C en arrosant du vin blanc et du jus. Reposez 15 minutes avant de trancher, ficelle en place."],
     en:["Soak the beans the day before and cook them 1½ hours with the bay, unsalted, in water that never comes to a rolling boil.","Cook the rice only halfway, 7 minutes, and refresh it: fully cooked, it would burst inside the stuffing.","Wilt the chopped chard with the onion, press it thoroughly dry and bind it with the rice, eggs and parmesan.","Lay the boned shoulder out flat, fill without packing — the stuffing swells by a good quarter — roll and tie with string every three centimetres.","Sear 20 minutes at 220°C, then 2 hours at 160°C basting with the white wine and juices. Rest 15 minutes before carving, string still on."]} },

{ id:'oignons-farcis-monegasques', c:'eu', lat:43.7324, lon:7.4198, base:4, prep:50, cook:60, diff:2, tags:['pork','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#e0b45a','#8f5a3a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Oignons farcis monégasques',en:'Monegasque stuffed onions'},
  p:{fr:'Monaco-Ville, Monaco',en:'Monaco-Ville, Monaco'},
  d:{fr:"De gros oignons doux évidés et farcis de chair à saucisse et de blettes, gratinés au four. Les cebe farcie sont le plat d'économie du Rocher : la chair prélevée dans l'oignon retourne dans la farce, et rien ne se perd — pas même la chapelure du pain de la veille.",
     en:"Large sweet onions hollowed out and filled with sausage meat and chard, gratinated. Cebe farcie are the Rock's thrift dish: the flesh scooped from the onion goes back into the filling, and nothing is wasted — not even yesterday's bread as crumbs."},
  i:[['onion',8,'pc'],['ground_pork',300,'g'],['swiss_chard',200,'g'],['parmesan',50,'g'],['breadcrumbs',60,'g'],['egg',1,'pc'],['garlic',3,'clove'],['beef_broth',300,'ml'],['olive_oil',60,'ml'],['thyme',3,'sprig'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez les oignons entiers non pelés 20 minutes à l'eau salée : cuits, ils s'évident sans se déchirer, crus ils cassent en couches.","Coupez un chapeau, évidez-les à la cuillère à melon en laissant deux couches d'épaisseur, et hachez la chair prélevée.","Faites revenir cette chair avec l'ail et les blettes hachées, pressez, et mêlez à la chair à saucisse, à l'œuf, au parmesan et à la chapelure.","Emplissez les oignons en dôme, rangez-les serrés dans un plat huilé — serrés, ils se soutiennent et ne s'affaissent pas.","Versez le bouillon jusqu'au tiers de leur hauteur et enfournez 55 minutes à 180 °C, en arrosant deux fois. Se mangent tièdes."],
     en:["Poach the whole unpeeled onions 20 minutes in salted water: cooked, they hollow out without tearing; raw, they break into layers.","Cut a lid, scoop them out with a melon baller leaving two layers of wall, and chop the flesh removed.","Fry that flesh with the garlic and chopped chard, press it dry, and mix with the sausage meat, egg, parmesan and breadcrumbs.","Fill the onions in a dome, pack them tightly in an oiled dish — tight, they hold each other up and do not collapse.","Pour broth to a third of their height and bake 55 minutes at 180°C, basting twice. Eaten warm."]} },

{ id:'escargots-a-la-monegasque', c:'eu', lat:43.7410, lon:7.4262, base:4, prep:60, cook:15, diff:2, tags:['festive','comfort','fast'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#4f6f3a','#8f6a4a','#e8dcb8','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Escargots à la monégasque',en:'Monegasque snails'},
  p:{fr:'Monte-Carlo, Monaco',en:'Monte-Carlo, Monaco'},
  d:{fr:"Des petits-gris remis en coquille sous un beurre aux noix, au persil et au vin blanc. La noix est la signature monégasque : elle remplace une partie de l'ail et donne au beurre un grain que la version bourguignonne, plus lisse, n'a pas.",
     en:"Small grey snails returned to their shells under a butter of walnut, parsley and white wine. The walnut is the Monegasque signature: it replaces part of the garlic and gives the butter a grain the smoother Burgundian version lacks."},
  i:[['snails',48,'pc'],['butter',150,'g'],['walnuts',80,'g'],['parsley',1,'bunch'],['garlic',4,'clove'],['shallot',2,'pc'],['white_wine',80,'ml'],['breadcrumbs',40,'g'],['thyme',2,'sprig'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Si vous partez d'escargots frais, faites-les jeûner huit jours, dégorgez-les au gros sel et pochez-les 2 heures au court-bouillon thymé.","Concassez les noix au couteau plutôt qu'au mixeur : il faut des éclats qui craquent, pas une poudre.","Travaillez le beurre en pommade avec les noix, le persil, l'ail, l'échalote et le vin blanc réduit à sec.","Glissez une noisette de beurre au fond de chaque coquille, l'escargot par-dessus, puis rebouchez généreusement et saupoudrez de chapelure.","Enfournez 12 minutes à 220 °C, ouverture vers le haut : le beurre doit grésiller et la chapelure blondir, sans que le beurre déborde."],
     en:["If starting from live snails, fast them for eight days, purge them in coarse salt and poach them 2 hours in a thyme court-bouillon.","Crush the walnuts with a knife rather than a blender: you want shards that crunch, not powder.","Cream the butter with the walnuts, parsley, garlic, shallot and the white wine reduced to nothing.","Slip a hazelnut of butter into each shell, the snail on top, then plug generously and dust with breadcrumbs.","Bake 12 minutes at 220°C, openings up: the butter should sizzle and the crumbs go gold, without the butter running over."]} },

{ id:'girella-monegasque', c:'eu', lat:43.7348, lon:7.4232, base:8, prep:120, cook:25, diff:2, tags:['bread','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#8f6a4a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Girella',en:'Girella'},
  p:{fr:'La Condamine, Monaco',en:'La Condamine, Monaco'},
  d:{fr:"Un pain roulé en spirale autour d'anchois, d'oignons et d'olives vertes, coupé en tranches. Les marchands ambulants la criaient girella cauda ! dans les ruelles de la Condamine ; la spirale n'est pas décorative, elle répartit la garniture salée dans chaque bouchée.",
     en:"A bread rolled in a spiral around anchovies, onions and green olives, cut into slices. Street sellers cried girella cauda! in the lanes of the Condamine; the spiral is not decorative, it spreads the salty filling through every mouthful."},
  i:[['flour',400,'g'],['fresh_yeast',15,'g'],['warm_water',250,'ml'],['anchovy_fillets',100,'g'],['onion',2,'pc'],['green_olives',100,'g'],['oregano',1,'tbsp'],['olive_oil',80,'ml'],['semolina',40,'g'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte à pain souple à l'huile d'olive et laissez-la lever 1 h 30 à couvert.","Faites confire les oignons émincés 30 minutes à feu très doux, jusqu'à ce qu'ils soient blonds et sans eau, et laissez-les refroidir complètement.","Une garniture tiède fait fondre la pâte au roulage et la spirale se défait : c'est la seule vraie difficulté.","Abaissez la pâte en rectangle de 5 mm, étalez oignons, anchois hachés, olives et origan en laissant deux centimètres de bord libre.","Roulez très serré dans le sens de la longueur, soudez, laissez pousser 40 minutes et cuisez 25 minutes à 210 °C. Se coupe en tranches d'un centimètre, tiède."],
     en:["Knead a soft olive-oil bread dough and prove it 1½ hours covered.","Confit the sliced onions 30 minutes over very low heat, until pale and dry, and cool them completely.","A warm filling melts the dough as you roll and the spiral unwinds: that is the only real difficulty.","Roll the dough into a 5 mm rectangle and spread the onions, chopped anchovies, olives and oregano, leaving a two-centimetre border.","Roll very tightly lengthwise, seal, prove 40 minutes and bake 25 minutes at 210°C. Cut into one-centimetre slices, warm."]} },

{ id:'tarte-citron-menton-monaco', c:'eu', lat:43.7390, lon:7.4270, base:8, prep:70, cook:35, diff:3, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8f0d0','#f2dfa8','#f4f0e6','#e0b45a'],garnish:'#c9754a'},
  n:{fr:'Tarte au citron de Menton',en:'Menton lemon tart'},
  p:{fr:'Monte-Carlo, Monaco',en:'Monte-Carlo, Monaco'},
  d:{fr:"Une tarte à la crème de citron de Menton sous une meringue flambée, servie dans les palaces de Monte-Carlo. Le citron de Menton n'a presque pas d'acidité mordante et une écorce épaisse très parfumée : c'est le zeste, plus que le jus, qui fait la différence.",
     en:"A tart of Menton lemon cream under a torched meringue, served in the palaces of Monte-Carlo. The Menton lemon has almost no biting acidity and a thick, highly scented rind: it is the zest, more than the juice, that makes the difference."},
  i:[['shortcrust_pastry',300,'g'],['lemon',5,'pc'],['sugar',280,'g'],['egg',3,'pc'],['egg_white',3,'pc'],['butter',150,'g'],['cornstarch',20,'g'],['ground_almonds',30,'g'],['salt',null,'']],
  s:{fr:["Foncez le moule, piquez le fond, chemisez de papier et de billes et cuisez à blanc 15 minutes à 180 °C, puis 5 minutes à nu.","Saupoudrez le fond encore chaud de poudre d'amande : elle boira l'humidité de la crème et gardera la pâte croustillante.","Faites infuser les zestes dans le jus une heure avant de rien cuire — c'est là que se joue le parfum, pas dans la cuisson.","Cuisez le jus zesté, 150 g de sucre, les œufs et la fécule au bain-marie jusqu'à 82 °C, puis incorporez le beurre froid en dés hors du feu, au mixeur plongeant.","Montez les blancs avec le sucre restant en meringue ferme, pochez-la sur la tarte froide et brûlez-la au chalumeau. Ne réfrigérez pas après : la meringue rendrait de l'eau."],
     en:["Line the tin, prick the base, line with paper and beans and blind-bake 15 minutes at 180°C, then 5 minutes uncovered.","Dust the still-hot base with ground almonds: they will drink the cream's moisture and keep the pastry crisp.","Infuse the zest in the juice for an hour before cooking anything — that is where the scent is decided, not in the cooking.","Cook the zested juice, 150 g of the sugar, the eggs and cornstarch over a bain-marie to 82°C, then blend in the cold diced butter off the heat with a stick blender.","Whisk the whites with the remaining sugar to a firm meringue, pipe it onto the cold tart and torch it. Do not chill afterwards: the meringue would weep."]} },

{ id:'biscuit-chataigne-miel', c:'eu', lat:43.7264, lon:7.4200, base:12, prep:40, cook:25, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#8f6a4a','#c9a878','#e8dcb8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Biscuit châtaigne et miel',en:'Chestnut and honey biscuit'},
  p:{fr:'Fontvieille, Monaco',en:'Fontvieille, Monaco'},
  d:{fr:"Un biscuit rustique à la farine de châtaigne et au miel d'acacia du Jardin exotique. On le confectionnait pour les ouvriers du chantier de Fontvieille, gagné sur la mer dans les années soixante-dix : dense, sucré au miel, il tenait un homme jusqu'à la relève.",
     en:"A rustic biscuit of chestnut flour and acacia honey from the Jardin Exotique. It was made for the workers on the Fontvieille site, reclaimed from the sea in the seventies: dense and honey-sweet, it kept a man going to the end of the shift."},
  i:[['chestnut_flour',200,'g'],['flour',100,'g'],['honey',80,'g'],['butter',80,'g'],['egg',2,'pc'],['whole_milk',60,'ml'],['cinnamon',1,'tsp'],['baking_powder',1,'tsp'],['walnuts',60,'g'],['salt',null,'']],
  s:{fr:["Tamisez la farine de châtaigne deux fois : elle s'agglomère en mottes dures qu'aucun batteur ne défait ensuite.","Faites tiédir le miel avec le beurre sans dépasser 50 °C, au-delà de quoi l'acacia perd son parfum floral.","Battez les œufs, ajoutez le mélange tiède, puis les farines, la levure, la cannelle et le sel, et enfin le lait.","La pâte est plus lourde qu'une pâte à biscuit ordinaire : la châtaigne n'a pas de gluten et ne lève presque pas, c'est normal.","Déposez des cuillerées espacées sur la plaque, parsemez de noix concassées et cuisez 22 minutes à 170 °C. Ils durcissent en refroidissant et se gardent quinze jours."],
     en:["Sift the chestnut flour twice: it clumps into hard nuggets no beater will later break up.","Warm the honey with the butter without going above 50°C, beyond which acacia loses its floral scent.","Beat the eggs, add the warm mixture, then the flours, baking powder, cinnamon and salt, and finally the milk.","The batter is heavier than an ordinary biscuit dough: chestnut has no gluten and barely rises, which is normal.","Drop well-spaced spoonfuls on the tray, scatter chopped walnuts and bake 22 minutes at 170°C. They harden as they cool and keep a fortnight."]} },

{ id:'endives-au-jambon', c:'eu', lat:50.847, lon:4.352, base:4, prep:30, cook:60, diff:1, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8dcb8','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chicons au gratin',en:'Belgian endive gratin'},
  p:{fr:'Bruxelles, Belgique',en:'Brussels, Belgium'},
  d:{fr:"Des endives braisées enroulées de jambon et gratinées sous une béchamel. Le chicon fut découvert par accident vers 1830 : un maraîcher de Schaerbeek avait abandonné des racines de chicorée dans sa cave, et elles avaient produit des bourgeons blancs.",
     en:"Braised endives wrapped in ham and gratinated under béchamel. The chicon was discovered by accident around 1830: a Schaerbeek grower had abandoned chicory roots in his cellar, and they had produced white shoots."},
  i:[['endive',8,'pc'],['ham',8,'slice'],['butter',80,'g'],['flour',50,'g'],['whole_milk',500,'ml'],['gruyere_cheese',120,'g'],['nutmeg',1,'pinch'],['sugar',1,'tsp'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ôtez le cône amer à la base de chaque endive en creusant au couteau pointu : c'est lui, et non la feuille, qui porte l'amertume.","Braisez-les à couvert au beurre 30 minutes avec une pincée de sucre et un trait de citron, sans ajouter d'eau.","Pressez-les ensuite entre les mains, fermement : une endive gorgée d'eau délave la béchamel et le gratin nage.","Enroulez chaque endive d'une tranche de jambon et rangez-les serrées, soudure dessous, dans un plat beurré.","Nappez d'une béchamel muscadée, parsemez de fromage et gratinez 25 minutes à 200 °C, jusqu'à ce que le dessus boursoufle."],
     en:["Cut out the bitter cone at the base of each endive with a pointed knife: it, not the leaf, carries the bitterness.","Braise them covered in butter for 30 minutes with a pinch of sugar and a squeeze of lemon, adding no water.","Then press them firmly between your hands: a waterlogged endive thins the béchamel and the gratin swims.","Wrap each endive in a slice of ham and pack them tightly, seam down, in a buttered dish.","Coat with a nutmegged béchamel, scatter cheese and gratinate 25 minutes at 200°C, until the top blisters."]} },

{ id:'appeltaart', c:'eu', lat:52.370, lon:4.895, base:10, prep:60, cook:80, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Appeltaart',en:'Appeltaart'},
  p:{fr:'Amsterdam, Pays-Bas',en:'Amsterdam, Netherlands'},
  d:{fr:"Une tarte aux pommes très haute, à pâte sablée épaisse et à treillis, servie avec de la crème fouettée. La recette néerlandaise est attestée depuis 1514 ; contrairement à la tarte française, elle se cuit dans un moule à charnière profond et se mange en parts verticales.",
     en:"A very tall apple tart with a thick shortcrust and a lattice top, served with whipped cream. The Dutch recipe is recorded from 1514; unlike the French tart it is baked in a deep springform tin and eaten in upright wedges."},
  i:[['flour',400,'g'],['butter',250,'g'],['brown_sugar',200,'g'],['egg',2,'pc'],['apple',1.2,'kg'],['cinnamon',2,'tsp'],['raisins',80,'g'],['breadcrumbs',3,'tbsp'],['lemon',1,'pc'],['rum',30,'ml'],['salt',null,'']],
  s:{fr:["Sablez le beurre froid dans la farine avec la moitié du sucre, liez d'un œuf et rassemblez sans pétrir ; réfrigérez 1 heure.","Faites gonfler les raisins dans le rhum tiède et coupez les pommes en gros quartiers, jamais en lamelles.","Foncez un moule à charnière de 24 cm en remontant la pâte à 5 cm de hauteur : l'appeltaart est haute, c'est sa signature.","Semez le fond de chapelure avant de garnir — elle boira le jus des pommes et gardera la pâte croustillante.","Couvrez d'un treillis, dorez et cuisez 1 h 20 à 175 °C. Laissez refroidir complètement dans le moule, sinon la tarte s'effondre au démoulage."],
     en:["Rub the cold butter into the flour with half the sugar, bind with one egg and bring together without kneading; chill an hour.","Plump the raisins in warm rum and cut the apples into large wedges, never slices.","Line a 24 cm springform tin, taking the pastry 5 cm up the sides: an appeltaart is tall, that is its signature.","Scatter breadcrumbs over the base before filling — they will drink the apple juices and keep the pastry crisp.","Cover with a lattice, glaze and bake 1 hour 20 at 175°C. Cool completely in the tin, or the tart collapses when released."]} },

{ id:'kibbeling', c:'eu', lat:52.377, lon:4.900, base:4, prep:30, cook:15, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'fish',food:['#e0b45a','#f2dfa8','#f4f0e6','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Kibbeling',en:'Kibbeling'},
  p:{fr:'Amsterdam, Pays-Bas',en:'Amsterdam, Netherlands'},
  d:{fr:"Des morceaux de cabillaud enrobés d'une pâte à bière et frits, vendus au cornet avec une sauce tartare. Le mot désignait autrefois les joues de morue, morceau de rebut que les poissonniers vendaient à bas prix ; ce sont aujourd'hui des dés de filet, mais le nom est resté.",
     en:"Chunks of cod in beer batter, fried and sold in a cone with tartare sauce. The word once meant cod cheeks, an offcut fishmongers sold cheap; today it is diced fillet, but the name has stuck."},
  i:[['cod',600,'g'],['flour',200,'g'],['beer',250,'ml'],['egg',1,'pc'],['baking_powder',1,'tsp'],['frying_oil',1.2,'l'],['mayonnaise',150,'g'],['pickles',4,'pc'],['capers',1,'tbsp'],['lemon',1,'pc'],['sweet_paprika',1,'tsp'],['salt',null,'']],
  s:{fr:["Taillez le cabillaud en cubes de 4 cm, salez-les et laissez-les 20 minutes au froid pour raffermir la chair.","Épongez-les à fond : une chair humide fait glisser la pâte, qui se détache en plaques dans l'huile.","Préparez la pâte à la dernière minute avec la bière très froide, en la laissant grumeleuse — une pâte reposée devient lourde et molle.","Farinez les cubes, trempez-les et plongez-les dans l'huile à 180 °C, six à la fois, 3 minutes.","Égouttez debout dans une passoire, salez et servez avec une tartare de mayonnaise, cornichons et câpres hachés."],
     en:["Cut the cod into 4 cm cubes, salt them and chill 20 minutes to firm the flesh.","Blot them thoroughly: wet flesh makes the batter slide, and it peels off in sheets in the oil.","Make the batter at the last minute with very cold beer, leaving it lumpy — a rested batter turns heavy and soft.","Flour the cubes, dip them and lower them into oil at 180°C, six at a time, for 3 minutes.","Drain upright in a colander, salt and serve with a tartare of mayonnaise, chopped gherkin and capers."]} },

{ id:'oliebollen', c:'eu', lat:52.365, lon:4.885, base:10, prep:150, cook:25, diff:2, tags:['sweet','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9924a','#e0b45a','#f4f0e6','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Oliebollen',en:'Oliebollen'},
  p:{fr:'Amsterdam, Pays-Bas',en:'Amsterdam, Netherlands'},
  d:{fr:"Des boules de pâte levée aux raisins et aux pommes, frites et couvertes de sucre glace, mangées le 31 décembre. La tradition remonterait aux Germains, qui en jetaient dans les champs pendant les nuits de Yule pour que la déesse Perchta, si elle éventrait un ventre, glisse sur la graisse.",
     en:"Balls of yeasted dough with raisins and apple, fried and buried in icing sugar, eaten on 31 December. The custom is said to go back to the Germanic tribes, who threw them into the fields on Yule nights so that if the goddess Perchta slit a belly, her blade would slide off the fat."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['whole_milk',250,'ml'],['egg',1,'pc'],['raisins',100,'g'],['apple',2,'pc'],['orange_zest',1,'pc'],['frying_oil',1.5,'l'],['powdered_sugar',150,'g'],['salt',null,'']],
  s:{fr:["Faites gonfler les raisins une heure à l'eau tiède, puis égouttez-les et épongez-les — mouillés, ils font éclabousser l'huile.","Battez une pâte levée molle, presque coulante : l'oliebol se prélève à la cuillère et ne se façonne jamais à la main.","Incorporez les raisins et les pommes en petits dés, et laissez lever 1 heure à couvert jusqu'à ce que la pâte bulle en surface.","Prélevez à deux cuillères huilées et laissez tomber dans l'huile à 175 °C : les boules se retournent d'elles-mêmes si elles sont assez rondes.","Comptez 7 minutes en tout, en les retournant si besoin — plus chaud, elles brunissent avant que le cœur soit cuit. Sucrez au sucre glace tièdes."],
     en:["Plump the raisins for an hour in warm water, then drain and blot them — wet, they make the oil spit.","Beat a soft, almost pourable yeasted batter: an oliebol is spooned out and never shaped by hand.","Fold in the raisins and diced apple, and prove for an hour covered until the batter bubbles on the surface.","Scoop with two oiled spoons and drop into oil at 175°C: the balls turn themselves if they are round enough.","Allow 7 minutes in all, turning if needed — hotter, and they brown before the centre cooks. Dust with icing sugar while warm."]} },

{ id:'gromperekichelcher', c:'eu', lat:49.611, lon:6.130, base:6, prep:30, cook:20, diff:1, tags:['veg','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#c9924a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Gromperekichelcher',en:'Gromperekichelcher'},
  p:{fr:'Luxembourg, Luxembourg',en:'Luxembourg City, Luxembourg'},
  d:{fr:"Des galettes de pomme de terre râpée au persil et à l'oignon, frites et vendues à toutes les fêtes foraines du Grand-Duché. On les mange avec de la compote de pommes ; le mot gromper vient du français grumpire, déformation de pomme de terre en usage en Lorraine.",
     en:"Cakes of grated potato with parsley and onion, fried and sold at every fairground in the Grand Duchy. They are eaten with apple sauce; the word gromper comes from grumpire, a Lorraine corruption of pomme de terre."},
  i:[['potato',1,'kg'],['onion',1,'pc'],['egg',2,'pc'],['flour',50,'g'],['parsley',5,'tbsp'],['leek',1,'pc'],['frying_oil',600,'ml'],['apple_sauce',300,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les pommes de terre au gros trou et pressez-les immédiatement dans un linge : il doit sortir un grand verre d'eau.","Laissez décanter cette eau cinq minutes, jetez le liquide clair et récupérez l'amidon blanc au fond, que vous remettez dans la râpure.","C'est cet amidon récupéré qui lie la galette : sans lui, il faut trois fois plus de farine et le résultat devient pâteux.","Mêlez à l'oignon râpé, au poireau émincé, aux œufs, au persil et au sel, et travaillez rapidement — la râpure noircit en quelques minutes.","Aplatissez des cuillerées dans un centimètre d'huile à 180 °C et laissez prendre 4 minutes par face, sans y toucher. Servez avec de la compote."],
     en:["Grate the potatoes coarsely and press them at once in a cloth: a large glassful of water should come out.","Let that water settle for five minutes, pour off the clear liquid and recover the white starch at the bottom, which goes back into the gratings.","That recovered starch is what binds the cake: without it you need three times the flour and the result turns pasty.","Mix with grated onion, sliced leek, eggs, parsley and salt, and work fast — the gratings darken within minutes.","Flatten spoonfuls into a centimetre of oil at 180°C and let them set 4 minutes a side, untouched. Serve with apple sauce."]} },

{ id:'bouneschlupp', c:'eu', lat:49.615, lon:6.135, base:6, prep:25, cook:60, diff:1, tags:['soup','pork','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'soup',food:['#7fae5a','#f4f0e6','#e8dcb8','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Bouneschlupp',en:'Bouneschlupp'},
  p:{fr:'Luxembourg, Luxembourg',en:'Luxembourg City, Luxembourg'},
  d:{fr:"Une soupe de haricots verts, de pommes de terre et de lard, liée à la crème, plat national luxembourgeois. Elle se fait avec les haricots filandreux de fin d'été, qu'on casse à la main plutôt qu'au couteau : la cassure suit le fil et emporte la ficelle.",
     en:"A soup of green beans, potato and bacon bound with cream, the Luxembourgish national dish. It is made with the stringy late-summer beans, snapped by hand rather than cut: the break follows the fibre and takes the string with it."},
  i:[['green_beans',500,'g'],['potato',500,'g'],['smoked_bacon',200,'g'],['onion',1,'pc'],['heavy_cream',200,'ml'],['flour',1,'tbsp'],['savory',2,'sprig'],['parsley',3,'tbsp'],['butter',30,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cassez les haricots à la main en tronçons de trois centimètres, en tirant le fil qui se détache à chaque cassure.","Faites fondre le lard en dés, ajoutez l'oignon et laissez blondir sans brûler.","Mouillez d'eau, ajoutez les pommes de terre en gros morceaux et la sarriette — c'est l'herbe des haricots, et sans elle la soupe manque de fond.","Laissez cuire 35 minutes, puis écrasez grossièrement quelques pommes de terre contre la paroi pour épaissir.","Liez à la crème mêlée d'une cuillerée de farine, hors ébullition, et laissez reposer un quart d'heure avant de servir."],
     en:["Snap the beans by hand into three-centimetre lengths, pulling away the string that comes loose at each break.","Render the diced bacon, add the onion and let it turn golden without burning.","Moisten with water, add the potatoes in large pieces and the savory — it is the bean herb, and without it the soup lacks depth.","Cook 35 minutes, then crush a few potatoes roughly against the side of the pot to thicken it.","Bind with the cream mixed with a spoonful of flour, off the boil, and rest a quarter of an hour before serving."]} },

{ id:'quetschentaart', c:'eu', lat:49.605, lon:6.125, base:8, prep:50, cook:45, diff:1, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#5a2a4a','#e0b45a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Quetschentaart',en:'Quetschentaart'},
  p:{fr:'Luxembourg, Luxembourg',en:'Luxembourg City, Luxembourg'},
  d:{fr:"Une tarte aux quetsches serrées debout dans la pâte, faite en septembre quand la prune violette mûrit. Les quetsches sont plantées à la verticale, la peau vers le bas : elles rendent leur jus en cuisant et il faut qu'il reste dans le fruit et non dans la pâte.",
     en:"A tart of damsons stood upright in the pastry, made in September when the purple plum ripens. The plums are set vertically, skin down: they release their juice as they bake and it must stay in the fruit and not in the pastry."},
  i:[['plums',1,'kg'],['flour',250,'g'],['butter',125,'g'],['sugar',150,'g'],['egg',1,'pc'],['cinnamon',1,'tsp'],['ground_almonds',40,'g'],['semolina',2,'tbsp'],['salt',null,'']],
  s:{fr:["Faites une pâte sablée au beurre froid, liée d'un œuf, et laissez-la reposer une heure au réfrigérateur.","Dénoyautez les quetsches en les ouvrant en deux sans les séparer entièrement, de manière qu'elles tiennent debout.","Semez le fond de pâte d'amande en poudre et de semoule : ce mélange absorbe le jus, très abondant chez la quetsche.","Plantez les prunes debout et serrées, peau vers le bas, en les faisant se chevaucher légèrement — elles réduisent d'un tiers.","Sucrez et cannellez, et cuisez 45 minutes à 190 °C. Sucrez de nouveau à la sortie, quand le jus affleure."],
     en:["Make a shortcrust with cold butter bound with an egg, and rest it an hour in the fridge.","Stone the damsons by opening them out without separating the halves, so that they will stand up.","Scatter ground almonds and semolina over the pastry base: the mixture absorbs the juice, which damsons give in quantity.","Stand the plums upright and tightly packed, skin down, overlapping slightly — they shrink by a third.","Sugar and cinnamon, and bake 45 minutes at 190°C. Sugar again as it comes out, when the juice rises."]} },

{ id:'frell-am-reisleck', c:'eu', lat:49.750, lon:6.170, base:4, prep:30, cook:25, diff:2, tags:['sea','sunday','fresh'],
  art:{v:'plate',bg:'#26485c',plate:'#f4f0e6',style:'fish',food:['#f4f0e6','#e0a8a0','#e8dcb8','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Truite au riesling',en:'Trout in Riesling'},
  p:{fr:'Vallée de la Moselle, Luxembourg',en:'Moselle valley, Luxembourg'},
  d:{fr:"Des truites pochées dans un riesling de la Moselle luxembourgeoise, la sauce liée à la crème. Le vin ne doit pas bouillir mais frémir : porté à ébullition, un riesling perd son acidité fine et laisse une amertume que la crème ne rattrape pas.",
     en:"Trout poached in a Riesling from the Luxembourg Moselle, the sauce bound with cream. The wine must tremble rather than boil: brought to the boil, a Riesling loses its fine acidity and leaves a bitterness cream cannot rescue."},
  i:[['trout',4,'pc'],['white_wine',200,'ml'],['heavy_cream',200,'ml'],['shallot',2,'pc'],['butter',60,'g'],['parsley',3,'tbsp'],['button_mushrooms',150,'g'],['lemon',1,'pc'],['potato',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Videz les truites, salez-les à l'intérieur et laissez-les reposer vingt minutes avant de les cuire.","Faites suer l'échalote ciselée au beurre sans coloration, puis couchez les truites dessus, tête-bêche pour qu'elles tiennent à plat.","Versez le riesling et un peu d'eau à mi-hauteur, couvrez et laissez pocher 12 minutes à frémissement — jamais à gros bouillons.","Retirez les poissons, levez les filets et gardez-les au chaud sous un papier beurré.","Faites réduire le jus de moitié, ajoutez la crème et les champignons, laissez épaissir 5 minutes et montez au beurre froid hors du feu."],
     en:["Gut the trout, salt them inside and rest them twenty minutes before cooking.","Sweat the chopped shallot in butter without colour, then lay the trout on top, head to tail so they sit flat.","Pour in the Riesling and a little water to half their depth, cover and poach 12 minutes at a tremble — never at a rolling boil.","Lift out the fish, take off the fillets and keep them warm under buttered paper.","Reduce the liquor by half, add the cream and mushrooms, thicken 5 minutes and whisk in cold butter off the heat."]} },

{ id:'kachkeis', c:'eu', lat:49.620, lon:6.115, base:4, prep:30, cook:20, diff:2, tags:['cheese','comfort','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Kachkéis',en:'Kachkéis'},
  p:{fr:'Luxembourg, Luxembourg',en:'Luxembourg City, Luxembourg'},
  d:{fr:"Un fromage cuit et fondu, coulant et jaune, tartiné sur du pain noir avec de la moutarde. Il est né du besoin de rattraper un caillé raté : on le laissait s'affiner jusqu'à ce qu'il devienne translucide, puis on le fondait — un fromage qui ne se mange jamais à la coupe.",
     en:"A cooked, melted cheese, runny and yellow, spread on black bread with mustard. It was born of the need to rescue a failed curd: it was left to ripen until translucent, then melted — a cheese never eaten in slices."},
  i:[['tvorog',500,'g'],['butter',60,'g'],['whole_milk',100,'ml'],['baking_soda',1,'tsp'],['egg',1,'pc'],['mustard',40,'g'],['rustic_bread',400,'g'],['cumin',1,'tsp'],['salt',null,'']],
  s:{fr:["Égouttez le caillé frais 12 heures dans un linge, puis émiettez-le et laissez-le mûrir deux jours à température ambiante, couvert d'un torchon.","Il est prêt quand il commence à sentir fort et que les grains deviennent translucides sur les bords : c'est cet affinage qui fait tout.","Saupoudrez de bicarbonate, mélangez et attendez une heure : le caillé se met à fondre de lui-même sous l'effet de l'alcalinité.","Faites-le fondre à feu très doux avec le beurre et le lait, en remuant sans arrêt jusqu'à obtenir une masse lisse et filante.","Liez d'un œuf battu hors du feu, salez et parfumez au cumin. Versez chaud dans un pot et servez tiède sur du pain noir, avec de la moutarde."],
     en:["Drain fresh curd 12 hours in a cloth, then crumble it and let it ripen two days at room temperature under a tea towel.","It is ready when it begins to smell strongly and the grains turn translucent at the edges: that ripening is everything.","Dust with bicarbonate, mix and wait an hour: the curd begins to melt of its own accord under the alkalinity.","Melt it over very low heat with the butter and milk, stirring without pause to a smooth, stringy mass.","Bind with a beaten egg off the heat, salt and scent with caraway. Pour it hot into a pot and serve warm on black bread, with mustard."]} },

{ id:'mielzepudder', c:'eu', lat:49.600, lon:6.140, base:6, prep:30, cook:60, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2dfa8','#4f3a2a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Mielzepudder',en:'Mielzepudder'},
  p:{fr:'Luxembourg, Luxembourg',en:'Luxembourg City, Luxembourg'},
  d:{fr:"Un pudding de semoule au lait et aux raisins, cuit au four et servi tiède. Mielz veut dire semoule en luxembourgeois ; c'était le dessert des jours ordinaires, fait avec ce qu'il y avait toujours dans la maison — de la farine, du lait et des œufs.",
     en:"A semolina and milk pudding with raisins, baked and served warm. Mielz means semolina in Luxembourgish; it was the everyday pudding, made from what was always in the house — flour, milk and eggs."},
  i:[['semolina',250,'g'],['whole_milk',1,'l'],['egg',3,'pc'],['sugar',100,'g'],['raisins',100,'g'],['cinnamon',1,'tsp'],['butter',50,'g'],['lemon_zest',1,'pc'],['rum',30,'ml'],['salt',null,'']],
  s:{fr:["Faites gonfler les raisins dans le rhum tiède une demi-heure et égouttez-les.","Portez le lait à frémissement avec le zeste, le sel et la moitié du sucre, puis versez la semoule en pluie en fouettant sans arrêt.","Cuisez 8 minutes à feu doux en remuant : la semoule doit épaissir jusqu'à ce que la cuillère y tienne debout.","Laissez tiédir à 50 °C avant d'ajouter les jaunes — versés dans une semoule brûlante, ils coagulent en grumeaux.","Incorporez les blancs montés en neige souple et les raisins, versez dans un plat beurré et cuisez 45 minutes à 180 °C. Servez tiède, jamais froid."],
     en:["Plump the raisins in warm rum for half an hour and drain them.","Bring the milk to a tremble with the zest, salt and half the sugar, then rain in the semolina, whisking without pause.","Cook 8 minutes over low heat, stirring: the semolina must thicken until a spoon stands up in it.","Let it cool to 50°C before adding the yolks — poured into scalding semolina they set into lumps.","Fold in the whites whisked to soft peaks and the raisins, turn into a buttered dish and bake 45 minutes at 180°C. Serve warm, never cold."]} },

{ id:'obatzda', c:'eu', lat:48.137, lon:11.575, base:6, prep:20, cook:0, diff:1, tags:['cheese','fast','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'other',food:['#e8a032','#f2dfa8','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Obatzda',en:'Obatzda'},
  p:{fr:'Munich, Bavière, Allemagne',en:'Munich, Bavaria, Germany'},
  d:{fr:"Un camembert trop fait écrasé au beurre et au paprika, servi au jardin de bière avec un bretzel. Katharina Eisenreich l'aurait mis à la carte en 1920 pour écouler ses fromages coulants ; obatzt veut dire écrasé en bavarois, et le geste est dans le nom.",
     en:"An overripe camembert crushed with butter and paprika, served in beer gardens with a pretzel. Katharina Eisenreich is said to have put it on the menu in 1920 to use up her runny cheeses; obatzt means mashed in Bavarian, and the gesture is in the name."},
  i:[['camembert',250,'g'],['butter',100,'g'],['sweet_paprika',1,'tbsp'],['chives',3,'tbsp'],['onion',1,'pc'],['beer',40,'ml'],['cumin',1,'tsp'],['brezel',4,'pc'],['radish',6,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez un camembert franchement fait, coulant sous la croûte : un fromage jeune ne s'écrase pas et reste en morceaux caoutchouteux.","Écrasez-le à la fourchette avec sa croûte — elle apporte le goût, et l'ôter revient à faire une tartinade fade.","Travaillez le beurre en pommade à part, puis incorporez-le au fromage en écrasant, jamais en fouettant.","Ajoutez le paprika, le cumin, l'oignon râpé et une lampée de bière pour détendre : la bière est l'ingrédient bavarois, elle apporte l'amertume qui coupe le gras.","Laissez reposer 2 heures au frais, sortez une demi-heure avant, et servez avec un bretzel et des radis."],
     en:["Choose a frankly ripe camembert, runny under the rind: a young cheese will not mash and stays in rubbery lumps.","Crush it with a fork, rind and all — the rind carries the flavour, and removing it makes a bland spread.","Cream the butter separately, then work it into the cheese by crushing, never by whisking.","Add the paprika, caraway, grated onion and a splash of beer to loosen it: the beer is the Bavarian element, bringing the bitterness that cuts the fat.","Rest it 2 hours in the cold, take it out half an hour ahead, and serve with a pretzel and radishes."]} },

{ id:'dampfnudeln', c:'eu', lat:48.130, lon:11.582, base:6, prep:120, cook:35, diff:3, tags:['sweet','comfort','slow'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'roll',food:['#f4f0e6','#c9924a','#e8c46a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Dampfnudeln',en:'Dampfnudeln'},
  p:{fr:'Munich, Bavière, Allemagne',en:'Munich, Bavaria, Germany'},
  d:{fr:"Des boules de pâte levée cuites à couvert dans un fond de lait beurré, moelleuses dessus et caramélisées dessous. Tout se joue dans un seul geste : on ne soulève jamais le couvercle, sinon la vapeur s'échappe et les boules retombent définitivement.",
     en:"Balls of yeasted dough cooked covered in a shallow layer of buttered milk, soft on top and caramelised beneath. It all hangs on one rule: the lid is never lifted, or the steam escapes and the dumplings collapse for good."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['whole_milk',350,'ml'],['butter',100,'g'],['sugar',80,'g'],['egg',2,'pc'],['vanilla',1,'pc'],['egg_yolk',3,'pc'],['heavy_cream',200,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte levée souple avec la farine, la levure, 150 ml de lait tiède, un œuf, 30 g de sucre et le beurre mou, et laissez lever 1 heure.","Façonnez des boules de 70 g et laissez-les pousser 30 minutes sur un linge fariné, bien espacées.","Dans une cocotte large, faites fondre le beurre restant avec le lait et le sucre : le liquide doit monter à un centimètre à peine, pas davantage.","Rangez les boules sans qu'elles se touchent, couvrez d'un couvercle lourd et laissez 30 minutes à feu doux — sans jamais soulever le couvercle.","Vous entendrez le liquide s'évaporer puis la base grésiller : c'est le signe que la croûte se forme. Servez avec une crème anglaise à la vanille."],
     en:["Knead a soft yeasted dough with the flour, yeast, 150 ml of warm milk, one egg, 30 g of sugar and the softened butter, and prove for an hour.","Shape 70 g balls and prove them 30 minutes on a floured cloth, well spaced.","In a wide pot, melt the remaining butter with the milk and sugar: the liquid should come up barely a centimetre, no more.","Set the balls in without touching, cover with a heavy lid and give them 30 minutes over low heat — never lifting the lid.","You will hear the liquid evaporate then the base sizzle: the sign the crust is forming. Serve with a vanilla custard."]} },

{ id:'halve-hahn', c:'eu', lat:50.938, lon:6.960, base:4, prep:15, cook:0, diff:1, tags:['cheese','fast','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e8c46a','#8f6a4a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Halve Hahn',en:'Halve Hahn'},
  p:{fr:'Cologne, Rhénanie, Allemagne',en:'Cologne, Rhineland, Germany'},
  d:{fr:"Un petit pain de seigle beurré avec une épaisse tranche de gouda vieux, de la moutarde et de l'oignon. Le nom signifie demi-coq et ne contient aucun poulet : la légende raconte qu'un plaisantin de Cologne commanda ainsi pour piéger un convive, et le nom est resté.",
     en:"A buttered rye roll with a thick slice of aged Gouda, mustard and onion. The name means half a cockerel and contains no chicken at all: legend has a Cologne joker order it that way to catch out a guest, and the name stuck."},
  i:[['rye_bread',4,'pc'],['gouda',300,'g'],['butter',60,'g'],['mustard',40,'g'],['onion',1,'pc'],['pickles',4,'pc'],['sweet_paprika',1,'tsp'],['pepper',null,'']],
  s:{fr:["Employez un roggenbrötchen, petit pain de seigle au carvi : le pain de froment ne tient pas devant un gouda vieilli.","Choisissez un gouda de dix-huit mois au moins, cristallisé et cassant, et taillez-en une tranche d'un bon centimètre.","La tranche doit être plus épaisse que le beurre et déborder du pain : à Cologne, un halve Hahn maigre est une offense.","Beurrez généreusement les deux faces, posez le fromage, puis la moutarde à part sur le bord de l'assiette — jamais étalée dessus.","Ajoutez des rondelles d'oignon cru et un cornichon. Se mange à la main, avec une Kölsch servie dans un verre étroit de vingt centilitres."],
     en:["Use a roggenbrötchen, a caraway rye roll: wheat bread cannot stand up to an aged Gouda.","Choose a Gouda of at least eighteen months, crystalline and brittle, and cut a slice a good centimetre thick.","The slice must be thicker than the butter and overhang the bread: in Cologne a thin halve Hahn is an offence.","Butter both faces generously, lay on the cheese, then the mustard on the side of the plate — never spread on it.","Add raw onion rings and a gherkin. Eaten by hand, with a Kölsch served in a narrow two-hundred-millilitre glass."]} },

{ id:'leipziger-allerlei', c:'eu', lat:51.340, lon:12.375, base:4, prep:50, cook:35, diff:3, tags:['veg','fresh','sunday'],
  art:{v:'plate',bg:'#28331f',plate:'#f4f0e6',style:'other',food:['#7fae5a','#f4f0e6','#e07a6a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Leipziger Allerlei',en:'Leipziger Allerlei'},
  p:{fr:'Leipzig, Saxe, Allemagne',en:'Leipzig, Saxony, Germany'},
  d:{fr:"Un ragoût de légumes de printemps aux écrevisses et aux quenelles de moelle, lié au beurre d'écrevisse. La légende raconte que les Leipzigois servaient ce plat sans viande aux mendiants et aux percepteurs pour paraître pauvres, tout en se régalant de ce qu'il cachait.",
     en:"A stew of spring vegetables with crayfish and marrow dumplings, bound with crayfish butter. Legend has it that the people of Leipzig served this meatless dish to beggars and tax collectors to look poor, while feasting on what it concealed."},
  i:[['carrot',3,'pc'],['cauliflower',1,'pc'],['peas',200,'g'],['asparagus',200,'g'],['crayfish',200,'g'],['butter',120,'g'],['flour',30,'g'],['heavy_cream',150,'ml'],['nutmeg',1,'pinch'],['button_mushrooms',150,'g'],['parsley',3,'tbsp'],['sugar',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez chaque légume séparément à l'eau bouillante salée et rafraîchissez-le aussitôt : ils n'ont ni le même temps ni la même couleur à préserver.","Les carottes se glacent au beurre et au sucre, les asperges se pochent trois minutes, les petits pois deux, le chou-fleur cinq.","Décortiquez les écrevisses et pilez les carapaces au mortier avec du beurre, puis faites fondre ce beurre et filtrez-le : c'est le beurre d'écrevisse, et c'est lui qui donne le goût et la couleur.","Faites un velouté avec le beurre d'écrevisse, la farine et le jus de cuisson des légumes, puis liez à la crème.","Réunissez tout hors du feu, réchauffez sans bouillir, et servez aussitôt : les légumes perdent leur couleur en dix minutes."],
     en:["Cook each vegetable separately in boiling salted water and refresh it at once: none shares a cooking time or a colour to preserve.","The carrots are glazed in butter and sugar, the asparagus poached three minutes, the peas two, the cauliflower five.","Shell the crayfish and pound the shells in a mortar with butter, then melt that butter and strain it: this is crayfish butter, and it gives the taste and the colour.","Make a velouté with the crayfish butter, flour and the vegetable cooking liquid, then bind with cream.","Combine everything off the heat, warm through without boiling, and serve at once: the vegetables lose their colour within ten minutes."]} },

{ id:'quarkkeulchen', c:'eu', lat:51.050, lon:13.738, base:4, prep:40, cook:20, diff:1, tags:['sweet','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f4f0e6','#f2dfa8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Quarkkeulchen',en:'Quarkkeulchen'},
  p:{fr:'Dresde, Saxe, Allemagne',en:'Dresden, Saxony, Germany'},
  d:{fr:"De petites galettes de quark et de pomme de terre de la veille, poêlées et sucrées à la cannelle. C'est un plat d'accommodement des restes : il faut des pommes de terre cuites la veille, refroidies et râpées, une pomme de terre fraîche rendrait la pâte collante et grise.",
     en:"Small cakes of quark and yesterday's potato, pan-fried and dusted with cinnamon sugar. It is a leftovers dish: the potatoes must have been boiled the day before, cooled and grated, as fresh potato would make the batter sticky and grey."},
  i:[['tvorog',250,'g'],['potato',300,'g'],['flour',150,'g'],['egg',2,'pc'],['sugar',60,'g'],['raisins',60,'g'],['cinnamon',2,'tsp'],['butter',80,'g'],['lemon_zest',1,'pc'],['apple_sauce',300,'g'],['salt',null,'']],
  s:{fr:["Cuisez les pommes de terre en robe des champs la veille et laissez-les refroidir douze heures : l'amidon rétrograde et devient ferme.","Pelez-les et râpez-les au gros trou, puis égouttez le quark dans un linge une heure.","Mêlez tout du bout des doigts sans travailler la pâte : trop pétrie, elle devient élastique et les galettes se contractent à la poêle.","Formez des galettes de 8 cm et un centimètre d'épaisseur, farinées légèrement.","Poêlez au beurre 4 minutes par face à feu moyen, et sucrez à la cannelle brûlantes. Servez avec de la compote de pommes."],
     en:["Boil the potatoes in their skins the day before and cool them twelve hours: the starch retrogrades and firms up.","Peel and grate them coarsely, then drain the quark in a cloth for an hour.","Mix everything with your fingertips without working the batter: overworked, it turns elastic and the cakes shrink in the pan.","Shape cakes 8 cm across and a centimetre thick, lightly floured.","Fry in butter 4 minutes a side over medium heat, and dust with cinnamon sugar while scalding. Serve with apple sauce."]} },

{ id:'braunkohl-mit-kassler', c:'eu', lat:53.144, lon:8.214, base:6, prep:40, cook:150, diff:2, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#4f6f3a','#e0a8a0','#e8dcb8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Braunkohl mit Kassler',en:'Braunkohl mit Kassler'},
  p:{fr:'Oldenbourg, Basse-Saxe, Allemagne',en:'Oldenburg, Lower Saxony, Germany'},
  d:{fr:"Du chou frisé longuement mijoté avec du carré de porc fumé et des pommes de terre caramélisées. On ne le fait qu'après les premières gelées : le froid transforme l'amidon du chou en sucre, et une feuille cueillie avant novembre reste dure et amère.",
     en:"Curly kale long stewed with smoked pork loin and caramelised potatoes. It is made only after the first frosts: cold turns the kale's starch to sugar, and a leaf picked before November stays tough and bitter."},
  i:[['curly_kale',1,'kg'],['smoked_pork_loin',600,'g'],['potato',1,'kg'],['smoked_bacon',200,'g'],['onion',2,'pc'],['oats',3,'tbsp'],['lard',60,'g'],['sugar',2,'tbsp'],['mustard',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Effeuillez le chou en retirant la nervure centrale, blanchissez-le 5 minutes et hachez-le grossièrement au couteau.","Faites fondre le lard et l'oignon dans le saindoux, ajoutez le chou et laissez-le compoter 20 minutes avant de mouiller.","Posez le carré de porc fumé dessus et laissez mijoter 2 heures à couvert, à feu doux, sans jamais remuer le fond.","Liez avec les flocons d'avoine dans la dernière demi-heure : c'est l'épaississant du Nord, et il ne se remplace pas par de la farine.","Faites sauter les pommes de terre à part dans du saindoux avec une cuillerée de sucre, jusqu'à ce qu'elles caramélisent. Servez le tout avec de la moutarde forte."],
     en:["Strip the kale from its central ribs, blanch it 5 minutes and chop it roughly by knife.","Render the bacon and onion in lard, add the kale and let it stew down 20 minutes before adding liquid.","Set the smoked loin on top and simmer 2 hours covered over low heat, never stirring the base.","Thicken with the oats in the last half hour: it is the northern thickener, and flour will not replace it.","Sauté the potatoes separately in lard with a spoonful of sugar, until they caramelise. Serve everything with strong mustard."]} },

{ id:'frankfurter-grune-sosse', c:'eu', lat:50.110, lon:8.682, base:6, prep:30, cook:20, diff:2, tags:['veg','fresh','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4f0e6',style:'other',food:['#7fae5a','#f4f0e6','#4f8f4a','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Grüne Soße de Francfort',en:'Frankfurt green sauce'},
  p:{fr:'Francfort, Hesse, Allemagne',en:'Frankfurt, Hesse, Germany'},
  d:{fr:"Une sauce froide de sept herbes obligatoires, servie sur des œufs durs et des pommes de terre. La composition est protégée : bourrache, cerfeuil, cresson, persil, pimprenelle, oseille et ciboulette, ni plus ni moins — Goethe, né à Francfort, en était réputé friand.",
     en:"A cold sauce of seven compulsory herbs, served over hard-boiled eggs and potatoes. The composition is protected: borage, chervil, cress, parsley, salad burnet, sorrel and chives, no more and no fewer — Goethe, born in Frankfurt, was said to love it."},
  i:[['parsley',1,'bunch'],['chives',1,'bunch'],['chervil',1,'bunch'],['borage',1,'bunch'],['sorrel',1,'bunch'],['watercress',1,'bunch'],['salad_burnet',1,'bunch'],['smetana',300,'g'],['plain_yogurt',200,'g'],['egg',8,'pc'],['mustard',1,'tbsp'],['white_vinegar',2,'tbsp'],['sunflower_oil',60,'ml'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Lavez les sept herbes et séchez-les à fond : une seule goutte d'eau restante dilue la sauce et la fait tourner en deux heures.","Hachez-les au couteau très finement, toutes ensemble — le mixeur oxyde les herbes et la sauce vire au brun olive.","Écrasez quatre jaunes d'œufs durs avec la moutarde, le vinaigre et l'huile pour faire une base émulsionnée.","Incorporez la smetana et le yaourt, puis les herbes, et hachez les blancs restants pour les ajouter en dés.","Laissez reposer 3 heures au froid, pas davantage : au-delà, les herbes noircissent. Servez sur des œufs durs et des pommes de terre chaudes."],
     en:["Wash the seven herbs and dry them thoroughly: a single drop of water left thins the sauce and turns it within two hours.","Chop them very finely by knife, all together — a blender oxidises herbs and the sauce turns olive brown.","Crush four hard-boiled yolks with the mustard, vinegar and oil to make an emulsified base.","Fold in the smetana and yoghurt, then the herbs, and dice the remaining whites to add.","Rest 3 hours in the cold, no longer: beyond that the herbs blacken. Serve over hard-boiled eggs and hot potatoes."]} },

{ id:'ahle-worscht', c:'eu', lat:51.312, lon:9.480, base:8, prep:120, cook:0, diff:3, tags:['pork','slow','comfort'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'other',food:['#8f3b2a','#6f2a2a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Ahle Worscht',en:'Ahle Worscht'},
  p:{fr:'Cassel, Hesse, Allemagne',en:'Kassel, Hesse, Germany'},
  d:{fr:"Une saucisse sèche de Hesse du Nord, embossée avec de la viande encore chaude d'abattage. C'est là toute sa particularité : la viande doit être travaillée dans les deux heures, avant que le pH ne descende, sans quoi elle ne lie plus et la saucisse s'effrite.",
     en:"A dry sausage from northern Hesse, cased with meat still warm from the slaughter. That is its whole peculiarity: the meat must be worked within two hours, before the pH falls, otherwise it no longer binds and the sausage crumbles."},
  i:[['pork_shoulder',1.2,'kg'],['pork_belly',600,'g'],['coarse_salt',45,'g'],['black_peppercorns',2,'tbsp'],['sausage_casings',null,''],['sugar',5,'g'],['garlic',2,'clove'],['rye_bread',400,'g'],['mustard',40,'g']],
  s:{fr:["Travaillez la viande dans les deux heures suivant l'abattage, encore tiède : c'est la condition impérative de l'ahle Worscht.","Hachez épaule et poitrine à la grille moyenne, en gardant du gras visible, et salez à 25 g au kilo.","Poivrez très généreusement et malaxez cinq minutes seulement : trop travaillée, la masse chauffe et le gras fond.","Embossez fermement en chassant l'air et liez en fers à cheval ou en boyaux droits selon la tradition du village.","Séchez trois semaines à 15 °C, puis affinez trois à six mois en cave. La saucisse doit perdre un tiers de son poids et se trancher à peine sans s'émietter."],
     en:["Work the meat within two hours of slaughter, still warm: that is the imperative condition of Ahle Worscht.","Mince the shoulder and belly on the medium plate, keeping visible fat, and salt at 25 g per kilo.","Pepper very generously and knead for five minutes only: overworked, the mass warms and the fat melts.","Fill the casings firmly, expelling air, and tie into horseshoes or straight lengths according to the village's tradition.","Dry three weeks at 15°C, then age three to six months in a cellar. It must lose a third of its weight and just hold together when sliced."]} },

{ id:'birchermuesli', c:'eu', lat:47.377, lon:8.542, base:4, prep:15, cook:0, diff:1, tags:['sweet','breakfast','fresh'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#e8dcb8','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Birchermüesli',en:'Birchermüesli'},
  p:{fr:'Zurich, Suisse',en:'Zurich, Switzerland'},
  d:{fr:"Des flocons d'avoine trempés une nuit, mêlés de pomme râpée, de noix et de lait condensé. Maximilian Bircher-Brenner le mit au point vers 1900 dans son sanatorium zurichois : ce n'était pas un petit-déjeuner mais une entrée, servie avant chaque repas, et la pomme y dominait de loin l'avoine.",
     en:"Oat flakes soaked overnight, mixed with grated apple, nuts and condensed milk. Maximilian Bircher-Brenner devised it around 1900 in his Zurich sanatorium: it was not a breakfast but a starter, served before every meal, and apple far outweighed oats."},
  i:[['oats',150,'g'],['apple',3,'pc'],['whole_milk',200,'ml'],['condensed_milk',60,'g'],['walnuts',60,'g'],['hazelnuts',40,'g'],['lemon',1,'pc'],['heavy_cream',100,'ml'],['honey',2,'tbsp'],['banana',1,'pc']],
  s:{fr:["Faites tremper les flocons d'avoine dans le lait une nuit entière au réfrigérateur : trempés une heure, ils restent secs à cœur et rêches.","Le lendemain, râpez les pommes non pelées au dernier moment, directement au-dessus du bol.","Arrosez-les aussitôt de jus de citron : sans cela, la pomme râpée brunit en trois minutes et le müesli devient gris.","La recette d'origine compte trois fois plus de pomme que d'avoine — l'inverse de ce que vendent les paquets modernes.","Incorporez le lait condensé, la crème, le miel et les fruits secs concassés, et servez immédiatement, encore froid."],
     en:["Soak the oats in milk overnight in the fridge: soaked for an hour they stay dry and harsh at the centre.","The next day, grate the unpeeled apples at the last moment, straight over the bowl.","Douse them at once with lemon juice: without it grated apple browns within three minutes and the müesli turns grey.","The original recipe holds three times more apple than oats — the reverse of what modern packets sell.","Fold in the condensed milk, cream, honey and chopped nuts, and serve immediately, still cold."]} },

{ id:'luxemburgerli', c:'eu', lat:47.370, lon:8.539, base:20, prep:120, cook:15, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e07a9a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#c9754a'},
  n:{fr:'Luxemburgerli',en:'Luxemburgerli'},
  p:{fr:'Zurich, Suisse',en:'Zurich, Switzerland'},
  d:{fr:"De minuscules macarons plus petits et plus légers que le parisien, fourrés d'une ganache aérée. Un apprenti luxembourgeois de la confiserie Sprüngli les rapporta vers 1957 ; ses collègues zurichois les nommèrent d'après lui, et le nom est resté déposé depuis.",
     en:"Tiny macarons, smaller and lighter than the Parisian kind, filled with an aerated ganache. A Luxembourgish apprentice at Sprüngli brought them back around 1957; his Zurich colleagues named them after him, and the name has been trademarked since."},
  i:[['ground_almonds',200,'g'],['powdered_sugar',200,'g'],['egg_white',4,'pc'],['sugar',150,'g'],['dark_chocolate',150,'g'],['heavy_cream',150,'ml'],['butter',50,'g'],['water',50,'ml'],['salt',null,'']],
  s:{fr:["Tamisez ensemble la poudre d'amande et le sucre glace deux fois, puis une troisième au tamis fin : le moindre grain fait un cratère dans la coque.","Montez une meringue italienne en versant sur les blancs un sirop cuit à 118 °C, et fouettez jusqu'à ce que la cuve refroidisse.","Macaronnez en écrasant la masse contre la paroi jusqu'à ce qu'elle forme un ruban qui s'efface en trente secondes — pas plus, pas moins.","Dressez des coques de 2 cm seulement, tapez la plaque et laissez croûter 30 minutes : on doit pouvoir toucher la surface sans qu'elle colle.","Cuisez 12 minutes à 150 °C, garnissez d'une ganache montée et laissez maturer 24 heures au froid avant de servir."],
     en:["Sift the ground almonds and icing sugar together twice, then a third time through a fine sieve: a single grain makes a crater in the shell.","Whisk an Italian meringue by pouring syrup cooked to 118°C onto the whites, and beat until the bowl cools.","Macaronner by pressing the mass against the side until it ribbons and settles within thirty seconds — no more, no less.","Pipe shells only 2 cm across, rap the tray and let them skin for 30 minutes: you should be able to touch the surface without it sticking.","Bake 12 minutes at 150°C, fill with a whipped ganache and mature 24 hours in the cold before serving."]} },

{ id:'engadiner-nusstorte', c:'eu', lat:46.797, lon:10.301, base:10, prep:70, cook:45, diff:2, tags:['sweet','bake','slow'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#c9924a','#8f6a4a','#e8dcb8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tourte aux noix de l’Engadine',en:'Engadine nut tart'},
  p:{fr:'Scuol, Engadine, Suisse',en:'Scuol, Engadine, Switzerland'},
  d:{fr:"Une tourte fermée de pâte sablée emplie de noix caramélisées à la crème. Les Engadinois émigrés confiseurs en Italie et en France la rapportèrent au début du XXᵉ siècle ; elle se garde trois semaines sans rien perdre, ce qui en fit le gâteau des cols et des longs voyages.",
     en:"A closed shortcrust tart filled with caramelised walnuts in cream. Engadine emigrants who worked as confectioners in Italy and France brought it back in the early 20th century; it keeps three weeks without loss, which made it the cake of mountain passes and long journeys."},
  i:[['flour',300,'g'],['butter',200,'g'],['sugar',350,'g'],['egg',2,'pc'],['walnuts',300,'g'],['heavy_cream',200,'ml'],['honey',60,'g'],['salt',null,'']],
  s:{fr:["Faites une pâte sablée riche au beurre et à un œuf, et laissez-la reposer 2 heures : elle est fragile et se travaille froide.","Faites un caramel à sec avec le sucre, sans eau ni remuage — remué, il cristallise et il faut tout recommencer.","Décuisez-le à la crème chaude versée en trois fois, en reculant : la projection est violente et le mélange durcit un instant avant de se lisser.","Ajoutez les noix concassées grossièrement et le miel, et laissez refroidir complètement avant de garnir.","Foncez, garnissez, couvrez d'un disque, soudez, dorez et piquez le dessus. Cuisez 45 minutes à 180 °C et attendez deux jours avant de couper."],
     en:["Make a rich shortcrust with butter and one egg, and rest it 2 hours: it is fragile and worked cold.","Make a dry caramel with the sugar, with no water and no stirring — stirred, it crystallises and you must start again.","Stop the cooking with hot cream poured in three additions, standing back: it spits violently and seizes for a moment before smoothing.","Add the roughly chopped walnuts and the honey, and cool completely before filling.","Line, fill, cover with a disc, seal, glaze and prick the top. Bake 45 minutes at 180°C and wait two days before cutting."]} },

{ id:'capuns', c:'eu', lat:46.850, lon:9.532, base:4, prep:70, cook:30, diff:3, tags:['pork','comfort','slow'],
  art:{v:'plate',bg:'#28331f',plate:'#f4f0e6',style:'roll',food:['#4f6f3a','#f4f0e6','#c9924a','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Capuns',en:'Capuns'},
  p:{fr:'Coire, Grisons, Suisse',en:'Chur, Grisons, Switzerland'},
  d:{fr:"Des feuilles de bette farcies d'une pâte à spätzle et de charcuterie, pochées puis gratinées à la crème. Chaque vallée des Grisons a sa version et personne ne s'accorde sur la taille : les uns les font gros comme le pouce, les autres comme un cigare, et le débat tient lieu de conversation.",
     en:"Chard leaves wrapped around a spätzle batter and cured meats, poached then baked in cream. Every Grisons valley has its version and nobody agrees on the size: some make them thumb-sized, others like a cigar, and the argument passes for conversation."},
  i:[['swiss_chard',24,'pc'],['flour',250,'g'],['egg',3,'pc'],['whole_milk',150,'ml'],['smoked_bacon',150,'g'],['salami',100,'g'],['heavy_cream',300,'ml'],['gruyere_cheese',120,'g'],['butter',60,'g'],['chives',3,'tbsp'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Blanchissez les feuilles de bette 20 secondes et rafraîchissez-les : plus longtemps, elles se déchirent au pliage.","Aplatissez la nervure centrale au couteau, à plat, sans la couper — elle doit plier sans casser.","Battez une pâte à spätzle épaisse avec la farine, les œufs, le lait et le sel, et incorporez le lard et le salami en petits dés.","Déposez une cuillerée sur chaque feuille et roulez en repliant les côtés, comme un petit paquet, soudure dessous.","Pochez 12 minutes dans un bouillon frémissant, rangez-les serrés dans un plat, nappez de crème et de fromage et gratinez 15 minutes à 200 °C."],
     en:["Blanch the chard leaves 20 seconds and refresh them: any longer and they tear when folded.","Flatten the central rib with a knife laid flat, without cutting it — it must bend and not snap.","Beat a thick spätzle batter with the flour, eggs, milk and salt, and fold in the diced bacon and salami.","Set a spoonful on each leaf and roll it up, folding the sides in like a small parcel, seam underneath.","Poach 12 minutes in simmering broth, pack them tightly in a dish, coat with cream and cheese and bake 15 minutes at 200°C."]} },

{ id:'kiachln', c:'eu', lat:47.269, lon:11.404, base:8, prep:120, cook:20, diff:2, tags:['sweet','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#4f3a2a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Kiachln du Tyrol',en:'Tyrolean Kiachln'},
  p:{fr:'Innsbruck, Tyrol, Autriche',en:'Innsbruck, Tyrol, Austria'},
  d:{fr:"Des galettes de pâte levée étirées à la main en disque au bord épais, frites dans le saindoux. Le bord est laissé plus épais et le centre presque translucide : on le remplit de confiture d'airelles ou, en version salée, de choucroute — le creux n'est pas un hasard, il est fait pour cela.",
     en:"Rounds of yeasted dough stretched by hand with a thick rim, fried in lard. The rim is left thick and the centre almost translucent: it is filled with lingonberry jam or, in the savoury version, sauerkraut — the hollow is deliberate."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['whole_milk',250,'ml'],['sugar',100,'g'],['egg',2,'pc'],['butter',50,'g'],['rum',30,'ml'],['lard',1,'kg'],['lingonberry_jam',300,'g'],['sauerkraut',300,'g'],['powdered_sugar',60,'g'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte levée souple au lait tiède, aux œufs, au sucre, au rhum et au beurre, et laissez-la lever 1 h 30.","Divisez en boules de 80 g et laissez-les pousser 30 minutes sous un linge.","Étirez chaque boule à la main sur le dos des poings, en tournant : le centre doit devenir presque transparent, le bord rester épais.","Un rouleau à pâtisserie écraserait le bord et la kiachl n'aurait plus de creux : le geste se fait aux mains, sans exception.","Plongez à plat dans le saindoux à 175 °C, 90 secondes par face. Garnissez le creux de confiture d'airelles ou de choucroute chaude."],
     en:["Knead a soft yeasted dough with warm milk, eggs, sugar, rum and butter, and prove it 1½ hours.","Divide into 80 g balls and prove them 30 minutes under a cloth.","Stretch each ball by hand over the backs of your fists, turning: the centre must go almost transparent, the rim stay thick.","A rolling pin would flatten the rim and the Kiachl would have no hollow: the shaping is done by hand, without exception.","Lower them flat into lard at 175°C, 90 seconds a side. Fill the hollow with lingonberry jam or hot sauerkraut."]} },

{ id:'salzburger-rindfleisch', c:'eu', lat:47.809, lon:13.055, base:4, prep:30, cook:120, diff:2, tags:['beef','slow','sunday'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'stew',food:['#8f5a3a','#f4f0e6','#c9a878','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Bœuf aux champignons de Salzbourg',en:'Salzburg beef with mushrooms'},
  p:{fr:'Salzbourg, Autriche',en:'Salzburg, Austria'},
  d:{fr:"Du bœuf braisé aux champignons dans une sauce à la crème et au vin rouge, servi avec des Spätzle. C'est la cuisine bourgeoise de l'Autriche alpine : la sauce ne se lie ni à la farine ni à la fécule mais par réduction, ce qui exige de ne jamais couvrir la cocotte à la fin.",
     en:"Beef braised with mushrooms in a cream and red wine sauce, served with Spätzle. This is the bourgeois cooking of alpine Austria: the sauce is thickened with neither flour nor starch but by reduction, which means never covering the pot at the end."},
  i:[['beef_chuck',600,'g'],['button_mushrooms',300,'g'],['heavy_cream',200,'ml'],['red_wine',100,'ml'],['onion',1,'pc'],['butter',60,'g'],['beef_broth',400,'ml'],['bay_leaf',2,'pc'],['juniper_berries',6,'pc'],['flour',250,'g'],['egg',3,'pc'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Saisissez le bœuf en gros cubes au beurre par petites quantités, jusqu'à ce qu'il soit franchement coloré sur toutes les faces.","Retirez-le, faites blondir l'oignon, déglacez au vin rouge et laissez-le s'évaporer entièrement avant d'ajouter le bouillon.","Braisez 1 h 30 à couvert avec le laurier et le genièvre, puis découvrez pour la dernière demi-heure.","Faites sauter les champignons à part, à feu vif, dans une poêle très chaude : ajoutés crus dans la cocotte, ils rendraient leur eau et délaveraient la sauce.","Ajoutez-les avec la crème et laissez réduire à découvert jusqu'à ce que la sauce nappe. Servez avec des Spätzle."],
     en:["Sear the beef in large cubes in butter in small batches, until frankly coloured on every face.","Lift it out, soften the onion, deglaze with red wine and let it evaporate entirely before adding the broth.","Braise 1½ hours covered with the bay and juniper, then uncover for the last half hour.","Sauté the mushrooms separately over high heat in a very hot pan: added raw to the pot they would weep and thin the sauce.","Add them with the cream and reduce uncovered until the sauce coats. Serve with Spätzle."]} },

{ id:'aebleskiver', c:'eu', lat:55.676, lon:12.568, base:6, prep:40, cook:25, diff:2, tags:['sweet','festive','fry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e0b45a','#f4f0e6','#c9402c','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Æbleskiver',en:'Æbleskiver'},
  p:{fr:'Copenhague, Danemark',en:'Copenhagen, Denmark'},
  d:{fr:"De petites boules de pâte cuites dans une poêle à alvéoles, servies au sucre glace et à la confiture pendant l'Avent. Le nom veut dire tranches de pomme : on en glissait autrefois au centre, usage abandonné, mais le nom est resté et le creux aussi.",
     en:"Small balls of batter cooked in a dimpled pan, served with icing sugar and jam through Advent. The name means apple slices: one was once slipped into the centre, a habit long abandoned, but the name has stayed and so has the hollow."},
  i:[['flour',250,'g'],['egg',2,'pc'],['buttermilk',250,'ml'],['butter',60,'g'],['sugar',50,'g'],['cardamom',1,'tsp'],['baking_powder',1,'tsp'],['lemon_zest',1,'pc'],['powdered_sugar',60,'g'],['lingonberry_jam',200,'g'],['salt',null,'']],
  s:{fr:["Séparez les œufs : les jaunes vont dans la pâte, les blancs montés en neige s'incorporent en dernier.","Ce sont les blancs qui font la légèreté : sans eux, l'æbleskiver est une boule dense et sourde.","Chauffez la poêle à alvéoles et beurrez chaque creux généreusement avant chaque fournée, jamais une seule fois pour toutes.","Emplissez les alvéoles aux trois quarts et attendez que le bord prenne, puis faites tourner d'un quart de tour à l'aiguille à tricoter.","Répétez le quart de tour quatre ou cinq fois : la pâte encore crue coule vers le bas à chaque rotation et ferme la sphère. Sucrez et servez avec de la confiture."],
     en:["Separate the eggs: the yolks go into the batter, the whites whisked to peaks are folded in last.","The whites are what give the lightness: without them an æbleskiv is a dense, dull ball.","Heat the dimpled pan and butter every hollow generously before each batch, never once for all.","Fill the hollows three-quarters full and wait for the edge to set, then turn a quarter turn with a knitting needle.","Repeat the quarter turn four or five times: the still-raw batter runs downward at each rotation and closes the sphere. Dust with sugar and serve with jam."]} },

{ id:'rugbrod', c:'eu', lat:55.680, lon:12.575, base:12, prep:2880, cook:100, diff:3, tags:['bread','slow','breakfast'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'roll',food:['#4f3a2a','#6f4a2a','#c9a878','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Rugbrød',en:'Rugbrød'},
  p:{fr:'Copenhague, Danemark',en:'Copenhagen, Denmark'},
  d:{fr:"Un pain de seigle dense, presque noir, semé de graines, base obligatoire du smørrebrød. Il est cuit dans un moule rectangulaire et non en boule : il doit être tranché fin et régulier pour supporter une garniture, et le Danois moyen en mange plusieurs tranches par jour.",
     en:"A dense, almost black rye bread studded with seeds, the compulsory base of smørrebrød. It is baked in a rectangular tin rather than as a round: it must slice thin and even to carry a topping, and the average Dane eats several slices a day."},
  i:[['rye_flour',500,'g'],['flour',250,'g'],['sourdough_starter',150,'g'],['warm_water',600,'ml'],['sunflower_seeds',100,'g'],['flax_seeds',80,'g'],['black_treacle',2,'tbsp'],['beer',150,'ml'],['coarse_salt',15,'g']],
  s:{fr:["Faites tremper les graines une nuit dans la bière et un peu d'eau : sèches, elles pomperaient l'eau de la pâte et le pain serait sec.","Mêlez le levain, l'eau tiède, les farines, la mélasse et le sel — la pâte de seigle est collante et ne se pétrit pas, on la remue à la cuillère.","Ne cherchez pas à développer du gluten : le seigle n'en a presque pas, et travailler la pâte ne fait que la rendre gommeuse.","Versez dans un moule à cake beurré, lissez à la spatule mouillée et laissez lever 4 à 6 heures, jusqu'à ce que des craquelures apparaissent en surface.","Cuisez 1 h 40 à 180 °C, démoulez et laissez refroidir 24 heures avant de trancher : coupé chaud, il colle au couteau et paraît cru."],
     en:["Soak the seeds overnight in the beer and a little water: dry, they would draw water out of the dough and the bread would be dry.","Mix the starter, warm water, flours, treacle and salt — rye dough is sticky and is not kneaded, it is stirred with a spoon.","Do not try to develop gluten: rye has almost none, and working the dough only makes it gummy.","Pour into a buttered loaf tin, smooth with a wet spatula and prove 4 to 6 hours, until cracks appear on the surface.","Bake 1 hour 40 at 180°C, turn out and cool 24 hours before slicing: cut warm it clings to the knife and seems raw."]} },

{ id:'remoulade-danoise', c:'eu', lat:55.673, lon:12.560, base:8, prep:30, cook:0, diff:1, tags:['fast','fresh','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#e8c46a','#f4f0e6','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Rémoulade danoise',en:'Danish remoulade'},
  p:{fr:'Copenhague, Danemark',en:'Copenhagen, Denmark'},
  d:{fr:"Une sauce jaune pâle aux légumes hachés et au curcuma, servie sur les hot-dogs et le poisson pané. Elle n'a plus grand-chose de la rémoulade française : les Danois y ont ajouté du chou-fleur, du sucre et du curcuma, et en consomment plus de deux kilos par personne et par an.",
     en:"A pale yellow sauce with chopped vegetables and turmeric, served on hot dogs and breaded fish. Little remains of the French remoulade: the Danes added cauliflower, sugar and turmeric, and get through over two kilos a head each year."},
  i:[['mayonnaise',250,'g'],['pickles',80,'g'],['cauliflower',100,'g'],['capers',20,'g'],['onion',1,'pc'],['turmeric',1,'tsp'],['mustard',1,'tbsp'],['sugar',1,'tbsp'],['white_vinegar',2,'tbsp'],['chives',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites blanchir le chou-fleur en tout petits bouquets 4 minutes et rafraîchissez-le : cru, il reste dur et acre dans la sauce.","Hachez cornichons, chou-fleur, câpres et oignon au couteau en dés d'un ou deux millimètres — c'est un travail long et il n'a pas de substitut.","Faites dégorger l'oignon dix minutes dans le vinaigre sucré, puis égouttez-le en gardant le vinaigre.","Mêlez le tout à la mayonnaise avec la moutarde, le curcuma, le sucre et le vinaigre récupéré.","Laissez reposer 24 heures au froid : la sauce est fade le premier jour et juste au second. Le curcuma continue de colorer pendant la nuit."],
     en:["Blanch the cauliflower in very small florets for 4 minutes and refresh it: raw, it stays hard and acrid in the sauce.","Chop the gherkins, cauliflower, capers and onion by knife into one- or two-millimetre dice — long work with no substitute.","Steep the onion ten minutes in the sweetened vinegar, then drain it keeping the vinegar.","Mix everything into the mayonnaise with the mustard, turmeric, sugar and the reserved vinegar.","Rest 24 hours in the cold: the sauce is bland on the first day and right on the second. The turmeric keeps colouring overnight."]} },

{ id:'koldskal', c:'eu', lat:55.686, lon:12.552, base:6, prep:20, cook:0, diff:1, tags:['sweet','fresh','fast'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4f0e6',style:'soup',food:['#f4f0e6','#f2dfa8','#e07a9a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Koldskål',en:'Koldskål'},
  p:{fr:'Copenhague, Danemark',en:'Copenhagen, Denmark'},
  d:{fr:"Une soupe froide de babeurre à la vanille et au citron, bue à la cuillère l'été avec de petits biscuits. Elle apparaît dans les cuisines danoises quand le thermomètre passe vingt degrés et disparaît en septembre : les supermarchés en vendent des palettes trois mois par an, et rien le reste du temps.",
     en:"A cold buttermilk soup with vanilla and lemon, eaten with a spoon in summer with small biscuits. It appears in Danish kitchens when the thermometer passes twenty degrees and vanishes in September: supermarkets sell pallets of it for three months and none the rest of the year."},
  i:[['buttermilk',700,'ml'],['plain_yogurt',200,'g'],['heavy_cream',100,'ml'],['egg_yolk',2,'pc'],['sugar',100,'g'],['vanilla',1,'pc'],['lemon',1,'pc'],['strawberries',200,'g'],['digestive_biscuits',150,'g']],
  s:{fr:["Fouettez les jaunes avec le sucre et la vanille grattée jusqu'à ce que le mélange blanchisse et forme un ruban.","Le koldskål ne se cuit jamais : les jaunes restent crus, ce qui exige des œufs très frais et un service dans la journée.","Versez le babeurre bien froid en filet, en fouettant sans arrêt, pour ne pas faire trancher le mélange.","Ajoutez le yaourt, la crème et le zeste de citron, puis le jus, goutte à goutte et en dernier — versé trop tôt, il fait cailler le babeurre.","Réfrigérez 2 heures et servez glacé, avec des fraises coupées et des kammerjunker émiettés dessus."],
     en:["Whisk the yolks with the sugar and scraped vanilla until pale and ribboning.","Koldskål is never cooked: the yolks stay raw, which requires very fresh eggs and serving the same day.","Pour in the very cold buttermilk in a stream, whisking without pause, so the mixture does not split.","Add the yoghurt, cream and lemon zest, then the juice, drop by drop and last — poured too early it curdles the buttermilk.","Chill 2 hours and serve iced, with cut strawberries and crumbled kammerjunker on top."]} },

{ id:'braendende-kaerlighed', c:'eu', lat:55.670, lon:12.580, base:4, prep:25, cook:35, diff:1, tags:['pork','comfort','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#c9924a','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Brændende kærlighed',en:'Brændende kærlighed'},
  p:{fr:'Copenhague, Danemark',en:'Copenhagen, Denmark'},
  d:{fr:"Une purée de pommes de terre creusée en cratère, emplie de lardons et d'oignons frits. Le nom veut dire amour brûlant : le cratère de graisse dorée au milieu du blanc évoquait un volcan, et c'était le repas des jours de fin de mois dans les foyers danois.",
     en:"Mashed potato hollowed into a crater and filled with fried bacon and onion. The name means burning love: the crater of golden fat in the white suggested a volcano, and it was the end-of-the-month meal in Danish households."},
  i:[['potato',1,'kg'],['smoked_bacon',250,'g'],['onion',3,'pc'],['butter',80,'g'],['whole_milk',200,'ml'],['pickled_beets',150,'g'],['chives',3,'tbsp'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez les pommes de terre entières avec la peau et pelez-les brûlantes : coupées avant cuisson, elles se gorgent d'eau.","Passez-les au presse-purée et montez au beurre puis au lait chaud, sans jamais employer de mixeur.","Faites rissoler les lardons doucement pour qu'ils rendent leur graisse avant de croustiller, puis faites-y blondir l'oignon vingt minutes.","La graisse ne se jette pas : elle est le cœur du plat, et c'est elle qui remplit le cratère.","Dressez la purée en dôme, creusez-la à la cuillère, emplissez du mélange brûlant et servez avec des betteraves au vinaigre."],
     en:["Boil the potatoes whole in their skins and peel them scalding: cut before cooking they take on water.","Rice them and beat in the butter then the hot milk, never using a blender.","Fry the bacon gently so it renders before it crisps, then soften the onion in that fat for twenty minutes.","The fat is not discarded: it is the heart of the dish, and it is what fills the crater.","Mound the mash, hollow it with a spoon, fill it with the scalding mixture and serve with pickled beetroot."]} },

{ id:'golabki', c:'eu', lat:52.230, lon:21.012, base:6, prep:60, cook:100, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#7fae5a','#c9532c','#e8dcb8','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Gołąbki',en:'Gołąbki'},
  p:{fr:'Varsovie, Pologne',en:'Warsaw, Poland'},
  d:{fr:"Des feuilles de chou farcies de viande, de riz et de champignons, mijotées en sauce tomate. Le nom veut dire petits pigeons : la Pologne partage l'usage avec la Russie, mais y ajoute presque toujours des champignons séchés, ce qui donne à la farce un fond boisé absent du golubtsy.",
     en:"Cabbage leaves stuffed with meat, rice and mushrooms, stewed in tomato sauce. The name means little pigeons: Poland shares the practice with Russia, but almost always adds dried mushrooms, giving the filling a woodland depth golubtsy lack."},
  i:[['green_cabbage',1,'pc'],['ground_pork',300,'g'],['ground_beef',200,'g'],['long_grain_rice',150,'g'],['dried_mushrooms',30,'g'],['onion',2,'pc'],['tomato_puree',500,'ml'],['smetana',150,'g'],['bay_leaf',2,'pc'],['smoked_bacon',100,'g'],['marjoram',1,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les champignons séchés une heure à l'eau tiède et gardez l'eau de trempage filtrée : elle vaut un bouillon.","Congelez le chou entier deux jours puis décongelez-le : les feuilles se détachent alors seules, sans ébouillanter, et ne se déchirent pas.","Cuisez le riz à moitié, 7 minutes, et mêlez-le aux viandes, aux champignons hachés, à l'oignon et à la marjolaine.","Roulez serré en repliant les côtés, et tapissez le fond de la cocotte de feuilles de chou abîmées pour que rien n'attache.","Rangez les rouleaux serrés, versez la tomate et l'eau des champignons, et laissez mijoter 1 h 30 à couvert sans jamais remuer. Servez à la smetana."],
     en:["Soak the dried mushrooms an hour in warm water and keep the strained liquid: it is worth a broth.","Freeze the whole cabbage for two days then thaw it: the leaves then come away by themselves, without blanching, and do not tear.","Cook the rice halfway, 7 minutes, and mix it with the meats, chopped mushrooms, onion and marjoram.","Roll tightly, folding the sides in, and line the base of the pot with damaged cabbage leaves so nothing catches.","Pack the rolls in, pour over the tomato and mushroom liquor, and simmer 1½ hours covered without ever stirring. Serve with smetana."]} },

{ id:'placki-ziemniaczane', c:'eu', lat:50.065, lon:19.945, base:4, prep:30, cook:25, diff:1, tags:['veg','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#c9924a','#f4f0e6','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Placki ziemniaczane',en:'Placki ziemniaczane'},
  p:{fr:'Cracovie, Pologne',en:'Kraków, Poland'},
  d:{fr:"Des galettes de pomme de terre râpée frites, servies avec de la crème aigre ou du sucre. En Silésie on les sert sous un goulasch, ailleurs avec de la compote : c'est l'un des rares plats polonais qui se mange indifféremment salé ou sucré, et la dispute reste ouverte.",
     en:"Fried grated potato cakes, served with sour cream or sugar. In Silesia they come under a goulash, elsewhere with apple sauce: one of the few Polish dishes eaten equally savoury or sweet, and the argument is unresolved."},
  i:[['potato',1,'kg'],['onion',1,'pc'],['egg',2,'pc'],['flour',50,'g'],['sunflower_oil',300,'ml'],['smetana',200,'g'],['apple_sauce',200,'g'],['sugar',40,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les pommes de terre au trou fin, pas au gros : la placki polonaise est plus fine et plus lisse que la latke ou la röstis.","Râpez l'oignon en même temps et directement dans la râpure : son acidité ralentit l'oxydation et retarde le noircissement.","Pressez à peine — contrairement à la galette luxembourgeoise, la placki garde une partie de son eau, qui la rend moelleuse au centre.","Ajoutez les œufs, la farine, le sel et beaucoup de poivre, et cuisez sans attendre : la pâte se délite au bout d'un quart d'heure.","Frites dans un demi-centimètre d'huile bien chaude, 3 minutes par face. Servez avec de la crème aigre, ou sucrées à la compote."],
     en:["Grate the potatoes on the fine holes, not the coarse: the Polish placki is finer and smoother than a latke or a rösti.","Grate the onion at the same time straight into the gratings: its acidity slows oxidation and delays the darkening.","Press only lightly — unlike the Luxembourg cake, a placki keeps some of its water, which makes it soft in the middle.","Add the eggs, flour, salt and plenty of pepper, and cook without delay: the batter breaks down within a quarter of an hour.","Fry in half a centimetre of hot oil, 3 minutes a side. Serve with sour cream, or sweetened with apple sauce."]} },

{ id:'sernik', c:'eu', lat:52.407, lon:16.925, base:10, prep:60, cook:80, diff:2, tags:['sweet','bake','cheese'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#f4f0e6','#e8c46a','#f2dfa8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Sernik',en:'Sernik'},
  p:{fr:'Poznań, Pologne',en:'Poznań, Poland'},
  d:{fr:"Un gâteau au twaróg, fromage frais polonais passé trois fois au tamis, plus dense et moins sucré qu'un cheesecake. Le twaróg n'est pas du fromage à la crème : il est maigre et granuleux, et c'est le tamisage répété, non la matière grasse, qui donne la texture lisse.",
     en:"A cake of twaróg, the Polish fresh cheese passed three times through a sieve, denser and less sweet than a cheesecake. Twaróg is not cream cheese: it is lean and grainy, and it is the repeated sieving, not the fat, that gives the smooth texture."},
  i:[['tvorog',700,'g'],['sugar',200,'g'],['egg',5,'pc'],['butter',120,'g'],['potato_starch',50,'g'],['vanilla',1,'pc'],['lemon_zest',1,'pc'],['raisins',80,'g'],['shortcrust_pastry',250,'g'],['salt',null,'']],
  s:{fr:["Passez le twaróg trois fois au tamis fin : deux fois ne suffisent pas, et le mixeur le rend élastique au lieu de lisse.","Travaillez le beurre pommade avec le sucre 8 minutes, puis ajoutez les jaunes un à un en attendant l'absorption complète.","Incorporez le fromage, la fécule de pomme de terre — jamais de maïs, elle donne un goût — le zeste et la vanille.","Montez les blancs en neige souple et incorporez-les en trois fois, à la spatule : ce sont eux qui empêchent le sernik d'être compact.","Cuisez 1 h 20 à 160 °C, puis laissez refroidir une heure porte entrouverte : sorti d'un coup, il s'affaisse au centre et se fend."],
     en:["Pass the twaróg three times through a fine sieve: twice is not enough, and a blender makes it elastic instead of smooth.","Cream the softened butter with the sugar for 8 minutes, then add the yolks one at a time, waiting for full absorption.","Fold in the cheese, the potato starch — never cornstarch, which leaves a taste — the zest and vanilla.","Whisk the whites to soft peaks and fold them in three times with a spatula: they are what stop a sernik being solid.","Bake 1 hour 20 at 160°C, then cool for an hour with the door ajar: taken out suddenly, it sinks in the centre and cracks."]} },

{ id:'kielbasa-grillee', c:'eu', lat:52.237, lon:21.020, base:4, prep:20, cook:20, diff:1, tags:['pork','grill','street'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'grill',food:['#8f3b2a','#c9924a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kiełbasa grillée',en:'Grilled kiełbasa'},
  p:{fr:'Varsovie, Pologne',en:'Warsaw, Poland'},
  d:{fr:"Une saucisse fumée de porc et de bœuf, fendue et grillée, servie dans du pain avec de la moutarde. Le kiełbasa wiejska, la saucisse de campagne, se vend au poids en couronne ; la fendre en deux avant de la griller n'est pas un détail, c'est ce qui l'empêche d'éclater et de perdre son jus.",
     en:"A smoked pork and beef sausage, split and grilled, served in bread with mustard. Kiełbasa wiejska, the country sausage, is sold by weight in a coil; splitting it before grilling is no detail, it is what stops it bursting and losing its juices."},
  i:[['smoked_sausage',600,'g'],['onion',2,'pc'],['mustard',60,'g'],['rye_bread',400,'g'],['pickles',4,'pc'],['sunflower_oil',20,'ml'],['marjoram',1,'tsp'],['pepper',null,'']],
  s:{fr:["Choisissez une kiełbasa fumée mais non cuite, souple sous le doigt : les saucisses précuites sèchent au gril et deviennent farineuses.","Fendez-la en deux dans la longueur sans traverser la peau du dessous, pour qu'elle s'ouvre à plat comme un livre.","Grillez-la côté chair d'abord sur des braises grises, sans flamme, 6 minutes, puis retournez-la sur la peau.","La peau doit gonfler et brunir sans éclater : si elle siffle et gicle, votre feu est trop vif et le jus s'en va.","Faites griller les rondelles d'oignon dans la graisse tombée sur la plaque, et servez la saucisse dans du pain de seigle avec de la moutarde forte."],
     en:["Choose a smoked but uncooked kiełbasa, yielding under the finger: pre-cooked sausages dry on the grill and turn mealy.","Split it lengthwise without cutting through the skin underneath, so it opens flat like a book.","Grill it cut side down first over grey, flameless coals for 6 minutes, then turn it onto the skin.","The skin should swell and brown without splitting: if it hisses and spurts, your fire is too fierce and the juice is going.","Grill the onion rings in the fat that has fallen on the plate, and serve the sausage in rye bread with strong mustard."]} }
];
